-- Migration: Restore LUZZI verses mangled by the original import
--
-- The original importer of luzzi.txt (the LUZZI / Riveduta 1924 source)
-- split each verse on its <br /> poetic line breaks and kept only the first
-- segment; where the verse did not end in <br /> it dropped the tags without
-- a space, joining the lines. Result: 2,453 Psalm verses truncated or joined
-- (Ps 23:1 read only "Salmo di Davide."), plus 41 verses in other books
-- (37 joined, 4 truncated: Num 24:20, Prov 30:1, Prov 31:1, Amos 1:2).
-- It also discarded everything before the `^` that marks a verse heading,
-- which in 4 verses where the heading falls mid-verse was the first half of
-- the verse itself (2 Kgs 25:21, Neh 7:73, John 12:36, Acts 9:19). 2,498
-- rows in all. (The headings themselves are restored by 018.)
--
-- Every new text below is the original source run through the importer's
-- own conversion (scripts/repair_luzzi_from_source.py), which reproduces
-- every undamaged row exactly.
--
-- Each UPDATE is guarded on verseID AND a known damaged text: either the
-- pre-repair text, or the interim text written on 2026-11-14 by a first
-- repair that had completed the Psalms from eBible ita1927. Re-running is a
-- no-op and never overwrites later edits.
--
-- After applying, refresh embeddings: `compute_embeddings.py --version LUZZI`
-- picks up the changed rows for `embedding` via text_hash; for
-- `embedding_labse`, NULL it on rows where text_hash != embedded_text_hash
-- first (the LaBSE column is only filled where NULL).

BEGIN;

UPDATE "LUZZI" SET text = 'Allora Balaam pronunziò il suo oracolo e disse: «Balak m''ha fatto venire da Aram, il re di Moab, dalle montagne d''Oriente. - ''Vieni'', disse, ''maledicimi Giacobbe! Vieni, esècra Israele!''' WHERE "verseID" = 91026 AND (text = 'Allora Balaam pronunziò il suo oracolo e disse:«Balak m''ha fatto venire da Aram, il re di Moab, dalle montagne d''Oriente. - ''Vieni'', disse, ''maledicimi Giacobbe! Vieni, esècra Israele!'''); -- 4 23:7
UPDATE "LUZZI" SET text = 'Allora Balaam pronunziò il suo oracolo e disse: «Lèvati, Balak, e ascolta! Porgimi orecchio, figliuolo di Tsippor!' WHERE "verseID" = 91037 AND (text = 'Allora Balaam pronunziò il suo oracolo e disse:«Lèvati, Balak, e ascolta! Porgimi orecchio, figliuolo di Tsippor!'); -- 4 23:18
UPDATE "LUZZI" SET text = 'E Balaam pronunziò il suo oracolo e disse: «Così dice Balaam, figliuolo di Beor, così dice l''uomo che ha l''occhio aperto,' WHERE "verseID" = 91052 AND (text = 'E Balaam pronunziò il suo oracolo e disse:«Così dice Balaam, figliuolo di Beor, così dice l''uomo che ha l''occhio aperto,'); -- 4 24:3
UPDATE "LUZZI" SET text = 'Allora Balaam pronunziò il suo oracolo e disse: «Così dice Balaam, figliuolo di Beor; così dice l''uomo che ha l''occhio aperto,' WHERE "verseID" = 91064 AND (text = 'Allora Balaam pronunziò il suo oracolo e disse:«Così dice Balaam, figliuolo di Beor; così dice l''uomo che ha l''occhio aperto,'); -- 4 24:15
