UPDATE "LUZZI" SET text = 'perseguiti pure il nemico l''anima mia e la raggiunga, e calpesti al suolo la mia vita, e stenda la mia gloria nella polvere. Sela.' WHERE "verseID" = 100599 AND (text = 'perseguiti pure il nemico l''anima mia e la raggiunga,'); -- 23 7:5
UPDATE "LUZZI" SET text = 'Lèvati, o Eterno, nell''ira tua, innalzati contro i furori de'' miei nemici, e dèstati in mio favore.' WHERE "verseID" = 100600 AND (text = 'Lèvati, o Eterno, nell''ira tua,'); -- 23 7:6
UPDATE "LUZZI" SET text = 'Tu hai ordinato il giudicio. Ti circondi l''assemblea de'' popoli, e ponti a sedere al disopra d''essa in luogo elevato.' WHERE "verseID" = 100601 AND (text = 'Tu hai ordinato il giudicio.' OR text = 'Tu hai ordinato il giudicio. Ti circondi l''assemblea de'' popoli, e ponti a sedere al di sopra d''essa in luogo elevato.'); -- 23 7:7
UPDATE "LUZZI" SET text = 'L''Eterno giudica i popoli; giudica me, o Eterno, secondo la mia giustizia e la mia integrità.' WHERE "verseID" = 100602 AND (text = 'L''Eterno giudica i popoli;'); -- 23 7:8
UPDATE "LUZZI" SET text = 'Deh, venga meno la malvagità de'' malvagi, ma stabilisci il giusto; poiché sei l''Iddio giusto che prova i cuori e le reni.' WHERE "verseID" = 100603 AND (text = 'Deh, venga meno la malvagità de'' malvagi,'); -- 23 7:9
UPDATE "LUZZI" SET text = 'Il mio scudo è in Dio, che salva i diritti di cuore.' WHERE "verseID" = 100604 AND (text = 'Il mio scudo è in Dio,'); -- 23 7:10
UPDATE "LUZZI" SET text = 'Iddio è un giusto giudice, un Dio che s''adira ogni giorno.' WHERE "verseID" = 100605 AND (text = 'Iddio è un giusto giudice,'); -- 23 7:11
UPDATE "LUZZI" SET text = 'Se il malvagio non si converte egli aguzzerà la sua spada; egli ha teso l''arco suo e lo tien pronto;' WHERE "verseID" = 100606 AND (text = 'Se il malvagio non si converte egli aguzzerà la sua spada;'); -- 23 7:12
UPDATE "LUZZI" SET text = 'dispone contro di lui strumenti di morte; le sue frecce le rende infocate.' WHERE "verseID" = 100607 AND (text = 'dispone contro di lui strumenti di morte;'); -- 23 7:13
UPDATE "LUZZI" SET text = 'Ecco, il malvagio è in doglie per produrre iniquità. Egli ha concepito malizia e partorisce menzogna.' WHERE "verseID" = 100608 AND (text = 'Ecco, il malvagio è in doglie per produrre iniquità.'); -- 23 7:14
UPDATE "LUZZI" SET text = 'Ha scavato una fossa e l''ha resa profonda, ma è caduto nella fossa che ha fatta.' WHERE "verseID" = 100609 AND (text = 'Ha scavato una fossa e l''ha resa profonda,'); -- 23 7:15
UPDATE "LUZZI" SET text = 'La sua malizia gli ritornerà sul capo, e la sua violenza gli scenderà sulla testa.' WHERE "verseID" = 100610 AND (text = 'La sua malizia gli ritornerà sul capo,'); -- 23 7:16
UPDATE "LUZZI" SET text = 'Io loderò l''Eterno per la sua giustizia, e salmeggerò al nome dell''Eterno, dell''Altissimo.' WHERE "verseID" = 100611 AND (text = 'Io loderò l''Eterno per la sua giustizia,e salmeggerò al nome dell''Eterno, dell''Altissimo.'); -- 23 7:17
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Sulla Ghittea. Salmo di Davide. O Eterno, Signor nostro, quant''è magnifico il tuo nome in tutta la terra! O Tu che hai posta la tua maestà nei cieli.' WHERE "verseID" = 100612 AND (text = 'Al Capo de'' musici. Sulla Ghittea. Salmo di Davide.'); -- 23 8:1
UPDATE "LUZZI" SET text = 'Dalla bocca de'' fanciulli e de'' lattanti tu hai tratto una forza, per cagione de'' tuoi nemici, per ridurre al silenzio l''avversario e il vendicatore.' WHERE "verseID" = 100613 AND (text = 'Dalla bocca de'' fanciulli e de'' lattanti tu hai tratto una forza,'); -- 23 8:2
UPDATE "LUZZI" SET text = 'Quand''io considero i tuoi cieli, opra delle tue dita, la luna e le stelle che tu hai disposte -' WHERE "verseID" = 100614 AND (text = 'Quand''io considero i tuoi cieli, opra delle tue dita,' OR text = 'Quand''io considero i tuoi cieli, opra delle tue dita, la luna e le stelle che tu hai disposte,'); -- 23 8:3
UPDATE "LUZZI" SET text = 'che cos''è l''uomo che tu n''abbia memoria? e il figliuol dell''uomo che tu ne prenda cura?' WHERE "verseID" = 100615 AND (text = 'che cos''è l''uomo che tu n''abbia memoria?'); -- 23 8:4
UPDATE "LUZZI" SET text = 'Eppure tu l''hai fatto poco minor di Dio, e l''hai coronato di gloria e d''onore.' WHERE "verseID" = 100616 AND (text = 'Eppure tu l''hai fatto poco minor di Dio,'); -- 23 8:5
UPDATE "LUZZI" SET text = 'Tu l''hai fatto signoreggiare sulle opere delle tue mani, hai posto ogni cosa sotto i suoi piedi:' WHERE "verseID" = 100617 AND (text = 'Tu l''hai fatto signoreggiare sulle opere delle tue mani,'); -- 23 8:6
UPDATE "LUZZI" SET text = 'pecore e buoi tutti quanti ed anche le fiere della campagna;' WHERE "verseID" = 100618 AND (text = 'pecore e buoi tutti quanti'); -- 23 8:7
UPDATE "LUZZI" SET text = 'gli uccelli del cielo e i pesci del mare, tutto quel che percorre i sentieri de'' mari.' WHERE "verseID" = 100619 AND (text = 'gli uccelli del cielo e i pesci del mare,'); -- 23 8:8
UPDATE "LUZZI" SET text = 'O Eterno, Signor nostro, quant''è magnifico il tuo nome in tutta la terra!' WHERE "verseID" = 100620 AND (text = 'O Eterno, Signor nostro,quant''è magnifico il tuo nome in tutta la terra!'); -- 23 8:9
UPDATE "LUZZI" SET text = 'Al Capo dei musici. Su «Muori pel figlio». Salmo di Davide. Io celebrerò l''Eterno con tutto il mio cuore, io narrerò tutte le tue maraviglie.' WHERE "verseID" = 100621 AND (text = 'Al Capo dei musici. Su «Muori pel figlio». Salmo di Davide.'); -- 23 9:1
UPDATE "LUZZI" SET text = 'Io mi rallegrerò e festeggerò in te, salmeggerò al tuo nome, o Altissimo,' WHERE "verseID" = 100622 AND (text = 'Io mi rallegrerò e festeggerò in te,'); -- 23 9:2
UPDATE "LUZZI" SET text = 'poiché i miei nemici voltan le spalle, cadono e periscono dinanzi al tuo cospetto.' WHERE "verseID" = 100623 AND (text = 'poiché i miei nemici voltan le spalle,'); -- 23 9:3
UPDATE "LUZZI" SET text = 'Poiché tu hai sostenuto il mio diritto e la mia causa; ti sei assiso sul trono come giusto giudice.' WHERE "verseID" = 100624 AND (text = 'Poiché tu hai sostenuto il mio diritto e la mia causa;'); -- 23 9:4
UPDATE "LUZZI" SET text = 'Tu hai sgridate le nazioni, hai distrutto l''empio, hai cancellato il loro nome in sempiterno.' WHERE "verseID" = 100625 AND (text = 'Tu hai sgridate le nazioni, hai distrutto l''empio,'); -- 23 9:5
UPDATE "LUZZI" SET text = 'È finita per il nemico! Son rovine perpetue! e delle città che tu hai distrutte perfin la memoria è perita.' WHERE "verseID" = 100626 AND (text = 'È finita per il nemico! Son rovine perpetue!' OR text = 'È finita per il nemico! Son rovine perpetue! e delle città che tu hai distrutte perfin la memoria e perita.'); -- 23 9:6
UPDATE "LUZZI" SET text = 'Ma l''Eterno siede come re in eterno; egli ha preparato il suo trono per il giudizio.' WHERE "verseID" = 100627 AND (text = 'Ma l''Eterno siede come re in eterno;'); -- 23 9:7
UPDATE "LUZZI" SET text = 'Ed egli giudicherà il mondo con giustizia, giudicherà i popoli con rettitudine.' WHERE "verseID" = 100628 AND (text = 'Ed egli giudicherà il mondo con giustizia,'); -- 23 9:8
UPDATE "LUZZI" SET text = 'E l''Eterno sarà un alto ricetto all''oppresso, un alto ricetto in tempi di distretta;' WHERE "verseID" = 100629 AND (text = 'E l''Eterno sarà un alto ricetto all''oppresso,'); -- 23 9:9
UPDATE "LUZZI" SET text = 'e quelli che conoscono il tuo nome confideranno in te, perché, o Eterno, tu non abbandoni quelli che ti cercano.' WHERE "verseID" = 100630 AND (text = 'e quelli che conoscono il tuo nome confideranno in te,'); -- 23 9:10
UPDATE "LUZZI" SET text = 'Salmeggiate l''Eterno che abita in Sion, raccontate tra i popoli le sue gesta.' WHERE "verseID" = 100631 AND (text = 'Salmeggiate l''Eterno che abita in Sion,'); -- 23 9:11
UPDATE "LUZZI" SET text = 'Perché colui che domanda ragion del sangue, si ricorda dei miseri e non ne dimentica il grido.' WHERE "verseID" = 100632 AND (text = 'Perché colui che domanda ragion del sangue,'); -- 23 9:12
UPDATE "LUZZI" SET text = 'Abbi pietà di me, o Eterno! Vedi l''afflizione che soffro da quelli che m''odiano, o tu che mi trai su dalle porte della morte,' WHERE "verseID" = 100633 AND (text = 'Abbi pietà di me, o Eterno!'); -- 23 9:13
UPDATE "LUZZI" SET text = 'acciocché io racconti tutte le tue lodi. Nelle porte della figliuola di Sion, io festeggerò per la tua salvazione.' WHERE "verseID" = 100634 AND (text = 'acciocché io racconti tutte le tue lodi.'); -- 23 9:14
UPDATE "LUZZI" SET text = 'Le nazioni sono sprofondate nella fossa che avean fatta; il loro piede è stato preso nella rete che aveano nascosta.' WHERE "verseID" = 100635 AND (text = 'Le nazioni sono sprofondate nella fossa che avean fatta;'); -- 23 9:15
UPDATE "LUZZI" SET text = 'L''Eterno s''è fatto conoscere, ha fatto giustizia; l''empio è stato preso al laccio nell''opera delle proprie mani. Higgaion. Sela.' WHERE "verseID" = 100636 AND (text = 'L''Eterno s''è fatto conoscere, ha fatto giustizia;'); -- 23 9:16
UPDATE "LUZZI" SET text = 'Gli empi se n''andranno al soggiorno de'' morti, sì, tutte le nazioni che dimenticano Iddio.' WHERE "verseID" = 100637 AND (text = 'Gli empi se n''andranno al soggiorno de'' morti,'); -- 23 9:17
UPDATE "LUZZI" SET text = 'Poiché il povero non sarà dimenticato per sempre, né la speranza de'' miseri perirà in perpetuo.' WHERE "verseID" = 100638 AND (text = 'Poiché il povero non sarà dimenticato per sempre,'); -- 23 9:18
UPDATE "LUZZI" SET text = 'Lèvati, o Eterno! Non lasciar che prevalga il mortale; sian giudicate le nazioni in tua presenza.' WHERE "verseID" = 100639 AND (text = 'Lèvati, o Eterno! Non lasciar che prevalga il mortale;'); -- 23 9:19
UPDATE "LUZZI" SET text = 'O Eterno, infondi spavento in loro; sappian le nazioni che non son altro che mortali. Sela.' WHERE "verseID" = 100640 AND (text = 'O Eterno, infondi spavento in loro;sappian le nazioni che non son altro che mortali. Sela.'); -- 23 9:20
UPDATE "LUZZI" SET text = 'O Eterno, perché te ne stai lontano? Perché ti nascondi in tempi di distretta?' WHERE "verseID" = 100641 AND (text = 'O Eterno, perché te ne stai lontano?'); -- 23 10:1
UPDATE "LUZZI" SET text = 'L''empio nella sua superbia perseguita con furore i miseri; essi rimangon presi nelle macchinazioni che gli empi hanno ordite;' WHERE "verseID" = 100642 AND (text = 'L''empio nella sua superbia perseguita con furore i miseri;'); -- 23 10:2
UPDATE "LUZZI" SET text = 'poiché l''empio si gloria delle brame dell''anima sua, benedice il rapace e disprezza l''Eterno.' WHERE "verseID" = 100643 AND (text = 'poiché l''empio si gloria delle brame dell''anima sua,'); -- 23 10:3
UPDATE "LUZZI" SET text = 'L''empio, nell''alterezza della sua faccia, dice: L''Eterno non farà inchieste. Tutti i suoi pensieri sono: Non c''è Dio!' WHERE "verseID" = 100644 AND (text = 'L''empio, nell''alterezza della sua faccia,' OR text = 'L''empio, nell''alterezza della sua faccia, dice: l''Eterno non farà inchieste. Tutti i suoi pensieri sono: Non c''è Dio!'); -- 23 10:4
UPDATE "LUZZI" SET text = 'Le sue vie son prospere in ogni tempo; cosa troppo alta per lui sono i tuoi giudizi; egli soffia contro tutti i suoi nemici.' WHERE "verseID" = 100645 AND (text = 'Le sue vie son prospere in ogni tempo;'); -- 23 10:5
UPDATE "LUZZI" SET text = 'Egli dice nel suo cuore: Non sarò mai smosso; d''età in età non m''accadrà male alcuno.' WHERE "verseID" = 100646 AND (text = 'Egli dice nel suo cuore: Non sarò mai smosso;'); -- 23 10:6
UPDATE "LUZZI" SET text = 'La sua bocca è piena di esecrazione, di frodi, e di oppressione; sotto la sua lingua v''è malizia ed iniquità.' WHERE "verseID" = 100647 AND (text = 'La sua bocca è piena di esecrazione, di frodi, e di oppressione;'); -- 23 10:7
UPDATE "LUZZI" SET text = 'Egli sta negli agguati de'' villaggi; uccide l''innocente in luoghi nascosti; i suoi occhi spiano il meschino.' WHERE "verseID" = 100648 AND (text = 'Egli sta negli agguati de'' villaggi;'); -- 23 10:8
UPDATE "LUZZI" SET text = 'Sta in agguato nel suo nascondiglio come un leone nella sua spelonca; sta in agguato per sorprendere il misero; egli sorprende il misero traendolo nella sua rete.' WHERE "verseID" = 100649 AND (text = 'Sta in agguato nel suo nascondiglio'); -- 23 10:9
UPDATE "LUZZI" SET text = 'Se ne sta quattro e chino, ed i meschini cadono tra le sue unghie.' WHERE "verseID" = 100650 AND (text = 'Se ne sta quattro e chino,'); -- 23 10:10
UPDATE "LUZZI" SET text = 'Egli dice nel cuor suo: Iddio dimentica, nasconde la sua faccia, mai lo vedrà.' WHERE "verseID" = 100651 AND (text = 'Egli dice nel cuor suo: Iddio dimentica,'); -- 23 10:11
UPDATE "LUZZI" SET text = 'Lèvati o Eterno! o Dio, alza la mano! Non dimenticare i miseri.' WHERE "verseID" = 100652 AND (text = 'Lèvati o Eterno! o Dio, alza la mano!'); -- 23 10:12
UPDATE "LUZZI" SET text = 'Perché l''empio disprezza Iddio? perché dice in cuor suo: Non ne farai ricerca?' WHERE "verseID" = 100653 AND (text = 'Perché l''empio disprezza Iddio?'); -- 23 10:13
UPDATE "LUZZI" SET text = 'Tu l''hai pur veduto; poiché tu riguardi ai travagli ed alle pene per prender la cosa in mano. A te si abbandona il meschino; tu sei l''aiutator dell''orfano.' WHERE "verseID" = 100654 AND (text = 'Tu l''hai pur veduto; poiché tu riguardi ai travagli'); -- 23 10:14
UPDATE "LUZZI" SET text = 'Fiacca il braccio dell''empio, cerca l''empietà del malvagio finché tu non ne trovi più.' WHERE "verseID" = 100655 AND (text = 'Fiacca il braccio dell''empio,'); -- 23 10:15
UPDATE "LUZZI" SET text = 'L''Eterno è re in sempiterno; le nazioni sono state sterminate dalla sua terra.' WHERE "verseID" = 100656 AND (text = 'L''Eterno è re in sempiterno;'); -- 23 10:16
UPDATE "LUZZI" SET text = 'O Eterno, tu esaudisci il desiderio degli umili; tu raffermerai il cuor loro, inclinerai le orecchie tue' WHERE "verseID" = 100657 AND (text = 'O Eterno, tu esaudisci il desiderio degli umili;'); -- 23 10:17
UPDATE "LUZZI" SET text = 'per far ragione all''orfano e all''oppresso, onde l''uomo, che è della terra, cessi dall''incutere spavento.' WHERE "verseID" = 100658 AND (text = 'per far ragione all''orfano e all''oppresso,onde l''uomo, che è della terra, cessi dall''incutere spavento.'); -- 23 10:18
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Di Davide. Io mi confido nell''Eterno. Come dite voi all''anima mia: Fuggi al tuo monte come un uccello?' WHERE "verseID" = 100659 AND (text = 'Al Capo de'' musici. Di Davide.'); -- 23 11:1
UPDATE "LUZZI" SET text = 'Poiché, ecco, gli empi tendono l''arco, accoccan le loro saette sulla corda per tirarle nell''oscurità contro i retti di cuore.' WHERE "verseID" = 100660 AND (text = 'Poiché, ecco, gli empi tendono l''arco,'); -- 23 11:2
UPDATE "LUZZI" SET text = 'Quando i fondamenti son rovinati che può fare il giusto?' WHERE "verseID" = 100661 AND (text = 'Quando i fondamenti son rovinati'); -- 23 11:3
UPDATE "LUZZI" SET text = 'L''Eterno è nel tempio della sua santità; l''Eterno ha il suo trono nei cieli; i suoi occhi veggono, le sue palpebre scrutano i figliuoli degli uomini.' WHERE "verseID" = 100662 AND (text = 'L''Eterno è nel tempio della sua santità;'); -- 23 11:4
UPDATE "LUZZI" SET text = 'L''Eterno scruta il giusto, ma l''anima sua odia l''empio e colui che ama la violenza.' WHERE "verseID" = 100663 AND (text = 'L''Eterno scruta il giusto,'); -- 23 11:5
UPDATE "LUZZI" SET text = 'Egli farà piovere sull''empio carboni accesi; zolfo e vento infocato sarà la parte del loro calice.' WHERE "verseID" = 100664 AND (text = 'Egli farà piovere sull''empio carboni accesi;'); -- 23 11:6
UPDATE "LUZZI" SET text = 'Poiché l''Eterno è giusto; egli ama la giustizia; gli uomini retti contempleranno la sua faccia.' WHERE "verseID" = 100665 AND (text = 'Poiché l''Eterno è giusto; egli ama la giustizia;gli uomini retti contempleranno la sua faccia.'); -- 23 11:7
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Sopra l''ottava. Salmo di Davide. Salva, o Eterno, poiché l''uomo pio vien meno, e i fedeli vengono a mancare tra i figliuoli degli uomini.' WHERE "verseID" = 100666 AND (text = 'Al Capo de'' musici. Sopra l''ottava. Salmo di Davide.'); -- 23 12:1
UPDATE "LUZZI" SET text = 'Ciascuno mentisce parlando col prossimo; parlano con labbro lusinghiero e con cuor doppio.' WHERE "verseID" = 100667 AND (text = 'Ciascuno mentisce parlando col prossimo;'); -- 23 12:2
UPDATE "LUZZI" SET text = 'L''Eterno recida tutte le labbra lusinghiere, la lingua che parla alteramente,' WHERE "verseID" = 100668 AND (text = 'L''Eterno recida tutte le labbra lusinghiere,'); -- 23 12:3
UPDATE "LUZZI" SET text = 'quelli che dicono: Con le nostre lingue prevarremo; le nostre labbra sono per noi; chi sarà signore su noi?' WHERE "verseID" = 100669 AND (text = 'quelli che dicono: Con le nostre lingue prevarremo;'); -- 23 12:4
UPDATE "LUZZI" SET text = 'Per l''oppressione dei miseri, per il grido d''angoscia de'' bisognosi, ora mi leverò, dice l''Eterno; darò loro la salvezza alla quale anelano.' WHERE "verseID" = 100670 AND (text = 'Per l''oppressione dei miseri, per il grido d''angoscia de'' bisognosi,'); -- 23 12:5
UPDATE "LUZZI" SET text = 'Le parole dell''Eterno son parole pure, sono argento affinato in un crogiuolo di terra, purificato sette volte.' WHERE "verseID" = 100671 AND (text = 'Le parole dell''Eterno son parole pure,'); -- 23 12:6
UPDATE "LUZZI" SET text = 'Tu, o Eterno, li proteggerai, li preserverai da questa generazione in perpetuo.' WHERE "verseID" = 100672 AND (text = 'Tu, o Eterno, li proteggerai,'); -- 23 12:7
UPDATE "LUZZI" SET text = 'Gli empi vanno attorno da tutte le parti quando la bassezza siede in alto tra i figliuoli degli uomini.' WHERE "verseID" = 100673 AND (text = 'Gli empi vanno attorno da tutte le partiquando la bassezza siede in alto tra i figliuoli degli uomini.'); -- 23 12:8
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Salmo di Davide. Fino a quando, o Eterno, mi dimenticherai tu? sarà egli per sempre? Fino a quando mi nasconderai la tua faccia?' WHERE "verseID" = 100674 AND (text = 'Al Capo de'' musici. Salmo di Davide.' OR text = 'Al Capo de'' musici. Salmo di Davide. Fino a quando, o Eterno, mi dimenticherai tu? Sarà egli per sempre? Fino a quando mi nasconderai la tua faccia?'); -- 23 13:1
UPDATE "LUZZI" SET text = 'Fino a quando avrò l''ansia nell''anima e l''affanno nel cuore tutto il giorno? Fino a quando s''innalzerà il mio nemico sopra me?' WHERE "verseID" = 100675 AND (text = 'Fino a quando avrò l''ansia nell''anima'); -- 23 13:2
UPDATE "LUZZI" SET text = 'Riguarda, rispondimi, o Eterno, Iddio mio! Illumina gli occhi miei che talora io non m''addormenti del sonno della morte,' WHERE "verseID" = 100676 AND (text = 'Riguarda, rispondimi, o Eterno, Iddio mio!'); -- 23 13:3
UPDATE "LUZZI" SET text = 'che talora il mio nemico non dica: L''ho vinto! e i miei avversari non festeggino se io vacillo.' WHERE "verseID" = 100677 AND (text = 'che talora il mio nemico non dica: L''ho vinto!'); -- 23 13:4
UPDATE "LUZZI" SET text = 'Quant''è a me, io confido nella tua benignità; il mio cuore giubilerà per la tua salvazione; io canterò all''Eterno perché m''ha fatto del bene.' WHERE "verseID" = 100678 AND (text = 'Quant''è a me, io confido nella tua benignità;il mio cuore giubilerà per la tua salvazione;io canterò all''Eterno perché m''ha fatto del bene.'); -- 23 13:5
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Di Davide. Lo stolto ha detto nel suo cuore: Non c''è Dio. Si sono corrotti, si son resi abominevoli nella loro condotta; non v''è alcuno che faccia il bene.' WHERE "verseID" = 100679 AND (text = 'Al Capo de'' musici. Di Davide.'); -- 23 14:1
UPDATE "LUZZI" SET text = 'L''Eterno ha riguardato dal cielo sui figliuoli degli uomini per vedere se vi fosse alcuno che avesse intelletto, che cercasse Iddio.' WHERE "verseID" = 100680 AND (text = 'L''Eterno ha riguardato dal cielo sui figliuoli degli uomini'); -- 23 14:2
UPDATE "LUZZI" SET text = 'Tutti si sono sviati, tutti quanti si son corrotti, non v''è alcuno che faccia il bene, neppur uno.' WHERE "verseID" = 100681 AND (text = 'Tutti si sono sviati, tutti quanti si son corrotti,'); -- 23 14:3
UPDATE "LUZZI" SET text = 'Son essi senza conoscenza tutti questi operatori d''iniquità, che mangiano il mio popolo come mangiano il pane e non invocano l''Eterno?' WHERE "verseID" = 100682 AND (text = 'Son essi senza conoscenza tutti questi operatori d''iniquità,'); -- 23 14:4
UPDATE "LUZZI" SET text = 'Ecco là, son presi da grande spavento perché Iddio è con la gente giusta.' WHERE "verseID" = 100683 AND (text = 'Ecco là, son presi da grande spavento'); -- 23 14:5
UPDATE "LUZZI" SET text = 'Voi, invece, fate onta al consiglio del misero, perché l''Eterno è il suo rifugio.' WHERE "verseID" = 100684 AND (text = 'Voi, invece, fate onta al consiglio del misero,'); -- 23 14:6
UPDATE "LUZZI" SET text = 'Oh, chi recherà da Sion la salvezza d''Israele? Quando l''Eterno ritrarrà dalla cattività il suo popolo, Giacobbe festeggerà, Israele si rallegrerà.' WHERE "verseID" = 100685 AND (text = 'Oh, chi recherà da Sion la salvezza d''Israele?Quando l''Eterno ritrarrà dalla cattività il suo popolo,Giacobbe festeggerà, Israele si rallegrerà.'); -- 23 14:7
UPDATE "LUZZI" SET text = 'Salmo di Davide. O Eterno, chi dimorerà nella tua tenda? chi abiterà sul monte della tua santità?' WHERE "verseID" = 100686 AND (text = 'Salmo di Davide. O Eterno, chi dimorerà nella tua tenda?'); -- 23 15:1
UPDATE "LUZZI" SET text = 'Colui che cammina in integrità ed opera giustizia e dice il vero come l''ha nel cuore;' WHERE "verseID" = 100687 AND (text = 'Colui che cammina in integrità ed opera giustizia'); -- 23 15:2
UPDATE "LUZZI" SET text = 'che non calunnia con la sua lingua, né fa male alcuno al suo compagno, né getta vituperio contro il suo prossimo.' WHERE "verseID" = 100688 AND (text = 'che non calunnia con la sua lingua,'); -- 23 15:3
UPDATE "LUZZI" SET text = 'Agli occhi suoi è sprezzato chi è spregevole, ma onora quelli che temono l''Eterno. Se ha giurato, foss''anche a suo danno, non muta;' WHERE "verseID" = 100689 AND (text = 'Agli occhi suoi è sprezzato chi è spregevole,'); -- 23 15:4
UPDATE "LUZZI" SET text = 'non dà il suo danaro ad usura, né accetta presenti a danno dell''innocente. Chi fa queste cose non sarà mai smosso.' WHERE "verseID" = 100690 AND (text = 'non dà il suo danaro ad usura,né accetta presenti a danno dell''innocente.Chi fa queste cose non sarà mai smosso.'); -- 23 15:5
UPDATE "LUZZI" SET text = 'Inno di Davide. Preservami, o Dio, perché io confido in te.' WHERE "verseID" = 100691 AND (text = 'Inno di Davide.'); -- 23 16:1
UPDATE "LUZZI" SET text = 'Io ho detto all''Eterno: Tu sei il mio Signore; io non ho bene all''infuori di te;' WHERE "verseID" = 100692 AND (text = 'Io ho detto all''Eterno: Tu sei il mio Signore;'); -- 23 16:2
UPDATE "LUZZI" SET text = 'e quanto ai santi che sono in terra essi sono la gente onorata in cui ripongo tutta la mia affezione.' WHERE "verseID" = 100693 AND (text = 'e quanto ai santi che sono in terra'); -- 23 16:3
UPDATE "LUZZI" SET text = 'I dolori di quelli che corron dietro ad altri dii saran moltiplicati; io non offrirò le loro libazioni di sangue, né le mie labbra proferiranno i loro nomi.' WHERE "verseID" = 100694 AND (text = 'I dolori di quelli che corron dietro ad altri dii'); -- 23 16:4
UPDATE "LUZZI" SET text = 'L''Eterno è la parte della mia eredità e il mio calice; tu mantieni quel che m''è toccato in sorte.' WHERE "verseID" = 100695 AND (text = 'L''Eterno è la parte della mia eredità e il mio calice;'); -- 23 16:5
UPDATE "LUZZI" SET text = 'La sorte è caduta per me in luoghi dilettevoli; una bella eredità mi è pur toccata!' WHERE "verseID" = 100696 AND (text = 'La sorte è caduta per me in luoghi dilettevoli;' OR text = 'La sorte è caduta per me in luoghi dilettevoli; una bella eredità mi e pur toccata!'); -- 23 16:6
UPDATE "LUZZI" SET text = 'Io benedirò l''Eterno che mi consiglia; anche la notte le mie reni mi ammaestrano.' WHERE "verseID" = 100697 AND (text = 'Io benedirò l''Eterno che mi consiglia;'); -- 23 16:7
UPDATE "LUZZI" SET text = 'Io ho sempre posto l''Eterno davanti agli occhi miei; poich''egli è alla mia destra, io non sarò punto smosso.' WHERE "verseID" = 100698 AND (text = 'Io ho sempre posto l''Eterno davanti agli occhi miei;'); -- 23 16:8
UPDATE "LUZZI" SET text = 'Perciò il mio cuore si rallegra e l''anima mia festeggia; anche la mia carne dimorerà al sicuro;' WHERE "verseID" = 100699 AND (text = 'Perciò il mio cuore si rallegra e l''anima mia festeggia;'); -- 23 16:9
UPDATE "LUZZI" SET text = 'poiché tu non abbandonerai l''anima mia in poter della morte, né permetterai che il tuo santo vegga la fossa.' WHERE "verseID" = 100700 AND (text = 'poiché tu non abbandonerai l''anima mia in poter della morte,' OR text = 'poiché tu non abbandonerai l''anima mia in poter della morte, ne permetterai che il tuo santo vegga la fossa.'); -- 23 16:10
UPDATE "LUZZI" SET text = 'Tu mi mostrerai il sentiero della vita; vi son gioie a sazietà nella tua presenza; vi son diletti alla tua destra in eterno.' WHERE "verseID" = 100701 AND (text = 'Tu mi mostrerai il sentiero della vita;vi son gioie a sazietà nella tua presenza;vi son diletti alla tua destra in eterno.'); -- 23 16:11
UPDATE "LUZZI" SET text = 'Preghiera di Davide. O Eterno, ascolta la giustizia, attendi al mio grido; porgi l''orecchio alla mia preghiera che non viene da labbra di frode.' WHERE "verseID" = 100702 AND (text = 'Preghiera di Davide.'); -- 23 17:1
UPDATE "LUZZI" SET text = 'Dalla tua presenza venga alla luce il mio diritto, gli occhi tuoi riconoscano la rettitudine.' WHERE "verseID" = 100703 AND (text = 'Dalla tua presenza venga alla luce il mio diritto,'); -- 23 17:2
UPDATE "LUZZI" SET text = 'Tu hai scrutato il mio cuore, l''hai visitato nella notte; m''hai provato e non hai rinvenuto nulla; la mia bocca non trapassa il mio pensiero.' WHERE "verseID" = 100704 AND (text = 'Tu hai scrutato il mio cuore, l''hai visitato nella notte;'); -- 23 17:3
UPDATE "LUZZI" SET text = 'Quanto alle opere degli uomini, io, per ubbidire alla parola delle tue labbra, mi son guardato dalle vie de'' violenti.' WHERE "verseID" = 100705 AND (text = 'Quanto alle opere degli uomini,'); -- 23 17:4
UPDATE "LUZZI" SET text = 'I miei passi si son tenuti saldi sui tuoi sentieri, i miei piedi non han vacillato.' WHERE "verseID" = 100706 AND (text = 'I miei passi si son tenuti saldi sui tuoi sentieri,'); -- 23 17:5
UPDATE "LUZZI" SET text = 'Io t''invoco, perché tu m''esaudisci, o Dio; inclina verso me il tuo orecchio, ascolta le mie parole!' WHERE "verseID" = 100707 AND (text = 'Io t''invoco, perché tu m''esaudisci, o Dio;'); -- 23 17:6
UPDATE "LUZZI" SET text = 'Spiega le maraviglie della tua bontà, o tu che con la tua destra salvi quelli che cercano un rifugio contro ai loro avversari.' WHERE "verseID" = 100708 AND (text = 'Spiega le maraviglie della tua bontà,'); -- 23 17:7
UPDATE "LUZZI" SET text = 'Preservami come la pupilla dell''occhio, nascondimi all''ombra delle tue ali' WHERE "verseID" = 100709 AND (text = 'Preservami come la pupilla dell''occhio,'); -- 23 17:8
UPDATE "LUZZI" SET text = 'dagli empi che voglion la mia rovina, dai miei mortali nemici che mi circondano.' WHERE "verseID" = 100710 AND (text = 'dagli empi che voglion la mia rovina,'); -- 23 17:9
UPDATE "LUZZI" SET text = 'Chiudono il loro cuore nel grasso, parlano alteramente colla lor bocca.' WHERE "verseID" = 100711 AND (text = 'Chiudono il loro cuore nel grasso,'); -- 23 17:10
UPDATE "LUZZI" SET text = 'Ora ci attorniano, seguendo i nostri passi; ci spiano per atterrarci.' WHERE "verseID" = 100712 AND (text = 'Ora ci attorniano, seguendo i nostri passi;'); -- 23 17:11
UPDATE "LUZZI" SET text = 'Il mio nemico somiglia ad un leone che brama lacerare, ad un leoncello che s''appiatta ne'' nascondigli.' WHERE "verseID" = 100713 AND (text = 'Il mio nemico somiglia ad un leone che brama lacerare,'); -- 23 17:12
UPDATE "LUZZI" SET text = 'Lèvati, o Eterno, vagli incontro, abbattilo; libera l''anima mia dall''empio con la tua spada;' WHERE "verseID" = 100714 AND (text = 'Lèvati, o Eterno,'); -- 23 17:13
UPDATE "LUZZI" SET text = 'liberami, con la tua mano, dagli uomini, o Eterno, dagli uomini del mondo la cui parte è in questa vita, e il cui ventre tu empi co'' tuoi tesori; hanno figliuoli in abbondanza, e lasciano il resto de'' loro averi ai loro fanciulli.' WHERE "verseID" = 100715 AND (text = 'liberami, con la tua mano, dagli uomini, o Eterno,'); -- 23 17:14
UPDATE "LUZZI" SET text = 'Quanto a me, per la mia giustizia, contemplerò la tua faccia, mi sazierò, al mio risveglio, della tua sembianza.' WHERE "verseID" = 100716 AND (text = 'Quanto a me, per la mia giustizia, contemplerò la tua faccia,mi sazierò, al mio risveglio, della tua sembianza.'); -- 23 17:15
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Di Davide, servo dell''Eterno, il quale rivolse all''Eterno le parole di questo cantico quando l''Eterno l''ebbe riscosso dalla mano di tutti i suoi nemici e dalla mano di Saul. Egli disse: Io t''amo, o Eterno, mia forza!' WHERE "verseID" = 100717 AND (text = 'Al Capo de'' musici. Di Davide, servo dell''Eterno, il quale rivolse all''Eterno le parole di questo cantico quando l''Eterno l''ebbe riscosso dalla mano di tutti i suoi nemici e dalla mano di Saul. Egli disse:'); -- 23 18:1
UPDATE "LUZZI" SET text = 'L''Eterno è la mia ròcca, la mia fortezza, il mio liberatore; il mio Dio, la mia rupe, in cui mi rifugio, il mio scudo, il mio potente salvatore, il mio alto ricetto.' WHERE "verseID" = 100718 AND (text = 'L''Eterno è la mia ròcca, la mia fortezza, il mio liberatore;'); -- 23 18:2
UPDATE "LUZZI" SET text = 'Io invocai l''Eterno ch''è degno d''ogni lode e fui salvato dai miei nemici.' WHERE "verseID" = 100719 AND (text = 'Io invocai l''Eterno ch''è degno d''ogni lode'); -- 23 18:3
UPDATE "LUZZI" SET text = 'I legami della morte m''aveano circondato e i torrenti della distruzione m''aveano spaventato.' WHERE "verseID" = 100720 AND (text = 'I legami della morte m''aveano circondato'); -- 23 18:4
UPDATE "LUZZI" SET text = 'I legami del soggiorno de'' morti m''aveano attorniato, i lacci della morte m''aveano còlto.' WHERE "verseID" = 100721 AND (text = 'I legami del soggiorno de'' morti m''aveano attorniato,'); -- 23 18:5
UPDATE "LUZZI" SET text = 'Nella mia distretta invocai l''Eterno e gridai al mio Dio. Egli udì la mia voce dal suo tempio e il mio grido pervenne a lui, ai suoi orecchi.' WHERE "verseID" = 100722 AND (text = 'Nella mia distretta invocai l''Eterno'); -- 23 18:6
UPDATE "LUZZI" SET text = 'Allora la terra fu scossa e tremò, i fondamenti de'' monti furono smossi e scrollati; perch''egli era acceso d''ira.' WHERE "verseID" = 100723 AND (text = 'Allora la terra fu scossa e tremò,'); -- 23 18:7
UPDATE "LUZZI" SET text = 'Un fumo saliva dalle sue nari; un fuoco consumante gli usciva dalla bocca, e ne procedevano carboni accesi.' WHERE "verseID" = 100724 AND (text = 'Un fumo saliva dalle sue nari;'); -- 23 18:8
UPDATE "LUZZI" SET text = 'Egli abbassò i cieli e discese, avendo sotto i piedi una densa caligine.' WHERE "verseID" = 100725 AND (text = 'Egli abbassò i cieli e discese,'); -- 23 18:9
UPDATE "LUZZI" SET text = 'Cavalcava sopra un cherubino e volava; volava veloce sulle ali del vento;' WHERE "verseID" = 100726 AND (text = 'Cavalcava sopra un cherubino e volava;'); -- 23 18:10
UPDATE "LUZZI" SET text = 'avea fatto delle tenebre la sua stanza nascosta, avea posto intorno a sé per suo padiglione l''oscurità dell''acque, le dense nubi de'' cieli.' WHERE "verseID" = 100727 AND (text = 'avea fatto delle tenebre la sua stanza nascosta,'); -- 23 18:11
UPDATE "LUZZI" SET text = 'Per lo splendore che lo precedeva, le dense nubi si sciolsero con gragnuola e con carboni accesi.' WHERE "verseID" = 100728 AND (text = 'Per lo splendore che lo precedeva, le dense nubi si sciolsero'); -- 23 18:12
UPDATE "LUZZI" SET text = 'L''Eterno tuonò ne'' cieli e l''Altissimo diè fuori la sua voce con gragnuola e con carboni accesi.' WHERE "verseID" = 100729 AND (text = 'L''Eterno tuonò ne'' cieli'); -- 23 18:13
UPDATE "LUZZI" SET text = 'E avventò le sue saette e disperse i nemici; lanciò folgori in gran numero e li mise in rotta.' WHERE "verseID" = 100730 AND (text = 'E avventò le sue saette e disperse i nemici;'); -- 23 18:14
UPDATE "LUZZI" SET text = 'Allora apparve il letto delle acque, e i fondamenti del mondo furono scoperti al tuo sgridare, o Eterno, al soffio del vento delle tue nari.' WHERE "verseID" = 100731 AND (text = 'Allora apparve il letto delle acque,'); -- 23 18:15
UPDATE "LUZZI" SET text = 'Egli distese dall''alto la mano e mi prese, mi trasse fuori delle grandi acque.' WHERE "verseID" = 100732 AND (text = 'Egli distese dall''alto la mano e mi prese,'); -- 23 18:16
UPDATE "LUZZI" SET text = 'Mi riscosse dal mio potente nemico, e da quelli che mi odiavano perch''eran più forti di me.' WHERE "verseID" = 100733 AND (text = 'Mi riscosse dal mio potente nemico,'); -- 23 18:17
UPDATE "LUZZI" SET text = 'Essi m''eran piombati addosso nel dì della mia calamità, ma l''Eterno fu il mio sostegno.' WHERE "verseID" = 100734 AND (text = 'Essi m''eran piombati addosso nel dì della mia calamità,'); -- 23 18:18
UPDATE "LUZZI" SET text = 'Egli mi trasse fuori al largo, mi liberò, perché mi gradisce.' WHERE "verseID" = 100735 AND (text = 'Egli mi trasse fuori al largo,'); -- 23 18:19
UPDATE "LUZZI" SET text = 'L''Eterno mi ha retribuito secondo la mia giustizia, mi ha reso secondo la purità delle mie mani,' WHERE "verseID" = 100736 AND (text = 'L''Eterno mi ha retribuito secondo la mia giustizia,'); -- 23 18:20
UPDATE "LUZZI" SET text = 'poiché ho osservato le vie dell''Eterno e non mi sono empiamente sviato dal mio Dio.' WHERE "verseID" = 100737 AND (text = 'poiché ho osservato le vie dell''Eterno'); -- 23 18:21
UPDATE "LUZZI" SET text = 'Poiché ho tenuto tutte le sue leggi davanti a me, e non ho rimosso da me i suoi statuti.' WHERE "verseID" = 100738 AND (text = 'Poiché ho tenuto tutte le sue leggi davanti a me,'); -- 23 18:22
UPDATE "LUZZI" SET text = 'E sono stato integro verso lui, e mi son guardato dalla mia iniquità.' WHERE "verseID" = 100739 AND (text = 'E sono stato integro verso lui,'); -- 23 18:23
UPDATE "LUZZI" SET text = 'Ond''è che l''Eterno m''ha reso secondo la mia giustizia, secondo la purità delle mie mani nel suo cospetto.' WHERE "verseID" = 100740 AND (text = 'Ond''è che l''Eterno m''ha reso secondo la mia giustizia,'); -- 23 18:24
UPDATE "LUZZI" SET text = 'Tu ti mostri pietoso verso il pio, integro verso l''uomo integro;' WHERE "verseID" = 100741 AND (text = 'Tu ti mostri pietoso verso il pio,'); -- 23 18:25
UPDATE "LUZZI" SET text = 'ti mostri puro col puro e ti mostri astuto col perverso;' WHERE "verseID" = 100742 AND (text = 'ti mostri puro col puro'); -- 23 18:26
UPDATE "LUZZI" SET text = 'poiché tu sei quel che salvi la gente afflitta e fai abbassare gli occhi alteri.' WHERE "verseID" = 100743 AND (text = 'poiché tu sei quel che salvi la gente afflitta'); -- 23 18:27
UPDATE "LUZZI" SET text = 'Sì, tu sei quel che fa risplendere la mia lampada; l''Eterno, il mio Dio, è quel che illumina le mie tenebre.' WHERE "verseID" = 100744 AND (text = 'Sì, tu sei quel che fa risplendere la mia lampada;'); -- 23 18:28
UPDATE "LUZZI" SET text = 'Con te io assalgo tutta una schiera e col mio Dio salgo sulle mura.' WHERE "verseID" = 100745 AND (text = 'Con te io assalgo tutta una schiera'); -- 23 18:29
UPDATE "LUZZI" SET text = 'La via di Dio è perfetta; la parola dell''Eterno è purgata col fuoco; egli è lo scudo di tutti quelli che sperano in lui.' WHERE "verseID" = 100746 AND (text = 'La via di Dio è perfetta;' OR text = 'La via di Dio è perfetta; la parola dell''Eterno e purgata col fuoco; egli è lo scudo di tutti quelli che sperano in lui.'); -- 23 18:30
UPDATE "LUZZI" SET text = 'Poiché chi è Dio fuor dell''Eterno? E chi è Ròcca fuor del nostro Dio,' WHERE "verseID" = 100747 AND (text = 'Poiché chi è Dio fuor dell''Eterno?'); -- 23 18:31
UPDATE "LUZZI" SET text = 'l''Iddio che mi cinge di forza e rende la mia vita perfetta?' WHERE "verseID" = 100748 AND (text = 'l''Iddio che mi cinge di forza' OR text = 'l''Iddio che mi cinge di forza e rende la mia via perfetta?'); -- 23 18:32
UPDATE "LUZZI" SET text = 'Egli rende i miei piedi simili a quelli delle cerve, e mi rende saldo sui miei alti luoghi;' WHERE "verseID" = 100749 AND (text = 'Egli rende i miei piedi simili a quelli delle cerve,'); -- 23 18:33
UPDATE "LUZZI" SET text = 'ammaestra le mie mani alla battaglia e le mie braccia tendono un arco di rame.' WHERE "verseID" = 100750 AND (text = 'ammaestra le mie mani alla battaglia'); -- 23 18:34
UPDATE "LUZZI" SET text = 'Tu m''hai anche dato lo scudo della tua salvezza, e la tua destra m''ha sostenuto, e la tua benignità m''ha fatto grande.' WHERE "verseID" = 100751 AND (text = 'Tu m''hai anche dato lo scudo della tua salvezza,'); -- 23 18:35
UPDATE "LUZZI" SET text = 'Tu hai allargato la via ai miei passi; e i miei piedi non hanno vacillato.' WHERE "verseID" = 100752 AND (text = 'Tu hai allargato la via ai miei passi;'); -- 23 18:36
UPDATE "LUZZI" SET text = 'Io ho inseguito i miei nemici e li ho raggiunti; e non son tornato indietro prima d''averli distrutti.' WHERE "verseID" = 100753 AND (text = 'Io ho inseguito i miei nemici e li ho raggiunti;'); -- 23 18:37
UPDATE "LUZZI" SET text = 'Io li ho abbattuti e non son potuti risorgere; son caduti sotto i miei piedi.' WHERE "verseID" = 100754 AND (text = 'Io li ho abbattuti e non son potuti risorgere;'); -- 23 18:38
UPDATE "LUZZI" SET text = 'Tu m''hai cinto di forza per la guerra; tu hai fatto piegare sotto di me i miei avversari;' WHERE "verseID" = 100755 AND (text = 'Tu m''hai cinto di forza per la guerra;'); -- 23 18:39
UPDATE "LUZZI" SET text = 'hai fatto voltar le spalle davanti a me ai miei nemici, e ho distrutto quelli che m''odiavano.' WHERE "verseID" = 100756 AND (text = 'hai fatto voltar le spalle davanti a me ai miei nemici,'); -- 23 18:40
UPDATE "LUZZI" SET text = 'Hanno gridato, ma non vi fu chi li salvasse; hanno gridato all''Eterno, ma egli non rispose loro.' WHERE "verseID" = 100757 AND (text = 'Hanno gridato, ma non vi fu chi li salvasse;'); -- 23 18:41
UPDATE "LUZZI" SET text = 'Io li ho tritati come polvere esposta al vento, li ho spazzati via come il fango delle strade.' WHERE "verseID" = 100758 AND (text = 'Io li ho tritati come polvere esposta al vento,'); -- 23 18:42
UPDATE "LUZZI" SET text = 'Tu m''hai liberato dalle dissensioni del popolo, m''hai costituito capo di nazioni; un popolo che non conoscevo mi è stato sottoposto.' WHERE "verseID" = 100759 AND (text = 'Tu m''hai liberato dalle dissensioni del popolo,' OR text = 'Tu m''hai liberato dalle dissensioni del popolo, m''hai costituito capo di nazioni; un popolo che non conoscevo mi e stato sottoposto.'); -- 23 18:43
UPDATE "LUZZI" SET text = 'Al solo udir parlare di me, m''hanno ubbidito; i figli degli stranieri m''hanno reso omaggio.' WHERE "verseID" = 100760 AND (text = 'Al solo udir parlare di me, m''hanno ubbidito;'); -- 23 18:44
UPDATE "LUZZI" SET text = 'I figli degli stranieri son venuti meno, sono usciti tremanti dai loro ripari.' WHERE "verseID" = 100761 AND (text = 'I figli degli stranieri son venuti meno,'); -- 23 18:45
UPDATE "LUZZI" SET text = 'Vive l''Eterno! Sia benedetta la mia ròcca! E sia esaltato l''Iddio della mia salvezza!' WHERE "verseID" = 100762 AND (text = 'Vive l''Eterno! Sia benedetta la mia ròcca!'); -- 23 18:46
UPDATE "LUZZI" SET text = 'l''Iddio che fa la mia vendetta e mi sottomette i popoli,' WHERE "verseID" = 100763 AND (text = 'l''Iddio che fa la mia vendetta'); -- 23 18:47
UPDATE "LUZZI" SET text = 'che mi scampa dai miei nemici. Sì, tu mi sollevi sopra i miei avversari, mi riscuoti dall''uomo violento.' WHERE "verseID" = 100764 AND (text = 'che mi scampa dai miei nemici.'); -- 23 18:48
UPDATE "LUZZI" SET text = 'Perciò, o Eterno, ti loderò fra le nazioni, e salmeggerò al tuo nome.' WHERE "verseID" = 100765 AND (text = 'Perciò, o Eterno, ti loderò fra le nazioni,'); -- 23 18:49
UPDATE "LUZZI" SET text = 'Grandi liberazioni egli accorda al suo re, ed usa benignità verso il suo unto, verso Davide e la sua progenie in perpetuo.' WHERE "verseID" = 100766 AND (text = 'Grandi liberazioni egli accorda al suo re,ed usa benignità verso il suo unto,verso Davide e la sua progenie in perpetuo.'); -- 23 18:50
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Salmo di Davide. I cieli raccontano la gloria di Dio e il firmamento annunzia l''opera delle sue mani.' WHERE "verseID" = 100767 AND (text = 'Al Capo de'' musici. Salmo di Davide.'); -- 23 19:1
UPDATE "LUZZI" SET text = 'Un giorno sgorga parole all''altro, una notte comunica conoscenza all''altra.' WHERE "verseID" = 100768 AND (text = 'Un giorno sgorga parole all''altro,'); -- 23 19:2
UPDATE "LUZZI" SET text = 'Non hanno favella né parole; la loro voce non s''ode.' WHERE "verseID" = 100769 AND (text = 'Non hanno favella né parole;'); -- 23 19:3
UPDATE "LUZZI" SET text = 'Ma il loro suono esce fuori per tutta la terra, e i loro accenti vanno fino all''estremità del mondo. Quivi Iddio ha posto una tenda per il sole,' WHERE "verseID" = 100770 AND (text = 'Ma il loro suono esce fuori per tutta la terra,'); -- 23 19:4
UPDATE "LUZZI" SET text = 'ed egli è simile a uno sposo ch''esce dalla sua camera nuziale; gioisce come un prode a correre l''arringo.' WHERE "verseID" = 100771 AND (text = 'ed egli è simile a uno sposo ch''esce dalla sua camera nuziale;'); -- 23 19:5
UPDATE "LUZZI" SET text = 'La sua uscita è da una estremità de'' cieli, e il suo giro arriva fino all''altra estremità; e niente è nascosto al suo calore.' WHERE "verseID" = 100772 AND (text = 'La sua uscita è da una estremità de'' cieli,'); -- 23 19:6
UPDATE "LUZZI" SET text = 'La legge dell''Eterno è perfetta, ella ristora l''anima; la testimonianza dell''Eterno è verace, rende savio il semplice.' WHERE "verseID" = 100773 AND (text = 'La legge dell''Eterno è perfetta, ella ristora l''anima;'); -- 23 19:7
UPDATE "LUZZI" SET text = 'I precetti dell''Eterno son giusti, rallegrano il cuore; il comandamento dell''Eterno è puro, illumina gli occhi.' WHERE "verseID" = 100774 AND (text = 'I precetti dell''Eterno son giusti, rallegrano il cuore;'); -- 23 19:8
UPDATE "LUZZI" SET text = 'Il timore dell''Eterno è puro, dimora in perpetuo; i giudizi dell''Eterno sono verità, tutti quanti son giusti,' WHERE "verseID" = 100775 AND (text = 'Il timore dell''Eterno è puro, dimora in perpetuo;'); -- 23 19:9
UPDATE "LUZZI" SET text = 'son più desiderabili dell''oro, anzi, più di molto oro finissimo, son più dolci del miele, anzi, di quello che stilla dai favi.' WHERE "verseID" = 100776 AND (text = 'son più desiderabili dell''oro, anzi, più di molto oro finissimo,'); -- 23 19:10
UPDATE "LUZZI" SET text = 'Anche il tuo servitore è da essi ammaestrato; v''è gran ricompensa ad osservarli.' WHERE "verseID" = 100777 AND (text = 'Anche il tuo servitore è da essi ammaestrato;'); -- 23 19:11
UPDATE "LUZZI" SET text = 'Chi conosce i suoi errori? Purificami da quelli che mi sono occulti.' WHERE "verseID" = 100778 AND (text = 'Chi conosce i suoi errori?'); -- 23 19:12
UPDATE "LUZZI" SET text = 'Trattieni pure il tuo servitore dai peccati volontari, e fa'' che non signoreggino su me; allora sarò integro, e puro di grandi trasgressioni.' WHERE "verseID" = 100779 AND (text = 'Trattieni pure il tuo servitore dai peccati volontari,'); -- 23 19:13
UPDATE "LUZZI" SET text = 'Siano grate nel tuo cospetto le parole della mia bocca e la meditazione del cuor mio, o Eterno, mia ròcca e mio redentore!' WHERE "verseID" = 100780 AND (text = 'Siano grate nel tuo cospetto le parole della mia boccae la meditazione del cuor mio,o Eterno, mia ròcca e mio redentore!'); -- 23 19:14
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Salmo di Davide. L''Eterno ti risponda nel dì della distretta; il nome dell''Iddio di Giacobbe ti levi in alto in salvo;' WHERE "verseID" = 100781 AND (text = 'Al Capo de'' musici. Salmo di Davide.'); -- 23 20:1
UPDATE "LUZZI" SET text = 'ti mandi soccorso dal santuario, e ti sostenga da Sion;' WHERE "verseID" = 100782 AND (text = 'ti mandi soccorso dal santuario,'); -- 23 20:2
UPDATE "LUZZI" SET text = 'si ricordi di tutte le tue offerte ed accetti il tuo olocausto. Sela.' WHERE "verseID" = 100783 AND (text = 'si ricordi di tutte le tue offerte'); -- 23 20:3
UPDATE "LUZZI" SET text = 'Ti dia egli quel che il tuo cuore desidera, e adempia ogni tuo disegno.' WHERE "verseID" = 100784 AND (text = 'Ti dia egli quel che il tuo cuore desidera,'); -- 23 20:4
UPDATE "LUZZI" SET text = 'Noi canteremo d''allegrezza per la tua vittoria, e alzeremo le nostre bandiere nel nome dell''Iddio nostro. L''Eterno esaudisca tutte le tue domande.' WHERE "verseID" = 100785 AND (text = 'Noi canteremo d''allegrezza per la tua vittoria,'); -- 23 20:5
UPDATE "LUZZI" SET text = 'Già io so che l''Eterno ha salvato il suo unto, e gli risponderà dal cielo della sua santità, con le potenti liberazioni della sua destra.' WHERE "verseID" = 100786 AND (text = 'Già io so che l''Eterno ha salvato il suo unto,'); -- 23 20:6
UPDATE "LUZZI" SET text = 'Gli uni confidano in carri, e gli altri in cavalli; ma noi ricorderemo il nome dell''Eterno, dell''Iddio nostro.' WHERE "verseID" = 100787 AND (text = 'Gli uni confidano in carri, e gli altri in cavalli;'); -- 23 20:7
UPDATE "LUZZI" SET text = 'Quelli piegano e cadono; ma noi restiamo in piè e teniam fermo.' WHERE "verseID" = 100788 AND (text = 'Quelli piegano e cadono;'); -- 23 20:8
UPDATE "LUZZI" SET text = 'O Eterno, salva il re! L''Eterno ci risponda nel giorno che noi l''invochiamo!' WHERE "verseID" = 100789 AND (text = 'O Eterno, salva il re!L''Eterno ci risponda nel giorno che noi l''invochiamo!'); -- 23 20:9
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Salmo di Davide. O Eterno, il re si rallegra nella tua forza; ed oh quanto esulta per la tua salvezza!' WHERE "verseID" = 100790 AND (text = 'Per il Capo de'' musici. Salmo di Davide.'); -- 23 21:1
UPDATE "LUZZI" SET text = 'Tu gli hai dato il desiderio del suo cuore e non gli hai rifiutata la richiesta delle sue labbra. Sela.' WHERE "verseID" = 100791 AND (text = 'Tu gli hai dato il desiderio del suo cuore'); -- 23 21:2
UPDATE "LUZZI" SET text = 'Poiché tu gli sei venuto incontro con benedizioni eccellenti, gli hai posta in capo una corona d''oro finissimo.' WHERE "verseID" = 100792 AND (text = 'Poiché tu gli sei venuto incontro con benedizioni eccellenti,'); -- 23 21:3
UPDATE "LUZZI" SET text = 'Egli t''avea chiesto vita, e tu gliel''hai data: lunghezza di giorni perpetua ed eterna.' WHERE "verseID" = 100793 AND (text = 'Egli t''avea chiesto vita, e tu gliel''hai data:'); -- 23 21:4
UPDATE "LUZZI" SET text = 'Grande è la sua gloria mercé la tua salvezza. Tu lo rivesti di maestà e di magnificenza;' WHERE "verseID" = 100794 AND (text = 'Grande è la sua gloria mercé la tua salvezza.'); -- 23 21:5
UPDATE "LUZZI" SET text = 'poiché lo ricolmi delle tue benedizioni in perpetuo, lo riempi di gioia nella tua presenza.' WHERE "verseID" = 100795 AND (text = 'poiché lo ricolmi delle tue benedizioni in perpetuo,'); -- 23 21:6
UPDATE "LUZZI" SET text = 'Perché il re si confida nell''Eterno, e, per la benignità dell''Altissimo, non sarà smosso.' WHERE "verseID" = 100796 AND (text = 'Perché il re si confida nell''Eterno,'); -- 23 21:7
UPDATE "LUZZI" SET text = 'La tua mano troverà tutti i tuoi nemici; la tua destra raggiungerà quelli che t''odiano.' WHERE "verseID" = 100797 AND (text = 'La tua mano troverà tutti i tuoi nemici;'); -- 23 21:8
UPDATE "LUZZI" SET text = 'Tu li metterai come in una fornace ardente, quando apparirai; l''Eterno, nel suo cruccio, li inabisserà, e il fuoco li divorerà.' WHERE "verseID" = 100798 AND (text = 'Tu li metterai come in una fornace ardente,'); -- 23 21:9
UPDATE "LUZZI" SET text = 'Tu farai sparire il loro frutto dalla terra e la loro progenie di tra i figli degli uomini;' WHERE "verseID" = 100799 AND (text = 'Tu farai sparire il loro frutto dalla terra'); -- 23 21:10
UPDATE "LUZZI" SET text = 'perché hanno ordito del male contro a te; han formato malvagi disegni, che non potranno attuare;' WHERE "verseID" = 100800 AND (text = 'perché hanno ordito del male contro a te;'); -- 23 21:11
UPDATE "LUZZI" SET text = 'poiché tu farai loro voltar le spalle, col tuo arco mirerai diritto alla loro faccia.' WHERE "verseID" = 100801 AND (text = 'poiché tu farai loro voltar le spalle,'); -- 23 21:12
UPDATE "LUZZI" SET text = 'Innalzati, o Eterno, con la tua forza; noi canteremo e celebreremo la tua potenza.' WHERE "verseID" = 100802 AND (text = 'Innalzati, o Eterno, con la tua forza;noi canteremo e celebreremo la tua potenza.'); -- 23 21:13
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Su ''Cerva dell''aurora''. Salmo di Davide. Dio mio, Dio mio, perché mi hai abbandonato? Perché te ne stai lontano, senza soccorrermi, senza dare ascolto alle parole del mio gemito?' WHERE "verseID" = 100803 AND (text = 'Per il Capo de'' musici. Su ''Cerva dell''aurora''. Salmo di Davide.'); -- 23 22:1
UPDATE "LUZZI" SET text = 'Dio mio, io grido di giorno, e tu non rispondi; di notte ancora, e non ho posa alcuna.' WHERE "verseID" = 100804 AND (text = 'Dio mio, io grido di giorno, e tu non rispondi;'); -- 23 22:2
UPDATE "LUZZI" SET text = 'Eppure tu sei il Santo, che siedi circondato dalle lodi d''Israele.' WHERE "verseID" = 100805 AND (text = 'Eppure tu sei il Santo,'); -- 23 22:3
UPDATE "LUZZI" SET text = 'I nostri padri confidarono in te; confidarono e tu li liberasti.' WHERE "verseID" = 100806 AND (text = 'I nostri padri confidarono in te;'); -- 23 22:4
UPDATE "LUZZI" SET text = 'Gridarono a te, e furono salvati; confidarono in te, e non furon confusi.' WHERE "verseID" = 100807 AND (text = 'Gridarono a te, e furono salvati;'); -- 23 22:5
UPDATE "LUZZI" SET text = 'Ma io sono un verme e non un uomo; il vituperio degli uomini, e lo sprezzato dal popolo.' WHERE "verseID" = 100808 AND (text = 'Ma io sono un verme e non un uomo;'); -- 23 22:6
UPDATE "LUZZI" SET text = 'Chiunque mi vede si fa beffe di me; allunga il labbro, scuote il capo, dicendo:' WHERE "verseID" = 100809 AND (text = 'Chiunque mi vede si fa beffe di me;'); -- 23 22:7
UPDATE "LUZZI" SET text = 'Ei si rimette nell''Eterno; lo liberi dunque; lo salvi, poiché lo gradisce!' WHERE "verseID" = 100810 AND (text = 'Ei si rimette nell''Eterno; lo liberi dunque;'); -- 23 22:8
UPDATE "LUZZI" SET text = 'Sì, tu sei quello che m''hai tratto dal seno materno; m''hai fatto riposar fidente sulle mammelle di mia madre.' WHERE "verseID" = 100811 AND (text = 'Sì, tu sei quello che m''hai tratto dal seno materno;'); -- 23 22:9
UPDATE "LUZZI" SET text = 'A te fui affidato fin dalla mia nascita, tu sei il mio Dio fin dal seno di mia madre.' WHERE "verseID" = 100812 AND (text = 'A te fui affidato fin dalla mia nascita,'); -- 23 22:10
UPDATE "LUZZI" SET text = 'Non t''allontanare da me, perché l''angoscia è vicina, e non v''è alcuno che m''aiuti.' WHERE "verseID" = 100813 AND (text = 'Non t''allontanare da me, perché l''angoscia è vicina,'); -- 23 22:11
UPDATE "LUZZI" SET text = 'Grandi tori m''han circondato; potenti tori di Basan m''hanno attorniato;' WHERE "verseID" = 100814 AND (text = 'Grandi tori m''han circondato;'); -- 23 22:12
UPDATE "LUZZI" SET text = 'apron la loro gola contro a me, come un leone rapace e ruggente.' WHERE "verseID" = 100815 AND (text = 'apron la loro gola contro a me,'); -- 23 22:13
UPDATE "LUZZI" SET text = 'Io son come acqua che si sparge, e tutte le mie ossa si sconnettono; il mio cuore è come la cera, si strugge in mezzo alle mie viscere.' WHERE "verseID" = 100816 AND (text = 'Io son come acqua che si sparge,'); -- 23 22:14
UPDATE "LUZZI" SET text = 'Il mio vigore s''inaridisce come terra cotta, e la lingua mi s''attacca al palato; tu m''hai posto nella polvere della morte.' WHERE "verseID" = 100817 AND (text = 'Il mio vigore s''inaridisce come terra cotta,'); -- 23 22:15
UPDATE "LUZZI" SET text = 'Poiché cani m''han circondato; uno stuolo di malfattori m''ha attorniato; m''hanno forato le mani e i piedi.' WHERE "verseID" = 100818 AND (text = 'Poiché cani m''han circondato;'); -- 23 22:16
UPDATE "LUZZI" SET text = 'Posso contare tutte le mie ossa. Essi mi guardano e m''osservano;' WHERE "verseID" = 100819 AND (text = 'Posso contare tutte le mie ossa.'); -- 23 22:17
UPDATE "LUZZI" SET text = 'spartiscon fra loro i miei vestimenti e tirano a sorte la mia veste.' WHERE "verseID" = 100820 AND (text = 'spartiscon fra loro i miei vestimenti'); -- 23 22:18
UPDATE "LUZZI" SET text = 'Tu dunque, o Eterno, non allontanarti, tu che sei la mia forza, t''affretta a soccorrermi.' WHERE "verseID" = 100821 AND (text = 'Tu dunque, o Eterno, non allontanarti,'); -- 23 22:19
UPDATE "LUZZI" SET text = 'Libera l''anima mia dalla spada, l''unica mia, dalla zampa del cane;' WHERE "verseID" = 100822 AND (text = 'Libera l''anima mia dalla spada,'); -- 23 22:20
UPDATE "LUZZI" SET text = 'salvami dalla gola del leone. Tu mi risponderai liberandomi dalle corna dei bufali.' WHERE "verseID" = 100823 AND (text = 'salvami dalla gola del leone.'); -- 23 22:21
UPDATE "LUZZI" SET text = 'Io annunzierò il tuo nome ai miei fratelli, ti loderò in mezzo all''assemblea.' WHERE "verseID" = 100824 AND (text = 'Io annunzierò il tuo nome ai miei fratelli,'); -- 23 22:22
UPDATE "LUZZI" SET text = 'O voi che temete l''Eterno, lodatelo! Glorificatelo voi, tutta la progenie di Giacobbe, e voi tutta la progenie d''Israele, abbiate timor di lui!' WHERE "verseID" = 100825 AND (text = 'O voi che temete l''Eterno, lodatelo!'); -- 23 22:23
UPDATE "LUZZI" SET text = 'Poich''egli non ha sprezzata né disdegnata l''afflizione dell''afflitto, e non ha nascosta la sua faccia da lui; ma quand''ha gridato a lui, ei l''ha esaudito.' WHERE "verseID" = 100826 AND (text = 'Poich''egli non ha sprezzata'); -- 23 22:24
UPDATE "LUZZI" SET text = 'Tu sei l''argomento della mia lode nella grande assemblea; io adempirò i miei voti in presenza di quelli che ti temono.' WHERE "verseID" = 100827 AND (text = 'Tu sei l''argomento della mia lode nella grande assemblea;'); -- 23 22:25
UPDATE "LUZZI" SET text = 'Gli umili mangeranno e saranno saziati; quei che cercano l''Eterno lo loderanno; il loro cuore vivrà in perpetuo.' WHERE "verseID" = 100828 AND (text = 'Gli umili mangeranno e saranno saziati;'); -- 23 22:26
UPDATE "LUZZI" SET text = 'Tutte le estremità della terra si ricorderan dell''Eterno e si convertiranno a lui; e tutte le famiglie delle nazioni adoreranno nel tuo cospetto.' WHERE "verseID" = 100829 AND (text = 'Tutte le estremità della terra si ricorderan dell''Eterno'); -- 23 22:27
UPDATE "LUZZI" SET text = 'Poiché all''Eterno appartiene il regno, ed egli signoreggia sulle nazioni.' WHERE "verseID" = 100830 AND (text = 'Poiché all''Eterno appartiene il regno,'); -- 23 22:28
UPDATE "LUZZI" SET text = 'Tutti gli opulenti della terra mangeranno e adoreranno; tutti quelli che scendon nella polvere e non posson mantenersi in vita s''inginocchieranno dinanzi a lui.' WHERE "verseID" = 100831 AND (text = 'Tutti gli opulenti della terra mangeranno e adoreranno;' OR text = 'Tutti gli opulenti della terra mangeranno e adoreranno; tutti quelli che scendon nella polvere e non possono mantenersi in vita s''inchineranno dinanzi a lui.'); -- 23 22:29
UPDATE "LUZZI" SET text = 'La posterità lo servirà; si parlerà del Signore alla ventura generazione.' WHERE "verseID" = 100832 AND (text = 'La posterità lo servirà;'); -- 23 22:30
UPDATE "LUZZI" SET text = 'Essi verranno e proclameranno la sua giustizia, e al popolo che nascerà diranno come egli ha operato.' WHERE "verseID" = 100833 AND (text = 'Essi verranno e proclameranno la sua giustizia,e al popolo che nascerà diranno come egli ha operato.'); -- 23 22:31
UPDATE "LUZZI" SET text = 'Salmo di Davide. L''Eterno è il mio pastore, nulla mi mancherà.' WHERE "verseID" = 100834 AND (text = 'Salmo di Davide.'); -- 23 23:1
UPDATE "LUZZI" SET text = 'Egli mi fa giacere in verdeggianti paschi, mi guida lungo le acque chete.' WHERE "verseID" = 100835 AND (text = 'Egli mi fa giacere in verdeggianti paschi,'); -- 23 23:2
UPDATE "LUZZI" SET text = 'Egli mi ristora l''anima, mi conduce per sentieri di giustizia, per amor del suo nome.' WHERE "verseID" = 100836 AND (text = 'Egli mi ristora l''anima,'); -- 23 23:3
UPDATE "LUZZI" SET text = 'Quand''anche camminassi nella valle dell''ombra della morte, io non temerei male alcuno, perché tu sei meco; il tuo bastone e la tua verga son quelli che mi consolano.' WHERE "verseID" = 100837 AND (text = 'Quand''anche camminassi nella valle dell''ombra della morte,'); -- 23 23:4
UPDATE "LUZZI" SET text = 'Tu apparecchi davanti a me la mensa al cospetto dei miei nemici; tu ungi il mio capo con olio; la mia coppa trabocca.' WHERE "verseID" = 100838 AND (text = 'Tu apparecchi davanti a me la mensa'); -- 23 23:5
UPDATE "LUZZI" SET text = 'Certo, beni e benignità m''accompagneranno tutti i giorni della mia vita; ed io abiterò nella casa dell''Eterno per lunghi giorni.' WHERE "verseID" = 100839 AND (text = 'Certo, beni e benignità m''accompagnerannotutti i giorni della mia vita;ed io abiterò nella casa dell''Eternoper lunghi giorni.'); -- 23 23:6
UPDATE "LUZZI" SET text = 'Salmo di Davide. All''Eterno appartiene la terra e tutto ciò ch''è in essa, il mondo e i suoi abitanti.' WHERE "verseID" = 100840 AND (text = 'Salmo di Davide.'); -- 23 24:1
UPDATE "LUZZI" SET text = 'Poich''egli l''ha fondata sui mari e l''ha stabilita sui fiumi.' WHERE "verseID" = 100841 AND (text = 'Poich''egli l''ha fondata sui mari'); -- 23 24:2
UPDATE "LUZZI" SET text = 'Chi salirà al monte dell''Eterno? e chi potrà stare nel luogo suo santo?' WHERE "verseID" = 100842 AND (text = 'Chi salirà al monte dell''Eterno?'); -- 23 24:3
UPDATE "LUZZI" SET text = 'L''uomo innocente di mani e puro di cuore, che non eleva l''animo a vanità, e non giura con intenti di frode.' WHERE "verseID" = 100843 AND (text = 'L''uomo innocente di mani e puro di cuore,'); -- 23 24:4
UPDATE "LUZZI" SET text = 'Egli riceverà benedizione dall''Eterno, e giustizia dall''Iddio della sua salvezza.' WHERE "verseID" = 100844 AND (text = 'Egli riceverà benedizione dall''Eterno,'); -- 23 24:5
UPDATE "LUZZI" SET text = 'Tale è la generazione di quelli che lo cercano, di quelli che cercan la tua faccia, o Dio di Giacobbe. Sela.' WHERE "verseID" = 100845 AND (text = 'Tale è la generazione di quelli che lo cercano,'); -- 23 24:6
UPDATE "LUZZI" SET text = 'O porte, alzate i vostri capi; e voi, porte eterne, alzatevi; e il Re di gloria entrerà.' WHERE "verseID" = 100846 AND (text = 'O porte, alzate i vostri capi;'); -- 23 24:7
UPDATE "LUZZI" SET text = 'Chi è questo Re di gloria? È l''Eterno, forte e potente, l''Eterno potente in battaglia.' WHERE "verseID" = 100847 AND (text = 'Chi è questo Re di gloria?'); -- 23 24:8
UPDATE "LUZZI" SET text = 'O porte, alzate i vostri capi; alzatevi, o porte eterne, e il Re di gloria entrerà.' WHERE "verseID" = 100848 AND (text = 'O porte, alzate i vostri capi;'); -- 23 24:9
UPDATE "LUZZI" SET text = 'Chi è questo Re di gloria? È l''Eterno degli eserciti; egli è il Re di gloria. Sela.' WHERE "verseID" = 100849 AND (text = 'Chi è questo Re di gloria?È l''Eterno degli eserciti;egli è il Re di gloria. Sela.'); -- 23 24:10
UPDATE "LUZZI" SET text = 'Di Davide. A te, o Eterno, io levo l''anima mia.' WHERE "verseID" = 100850 AND (text = 'Di Davide.'); -- 23 25:1
UPDATE "LUZZI" SET text = 'Dio mio, in te mi confido; fa'' ch''io non sia confuso, che i miei nemici non trionfino di me.' WHERE "verseID" = 100851 AND (text = 'Dio mio, in te mi confido;'); -- 23 25:2
UPDATE "LUZZI" SET text = 'Nessuno di quelli che sperano in te sia confuso; sian confusi quelli che si conducono slealmente senza cagione.' WHERE "verseID" = 100852 AND (text = 'Nessuno di quelli che sperano in te sia confuso;'); -- 23 25:3
UPDATE "LUZZI" SET text = 'O Eterno, fammi conoscere le tue vie, insegnami i tuoi sentieri.' WHERE "verseID" = 100853 AND (text = 'O Eterno, fammi conoscere le tue vie,'); -- 23 25:4
UPDATE "LUZZI" SET text = 'Guidami nella tua verità ed ammaestrami; poiché tu sei l''Iddio della mia salvezza: io spero in te del continuo.' WHERE "verseID" = 100854 AND (text = 'Guidami nella tua verità ed ammaestrami;'); -- 23 25:5
UPDATE "LUZZI" SET text = 'Ricordati, o Eterno, delle tue compassioni e delle tue benignità; perché sono ab eterno.' WHERE "verseID" = 100855 AND (text = 'Ricordati, o Eterno, delle tue compassioni e delle tue benignità;'); -- 23 25:6
UPDATE "LUZZI" SET text = 'Non ti ricordar de'' peccati della mia giovinezza, né delle mie trasgressioni; secondo la tua benignità ricordati di me per amor della tua bontà, o Eterno.' WHERE "verseID" = 100856 AND (text = 'Non ti ricordar de'' peccati della mia giovinezza,'); -- 23 25:7
UPDATE "LUZZI" SET text = 'L''Eterno è buono e diritto; perciò insegnerà la via ai peccatori.' WHERE "verseID" = 100857 AND (text = 'L''Eterno è buono e diritto;'); -- 23 25:8
UPDATE "LUZZI" SET text = 'Guiderà i mansueti nella giustizia, insegnerà ai mansueti la sua via.' WHERE "verseID" = 100858 AND (text = 'Guiderà i mansueti nella giustizia,'); -- 23 25:9
UPDATE "LUZZI" SET text = 'Tutti i sentieri dell''Eterno sono benignità e verità per quelli che osservano il suo patto e le sue testimonianze.' WHERE "verseID" = 100859 AND (text = 'Tutti i sentieri dell''Eterno sono benignità e verità'); -- 23 25:10
UPDATE "LUZZI" SET text = 'Per amor del tuo nome, o Eterno, perdona la mia iniquità, perch''ella è grande.' WHERE "verseID" = 100860 AND (text = 'Per amor del tuo nome, o Eterno,'); -- 23 25:11
UPDATE "LUZZI" SET text = 'Chi è l''uomo che tema l''Eterno? Ei gl''insegnerà la via che deve scegliere.' WHERE "verseID" = 100861 AND (text = 'Chi è l''uomo che tema l''Eterno?'); -- 23 25:12
UPDATE "LUZZI" SET text = 'L''anima sua dimorerà nel benessere, e la sua progenie erederà la terra.' WHERE "verseID" = 100862 AND (text = 'L''anima sua dimorerà nel benessere,'); -- 23 25:13
UPDATE "LUZZI" SET text = 'Il segreto dell''Eterno è per quelli che lo temono ed egli fa loro conoscere il suo patto.' WHERE "verseID" = 100863 AND (text = 'Il segreto dell''Eterno è per quelli che lo temono' OR text = 'Il segreto dell''Eterno è per quelli che lo temono, ed egli fa loro conoscere il suo patto.'); -- 23 25:14
UPDATE "LUZZI" SET text = 'I miei occhi son del continuo verso l''Eterno, perch''egli è quel che trarrà i miei piedi dalla rete.' WHERE "verseID" = 100864 AND (text = 'I miei occhi son del continuo verso l''Eterno,'); -- 23 25:15
UPDATE "LUZZI" SET text = 'Volgiti a me, ed abbi pietà di me, perch''io son solo ed afflitto.' WHERE "verseID" = 100865 AND (text = 'Volgiti a me, ed abbi pietà di me,'); -- 23 25:16
UPDATE "LUZZI" SET text = 'Le angosce del mio cuore si sono aumentate; traimi fuori delle mie distrette.' WHERE "verseID" = 100866 AND (text = 'Le angosce del mio cuore si sono aumentate;' OR text = 'Le angosce del mio cuore si sono aumentate; traimi fuori dalle mie distrette.'); -- 23 25:17
UPDATE "LUZZI" SET text = 'Vedi la mia afflizione ed il mio affanno, e perdonami tutti i miei peccati.' WHERE "verseID" = 100867 AND (text = 'Vedi la mia afflizione ed il mio affanno,'); -- 23 25:18
UPDATE "LUZZI" SET text = 'Vedi i miei nemici, perché son molti, e m''odiano d''un odio violento.' WHERE "verseID" = 100868 AND (text = 'Vedi i miei nemici, perché son molti,'); -- 23 25:19
UPDATE "LUZZI" SET text = 'Guarda l''anima mia e salvami; fa'' ch''io non sia confuso, perché mi confido in te.' WHERE "verseID" = 100869 AND (text = 'Guarda l''anima mia e salvami;'); -- 23 25:20
UPDATE "LUZZI" SET text = 'L''integrità e la dirittura mi proteggano, perché spero in te.' WHERE "verseID" = 100870 AND (text = 'L''integrità e la dirittura mi proteggano,'); -- 23 25:21
UPDATE "LUZZI" SET text = 'Di Davide. Fammi giustizia, o Eterno, perch''io cammino nella mia integrità, e confido nell''Eterno senza vacillare.' WHERE "verseID" = 100872 AND (text = 'Di Davide.'); -- 23 26:1
UPDATE "LUZZI" SET text = 'Scrutami o Eterno, e sperimentami; prova le mie reni ed il mio cuore.' WHERE "verseID" = 100873 AND (text = 'Scrutami o Eterno, e sperimentami;'); -- 23 26:2
UPDATE "LUZZI" SET text = 'Poiché ho davanti agli occhi la tua benignità e cammino nella tua verità.' WHERE "verseID" = 100874 AND (text = 'Poiché ho davanti agli occhi la tua benignità'); -- 23 26:3
UPDATE "LUZZI" SET text = 'Io non mi seggo con uomini bugiardi, e non vo con gente che simula.' WHERE "verseID" = 100875 AND (text = 'Io non mi seggo con uomini bugiardi,'); -- 23 26:4
UPDATE "LUZZI" SET text = 'Io odio l''assemblea de'' malvagi, e non mi seggo con gli empi.' WHERE "verseID" = 100876 AND (text = 'Io odio l''assemblea de'' malvagi,'); -- 23 26:5
UPDATE "LUZZI" SET text = 'Io lavo le mie mani nell''innocenza, e così fo il giro del tuo altare, o Eterno,' WHERE "verseID" = 100877 AND (text = 'Io lavo le mie mani nell''innocenza,'); -- 23 26:6
UPDATE "LUZZI" SET text = 'per far risonare voci di lode, e per raccontare tutte le tue maraviglie.' WHERE "verseID" = 100878 AND (text = 'per far risonare voci di lode,'); -- 23 26:7
UPDATE "LUZZI" SET text = 'O Eterno, io amo il soggiorno della tua casa e il luogo ove risiede la tua gloria.' WHERE "verseID" = 100879 AND (text = 'O Eterno, io amo il soggiorno della tua casa'); -- 23 26:8
UPDATE "LUZZI" SET text = 'Non metter l''anima mia in un fascio coi peccatori, né la mia vita con gli uomini di sangue,' WHERE "verseID" = 100880 AND (text = 'Non metter l''anima mia in un fascio coi peccatori,'); -- 23 26:9
UPDATE "LUZZI" SET text = 'nelle cui mani è scelleratezza, e la cui destra è colma di presenti.' WHERE "verseID" = 100881 AND (text = 'nelle cui mani è scelleratezza,'); -- 23 26:10
UPDATE "LUZZI" SET text = 'Quant''è a me, io cammino nella mia integrità; liberami, ed abbi pietà di me.' WHERE "verseID" = 100882 AND (text = 'Quant''è a me, io cammino nella mia integrità;'); -- 23 26:11
UPDATE "LUZZI" SET text = 'Il mio piè sta fermo in luogo piano. Io benedirò l''Eterno nelle assemblee.' WHERE "verseID" = 100883 AND (text = 'Il mio piè sta fermo in luogo piano.Io benedirò l''Eterno nelle assemblee.'); -- 23 26:12
UPDATE "LUZZI" SET text = 'Di Davide. L''Eterno è la mia luce e la mia salvezza; di chi temerò? L''Eterno è il baluardo della mia vita; di chi avrò paura?' WHERE "verseID" = 100884 AND (text = 'Di Davide.'); -- 23 27:1
UPDATE "LUZZI" SET text = 'Quando i malvagi che mi sono avversari e nemici, m''hanno assalito per divorar la mia carne, eglino stessi han vacillato e sono caduti.' WHERE "verseID" = 100885 AND (text = 'Quando i malvagi che mi sono avversari e nemici,'); -- 23 27:2
UPDATE "LUZZI" SET text = 'Quand''anche un esercito si accampasse contro a me, il mio cuore non avrebbe paura; quand''anche la guerra si levasse contro a me, anche allora sarei fiducioso.' WHERE "verseID" = 100886 AND (text = 'Quand''anche un esercito si accampasse contro a me,'); -- 23 27:3
UPDATE "LUZZI" SET text = 'Una cosa ho chiesto all''Eterno, e quella ricerco: ch''io dimori nella casa dell''Eterno tutti i giorni della mia vita, per mirare la bellezza dell''Eterno e meditare nel suo tempio.' WHERE "verseID" = 100887 AND (text = 'Una cosa ho chiesto all''Eterno, e quella ricerco:'); -- 23 27:4
UPDATE "LUZZI" SET text = 'Poich''egli mi nasconderà nella sua tenda nel giorno dell''avversità, m''occulterà nel luogo più segreto del suo padiglione, mi leverà in alto sopra una roccia.' WHERE "verseID" = 100888 AND (text = 'Poich''egli mi nasconderà nella sua tenda'); -- 23 27:5
UPDATE "LUZZI" SET text = 'Già fin d''ora il mio capo s''eleva sui miei nemici che m''attorniano. Io offrirò nel suo padiglione sacrifici con giubilo; io canterò e salmeggerò all''Eterno.' WHERE "verseID" = 100889 AND (text = 'Già fin d''ora il mio capo s''eleva'); -- 23 27:6
UPDATE "LUZZI" SET text = 'O Eterno, ascolta la mia voce, io t''invoco; abbi pietà di me, e rispondimi.' WHERE "verseID" = 100890 AND (text = 'O Eterno, ascolta la mia voce, io t''invoco;'); -- 23 27:7
UPDATE "LUZZI" SET text = 'Il mio cuore mi dice da parte tua: Cercate la mia faccia! Io cerco la tua faccia, o Eterno.' WHERE "verseID" = 100891 AND (text = 'Il mio cuore mi dice da parte tua: Cercate la mia faccia!'); -- 23 27:8
UPDATE "LUZZI" SET text = 'Non mi nascondere il tuo volto, non rigettar con ira il tuo servitore; tu sei stato il mio aiuto; non mi lasciare, non m''abbandonare, o Dio della mia salvezza!' WHERE "verseID" = 100892 AND (text = 'Non mi nascondere il tuo volto,'); -- 23 27:9
UPDATE "LUZZI" SET text = 'Quando mio padre e mia madre m''avessero abbandonato, pure l''Eterno mi accoglierà.' WHERE "verseID" = 100893 AND (text = 'Quando mio padre e mia madre m''avessero abbandonato,'); -- 23 27:10
UPDATE "LUZZI" SET text = 'O Eterno, insegnami la tua via, e guidami per un sentiero diritto, a cagione de'' miei nemici.' WHERE "verseID" = 100894 AND (text = 'O Eterno, insegnami la tua via,'); -- 23 27:11
UPDATE "LUZZI" SET text = 'Non darmi in balìa de'' miei nemici; perché son sorti contro di me falsi testimoni, gente che respira violenza.' WHERE "verseID" = 100895 AND (text = 'Non darmi in balìa de'' miei nemici;'); -- 23 27:12
UPDATE "LUZZI" SET text = 'Ah! se non avessi avuto fede di veder la bontà dell''Eterno sulla terra de'' viventi!...' WHERE "verseID" = 100896 AND (text = 'Ah! se non avessi avuto fede di veder la bontà dell''Eterno' OR text = 'Ah! se non avessi avuto fede di veder la bontà dell''Eterno sulla terra de'' viventi!…'); -- 23 27:13
UPDATE "LUZZI" SET text = 'Spera nell''Eterno! Sii forte, il tuo cuore si rinfranchi, sì, spera nell''Eterno!' WHERE "verseID" = 100897 AND (text = 'Spera nell''Eterno!Sii forte, il tuo cuore si rinfranchi,sì, spera nell''Eterno!'); -- 23 27:14
UPDATE "LUZZI" SET text = 'Di Davide. Io grido a te, o Eterno; Ròcca mia, non esser sordo alla mia voce, che talora, se t''allontani senza rispondermi, io non diventi simile a quelli che scendon nella fossa.' WHERE "verseID" = 100898 AND (text = 'Di Davide.'); -- 23 28:1
UPDATE "LUZZI" SET text = 'Ascolta la voce delle mie supplicazioni quando grido a te, quando alzo le mani verso il santuario della tua santità.' WHERE "verseID" = 100899 AND (text = 'Ascolta la voce delle mie supplicazioni quando grido a te,'); -- 23 28:2
UPDATE "LUZZI" SET text = 'Non trascinarmi via con gli empi e con gli operatori d''iniquità, i quali parlano di pace col prossimo ma hanno la malizia nel cuore.' WHERE "verseID" = 100900 AND (text = 'Non trascinarmi via con gli empi e con gli operatori d''iniquità,' OR text = 'Non trascinarmi via con gli empi e con gli operatori d''iniquità, i quali parlano di pace col prossimo, ma hanno la malizia nel cuore.'); -- 23 28:3
UPDATE "LUZZI" SET text = 'Rendi loro secondo le loro opere, secondo la malvagità dei loro atti; rendi loro secondo l''opera delle loro mani; da'' loro ciò che si meritano.' WHERE "verseID" = 100901 AND (text = 'Rendi loro secondo le loro opere,' OR text = 'Rendi loro secondo le loro opere, secondo la malvagità de'' loro atti; rendi loro secondo l''opera delle loro mani; da'' loro ciò che si meritano.'); -- 23 28:4
UPDATE "LUZZI" SET text = 'Perché non considerano gli atti dell''Eterno, né l''opera delle sue mani, ei li abbatterà e non li rileverà.' WHERE "verseID" = 100902 AND (text = 'Perché non considerano gli atti dell''Eterno,'); -- 23 28:5
UPDATE "LUZZI" SET text = 'Benedetto sia l''Eterno, poiché ha udito la voce delle mie supplicazioni.' WHERE "verseID" = 100903 AND (text = 'Benedetto sia l''Eterno,'); -- 23 28:6
UPDATE "LUZZI" SET text = 'L''Eterno è la mia forza ed il mio scudo; in lui s''è confidato il mio cuore, e sono stato soccorso; perciò il mio cuore festeggia, ed io lo celebrerò col mio cantico.' WHERE "verseID" = 100904 AND (text = 'L''Eterno è la mia forza ed il mio scudo;'); -- 23 28:7
UPDATE "LUZZI" SET text = 'L''Eterno è la forza del suo popolo; egli è un baluardo di salvezza per il suo unto.' WHERE "verseID" = 100905 AND (text = 'L''Eterno è la forza del suo popolo;' OR text = 'L''Eterno è la forza del suo popolo; egli è un baluardo di salvezza per il suo Unto.'); -- 23 28:8
UPDATE "LUZZI" SET text = 'Salva il tuo popolo e benedici la tua eredità; e pascili, e sostienili in perpetuo.' WHERE "verseID" = 100906 AND (text = 'Salva il tuo popolo e benedici la tua eredità;e pascili, e sostienili in perpetuo.'); -- 23 28:9
UPDATE "LUZZI" SET text = 'Salmo di Davide. Date all''Eterno, o figliuoli de'' potenti, date all''Eterno gloria e forza!' WHERE "verseID" = 100907 AND (text = 'Salmo di Davide.'); -- 23 29:1
UPDATE "LUZZI" SET text = 'Date all''Eterno la gloria dovuta al suo nome; adorate l''Eterno, con santa magnificenza.' WHERE "verseID" = 100908 AND (text = 'Date all''Eterno la gloria dovuta al suo nome;'); -- 23 29:2
UPDATE "LUZZI" SET text = 'La voce dell''Eterno è sulle acque; l''Iddio di gloria tuona; l''Eterno è sulle grandi acque.' WHERE "verseID" = 100909 AND (text = 'La voce dell''Eterno è sulle acque;'); -- 23 29:3
UPDATE "LUZZI" SET text = 'La voce dell''Eterno è potente, la voce dell''Eterno è piena di maestà.' WHERE "verseID" = 100910 AND (text = 'La voce dell''Eterno è potente,'); -- 23 29:4
UPDATE "LUZZI" SET text = 'La voce dell''Eterno rompe i cedri; l''Eterno spezza i cedri del Libano.' WHERE "verseID" = 100911 AND (text = 'La voce dell''Eterno rompe i cedri;'); -- 23 29:5
UPDATE "LUZZI" SET text = 'Fa saltellare i monti come vitelli, il Libano e il Sirio come giovani bufali.' WHERE "verseID" = 100912 AND (text = 'Fa saltellare i monti come vitelli,'); -- 23 29:6
UPDATE "LUZZI" SET text = 'La voce dell''Eterno fa tremare il deserto; l''Eterno fa tremare il deserto di Cades.' WHERE "verseID" = 100914 AND (text = 'La voce dell''Eterno fa tremare il deserto;'); -- 23 29:8
UPDATE "LUZZI" SET text = 'La voce dell''Eterno fa partorire le cerve e sfronda le selve. E nel suo tempio tutto esclama: Gloria!' WHERE "verseID" = 100915 AND (text = 'La voce dell''Eterno fa partorire le cerve'); -- 23 29:9
UPDATE "LUZZI" SET text = 'L''Eterno sedeva sovrano sul diluvio, anzi l''Eterno siede re in perpetuo.' WHERE "verseID" = 100916 AND (text = 'L''Eterno sedeva sovrano sul diluvio,'); -- 23 29:10
UPDATE "LUZZI" SET text = 'L''Eterno darà forza al suo popolo; l''Eterno benedirà il suo popolo dandogli pace.' WHERE "verseID" = 100917 AND (text = 'L''Eterno darà forza al suo popolo;l''Eterno benedirà il suo popolo dandogli pace.'); -- 23 29:11
UPDATE "LUZZI" SET text = 'Salmo. Cantico per la dedicazione della Casa. Di Davide. Io t''esalto, o Eterno, perché m''hai tratto in alto, e non hai permesso che i miei nemici si rallegrassero di me.' WHERE "verseID" = 100918 AND (text = 'Salmo. Cantico per la dedicazione della Casa. Di Davide.'); -- 23 30:1
UPDATE "LUZZI" SET text = 'O Eterno, Dio mio, io ho gridato a te, e tu m''hai sanato.' WHERE "verseID" = 100919 AND (text = 'O Eterno, Dio mio,'); -- 23 30:2
UPDATE "LUZZI" SET text = 'O Eterno, tu hai fatto risalir l''anima mia dal soggiorno de'' morti, tu m''hai ridato la vita perch''io non scendessi nella fossa.' WHERE "verseID" = 100920 AND (text = 'O Eterno, tu hai fatto risalir l''anima mia'); -- 23 30:3
UPDATE "LUZZI" SET text = 'Salmeggiate all''Eterno, voi suoi fedeli, e celebrate la memoria della sua santità.' WHERE "verseID" = 100921 AND (text = 'Salmeggiate all''Eterno, voi suoi fedeli,'); -- 23 30:4
UPDATE "LUZZI" SET text = 'Poiché l''ira sua è sol per un momento, ma la sua benevolenza è per tutta una vita. La sera alberga da noi il pianto; ma la mattina viene il giubilo.' WHERE "verseID" = 100922 AND (text = 'Poiché l''ira sua è sol per un momento,' OR text = 'Poiché l''ira sua è sol per un momento, ma la sua benevolenza e per tutta una vita. La sera alberga da noi il pianto; ma la mattina viene il giubilo.'); -- 23 30:5
UPDATE "LUZZI" SET text = 'Quanto a me, nella mia prosperità, dicevo: Non sarò mai smosso.' WHERE "verseID" = 100923 AND (text = 'Quanto a me, nella mia prosperità, dicevo:'); -- 23 30:6
UPDATE "LUZZI" SET text = 'O Eterno, per il tuo favore, avevi reso forte il mio monte; tu nascondesti la tua faccia, ed io fui smarrito.' WHERE "verseID" = 100924 AND (text = 'O Eterno, per il tuo favore, avevi reso forte il mio monte;'); -- 23 30:7
UPDATE "LUZZI" SET text = 'Io ho gridato a te, o Eterno; ho supplicato l''Eterno, dicendo:' WHERE "verseID" = 100925 AND (text = 'Io ho gridato a te, o Eterno;'); -- 23 30:8
UPDATE "LUZZI" SET text = 'Che profitto avrai dal mio sangue s''io scendo nella fossa? Forse che la polvere ti celebrerà? predicherà essa la tua verità?' WHERE "verseID" = 100926 AND (text = 'Che profitto avrai dal mio sangue s''io scendo nella fossa?'); -- 23 30:9
UPDATE "LUZZI" SET text = 'Ascolta, o Eterno, ed abbi pietà di me; o Eterno, sii tu il mio aiuto!' WHERE "verseID" = 100927 AND (text = 'Ascolta, o Eterno, ed abbi pietà di me;'); -- 23 30:10
UPDATE "LUZZI" SET text = 'Tu hai mutato il mio duolo, in danza; hai sciolto il mio cilicio e m''hai cinto d''allegrezza,' WHERE "verseID" = 100928 AND (text = 'Tu hai mutato il mio duolo, in danza;' OR text = 'Tu hai mutato il mio duolo, in danza; hai sciolto il mio cilicio a m''hai cinto d''allegrezza,'); -- 23 30:11
UPDATE "LUZZI" SET text = 'affinché l''anima mia salmeggia a te e non si taccia. O Eterno, Dio mio, io ti celebrerò in perpetuo.' WHERE "verseID" = 100929 AND (text = 'affinché l''anima mia salmeggia a te e non si taccia.O Eterno, Dio mio, io ti celebrerò in perpetuo.'); -- 23 30:12
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Salmo di Davide. O Eterno, io mi son confidato in te, fa'' ch''io non sia giammai confuso; liberami per la tua giustizia.' WHERE "verseID" = 100930 AND (text = 'Per il Capo de'' musici. Salmo di Davide.'); -- 23 31:1
UPDATE "LUZZI" SET text = 'Inclina a me il tuo orecchio; affrettati a liberarmi; siimi una forte ròcca, una fortezza ove tu mi salvi.' WHERE "verseID" = 100931 AND (text = 'Inclina a me il tuo orecchio; affrettati a liberarmi;'); -- 23 31:2
UPDATE "LUZZI" SET text = 'Poiché tu sei la mia ròcca e la mia fortezza; per amor del tuo nome guidami e conducimi.' WHERE "verseID" = 100932 AND (text = 'Poiché tu sei la mia ròcca e la mia fortezza;'); -- 23 31:3
UPDATE "LUZZI" SET text = 'Trammi dalla rete che m''han tesa di nascosto; poiché tu sei il mio baluardo.' WHERE "verseID" = 100933 AND (text = 'Trammi dalla rete che m''han tesa di nascosto;'); -- 23 31:4
UPDATE "LUZZI" SET text = 'Io rimetto il mio spirito nelle tue mani; tu m''hai riscattato, o Eterno, Dio di verità.' WHERE "verseID" = 100934 AND (text = 'Io rimetto il mio spirito nelle tue mani;'); -- 23 31:5
UPDATE "LUZZI" SET text = 'Io odio quelli che attendono alle vanità menzognere; e quanto a me confido nell''Eterno.' WHERE "verseID" = 100935 AND (text = 'Io odio quelli che attendono alle vanità menzognere;'); -- 23 31:6
UPDATE "LUZZI" SET text = 'Io festeggerò e mi rallegrerò per la tua benignità; poiché tu hai veduta la mia afflizione, hai preso conoscenza delle distrette dell''anima mia,' WHERE "verseID" = 100936 AND (text = 'Io festeggerò e mi rallegrerò per la tua benignità;'); -- 23 31:7
UPDATE "LUZZI" SET text = 'e non m''hai dato in man del nemico; tu m''hai messo i piedi al largo.' WHERE "verseID" = 100937 AND (text = 'e non m''hai dato in man del nemico;'); -- 23 31:8
UPDATE "LUZZI" SET text = 'Abbi pietà di me, o Eterno, perché sono in distretta; l''occhio mio, l''anima mia, le mie viscere son rosi dal cordoglio.' WHERE "verseID" = 100938 AND (text = 'Abbi pietà di me, o Eterno, perché sono in distretta;'); -- 23 31:9
UPDATE "LUZZI" SET text = 'Poiché la mia vita vien meno dal dolore e i miei anni per il sospirare; la forza m''è venuta a mancare per la mia afflizione, e le mie ossa si consumano.' WHERE "verseID" = 100939 AND (text = 'Poiché la mia vita vien meno dal dolore'); -- 23 31:10
UPDATE "LUZZI" SET text = 'A cagione di tutti i miei nemici son diventato un obbrobrio, e un grande obbrobrio ai miei vicini, e uno spavento ai miei conoscenti. Quelli che mi veggono fuori fuggon lungi da me.' WHERE "verseID" = 100940 AND (text = 'A cagione di tutti i miei nemici son diventato un obbrobrio,' OR text = 'A cagione di tutti i miei nemici son diventato un obbrobrio, un grande obbrobrio ai miei vicini, e uno spavento ai miei conoscenti. Quelli che mi veggono fuori fuggon lungi da me.'); -- 23 31:11
UPDATE "LUZZI" SET text = 'Io son del tutto dimenticato come un morto; son simile a un vaso rotto.' WHERE "verseID" = 100941 AND (text = 'Io son del tutto dimenticato come un morto;'); -- 23 31:12
UPDATE "LUZZI" SET text = 'Perché odo il diffamare di molti, spavento m''è d''ogn''intorno, mentr''essi si consigliano a mio danno, e macchinano di tormi la vita.' WHERE "verseID" = 100942 AND (text = 'Perché odo il diffamare di molti,'); -- 23 31:13
UPDATE "LUZZI" SET text = 'Ma io mi confido in te, o Eterno; io ho detto: Tu sei l''Iddio mio.' WHERE "verseID" = 100943 AND (text = 'Ma io mi confido in te, o Eterno;'); -- 23 31:14
UPDATE "LUZZI" SET text = 'I miei giorni sono in tua mano; liberami dalla mano de'' miei nemici e dai miei persecutori.' WHERE "verseID" = 100944 AND (text = 'I miei giorni sono in tua mano;'); -- 23 31:15
UPDATE "LUZZI" SET text = 'Fa'' risplendere il tuo volto sul tuo servitore; salvami per la tua benignità.' WHERE "verseID" = 100945 AND (text = 'Fa'' risplendere il tuo volto sul tuo servitore;'); -- 23 31:16
UPDATE "LUZZI" SET text = 'O Eterno, fa'' ch''io non sia confuso, perché io t''invoco; siano confusi gli empi, sian ridotti al silenzio nel soggiorno de'' morti.' WHERE "verseID" = 100946 AND (text = 'O Eterno, fa'' ch''io non sia confuso, perché io t''invoco;'); -- 23 31:17
UPDATE "LUZZI" SET text = 'Ammutoliscano le labbra bugiarde che parlano arrogantemente contro al giusto con alterigia e con disprezzo.' WHERE "verseID" = 100947 AND (text = 'Ammutoliscano le labbra bugiarde'); -- 23 31:18
UPDATE "LUZZI" SET text = 'Quant''è grande la bontà che tu riserbi a quelli che ti temono, e di cui dai prova in presenza de'' figliuoli degli uomini, verso quelli che si confidano in te!' WHERE "verseID" = 100948 AND (text = 'Quant''è grande la bontà' OR text = 'Quant''è grande la bontà che tu riserbi a quelli che ti temono, e di cui dài prova in presenza de'' figliuoli degli uomini, verso quelli che si confidano in te!'); -- 23 31:19
UPDATE "LUZZI" SET text = 'Tu li nascondi all''ombra della tua presenza, lungi dalle macchinazioni degli uomini; tu li occulti in una tenda, lungi dagli attacchi delle lingue.' WHERE "verseID" = 100949 AND (text = 'Tu li nascondi all''ombra della tua presenza,'); -- 23 31:20
UPDATE "LUZZI" SET text = 'Sia benedetto l''Eterno! poich''egli ha reso mirabile la sua benignità per me, ponendomi come in una città fortificata.' WHERE "verseID" = 100950 AND (text = 'Sia benedetto l''Eterno!'); -- 23 31:21
UPDATE "LUZZI" SET text = 'Quanto a me, nel mio smarrimento, dicevo: Io son reietto dalla tua presenza; ma tu hai udita la voce delle mie supplicazioni, quand''ho gridato a te.' WHERE "verseID" = 100951 AND (text = 'Quanto a me, nel mio smarrimento, dicevo:'); -- 23 31:22
UPDATE "LUZZI" SET text = 'Amate l''Eterno, voi tutti i suoi santi! L''Eterno preserva i fedeli, e rende ampia retribuzione a chi procede alteramente.' WHERE "verseID" = 100952 AND (text = 'Amate l''Eterno, voi tutti i suoi santi!'); -- 23 31:23
UPDATE "LUZZI" SET text = 'Siate saldi, e il vostro cuore si fortifichi, o voi tutti che sperate nell''Eterno!' WHERE "verseID" = 100953 AND (text = 'Siate saldi, e il vostro cuore si fortifichi,o voi tutti che sperate nell''Eterno!'); -- 23 31:24
UPDATE "LUZZI" SET text = 'Di Davide. Cantico. Beato colui la cui trasgressione è rimessa e il cui peccato è coperto!' WHERE "verseID" = 100954 AND (text = 'Di Davide. Cantico.' OR text = 'Di Davide. Cantico. Beato colui la cui trasgressione e rimessa e il cui peccato è coperto!'); -- 23 32:1
UPDATE "LUZZI" SET text = 'Beato l''uomo a cui l''Eterno non imputa l''iniquità e nel cui spirito non è frode alcuna!' WHERE "verseID" = 100955 AND (text = 'Beato l''uomo a cui l''Eterno non imputa l''iniquità'); -- 23 32:2
UPDATE "LUZZI" SET text = 'Mentr''io mi son taciuto le mie ossa si son consumate pel ruggire ch''io facevo tutto il giorno.' WHERE "verseID" = 100956 AND (text = 'Mentr''io mi son taciuto le mie ossa si son consumate'); -- 23 32:3
UPDATE "LUZZI" SET text = 'Poiché giorno e notte la tua mano s''aggravava su me, il mio succo vitale s''era mutato come per arsura d''estate. Sela.' WHERE "verseID" = 100957 AND (text = 'Poiché giorno e notte la tua mano s''aggravava su me,'); -- 23 32:4
UPDATE "LUZZI" SET text = 'Io t''ho dichiarato il mio peccato, non ho coperta la mia iniquità. Io ho detto: Confesserò le mie trasgressioni all''Eterno; e tu hai perdonato l''iniquità del mio peccato. Sela.' WHERE "verseID" = 100958 AND (text = 'Io t''ho dichiarato il mio peccato,'); -- 23 32:5
UPDATE "LUZZI" SET text = 'Perciò ogni uomo pio t''invochi nel tempo che puoi esser trovato; e quando straripino le grandi acque, esse, per certo, non giungeranno fino a lui.' WHERE "verseID" = 100959 AND (text = 'Perciò ogni uomo pio t''invochi nel tempo che puoi esser trovato;'); -- 23 32:6
UPDATE "LUZZI" SET text = 'Tu sei il mio ricetto, tu mi guarderai da distretta, tu mi circonderai di canti di liberazione. Sela.' WHERE "verseID" = 100960 AND (text = 'Tu sei il mio ricetto, tu mi guarderai da distretta,'); -- 23 32:7
UPDATE "LUZZI" SET text = 'Io t''ammaestrerò e t''insegnerò la via per la quale devi camminare; io ti consiglierò e avrò gli occhi su te.' WHERE "verseID" = 100961 AND (text = 'Io t''ammaestrerò e t''insegnerò la via'); -- 23 32:8
UPDATE "LUZZI" SET text = 'Non siate come il cavallo e come il mulo che non hanno intelletto, la cui bocca bisogna frenare con morso e con briglia, altrimenti non ti s''accostano!' WHERE "verseID" = 100962 AND (text = 'Non siate come il cavallo'); -- 23 32:9
UPDATE "LUZZI" SET text = 'Molti dolori aspettano l''empio; ma chi confida nell''Eterno, la sua grazia lo circonderà.' WHERE "verseID" = 100963 AND (text = 'Molti dolori aspettano l''empio;'); -- 23 32:10
UPDATE "LUZZI" SET text = 'Rallegratevi nell''Eterno, e fate festa, o giusti! Giubilate voi tutti che siete diritti di cuore!' WHERE "verseID" = 100964 AND (text = 'Rallegratevi nell''Eterno, e fate festa, o giusti!Giubilate voi tutti che siete diritti di cuore!'); -- 23 32:11
UPDATE "LUZZI" SET text = 'Giubilate, o giusti, nell''Eterno; la lode s''addice agli uomini retti.' WHERE "verseID" = 100965 AND (text = 'Giubilate, o giusti, nell''Eterno;'); -- 23 33:1
UPDATE "LUZZI" SET text = 'Celebrate l''Eterno con la cetra; salmeggiate a lui col saltèro a dieci corde.' WHERE "verseID" = 100966 AND (text = 'Celebrate l''Eterno con la cetra;'); -- 23 33:2
UPDATE "LUZZI" SET text = 'Cantategli un cantico nuovo, sonate maestrevolmente con giubilo.' WHERE "verseID" = 100967 AND (text = 'Cantategli un cantico nuovo,'); -- 23 33:3
UPDATE "LUZZI" SET text = 'Poiché la parola dell''Eterno è diritta e tutta l''opera sua è fatta con fedeltà.' WHERE "verseID" = 100968 AND (text = 'Poiché la parola dell''Eterno è diritta'); -- 23 33:4
UPDATE "LUZZI" SET text = 'Egli ama la giustizia e l''equità; la terra è piena della benignità dell''Eterno.' WHERE "verseID" = 100969 AND (text = 'Egli ama la giustizia e l''equità;'); -- 23 33:5
UPDATE "LUZZI" SET text = 'I cieli furon fatti dalla parola dell''Eterno, e tutto il loro esercito dal soffio della sua bocca.' WHERE "verseID" = 100970 AND (text = 'I cieli furon fatti dalla parola dell''Eterno,'); -- 23 33:6
UPDATE "LUZZI" SET text = 'Egli adunò le acque del mare come in un mucchio; egli ammassò gli abissi in serbatoi.' WHERE "verseID" = 100971 AND (text = 'Egli adunò le acque del mare come in un mucchio;'); -- 23 33:7
UPDATE "LUZZI" SET text = 'Tutta la terra tema l''Eterno; lo paventino tutti gli abitanti del mondo.' WHERE "verseID" = 100972 AND (text = 'Tutta la terra tema l''Eterno;'); -- 23 33:8
UPDATE "LUZZI" SET text = 'Poich''egli parlò, e la cosa fu; egli comandò e la cosa sorse.' WHERE "verseID" = 100973 AND (text = 'Poich''egli parlò, e la cosa fu;'); -- 23 33:9
UPDATE "LUZZI" SET text = 'L''Eterno dissipa il consiglio delle nazioni, egli annulla i disegni dei popoli.' WHERE "verseID" = 100974 AND (text = 'L''Eterno dissipa il consiglio delle nazioni,'); -- 23 33:10
UPDATE "LUZZI" SET text = 'Il consiglio dell''Eterno sussiste in perpetuo, i disegni del suo cuore durano d''età in età.' WHERE "verseID" = 100975 AND (text = 'Il consiglio dell''Eterno sussiste in perpetuo,'); -- 23 33:11
UPDATE "LUZZI" SET text = 'Beata la nazione il cui Dio è l''Eterno; beato il popolo ch''egli ha scelto per sua eredità.' WHERE "verseID" = 100976 AND (text = 'Beata la nazione il cui Dio è l''Eterno;'); -- 23 33:12
UPDATE "LUZZI" SET text = 'L''Eterno guarda dal cielo; egli vede tutti i figliuoli degli uomini:' WHERE "verseID" = 100977 AND (text = 'L''Eterno guarda dal cielo;'); -- 23 33:13
UPDATE "LUZZI" SET text = 'dal luogo ove dimora, osserva tutti gli abitanti della terra;' WHERE "verseID" = 100978 AND (text = 'dal luogo ove dimora, osserva'); -- 23 33:14
UPDATE "LUZZI" SET text = 'egli, che ha formato il cuore di loro tutti, che considera tutte le opere loro.' WHERE "verseID" = 100979 AND (text = 'egli, che ha formato il cuore di loro tutti,'); -- 23 33:15
UPDATE "LUZZI" SET text = 'Il re non è salvato per grandezza d''esercito; il prode non scampa per la sua gran forza.' WHERE "verseID" = 100980 AND (text = 'Il re non è salvato per grandezza d''esercito;'); -- 23 33:16
UPDATE "LUZZI" SET text = 'Il cavallo è cosa fallace per salvare; esso non può liberare alcuno col suo grande vigore.' WHERE "verseID" = 100981 AND (text = 'Il cavallo è cosa fallace per salvare;'); -- 23 33:17
UPDATE "LUZZI" SET text = 'Ecco, l''occhio dell''Eterno è su quelli che lo temono, su quelli che sperano nella sua benignità,' WHERE "verseID" = 100982 AND (text = 'Ecco, l''occhio dell''Eterno è su quelli che lo temono,'); -- 23 33:18
UPDATE "LUZZI" SET text = 'per liberare l''anima loro dalla morte e per conservarli in vita in tempo di fame.' WHERE "verseID" = 100983 AND (text = 'per liberare l''anima loro dalla morte'); -- 23 33:19
UPDATE "LUZZI" SET text = 'L''anima nostra aspetta l''Eterno; egli è il nostro aiuto e il nostro scudo.' WHERE "verseID" = 100984 AND (text = 'L''anima nostra aspetta l''Eterno;'); -- 23 33:20
UPDATE "LUZZI" SET text = 'In lui, certo, si rallegrerà il cuor nostro, perché abbiam confidato nel nome della sua santità.' WHERE "verseID" = 100985 AND (text = 'In lui, certo, si rallegrerà il cuor nostro,'); -- 23 33:21
UPDATE "LUZZI" SET text = 'La tua benignità, o Eterno, sia sopra noi, poiché noi abbiamo sperato in te.' WHERE "verseID" = 100986 AND (text = 'La tua benignità, o Eterno, sia sopra noi,poiché noi abbiamo sperato in te.'); -- 23 33:22
UPDATE "LUZZI" SET text = 'Di Davide, quando si finse insensato davanti ad Abimelec e, cacciato da lui, se ne andò. Io benedirò l''Eterno in ogni tempo; la sua lode sarà del continuo nella mia bocca.' WHERE "verseID" = 100987 AND (text = 'Di Davide, quando si finse insensato davanti ad Abimelec e, cacciato da lui, se ne andò.'); -- 23 34:1
UPDATE "LUZZI" SET text = 'L''anima mia si glorierà nell''Eterno; gli umili l''udranno e si rallegreranno.' WHERE "verseID" = 100988 AND (text = 'L''anima mia si glorierà nell''Eterno;'); -- 23 34:2
UPDATE "LUZZI" SET text = 'Magnificate meco l''Eterno, ed esaltiamo il suo nome tutt''insieme.' WHERE "verseID" = 100989 AND (text = 'Magnificate meco l''Eterno,' OR text = 'Magnificate meco l''Eterno, ed esaltiamo il suo nome tutti insieme.'); -- 23 34:3
UPDATE "LUZZI" SET text = 'Io ho cercato l''Eterno, ed egli m''ha risposto e m''ha liberato da tutti i miei spaventi.' WHERE "verseID" = 100990 AND (text = 'Io ho cercato l''Eterno, ed egli m''ha risposto'); -- 23 34:4
UPDATE "LUZZI" SET text = 'Quelli che riguardano a lui sono illuminati, e le loro facce non sono svergognate.' WHERE "verseID" = 100991 AND (text = 'Quelli che riguardano a lui sono illuminati,'); -- 23 34:5
UPDATE "LUZZI" SET text = 'Quest''afflitto ha gridato, e l''Eterno l''ha esaudito e l''ha salvato da tutte le sue distrette.' WHERE "verseID" = 100992 AND (text = 'Quest''afflitto ha gridato, e l''Eterno l''ha esaudito'); -- 23 34:6
UPDATE "LUZZI" SET text = 'L''Angelo dell''Eterno s''accampa intorno a quelli che lo temono, e li libera.' WHERE "verseID" = 100993 AND (text = 'L''Angelo dell''Eterno'); -- 23 34:7
UPDATE "LUZZI" SET text = 'Gustate e vedete quanto l''Eterno è buono! Beato l''uomo che confida in lui.' WHERE "verseID" = 100994 AND (text = 'Gustate e vedete quanto l''Eterno è buono!'); -- 23 34:8
UPDATE "LUZZI" SET text = 'Temete l''Eterno, voi suoi santi, poiché nulla manca a quelli che lo temono.' WHERE "verseID" = 100995 AND (text = 'Temete l''Eterno, voi suoi santi,'); -- 23 34:9
UPDATE "LUZZI" SET text = 'I leoncelli soffron penuria e fame, ma quelli che cercano l''Eterno non mancano d''alcun bene.' WHERE "verseID" = 100996 AND (text = 'I leoncelli soffron penuria e fame,'); -- 23 34:10
UPDATE "LUZZI" SET text = 'Venite, figliuoli, ascoltatemi; io v''insegnerò il timor dell''Eterno.' WHERE "verseID" = 100997 AND (text = 'Venite, figliuoli, ascoltatemi;'); -- 23 34:11
UPDATE "LUZZI" SET text = 'Qual è l''uomo che prenda piacere nella vita, ed ami lunghezza di giorni per goder del bene?' WHERE "verseID" = 100998 AND (text = 'Qual è l''uomo che prenda piacere nella vita,'); -- 23 34:12
UPDATE "LUZZI" SET text = 'Guarda la tua lingua dal male e le tue labbra dal parlar con frode.' WHERE "verseID" = 100999 AND (text = 'Guarda la tua lingua dal male' OR text = 'Guarda la tua lingua dal male a le tue labbra dal parlar con frode.'); -- 23 34:13
UPDATE "LUZZI" SET text = 'Dipartiti dal male e fa'' il bene; cerca la pace, e procacciala.' WHERE "verseID" = 101000 AND (text = 'Dipartiti dal male e fa'' il bene;'); -- 23 34:14
UPDATE "LUZZI" SET text = 'Gli occhi dell''Eterno sono sui giusti e le sue orecchie sono attente al loro grido.' WHERE "verseID" = 101001 AND (text = 'Gli occhi dell''Eterno sono sui giusti'); -- 23 34:15
UPDATE "LUZZI" SET text = 'La faccia dell''Eterno è contro quelli che fanno il male per sterminare di sulla terra la loro memoria.' WHERE "verseID" = 101002 AND (text = 'La faccia dell''Eterno è contro quelli che fanno il male'); -- 23 34:16
UPDATE "LUZZI" SET text = 'I giusti gridano e l''Eterno li esaudisce e li libera da tutte le loro distrette.' WHERE "verseID" = 101003 AND (text = 'I giusti gridano e l''Eterno li esaudisce'); -- 23 34:17
UPDATE "LUZZI" SET text = 'L''Eterno è vicino a quelli che hanno il cuor rotto, e salva quelli che hanno lo spirito contrito.' WHERE "verseID" = 101004 AND (text = 'L''Eterno è vicino a quelli che hanno il cuor rotto,'); -- 23 34:18
UPDATE "LUZZI" SET text = 'Molte sono le afflizioni del giusto; ma l''Eterno lo libera da tutte.' WHERE "verseID" = 101005 AND (text = 'Molte sono le afflizioni del giusto;'); -- 23 34:19
UPDATE "LUZZI" SET text = 'Egli preserva tutte le ossa di lui, non uno ne è rotto.' WHERE "verseID" = 101006 AND (text = 'Egli preserva tutte le ossa di lui,'); -- 23 34:20
UPDATE "LUZZI" SET text = 'La malvagità farà perire il malvagio, e quelli che odiano il giusto saranno condannati.' WHERE "verseID" = 101007 AND (text = 'La malvagità farà perire il malvagio,'); -- 23 34:21
UPDATE "LUZZI" SET text = 'L''Eterno riscatta l''anima de'' suoi servitori, e nessun di quelli che confidano in lui sarà condannato.' WHERE "verseID" = 101008 AND (text = 'L''Eterno riscatta l''anima de'' suoi servitori,e nessun di quelli che confidano in lui sarà condannato.'); -- 23 34:22
UPDATE "LUZZI" SET text = 'Di Davide. O Eterno, contendi con quelli che contendono meco, combatti con quelli che combattono meco.' WHERE "verseID" = 101009 AND (text = 'Di Davide.'); -- 23 35:1
UPDATE "LUZZI" SET text = 'Prendi lo scudo e la targa e lèvati in mio aiuto.' WHERE "verseID" = 101010 AND (text = 'Prendi lo scudo e la targa'); -- 23 35:2
UPDATE "LUZZI" SET text = 'Tira fuori la lancia e chiudi il passo ai miei persecutori; di'' all''anima mia: Io son la tua salvezza.' WHERE "verseID" = 101011 AND (text = 'Tira fuori la lancia e chiudi il passo ai miei persecutori;'); -- 23 35:3
UPDATE "LUZZI" SET text = 'Sian confusi e svergognati quelli che cercano l''anima mia; voltin le spalle e arrossiscano quei che macchinano la mia rovina.' WHERE "verseID" = 101012 AND (text = 'Sian confusi e svergognati quelli che cercano l''anima mia;'); -- 23 35:4
UPDATE "LUZZI" SET text = 'Sian come pula al vento e l''angelo dell''Eterno li scacci.' WHERE "verseID" = 101013 AND (text = 'Sian come pula al vento'); -- 23 35:5
UPDATE "LUZZI" SET text = 'Sia la via loro tenebrosa e sdrucciolevole, e l''insegua l''angelo dell''Eterno.' WHERE "verseID" = 101014 AND (text = 'Sia la via loro tenebrosa e sdrucciolevole,'); -- 23 35:6
UPDATE "LUZZI" SET text = 'Poiché, senza cagione, m''hanno teso di nascosto la loro rete, senza cagione hanno scavato una fossa per togliermi la vita.' WHERE "verseID" = 101015 AND (text = 'Poiché, senza cagione, m''hanno teso di nascosto la loro rete,'); -- 23 35:7
UPDATE "LUZZI" SET text = 'Li colga una ruina improvvisa e sian presi nella rete ch''essi hanno nascosta; scendano nella rovina apparecchiata per me.' WHERE "verseID" = 101016 AND (text = 'Li colga una ruina improvvisa' OR text = 'Li colga una ruina improvvisa e sian presi nella rete ch''essi stessi hanno nascosta; scendano nella rovina apparecchiata per me.'); -- 23 35:8
UPDATE "LUZZI" SET text = 'Allora l''anima mia festeggerà nell''Eterno, e si rallegrerà nella sua salvezza.' WHERE "verseID" = 101017 AND (text = 'Allora l''anima mia festeggerà nell''Eterno,'); -- 23 35:9
UPDATE "LUZZI" SET text = 'Tutte le mie ossa diranno: O Eterno, chi è pari a te che liberi il misero da chi è più forte di lui, il misero e il bisognoso da chi lo spoglia?' WHERE "verseID" = 101018 AND (text = 'Tutte le mie ossa diranno: O Eterno, chi è pari a te'); -- 23 35:10
UPDATE "LUZZI" SET text = 'Iniqui testimoni si levano; mi domandano cose delle quali non so nulla.' WHERE "verseID" = 101019 AND (text = 'Iniqui testimoni si levano;'); -- 23 35:11
UPDATE "LUZZI" SET text = 'Mi rendono male per bene; derelitta è l''anima mia.' WHERE "verseID" = 101020 AND (text = 'Mi rendono male per bene;'); -- 23 35:12
UPDATE "LUZZI" SET text = 'Eppure io, quand''eran malati, vestivo il cilicio, affliggevo l''anima mia col digiuno, e pregavo col capo curvo sul seno...' WHERE "verseID" = 101021 AND (text = 'Eppure io, quand''eran malati, vestivo il cilicio,' OR text = 'Eppure io, quand''eran malati, vestivo il cilicio, affliggevo l''anima mia col digiuno, e pregavo col capo curvo sul seno…'); -- 23 35:13
UPDATE "LUZZI" SET text = 'Camminavo triste come per la perdita d''un amico, d''un fratello, andavo chino, abbrunato, come uno che pianga sua madre.' WHERE "verseID" = 101022 AND (text = 'Camminavo triste come per la perdita d''un amico, d''un fratello,'); -- 23 35:14
UPDATE "LUZZI" SET text = 'Ma, quand''io vacillo, essi si rallegrano, s''adunano assieme; s''aduna contro di me gente abietta che io non conosco; mi lacerano senza posa.' WHERE "verseID" = 101023 AND (text = 'Ma, quand''io vacillo, essi si rallegrano, s''adunano assieme;'); -- 23 35:15
UPDATE "LUZZI" SET text = 'Come profani buffoni da mensa, digrignano i denti contro di me.' WHERE "verseID" = 101024 AND (text = 'Come profani buffoni da mensa,'); -- 23 35:16
UPDATE "LUZZI" SET text = 'O Signore, fino a quando vedrai tu questo? Ritrai l''anima mia dalle loro ruine, l''unica mia, di fra i leoncelli.' WHERE "verseID" = 101025 AND (text = 'O Signore, fino a quando vedrai tu questo?'); -- 23 35:17
UPDATE "LUZZI" SET text = 'Io ti celebrerò nella grande assemblea, ti loderò in mezzo a gran popolo.' WHERE "verseID" = 101026 AND (text = 'Io ti celebrerò nella grande assemblea,'); -- 23 35:18
UPDATE "LUZZI" SET text = 'Non si rallegrino di me quelli che a torto mi sono nemici, né ammicchino con l''occhio quelli che m''odian senza cagione.' WHERE "verseID" = 101027 AND (text = 'Non si rallegrino di me quelli che a torto mi sono nemici,'); -- 23 35:19
UPDATE "LUZZI" SET text = 'Poiché non parlan di pace, anzi macchinan frodi contro la gente pacifica del paese.' WHERE "verseID" = 101028 AND (text = 'Poiché non parlan di pace,'); -- 23 35:20
UPDATE "LUZZI" SET text = 'Apron larga la bocca contro me e dicono: Ah, ah! l''occhio nostro l''ha visto.' WHERE "verseID" = 101029 AND (text = 'Apron larga la bocca contro me'); -- 23 35:21
UPDATE "LUZZI" SET text = 'Anche tu hai visto, o Eterno; non tacere! O Signore, non allontanarti da me.' WHERE "verseID" = 101030 AND (text = 'Anche tu hai visto, o Eterno; non tacere!'); -- 23 35:22
UPDATE "LUZZI" SET text = 'Risvegliati, destati, per farmi ragione, o mio Dio, mio Signore, per difender la mia causa.' WHERE "verseID" = 101031 AND (text = 'Risvegliati, destati, per farmi ragione,'); -- 23 35:23
UPDATE "LUZZI" SET text = 'Giudicami secondo la tua giustizia, o Eterno, Iddio mio, e fa'' ch''essi non si rallegrino su me;' WHERE "verseID" = 101032 AND (text = 'Giudicami secondo la tua giustizia, o Eterno, Iddio mio,'); -- 23 35:24
UPDATE "LUZZI" SET text = 'che non dicano in cuor loro: Ah, ecco il nostro desiderio! che non dican: L''abbiamo inghiottito.' WHERE "verseID" = 101033 AND (text = 'che non dicano in cuor loro: Ah, ecco il nostro desiderio!' OR text = 'che non dicano in cuor loro: Ah, ecco il nostro desiderio! che non dicano: L''abbiamo inghiottito.'); -- 23 35:25
UPDATE "LUZZI" SET text = 'Siano tutti insieme svergognati e confusi quelli che si rallegrano del mio male; sian rivestiti d''onta e di vituperio quelli che si levano superbi contro di me.' WHERE "verseID" = 101034 AND (text = 'Siano tutti insieme svergognati e confusi'); -- 23 35:26
UPDATE "LUZZI" SET text = 'Cantino e si rallegrino quelli che si compiacciono della mia giustizia, e dican del continuo: Magnificato sia l''Eterno che vuole la pace del suo servitore!' WHERE "verseID" = 101035 AND (text = 'Cantino e si rallegrino'); -- 23 35:27
UPDATE "LUZZI" SET text = 'E la mia lingua parlerà della tua giustizia, e dirà del continuo la tua lode.' WHERE "verseID" = 101036 AND (text = 'E la mia lingua parlerà della tua giustizia,e dirà del continuo la tua lode.'); -- 23 35:28
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Di Davide, servo dell''Eterno. L''iniquità parla all''empio nell''intimo del suo cuore; non c''è timor di Dio davanti ai suoi occhi.' WHERE "verseID" = 101037 AND (text = 'Per il Capo de'' musici. Di Davide, servo dell''Eterno.'); -- 23 36:1
UPDATE "LUZZI" SET text = 'Essa lo lusinga che la sua empietà non sarà scoperta né presa in odio.' WHERE "verseID" = 101038 AND (text = 'Essa lo lusinga'); -- 23 36:2
UPDATE "LUZZI" SET text = 'Le parole della sua bocca sono iniquità e frode; egli ha cessato d''esser savio e di fare il bene.' WHERE "verseID" = 101039 AND (text = 'Le parole della sua bocca sono iniquità e frode;'); -- 23 36:3
UPDATE "LUZZI" SET text = 'Egli medita iniquità sopra il suo letto; si tiene nella via che non è buona; non aborre il male.' WHERE "verseID" = 101040 AND (text = 'Egli medita iniquità sopra il suo letto;'); -- 23 36:4
UPDATE "LUZZI" SET text = 'O Eterno, la tua benignità va fino al cielo, e la tua fedeltà fino alle nuvole.' WHERE "verseID" = 101041 AND (text = 'O Eterno, la tua benignità va fino al cielo,'); -- 23 36:5
UPDATE "LUZZI" SET text = 'La tua giustizia è come le montagne di Dio, i tuoi giudizi sono un grande abisso. O Eterno, tu conservi uomini e bestie.' WHERE "verseID" = 101042 AND (text = 'La tua giustizia è come le montagne di Dio,'); -- 23 36:6
UPDATE "LUZZI" SET text = 'O Dio, com''è preziosa la tua benignità! Perciò i figliuoli degli uomini si rifugiano all''ombra delle tue ali,' WHERE "verseID" = 101043 AND (text = 'O Dio, com''è preziosa la tua benignità!'); -- 23 36:7
UPDATE "LUZZI" SET text = 'son saziati dell''abbondanza della tua casa, e tu li abbeveri al torrente delle tue delizie.' WHERE "verseID" = 101044 AND (text = 'son saziati dell''abbondanza della tua casa,'); -- 23 36:8
UPDATE "LUZZI" SET text = 'Poiché in te è la fonte della vita, e per la tua luce noi vediamo la luce.' WHERE "verseID" = 101045 AND (text = 'Poiché in te è la fonte della vita,'); -- 23 36:9
UPDATE "LUZZI" SET text = 'Continua la tua benignità verso di quelli che ti conoscono, e la tua giustizia verso i retti di cuore.' WHERE "verseID" = 101046 AND (text = 'Continua la tua benignità verso di quelli che ti conoscono,'); -- 23 36:10
UPDATE "LUZZI" SET text = 'Non mi venga sopra il piè del superbo, e la mano degli empi non mi metta in fuga.' WHERE "verseID" = 101047 AND (text = 'Non mi venga sopra il piè del superbo,'); -- 23 36:11
UPDATE "LUZZI" SET text = 'Ecco là, gli operatori d''iniquità sono caduti; sono atterrati, e non possono risorgere.' WHERE "verseID" = 101048 AND (text = 'Ecco là, gli operatori d''iniquità sono caduti;sono atterrati, e non possono risorgere.'); -- 23 36:12
UPDATE "LUZZI" SET text = 'Di Davide. Non ti crucciare a cagion de'' malvagi; non portare invidia a quelli che operano perversamente;' WHERE "verseID" = 101049 AND (text = 'Di Davide.'); -- 23 37:1
UPDATE "LUZZI" SET text = 'perché saran di subito falciati come il fieno, e appassiranno come l''erba verde.' WHERE "verseID" = 101050 AND (text = 'perché saran di subito falciati come il fieno,'); -- 23 37:2
UPDATE "LUZZI" SET text = 'Confidati nell''Eterno e fa'' il bene; abita il paese e coltiva la fedeltà.' WHERE "verseID" = 101051 AND (text = 'Confidati nell''Eterno e fa'' il bene;'); -- 23 37:3
UPDATE "LUZZI" SET text = 'Prendi il tuo diletto nell''Eterno, ed egli ti darà quel che il tuo cuore domanda.' WHERE "verseID" = 101052 AND (text = 'Prendi il tuo diletto nell''Eterno,'); -- 23 37:4
UPDATE "LUZZI" SET text = 'Rimetti la tua sorte nell''Eterno; confidati in lui, ed egli opererà.' WHERE "verseID" = 101053 AND (text = 'Rimetti la tua sorte nell''Eterno;' OR text = 'Rimetti la tua sorte nell''Eterno; confidati in lui, ed egli opererà'); -- 23 37:5
UPDATE "LUZZI" SET text = 'Egli farà risplendere la tua giustizia come la luce, il tuo diritto come il mezzodì.' WHERE "verseID" = 101054 AND (text = 'Egli farà risplendere la tua giustizia come la luce,' OR text = 'Egli farà risplendere la tua giustizia come la luce, e il tuo diritto come il mezzodì.'); -- 23 37:6
UPDATE "LUZZI" SET text = 'Sta'' in silenzio dinanzi all''Eterno, e aspettalo; non ti crucciare per colui che prospera nella sua via, per l''uomo che riesce ne'' suoi malvagi disegni.' WHERE "verseID" = 101055 AND (text = 'Sta'' in silenzio dinanzi all''Eterno, e aspettalo;'); -- 23 37:7
UPDATE "LUZZI" SET text = 'Cessa dall''ira e lascia lo sdegno; non crucciarti ciò non conduce che al mal fare.' WHERE "verseID" = 101056 AND (text = 'Cessa dall''ira e lascia lo sdegno;' OR text = 'Cessa dall''ira e lascia lo sdegno; non crucciarti; ciò non conduce che al mal fare.'); -- 23 37:8
UPDATE "LUZZI" SET text = 'Poiché i malvagi saranno sterminati; ma quelli che sperano nell''Eterno possederanno la terra.' WHERE "verseID" = 101057 AND (text = 'Poiché i malvagi saranno sterminati;'); -- 23 37:9
UPDATE "LUZZI" SET text = 'Ancora un poco e l''empio non sarà più; tu osserverai il suo luogo, ed egli non vi sarà più.' WHERE "verseID" = 101058 AND (text = 'Ancora un poco e l''empio non sarà più;'); -- 23 37:10
UPDATE "LUZZI" SET text = 'Ma i mansueti erederanno la terra e godranno abbondanza di pace.' WHERE "verseID" = 101059 AND (text = 'Ma i mansueti erederanno la terra'); -- 23 37:11
UPDATE "LUZZI" SET text = 'L''empio macchina contro il giusto e digrigna i denti contro lui.' WHERE "verseID" = 101060 AND (text = 'L''empio macchina contro il giusto'); -- 23 37:12
UPDATE "LUZZI" SET text = 'Il Signore si ride di lui, perché vede che il suo giorno viene.' WHERE "verseID" = 101061 AND (text = 'Il Signore si ride di lui,'); -- 23 37:13
UPDATE "LUZZI" SET text = 'Gli empi han tratto la spada e teso il loro arco per abbattere il misero e il bisognoso, per sgozzare quelli che vanno per la via diritta.' WHERE "verseID" = 101062 AND (text = 'Gli empi han tratto la spada e teso il loro arco'); -- 23 37:14
UPDATE "LUZZI" SET text = 'La loro spada entrerà loro nel cuore, e gli archi loro saranno rotti.' WHERE "verseID" = 101063 AND (text = 'La loro spada entrerà loro nel cuore,'); -- 23 37:15
UPDATE "LUZZI" SET text = 'Meglio vale il poco del giusto che l''abbondanza di molti empi.' WHERE "verseID" = 101064 AND (text = 'Meglio vale il poco del giusto'); -- 23 37:16
UPDATE "LUZZI" SET text = 'Perché le braccia degli empi saranno rotte; ma l''Eterno sostiene i giusti.' WHERE "verseID" = 101065 AND (text = 'Perché le braccia degli empi saranno rotte;'); -- 23 37:17
UPDATE "LUZZI" SET text = 'L''Eterno conosce i giorni degli uomini integri; e la loro eredità durerà in perpetuo.' WHERE "verseID" = 101066 AND (text = 'L''Eterno conosce i giorni degli uomini integri;'); -- 23 37:18
UPDATE "LUZZI" SET text = 'Essi non saran confusi nel tempo dell''avversità, e saranno saziati nel tempo della fame.' WHERE "verseID" = 101067 AND (text = 'Essi non saran confusi nel tempo dell''avversità,' OR text = 'Essi non saran confusi nel tempo dell''avversità, e saranno saziati nel tempo dalla fame.'); -- 23 37:19
UPDATE "LUZZI" SET text = 'Ma gli empi periranno; e i nemici dell''Eterno come grasso d''agnelli, saran consumati e andranno in fumo.' WHERE "verseID" = 101068 AND (text = 'Ma gli empi periranno;' OR text = 'Ma gli empi periranno; e i nemici dell''Eterno, come grasso d''agnelli, saran consumati e andranno in fumo.'); -- 23 37:20
UPDATE "LUZZI" SET text = 'L''empio prende a prestito e non rende: ma il giusto è pietoso e dona.' WHERE "verseID" = 101069 AND (text = 'L''empio prende a prestito e non rende:'); -- 23 37:21
UPDATE "LUZZI" SET text = 'Poiché quelli che Dio benedice erederanno la terra, ma quelli ch''ei maledice saranno sterminati.' WHERE "verseID" = 101070 AND (text = 'Poiché quelli che Dio benedice erederanno la terra,'); -- 23 37:22
UPDATE "LUZZI" SET text = 'I passi dell''uomo dabbene son diretti dall''Eterno ed egli gradisce le vie di lui.' WHERE "verseID" = 101071 AND (text = 'I passi dell''uomo dabbene son diretti dall''Eterno'); -- 23 37:23
UPDATE "LUZZI" SET text = 'Se cade, non è però atterrato, perché l''Eterno lo sostiene per la mano.' WHERE "verseID" = 101072 AND (text = 'Se cade, non è però atterrato,'); -- 23 37:24
UPDATE "LUZZI" SET text = 'Io sono stato giovane e son anche divenuto vecchio, ma non ho visto il giusto abbandonato, né la sua progenie accattare il pane.' WHERE "verseID" = 101073 AND (text = 'Io sono stato giovane e son anche divenuto vecchio,'); -- 23 37:25
UPDATE "LUZZI" SET text = 'Egli tutti i giorni è pietoso e presta, e la sua progenie è in benedizione.' WHERE "verseID" = 101074 AND (text = 'Egli tutti i giorni è pietoso e presta,'); -- 23 37:26
UPDATE "LUZZI" SET text = 'Ritraiti dal male e fa'' il bene, e dimorerai nel paese in perpetuo.' WHERE "verseID" = 101075 AND (text = 'Ritraiti dal male e fa'' il bene,'); -- 23 37:27
UPDATE "LUZZI" SET text = 'Poiché l''Eterno ama la giustizia e non abbandona i suoi santi; essi son conservati in perpetuo; ma la progenie degli empi sarà sterminata.' WHERE "verseID" = 101076 AND (text = 'Poiché l''Eterno ama la giustizia'); -- 23 37:28
UPDATE "LUZZI" SET text = 'I giusti erederanno la terra e l''abiteranno in perpetuo.' WHERE "verseID" = 101077 AND (text = 'I giusti erederanno la terra'); -- 23 37:29
UPDATE "LUZZI" SET text = 'La bocca del giusto proferisce sapienza e la sua lingua pronunzia giustizia.' WHERE "verseID" = 101078 AND (text = 'La bocca del giusto proferisce sapienza'); -- 23 37:30
UPDATE "LUZZI" SET text = 'La legge del suo Dio è nel suo cuore; i suoi passi non vacilleranno.' WHERE "verseID" = 101079 AND (text = 'La legge del suo Dio è nel suo cuore;'); -- 23 37:31
UPDATE "LUZZI" SET text = 'L''empio spia il giusto e cerca di farlo morire.' WHERE "verseID" = 101080 AND (text = 'L''empio spia il giusto'); -- 23 37:32
UPDATE "LUZZI" SET text = 'L''Eterno non l''abbandonerà nelle sue mani, e non lo condannerà quando verrà in giudicio.' WHERE "verseID" = 101081 AND (text = 'L''Eterno non l''abbandonerà nelle sue mani,'); -- 23 37:33
UPDATE "LUZZI" SET text = 'Aspetta l''Eterno e osserva la sua via; egli t''innalzerà perché tu eredi la terra; e quando gli empi saranno sterminati, tu lo vedrai.' WHERE "verseID" = 101082 AND (text = 'Aspetta l''Eterno e osserva la sua via;'); -- 23 37:34
UPDATE "LUZZI" SET text = 'Io ho veduto l''empio potente, e distendersi come albero verde sul suolo natìo;' WHERE "verseID" = 101083 AND (text = 'Io ho veduto l''empio potente,'); -- 23 37:35
UPDATE "LUZZI" SET text = 'ma è passato via, ed ecco, non è più; io l''ho cercato, ma non s''è più trovato.' WHERE "verseID" = 101084 AND (text = 'ma è passato via, ed ecco, non è più;'); -- 23 37:36
UPDATE "LUZZI" SET text = 'Osserva l''uomo integro e considera l''uomo retto; perché v''è una posterità per l''uomo di pace.' WHERE "verseID" = 101085 AND (text = 'Osserva l''uomo integro e considera l''uomo retto;'); -- 23 37:37
UPDATE "LUZZI" SET text = 'Mentre i trasgressori saranno tutti quanti distrutti; la posterità degli empi sarà sterminata.' WHERE "verseID" = 101086 AND (text = 'Mentre i trasgressori saranno tutti quanti distrutti;'); -- 23 37:38
UPDATE "LUZZI" SET text = 'Ma la salvezza dei giusti procede dall''Eterno; egli è la loro fortezza nel tempo della distretta.' WHERE "verseID" = 101087 AND (text = 'Ma la salvezza dei giusti procede dall''Eterno;'); -- 23 37:39
UPDATE "LUZZI" SET text = 'L''Eterno li aiuta e li libera: li libera dagli empi e li salva, perché si sono rifugiati in lui.' WHERE "verseID" = 101088 AND (text = 'L''Eterno li aiuta e li libera: li liberadagli empi e li salva,perché si sono rifugiati in lui.'); -- 23 37:40
UPDATE "LUZZI" SET text = 'Salmo di Davide. Per far ricordare. O Eterno, non mi correggere nella tua ira, e non castigarmi nel tuo cruccio!' WHERE "verseID" = 101089 AND (text = 'Salmo di Davide. Per far ricordare.'); -- 23 38:1
UPDATE "LUZZI" SET text = 'Poiché le tue saette si sono confitte in me e la tua mano m''è calata addosso.' WHERE "verseID" = 101090 AND (text = 'Poiché le tue saette si sono confitte in me' OR text = 'Poiché le tue saette si sono confitte in me, e la tua mano m''è calata addosso.'); -- 23 38:2
UPDATE "LUZZI" SET text = 'Non v''è nulla d''intatto nella mia carne a cagion della tua ira; non v''è requie per le mie ossa a cagion del mio peccato.' WHERE "verseID" = 101091 AND (text = 'Non v''è nulla d''intatto nella mia carne a cagion della tua ira;'); -- 23 38:3
UPDATE "LUZZI" SET text = 'Poiché le mie iniquità sorpassano il mio capo; son come un grave carico, troppo pesante per me.' WHERE "verseID" = 101092 AND (text = 'Poiché le mie iniquità sorpassano il mio capo;'); -- 23 38:4
UPDATE "LUZZI" SET text = 'Le mie piaghe son fetide e purulenti per la mia follia.' WHERE "verseID" = 101093 AND (text = 'Le mie piaghe son fetide e purulenti'); -- 23 38:5
UPDATE "LUZZI" SET text = 'Io son tutto curvo e abbattuto, vo attorno tuttodì vestito a bruno.' WHERE "verseID" = 101094 AND (text = 'Io son tutto curvo e abbattuto,'); -- 23 38:6
UPDATE "LUZZI" SET text = 'Poiché i miei fianchi son pieni d''infiammazione, e non v''è nulla d''intatto nella mia carne.' WHERE "verseID" = 101095 AND (text = 'Poiché i miei fianchi son pieni d''infiammazione,'); -- 23 38:7
UPDATE "LUZZI" SET text = 'Son tutto fiacco e rotto; io ruggisco per il fremito del mio cuore.' WHERE "verseID" = 101096 AND (text = 'Son tutto fiacco e rotto;'); -- 23 38:8
UPDATE "LUZZI" SET text = 'Signore, ogni mio desiderio è nel tuo cospetto, e i miei sospiri non ti son nascosti.' WHERE "verseID" = 101097 AND (text = 'Signore, ogni mio desiderio è nel tuo cospetto,'); -- 23 38:9
UPDATE "LUZZI" SET text = 'Il mio cuore palpita, la mia forza mi lascia, ed anche la luce de'' miei occhi m''è venuta meno.' WHERE "verseID" = 101098 AND (text = 'Il mio cuore palpita, la mia forza mi lascia,'); -- 23 38:10
UPDATE "LUZZI" SET text = 'I miei amici, i miei compagni stan lontani dalla mia piaga, e i miei prossimi si fermano da lungi.' WHERE "verseID" = 101099 AND (text = 'I miei amici, i miei compagni stan lontani dalla mia piaga,'); -- 23 38:11
UPDATE "LUZZI" SET text = 'Quelli che cercan la mia vita mi tendono reti, e quelli che procurano il mio male proferiscon cose maligne e tutto il giorno meditano frodi.' WHERE "verseID" = 101100 AND (text = 'Quelli che cercan la mia vita mi tendono reti,'); -- 23 38:12
UPDATE "LUZZI" SET text = 'Ma io, come un sordo, non odo: son come un muto che non apre la bocca.' WHERE "verseID" = 101101 AND (text = 'Ma io, come un sordo, non odo:'); -- 23 38:13
UPDATE "LUZZI" SET text = 'Son come un uomo che non ascolta, e nella cui bocca non è replica di sorta.' WHERE "verseID" = 101102 AND (text = 'Son come un uomo che non ascolta,'); -- 23 38:14
UPDATE "LUZZI" SET text = 'Poiché, in te io spero, o Eterno; tu risponderai, o Signore, Iddio mio!' WHERE "verseID" = 101103 AND (text = 'Poiché, in te io spero, o Eterno;'); -- 23 38:15
UPDATE "LUZZI" SET text = 'Io ho detto: Non si rallegrino di me; e quando il mio piè vacilla, non s''innalzano superbi contro a me.' WHERE "verseID" = 101104 AND (text = 'Io ho detto: Non si rallegrino di me;' OR text = 'Io ho detto: Non si rallegrino di me; e quando il mio piè vacilla, non s''innalzino superbi contro a me.'); -- 23 38:16
UPDATE "LUZZI" SET text = 'Perché io sto per cadere, e il mio dolore è del continuo davanti a me.' WHERE "verseID" = 101105 AND (text = 'Perché io sto per cadere,'); -- 23 38:17
UPDATE "LUZZI" SET text = 'Io confesso la mia iniquità, e sono angosciato per il mio peccato.' WHERE "verseID" = 101106 AND (text = 'Io confesso la mia iniquità,'); -- 23 38:18
UPDATE "LUZZI" SET text = 'Ma quelli che senza motivo mi sono nemici sono forti, e quelli che m''odiano a torto son moltiplicati.' WHERE "verseID" = 101107 AND (text = 'Ma quelli che senza motivo mi sono nemici sono forti,' OR text = 'Ma quelli che senza motivo mi sono nemici sono forti, quelli che m''odiano a torto son moltiplicati.'); -- 23 38:19
UPDATE "LUZZI" SET text = 'Anche quelli che mi rendon male per bene sono miei avversari, perché seguo il bene.' WHERE "verseID" = 101108 AND (text = 'Anche quelli che mi rendon male per bene'); -- 23 38:20
UPDATE "LUZZI" SET text = 'O Eterno, non abbandonarmi; Dio mio, non allontanarti da me;' WHERE "verseID" = 101109 AND (text = 'O Eterno, non abbandonarmi;'); -- 23 38:21
UPDATE "LUZZI" SET text = 'affrettati in mio aiuto, o Signore, mia salvezza!' WHERE "verseID" = 101110 AND (text = 'affrettati in mio aiuto,o Signore, mia salvezza!'); -- 23 38:22
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Per Jeduthun. Salmo di Davide. Io dicevo: Farò attenzione alle mie vie per non peccare con la mia lingua; metterò un freno alla mia bocca, finché l''empio mi starà davanti.' WHERE "verseID" = 101111 AND (text = 'Per il Capo de'' musici. Per Jeduthun. Salmo di Davide.'); -- 23 39:1
UPDATE "LUZZI" SET text = 'Io sono stato muto, in silenzio, mi son taciuto senz''averne bene; anzi il mio dolore s''è inasprito.' WHERE "verseID" = 101112 AND (text = 'Io sono stato muto, in silenzio,'); -- 23 39:2
UPDATE "LUZZI" SET text = 'Il mio cuore si riscaldava dentro di me; mentre meditavo, un fuoco s''è acceso; allora la mia lingua ha parlato.' WHERE "verseID" = 101113 AND (text = 'Il mio cuore si riscaldava dentro di me;'); -- 23 39:3
UPDATE "LUZZI" SET text = 'O Eterno, fammi conoscere la mia fine e qual è la misura de'' miei giorni. Fa'' ch''io sappia quanto son frale.' WHERE "verseID" = 101114 AND (text = 'O Eterno, fammi conoscere la mia fine'); -- 23 39:4
UPDATE "LUZZI" SET text = 'Ecco, tu hai ridotto i miei giorni alla lunghezza di qualche palmo, e la mia durata è come nulla dinanzi a te; certo, ogni uomo, benché saldo in piè, non è che vanità. Sela.' WHERE "verseID" = 101115 AND (text = 'Ecco, tu hai ridotto i miei giorni'); -- 23 39:5
UPDATE "LUZZI" SET text = 'Certo, l''uomo va e viene come un''ombra; certo, s''affanna per quel ch''è vanità: egli ammassa, senza sapere chi raccoglierà.' WHERE "verseID" = 101116 AND (text = 'Certo, l''uomo va e viene come un''ombra;'); -- 23 39:6
UPDATE "LUZZI" SET text = 'E ora, o Signore, che aspetto? La mia speranza è in te.' WHERE "verseID" = 101117 AND (text = 'E ora, o Signore, che aspetto?'); -- 23 39:7
UPDATE "LUZZI" SET text = 'Liberami da tutte le mie trasgressioni; non far di me il vituperio dello stolto.' WHERE "verseID" = 101118 AND (text = 'Liberami da tutte le mie trasgressioni;'); -- 23 39:8
UPDATE "LUZZI" SET text = 'Io me ne sto muto, non aprirò bocca, perché sei tu che hai agito.' WHERE "verseID" = 101119 AND (text = 'Io me ne sto muto, non aprirò bocca,'); -- 23 39:9
UPDATE "LUZZI" SET text = 'Toglimi d''addosso il tuo flagello! Io mi consumo sotto i colpi della tua mano.' WHERE "verseID" = 101120 AND (text = 'Toglimi d''addosso il tuo flagello!'); -- 23 39:10
UPDATE "LUZZI" SET text = 'Quando castigando l''iniquità tu correggi l''uomo, tu distruggi come la tignuola quel che ha di più caro; certo, ogni uomo non è che vanità. Sela.' WHERE "verseID" = 101121 AND (text = 'Quando castigando l''iniquità tu correggi l''uomo,'); -- 23 39:11
UPDATE "LUZZI" SET text = 'O Eterno, ascolta la mia preghiera, e porgi l''orecchio al mio grido; non esser sordo alle mie lacrime; poiché io sono uno straniero presso a te, un pellegrino, come tutti i miei padri.' WHERE "verseID" = 101122 AND (text = 'O Eterno, ascolta la mia preghiera,'); -- 23 39:12
UPDATE "LUZZI" SET text = 'Distogli da me il tuo sguardo ond''io mi rianimi, prima che me ne vada, e non sia più.' WHERE "verseID" = 101123 AND (text = 'Distogli da me il tuo sguardo ond''io mi rianimi,prima che me ne vada, e non sia più.'); -- 23 39:13
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Di Davide. Salmo. Io ho pazientemente aspettato l''Eterno, ed egli s''è inclinato a me ed ha ascoltato il mio grido.' WHERE "verseID" = 101124 AND (text = 'Per il Capo de'' musici. Di Davide. Salmo.'); -- 23 40:1
UPDATE "LUZZI" SET text = 'Egli m''ha tratto fuori da una fossa di perdizione, dal pantano fangoso; ha fatto posare i miei piedi sulla roccia, ed ha stabilito i miei passi.' WHERE "verseID" = 101125 AND (text = 'Egli m''ha tratto fuori da una fossa di perdizione,'); -- 23 40:2
UPDATE "LUZZI" SET text = 'Egli ha messo nella mia bocca un nuovo cantico a lode del nostro Dio. Molti vedran questo e temeranno e confideranno nell''Eterno.' WHERE "verseID" = 101126 AND (text = 'Egli ha messo nella mia bocca un nuovo cantico'); -- 23 40:3
UPDATE "LUZZI" SET text = 'Beato l''uomo che ripone nell''Eterno la sua fiducia, e non riguarda ai superbi né a quei che si svian dietro alla menzogna!' WHERE "verseID" = 101127 AND (text = 'Beato l''uomo che ripone nell''Eterno la sua fiducia,'); -- 23 40:4
UPDATE "LUZZI" SET text = 'O Eterno, Iddio mio, hai moltiplicato le tue maraviglie e i tuoi pensieri in favor nostro; non si può farne il conto dinanzi a te. Se volessi narrarli e parlarne, son tanti che non si posson contare.' WHERE "verseID" = 101128 AND (text = 'O Eterno, Iddio mio, hai moltiplicato le tue maraviglie'); -- 23 40:5
UPDATE "LUZZI" SET text = 'Tu non prendi piacere né in sacrifizio né in offerta; tu m''hai aperto gli orecchi. Tu non domandi né olocausto né sacrifizio per il peccato.' WHERE "verseID" = 101129 AND (text = 'Tu non prendi piacere né in sacrifizio né in offerta;'); -- 23 40:6
UPDATE "LUZZI" SET text = 'Allora ho detto: Eccomi, vengo! Sta scritto di me nel rotolo del libro.' WHERE "verseID" = 101130 AND (text = 'Allora ho detto: Eccomi, vengo!'); -- 23 40:7
UPDATE "LUZZI" SET text = 'Dio mio, io prendo piacere a far la tua volontà, e la tua legge è dentro al mio cuore.' WHERE "verseID" = 101131 AND (text = 'Dio mio, io prendo piacere a far la tua volontà,'); -- 23 40:8
UPDATE "LUZZI" SET text = 'Io ho proclamato la tua giustizia nella grande assemblea; ecco, io non tengo chiuse le mie labbra, tu lo sai, o Eterno.' WHERE "verseID" = 101132 AND (text = 'Io ho proclamato la tua giustizia nella grande assemblea;'); -- 23 40:9
UPDATE "LUZZI" SET text = 'Io non ho nascosto la tua giustizia entro il mio cuore; ho narrato la tua fedeltà e la tua salvezza; non ho celato la tua benignità né la tua verità alla grande assemblea.' WHERE "verseID" = 101133 AND (text = 'Io non ho nascosto la tua giustizia entro il mio cuore;'); -- 23 40:10
UPDATE "LUZZI" SET text = 'Tu, o Eterno, non rifiutarmi le tue compassioni; la tua benignità e la tua verità mi guardino del continuo!' WHERE "verseID" = 101134 AND (text = 'Tu, o Eterno, non rifiutarmi le tue compassioni;'); -- 23 40:11
UPDATE "LUZZI" SET text = 'Poiché mali innumerevoli mi circondano; le mie iniquità m''hanno raggiunto, e non posso abbracciarle con lo sguardo. Sono in maggior numero dei capelli del mio capo, e il mio cuore vien meno!' WHERE "verseID" = 101135 AND (text = 'Poiché mali innumerevoli mi circondano;' OR text = 'Poiché mali innumerevoli mi circondano; le mie iniquità m''hanno raggiunto, e non posso abbracciarle con lo sguardo. Sono in maggior numero de'' capelli del mio capo, e il mio cuore vien meno!'); -- 23 40:12
UPDATE "LUZZI" SET text = 'Piacciati, o Eterno, di liberarmi! O Eterno, affrettati in mio aiuto!' WHERE "verseID" = 101136 AND (text = 'Piacciati, o Eterno, di liberarmi!'); -- 23 40:13
UPDATE "LUZZI" SET text = 'Siano confusi e svergognati tutti quanti quelli che cercano l''anima mia per farla perire! Voltin le spalle e siano coperti d''onta quelli che prendon piacere nel mio male!' WHERE "verseID" = 101137 AND (text = 'Siano confusi e svergognati tutti quanti'); -- 23 40:14
UPDATE "LUZZI" SET text = 'Restino muti di stupore per la loro ignominia quelli che mi dicono: Ah, ah!...' WHERE "verseID" = 101138 AND (text = 'Restino muti di stupore per la loro ignominia' OR text = 'Restino muti di stupore per la loro ignominia quelli che mi dicono: Ah, ah!…'); -- 23 40:15
UPDATE "LUZZI" SET text = 'Gioiscano e si rallegrino in te, tutti quelli che ti cercano; quelli che amano la tua salvezza dicano del continuo: Sia magnificato l''Eterno!' WHERE "verseID" = 101139 AND (text = 'Gioiscano e si rallegrino in te, tutti quelli che ti cercano;'); -- 23 40:16
UPDATE "LUZZI" SET text = 'Quanto a me son misero e bisognoso, ma il Signore ha cura di me. Tu sei il mio aiuto e il mio liberatore; o Dio mio, non tardare!' WHERE "verseID" = 101140 AND (text = 'Quanto a me son misero e bisognoso,ma il Signore ha cura di me.Tu sei il mio aiuto e il mio liberatore;o Dio mio, non tardare!'); -- 23 40:17
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Salmo di Davide. Beato colui che si dà pensiero del povero! nel giorno della sventura l''Eterno lo libererà.' WHERE "verseID" = 101141 AND (text = 'Per il Capo de'' musici. Salmo di Davide.'); -- 23 41:1
UPDATE "LUZZI" SET text = 'L''Eterno lo guarderà e lo manterrà in vita; egli sarà reso felice sulla terra, e tu non lo darai in balìa de'' suoi nemici.' WHERE "verseID" = 101142 AND (text = 'L''Eterno lo guarderà e lo manterrà in vita;'); -- 23 41:2
UPDATE "LUZZI" SET text = 'L''Eterno lo sosterrà quando sarà nel letto della infermità; tu trasformerai interamente il suo letto di malattia.' WHERE "verseID" = 101143 AND (text = 'L''Eterno lo sosterrà quando sarà nel letto della infermità;'); -- 23 41:3
UPDATE "LUZZI" SET text = 'Io ho detto: O Eterno, abbi pietà di me; sana l''anima mia, perché ho peccato contro a te.' WHERE "verseID" = 101144 AND (text = 'Io ho detto: O Eterno, abbi pietà di me;'); -- 23 41:4
UPDATE "LUZZI" SET text = 'I miei nemici mi augurano del male, dicendo: Quando morrà? e quando perirà il suo nome?' WHERE "verseID" = 101145 AND (text = 'I miei nemici mi augurano del male, dicendo:'); -- 23 41:5
UPDATE "LUZZI" SET text = 'E se un di loro viene a vedermi, parla con menzogna: il suo cuore intanto ammassa iniquità dentro di sé; appena uscito, egli parla.' WHERE "verseID" = 101146 AND (text = 'E se un di loro viene a vedermi, parla con menzogna:'); -- 23 41:6
UPDATE "LUZZI" SET text = 'Tutti quelli che m''odiano bisbiglian fra loro contro a me; contro a me macchinano del male.' WHERE "verseID" = 101147 AND (text = 'Tutti quelli che m''odiano bisbiglian fra loro contro a me;'); -- 23 41:7
UPDATE "LUZZI" SET text = 'Un male incurabile, essi dicono, gli s''è attaccato addosso; ed ora che giace, non si rileverà mai più.' WHERE "verseID" = 101148 AND (text = 'Un male incurabile, essi dicono, gli s''è attaccato addosso;'); -- 23 41:8
UPDATE "LUZZI" SET text = 'Perfino l''uomo col quale vivevo in pace, nel quale confidavo, che mangiava il mio pane, ha alzato il calcagno contro a me.' WHERE "verseID" = 101149 AND (text = 'Perfino l''uomo col quale vivevo in pace,'); -- 23 41:9
UPDATE "LUZZI" SET text = 'Ma tu, o Eterno, abbi pietà di me e rialzami, ed io renderò loro quel che si meritano.' WHERE "verseID" = 101150 AND (text = 'Ma tu, o Eterno, abbi pietà di me e rialzami,'); -- 23 41:10
UPDATE "LUZZI" SET text = 'Da questo io riconoscerò che tu mi gradisci, se il mio nemico non trionferà di me.' WHERE "verseID" = 101151 AND (text = 'Da questo io riconoscerò che tu mi gradisci,'); -- 23 41:11
UPDATE "LUZZI" SET text = 'Quanto a me, tu mi sostieni nella mia integrità e mi stabilisci nel tuo cospetto in perpetuo.' WHERE "verseID" = 101152 AND (text = 'Quanto a me, tu mi sostieni nella mia integrità'); -- 23 41:12
UPDATE "LUZZI" SET text = 'SIA BENEDETTO L''ETERNO, L''IDDIO D''ISRAELE, DI SECOLO IN SECOLO. AMEN! AMEN!' WHERE "verseID" = 101153 AND (text = 'SIA BENEDETTO L''ETERNO, L''IDDIO D''ISRAELE,DI SECOLO IN SECOLO. AMEN! AMEN!'); -- 23 41:13
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Cantico dei figliuoli di Core. Come la cerva agogna i rivi dell''acque, così l''anima mia agogna te, o Dio.' WHERE "verseID" = 101154 AND (text = 'Per il Capo de'' musici. Cantico dei figliuoli di Core.'); -- 23 42:1
UPDATE "LUZZI" SET text = 'L''anima mia è assetata di Dio, dell''Iddio vivente: Quando verrò e comparirò al cospetto di Dio?' WHERE "verseID" = 101155 AND (text = 'L''anima mia è assetata di Dio, dell''Iddio vivente:'); -- 23 42:2
UPDATE "LUZZI" SET text = 'Le mie lacrime son diventate il mio cibo giorno e notte, da che mi van dicendo del continuo: Dov''è il tuo Dio?' WHERE "verseID" = 101156 AND (text = 'Le mie lacrime son diventate il mio cibo giorno e notte,'); -- 23 42:3
UPDATE "LUZZI" SET text = 'Non posso non ricordare con profonda commozione il tempo in cui procedevo con la folla e la guidavo alla casa di Dio, tra i canti di giubilo e di lode d''una moltitudine in festa.' WHERE "verseID" = 101157 AND (text = 'Non posso non ricordare con profonda commozione'); -- 23 42:4
UPDATE "LUZZI" SET text = 'Perché t''abbatti anima mia? perché ti commuovi in me? Spera in Dio, perch''io lo celebrerò ancora; egli è la mia salvezza e il mio Dio.' WHERE "verseID" = 101158 AND (text = 'Perché t''abbatti anima mia? perché ti commuovi in me?'); -- 23 42:5
UPDATE "LUZZI" SET text = 'L''anima mia è abbattuta in me; perciò io ripenso a te dal paese del Giordano, dai monti dell''Hermon, dal monte Mitsar.' WHERE "verseID" = 101159 AND (text = 'L''anima mia è abbattuta in me;'); -- 23 42:6
UPDATE "LUZZI" SET text = 'Un abisso chiama un altro abisso al rumore delle tue cascate; tutte le tue onde ed i tuoi flutti mi son passati addosso.' WHERE "verseID" = 101160 AND (text = 'Un abisso chiama un altro abisso al rumore delle tue cascate;'); -- 23 42:7
UPDATE "LUZZI" SET text = 'L''Eterno, di giorno, mandava la sua benignità, e la notte eran meco i suoi cantici, la preghiera all''Iddio della mia vita.' WHERE "verseID" = 101161 AND (text = 'L''Eterno, di giorno, mandava la sua benignità,'); -- 23 42:8
UPDATE "LUZZI" SET text = 'Io dirò a Dio, ch''è la mia ròcca: Perché mi hai dimenticato? Perché vo io vestito a bruno per l''oppression del nemico?' WHERE "verseID" = 101162 AND (text = 'Io dirò a Dio, ch''è la mia ròcca: Perché mi hai dimenticato?'); -- 23 42:9
UPDATE "LUZZI" SET text = 'Trafiggendomi le ossa, i miei nemici mi fanno onta dicendomi continuamente: Dov''è il tuo Dio?' WHERE "verseID" = 101163 AND (text = 'Trafiggendomi le ossa, i miei nemici mi fanno onta'); -- 23 42:10
UPDATE "LUZZI" SET text = 'Perché t''abbatti anima mia? perché ti commuovi in me? Spera in Dio, perché lo celebrerò ancora; egli è la mia salvezza e il mio Dio.' WHERE "verseID" = 101164 AND (text = 'Perché t''abbatti anima mia? perché ti commuovi in me?Spera in Dio, perché lo celebrerò ancora;egli è la mia salvezza e il mio Dio.'); -- 23 42:11
UPDATE "LUZZI" SET text = 'Fammi ragione, o Dio, difendi la mia causa contro un''empia gente; liberami dall''uomo frodolento e iniquo.' WHERE "verseID" = 101165 AND (text = 'Fammi ragione, o Dio, difendi la mia causa'); -- 23 43:1
UPDATE "LUZZI" SET text = 'Poiché tu sei l''Iddio ch''è la mia fortezza; perché mi hai rigettato? Perché vo io vestito a bruno per l''oppression del nemico?' WHERE "verseID" = 101166 AND (text = 'Poiché tu sei l''Iddio ch''è la mia fortezza;'); -- 23 43:2
UPDATE "LUZZI" SET text = 'Manda la tua luce e la tua verità; mi guidino esse, mi conducano al monte della tua santità, nei tuoi tabernacoli.' WHERE "verseID" = 101167 AND (text = 'Manda la tua luce e la tua verità; mi guidino esse,'); -- 23 43:3
UPDATE "LUZZI" SET text = 'Allora andrò all''altare di Dio, all''Iddio, ch''è la mia allegrezza ed il mio giubilo; e ti celebrerò con la cetra, o Dio, Dio mio!' WHERE "verseID" = 101168 AND (text = 'Allora andrò all''altare di Dio,'); -- 23 43:4
UPDATE "LUZZI" SET text = 'Perché t''abbatti anima mia? perché ti commuovi in me? Spera in Dio, perché lo celebrerò ancora; egli è la mia salvezza ed il mio Dio.' WHERE "verseID" = 101169 AND (text = 'Perché t''abbatti anima mia? perché ti commuovi in me?Spera in Dio, perché lo celebrerò ancora;egli è la mia salvezza ed il mio Dio.'); -- 23 43:5
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Dei figliuoli di Core. Cantico. O Dio, noi abbiamo udito coi nostri orecchi, i nostri padri ci hanno raccontato l''opera che compisti ai loro giorni, ai giorni antichi.' WHERE "verseID" = 101170 AND (text = 'Al Capo de'' musici. Dei figliuoli di Core. Cantico.'); -- 23 44:1
UPDATE "LUZZI" SET text = 'Tu con la tua mano scacciasti le nazioni e stabilisti i nostri padri; distruggesti dei popoli per estender loro.' WHERE "verseID" = 101171 AND (text = 'Tu con la tua mano scacciasti le nazioni'); -- 23 44:2
UPDATE "LUZZI" SET text = 'Poiché essi non conquistarono il paese con la loro spada, né fu il loro braccio che li salvò, ma la tua destra, il tuo braccio, la luce del tuo volto, perché li gradivi.' WHERE "verseID" = 101172 AND (text = 'Poiché essi non conquistarono il paese con la loro spada,'); -- 23 44:3
UPDATE "LUZZI" SET text = 'Tu sei il mio re, o Dio, ordina la salvezza di Giacobbe!' WHERE "verseID" = 101173 AND (text = 'Tu sei il mio re, o Dio,'); -- 23 44:4
UPDATE "LUZZI" SET text = 'Con te noi abbatteremo i nostri nemici, nel tuo nome calpesteremo quelli che si levan contro a noi.' WHERE "verseID" = 101174 AND (text = 'Con te noi abbatteremo i nostri nemici,'); -- 23 44:5
UPDATE "LUZZI" SET text = 'Poiché non è nel mio arco che io confido, e non è la mia spada che mi salverà;' WHERE "verseID" = 101175 AND (text = 'Poiché non è nel mio arco che io confido,'); -- 23 44:6
UPDATE "LUZZI" SET text = 'ma sei tu che ci salvi dai nostri nemici e rendi confusi quelli che ci odiano.' WHERE "verseID" = 101176 AND (text = 'ma sei tu che ci salvi dai nostri nemici'); -- 23 44:7
UPDATE "LUZZI" SET text = 'In Dio noi ci glorieremo ogni giorno, e celebreremo il tuo nome in perpetuo. Sela.' WHERE "verseID" = 101177 AND (text = 'In Dio noi ci glorieremo ogni giorno,'); -- 23 44:8
UPDATE "LUZZI" SET text = 'Ma ora ci hai reietti e coperti d''onta, e non esci più coi nostri eserciti.' WHERE "verseID" = 101178 AND (text = 'Ma ora ci hai reietti e coperti d''onta,'); -- 23 44:9
UPDATE "LUZZI" SET text = 'Tu ci fai voltar le spalle davanti al nemico, e quelli che ci odiano ci depredano.' WHERE "verseID" = 101179 AND (text = 'Tu ci fai voltar le spalle davanti al nemico,'); -- 23 44:10
UPDATE "LUZZI" SET text = 'Ci hai dati via come pecore da mangiare, e ci hai dispersi fra le nazioni.' WHERE "verseID" = 101180 AND (text = 'Ci hai dati via come pecore da mangiare,'); -- 23 44:11
UPDATE "LUZZI" SET text = 'Tu vendi il tuo popolo per un nulla, e non ti sei tenuto alto nel fissarne il prezzo.' WHERE "verseID" = 101181 AND (text = 'Tu vendi il tuo popolo per un nulla,'); -- 23 44:12
UPDATE "LUZZI" SET text = 'Tu ci fai oggetto d''obbrobrio per i nostri vicini, di beffe e di scherno per quelli che ci stan d''intorno.' WHERE "verseID" = 101182 AND (text = 'Tu ci fai oggetto d''obbrobrio per i nostri vicini,'); -- 23 44:13
UPDATE "LUZZI" SET text = 'Tu ci rendi la favola delle nazioni, e i popoli scuotono il capo, quando si tratta di noi.' WHERE "verseID" = 101183 AND (text = 'Tu ci rendi la favola delle nazioni,'); -- 23 44:14
UPDATE "LUZZI" SET text = 'Tuttodì l''onta mia mi sta dinanzi, e la vergogna mi cuopre la faccia' WHERE "verseID" = 101184 AND (text = 'Tuttodì l''onta mia mi sta dinanzi,'); -- 23 44:15
UPDATE "LUZZI" SET text = 'all''udire chi mi vitupera e m''oltraggia, al vedere il nemico ed il vendicativo.' WHERE "verseID" = 101185 AND (text = 'all''udire chi mi vitupera e m''oltraggia,'); -- 23 44:16
UPDATE "LUZZI" SET text = 'Tutto questo ci è avvenuto. Eppure non t''abbiam dimenticato e non siamo stati infedeli al tuo patto.' WHERE "verseID" = 101186 AND (text = 'Tutto questo ci è avvenuto. Eppure non t''abbiam dimenticato'); -- 23 44:17
UPDATE "LUZZI" SET text = 'Il nostro cuore non si è rivolto indietro, e i nostri passi non si sono sviati dal tuo sentiero,' WHERE "verseID" = 101187 AND (text = 'Il nostro cuore non si è rivolto indietro,'); -- 23 44:18
UPDATE "LUZZI" SET text = 'perché tu ci avessi a fiaccare cacciandoci in dimore di sciacalli, perché tu avessi a stender su noi l''ombra della morte.' WHERE "verseID" = 101188 AND (text = 'perché tu ci avessi a fiaccare cacciandoci in dimore di sciacalli,'); -- 23 44:19
UPDATE "LUZZI" SET text = 'Se avessimo dimenticato il nome del nostro Dio e avessimo teso le mani verso un dio straniero,' WHERE "verseID" = 101189 AND (text = 'Se avessimo dimenticato il nome del nostro Dio' OR text = 'Se avessimo dimenticato il nome del nostro Dio, e avessimo teso le mani verso un dio straniero,'); -- 23 44:20
UPDATE "LUZZI" SET text = 'Dio non l''avrebbe egli scoperto? Poich''egli conosce i segreti del cuore.' WHERE "verseID" = 101190 AND (text = 'Dio non l''avrebbe egli scoperto?'); -- 23 44:21
UPDATE "LUZZI" SET text = 'Anzi è per cagion tua che siamo ogni dì messi a morte, e reputati come pecore da macello.' WHERE "verseID" = 101191 AND (text = 'Anzi è per cagion tua che siamo ogni dì messi a morte,'); -- 23 44:22
UPDATE "LUZZI" SET text = 'Risvegliati! Perché dormi, o Signore? Destati, non rigettarci in perpetuo!' WHERE "verseID" = 101192 AND (text = 'Risvegliati! Perché dormi, o Signore?'); -- 23 44:23
UPDATE "LUZZI" SET text = 'Perché nascondi la tua faccia e dimentichi la nostra afflizione e la nostra oppressione?' WHERE "verseID" = 101193 AND (text = 'Perché nascondi la tua faccia'); -- 23 44:24
UPDATE "LUZZI" SET text = 'Poiché l''anima nostra è abbattuta nella polvere; il nostro corpo aderisce alla terra.' WHERE "verseID" = 101194 AND (text = 'Poiché l''anima nostra è abbattuta nella polvere;'); -- 23 44:25
UPDATE "LUZZI" SET text = 'Lèvati in nostro aiuto, e liberaci, per amor della tua benignità.' WHERE "verseID" = 101195 AND (text = 'Lèvati in nostro aiuto,e liberaci, per amor della tua benignità.'); -- 23 44:26
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Sopra ''i gigli''. De'' figliuoli di Core. Cantico. Inno nuziale. Mi ferve in cuore una parola soave; io dico: l''opera mia è per un re; la mia lingua sarà come la penna d''un veloce scrittore.' WHERE "verseID" = 101196 AND (text = 'Per il Capo de'' musici. Sopra ''i gigli''. De'' figliuoli di Core. Cantico. Inno nuziale.'); -- 23 45:1
UPDATE "LUZZI" SET text = 'Tu sei bello, più bello di tutti i figliuoli degli uomini; la grazia è sparsa sulle tue labbra; perciò Iddio ti ha benedetto in eterno.' WHERE "verseID" = 101197 AND (text = 'Tu sei bello, più bello di tutti i figliuoli degli uomini;'); -- 23 45:2
UPDATE "LUZZI" SET text = 'Cingiti la spada al fianco, o prode; vestiti della tua gloria e della tua magnificenza.' WHERE "verseID" = 101198 AND (text = 'Cingiti la spada al fianco, o prode;' OR text = 'Cingiti la spada al fianco, o prode; vèstiti della tua gloria e della tua magnificenza.'); -- 23 45:3
UPDATE "LUZZI" SET text = 'E, nella tua magnificenza, avanza sul carro, per la causa della verità, della clemenza e della giustizia; e la tua destra ti farà vedere cose tremende.' WHERE "verseID" = 101199 AND (text = 'E, nella tua magnificenza, avanza sul carro,'); -- 23 45:4
UPDATE "LUZZI" SET text = 'Le tue frecce sono aguzze; i popoli cadranno sotto di te; esse penetreranno nel cuore dei nemici del re.' WHERE "verseID" = 101200 AND (text = 'Le tue frecce sono aguzze;'); -- 23 45:5
UPDATE "LUZZI" SET text = 'Il tuo trono, o Dio, è per ogni eternità; lo scettro del tuo regno è uno scettro di dirittura.' WHERE "verseID" = 101201 AND (text = 'Il tuo trono, o Dio, è per ogni eternità;'); -- 23 45:6
UPDATE "LUZZI" SET text = 'Tu ami la giustizia e odii l''empietà. Perciò Iddio, l''Iddio tuo, ti ha unto d''olio di letizia a preferenza de'' tuoi colleghi.' WHERE "verseID" = 101202 AND (text = 'Tu ami la giustizia e odii l''empietà.'); -- 23 45:7
UPDATE "LUZZI" SET text = 'Tutti i tuoi vestimenti sanno di mirra, d''aloe, di cassia; dai palazzi d''avorio la musica degli strumenti ti rallegra.' WHERE "verseID" = 101203 AND (text = 'Tutti i tuoi vestimenti sanno di mirra, d''aloe, di cassia;'); -- 23 45:8
UPDATE "LUZZI" SET text = 'Figliuole di re son fra le tue dame d''onore, alla tua destra sta la regina, adorna d''oro d''Ophir.' WHERE "verseID" = 101204 AND (text = 'Figliuole di re son fra le tue dame d''onore,'); -- 23 45:9
UPDATE "LUZZI" SET text = 'Ascolta, o fanciulla, e guarda e porgi l''orecchio; dimentica il tuo popolo e la casa di tuo padre;' WHERE "verseID" = 101205 AND (text = 'Ascolta, o fanciulla, e guarda e porgi l''orecchio;'); -- 23 45:10
UPDATE "LUZZI" SET text = 'e il re porrà amore alla tua bellezza. Poich''egli è il tuo signore, prostrati dinanzi a lui.' WHERE "verseID" = 101206 AND (text = 'e il re porrà amore alla tua bellezza.'); -- 23 45:11
UPDATE "LUZZI" SET text = 'E la figliuola di Tiro, con de'' doni, e i ricchi del popolo ricercheranno il tuo favore.' WHERE "verseID" = 101207 AND (text = 'E la figliuola di Tiro, con de'' doni,'); -- 23 45:12
UPDATE "LUZZI" SET text = 'Tutta splendore è la figliuola del re, nelle sue stanze; la sua veste è tutta trapunta d''oro.' WHERE "verseID" = 101208 AND (text = 'Tutta splendore è la figliuola del re, nelle sue stanze;'); -- 23 45:13
UPDATE "LUZZI" SET text = 'Ella sarà condotta al re in vesti ricamate; seguìta dalle vergini sue compagne, che gli saranno presentate;' WHERE "verseID" = 101209 AND (text = 'Ella sarà condotta al re in vesti ricamate;'); -- 23 45:14
UPDATE "LUZZI" SET text = 'saran condotte con letizia e con giubilo; ed esse entreranno nel palazzo del re.' WHERE "verseID" = 101210 AND (text = 'saran condotte con letizia e con giubilo;'); -- 23 45:15
UPDATE "LUZZI" SET text = 'I tuoi figliuoli prenderanno il posto de'' tuoi padri; tu li costituirai principi per tutta la terra.' WHERE "verseID" = 101211 AND (text = 'I tuoi figliuoli prenderanno il posto de'' tuoi padri;'); -- 23 45:16
UPDATE "LUZZI" SET text = 'Io renderò il tuo nome celebre per ogni età; perciò i popoli ti loderanno in sempiterno.' WHERE "verseID" = 101212 AND (text = 'Io renderò il tuo nome celebre per ogni età;perciò i popoli ti loderanno in sempiterno.'); -- 23 45:17
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Dei figliuoli di Core. Per voci di fanciulle. Canto. Dio è per noi un rifugio ed una forza, un aiuto sempre pronto nelle distrette.' WHERE "verseID" = 101213 AND (text = 'Per il Capo de'' musici. Dei figliuoli di Core. Per voci di fanciulle. Canto.'); -- 23 46:1
UPDATE "LUZZI" SET text = 'Perciò noi non temeremo, anche quando fosse sconvolta la terra, quando i monti fossero smossi in seno ai mari,' WHERE "verseID" = 101214 AND (text = 'Perciò noi non temeremo, anche quando fosse sconvolta la terra,'); -- 23 46:2
UPDATE "LUZZI" SET text = 'quando le acque del mare muggissero e schiumassero, e per il loro gonfiarsi tremassero i monti.' WHERE "verseID" = 101215 AND (text = 'quando le acque del mare muggissero e schiumassero,'); -- 23 46:3
UPDATE "LUZZI" SET text = 'V''è un fiume, i cui rivi rallegrano la città di Dio, il luogo santo della dimora dell''Altissimo.' WHERE "verseID" = 101216 AND (text = 'V''è un fiume, i cui rivi rallegrano la città di Dio,'); -- 23 46:4
UPDATE "LUZZI" SET text = 'Iddio è nel mezzo di lei; essa non sarà smossa. Iddio la soccorrerà allo schiarire del mattino.' WHERE "verseID" = 101217 AND (text = 'Iddio è nel mezzo di lei; essa non sarà smossa.'); -- 23 46:5
UPDATE "LUZZI" SET text = 'Le nazioni romoreggiano, i regni si commuovono; egli fa udire la sua voce, la terra si strugge.' WHERE "verseID" = 101218 AND (text = 'Le nazioni romoreggiano, i regni si commuovono;'); -- 23 46:6
UPDATE "LUZZI" SET text = 'L''Eterno degli eserciti è con noi, l''Iddio di Giacobbe è il nostro alto ricetto. Sela.' WHERE "verseID" = 101219 AND (text = 'L''Eterno degli eserciti è con noi,'); -- 23 46:7
UPDATE "LUZZI" SET text = 'Venite, mirate le opere dell''Eterno, il quale compie sulla terra cose stupende.' WHERE "verseID" = 101220 AND (text = 'Venite, mirate le opere dell''Eterno,'); -- 23 46:8
UPDATE "LUZZI" SET text = 'Egli fa cessar le guerre fino all''estremità della terra; rompe gli archi e spezza le lance, arde i carri nel fuoco.' WHERE "verseID" = 101221 AND (text = 'Egli fa cessar le guerre fino all''estremità della terra;'); -- 23 46:9
UPDATE "LUZZI" SET text = 'Fermatevi, ei dice, e riconoscete che io sono Dio. Io sarò esaltato fra le nazioni, sarò esaltato sulla terra.' WHERE "verseID" = 101222 AND (text = 'Fermatevi, ei dice, e riconoscete che io sono Dio.'); -- 23 46:10
UPDATE "LUZZI" SET text = 'L''Eterno degli eserciti è con noi; l''Iddio di Giacobbe è il nostro alto ricetto. Sela.' WHERE "verseID" = 101223 AND (text = 'L''Eterno degli eserciti è con noi;l''Iddio di Giacobbe è il nostro alto ricetto. Sela.'); -- 23 46:11
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Dei figliuoli di Core. Salmo. Battete le mani, o popoli tutti; acclamate Iddio con grida d''allegrezza!' WHERE "verseID" = 101224 AND (text = 'Per il Capo de'' musici. Dei figliuoli di Core. Salmo.'); -- 23 47:1
UPDATE "LUZZI" SET text = 'Poiché l''Eterno, l''Altissimo, è tremendo, re supremo su tutta la terra.' WHERE "verseID" = 101225 AND (text = 'Poiché l''Eterno, l''Altissimo, è tremendo,'); -- 23 47:2
UPDATE "LUZZI" SET text = 'Egli riduce i popoli sotto di noi, e le nazioni sotto i nostri piedi.' WHERE "verseID" = 101226 AND (text = 'Egli riduce i popoli sotto di noi,'); -- 23 47:3
UPDATE "LUZZI" SET text = 'Egli scelse per noi la nostra eredità, gloria di Giacobbe ch''egli ama. Sela.' WHERE "verseID" = 101227 AND (text = 'Egli scelse per noi la nostra eredità,'); -- 23 47:4
UPDATE "LUZZI" SET text = 'Iddio è salito in mezzo alle acclamazioni, l''Eterno è salito al suon delle trombe.' WHERE "verseID" = 101228 AND (text = 'Iddio è salito in mezzo alle acclamazioni,'); -- 23 47:5
UPDATE "LUZZI" SET text = 'Salmeggiate a Dio, salmeggiate; salmeggiate al nostro re, salmeggiate!' WHERE "verseID" = 101229 AND (text = 'Salmeggiate a Dio, salmeggiate;'); -- 23 47:6
UPDATE "LUZZI" SET text = 'Poiché Dio è re di tutta la terra; cantategli un bell''inno.' WHERE "verseID" = 101230 AND (text = 'Poiché Dio è re di tutta la terra;'); -- 23 47:7
UPDATE "LUZZI" SET text = 'Iddio regna sulle nazioni; Iddio siede sul trono della sua santità.' WHERE "verseID" = 101231 AND (text = 'Iddio regna sulle nazioni;'); -- 23 47:8
UPDATE "LUZZI" SET text = 'I principi de'' popoli s''adunano assieme per essere il popolo dell''Iddio d''Abramo: perché a Dio appartengono i potenti della terra; egli è sommamente elevato.' WHERE "verseID" = 101232 AND (text = 'I principi de'' popoli s''adunano assiemeper essere il popolo dell''Iddio d''Abramo:perché a Dio appartengono i potenti della terra;egli è sommamente elevato.'); -- 23 47:9
UPDATE "LUZZI" SET text = 'Canto. Salmo de'' figliuoli di Core. Grande è l''Eterno e lodato altamente nella città dell''Iddio nostro, sul monte della sua santità.' WHERE "verseID" = 101233 AND (text = 'Canto. Salmo de'' figliuoli di Core.'); -- 23 48:1
UPDATE "LUZZI" SET text = 'Bello si erge, gioia di tutta la terra, il monte di Sion, dalle parti del settentrione, bella è la città del gran re.' WHERE "verseID" = 101234 AND (text = 'Bello si erge, gioia di tutta la terra,'); -- 23 48:2
UPDATE "LUZZI" SET text = 'Nei palazzi d''essa Dio s''è fatto conoscere come un''altra fortezza.' WHERE "verseID" = 101235 AND (text = 'Nei palazzi d''essa Dio s''è fatto conoscere' OR text = 'Nei palazzi d''essa Dio s''è fatto conoscere come un''alta fortezza.'); -- 23 48:3
UPDATE "LUZZI" SET text = 'Poiché ecco, i re s''erano adunati, e si avanzavano assieme.' WHERE "verseID" = 101236 AND (text = 'Poiché ecco, i re s''erano adunati,' OR text = 'Poiché ecco, i re s''erano adunati, si avanzavano assieme.'); -- 23 48:4
UPDATE "LUZZI" SET text = 'Appena la videro, rimasero attoniti, smarriti, si misero in fuga,' WHERE "verseID" = 101237 AND (text = 'Appena la videro, rimasero attoniti,'); -- 23 48:5
UPDATE "LUZZI" SET text = 'un tremore li colse quivi, una doglia come di donna che partorisce.' WHERE "verseID" = 101238 AND (text = 'un tremore li colse quivi,'); -- 23 48:6
UPDATE "LUZZI" SET text = 'Col vento orientale tu spezzi le navi di Tarsis.' WHERE "verseID" = 101239 AND (text = 'Col vento orientale'); -- 23 48:7
UPDATE "LUZZI" SET text = 'Quel che avevamo udito l''abbiamo veduto nella città dell''Eterno degli eserciti, nella città del nostro Dio. Dio la renderà stabile in perpetuo. Sela.' WHERE "verseID" = 101240 AND (text = 'Quel che avevamo udito l''abbiamo veduto'); -- 23 48:8
UPDATE "LUZZI" SET text = 'O Dio, noi abbiam meditato sulla tua benignità dentro al tuo tempio.' WHERE "verseID" = 101241 AND (text = 'O Dio, noi abbiam meditato sulla tua benignità'); -- 23 48:9
UPDATE "LUZZI" SET text = 'O Dio, qual è il tuo nome, tale è la tua lode fino all''estremità della terra; la tua destra è piena di giustizia.' WHERE "verseID" = 101242 AND (text = 'O Dio, qual è il tuo nome,'); -- 23 48:10
UPDATE "LUZZI" SET text = 'Si rallegri il monte di Sion, festeggino le figliuole di Giuda per i tuoi giudizi!' WHERE "verseID" = 101243 AND (text = 'Si rallegri il monte di Sion,'); -- 23 48:11
UPDATE "LUZZI" SET text = 'Circuite Sion, giratele attorno, contatene le torri,' WHERE "verseID" = 101244 AND (text = 'Circuite Sion, giratele attorno,'); -- 23 48:12
UPDATE "LUZZI" SET text = 'osservatene i bastioni, considerate i suoi palazzi, onde possiate parlarne alla futura generazione.' WHERE "verseID" = 101245 AND (text = 'osservatene i bastioni,'); -- 23 48:13
UPDATE "LUZZI" SET text = 'Poiché questo Dio è il nostro Dio in sempiterno: egli sarà la nostra guida fino alla morte.' WHERE "verseID" = 101246 AND (text = 'Poiché questo Dio è il nostro Dio in sempiterno:egli sarà la nostra guida fino alla morte.'); -- 23 48:14
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. De'' figliuoli di Core. Salmo. Udite questo, popoli tutti; porgete orecchio, voi tutti gli abitanti del mondo!' WHERE "verseID" = 101247 AND (text = 'Per il Capo de'' musici. De'' figliuoli di Core. Salmo.'); -- 23 49:1
UPDATE "LUZZI" SET text = 'Plebei e nobili, ricchi e poveri tutti insieme.' WHERE "verseID" = 101248 AND (text = 'Plebei e nobili,'); -- 23 49:2
UPDATE "LUZZI" SET text = 'La mia bocca proferirà cose savie, e la meditazione del mio cuore sarà piena di senno.' WHERE "verseID" = 101249 AND (text = 'La mia bocca proferirà cose savie,'); -- 23 49:3
UPDATE "LUZZI" SET text = 'Io presterò orecchio alle sentenze, spiegherò a suon di cetra il mio enigma.' WHERE "verseID" = 101250 AND (text = 'Io presterò orecchio alle sentenze,'); -- 23 49:4
UPDATE "LUZZI" SET text = 'Perché temerei ne'' giorni dell''avversità quando mi circonda l''iniquità dei miei insidiatori,' WHERE "verseID" = 101251 AND (text = 'Perché temerei ne'' giorni dell''avversità'); -- 23 49:5
UPDATE "LUZZI" SET text = 'i quali confidano ne'' loro grandi averi e si gloriano della grandezza delle loro ricchezze?' WHERE "verseID" = 101252 AND (text = 'i quali confidano ne'' loro grandi averi'); -- 23 49:6
UPDATE "LUZZI" SET text = 'Nessuno però può in alcun modo redimere il fratello, né dare a Dio il prezzo del riscatto d''esso.' WHERE "verseID" = 101253 AND (text = 'Nessuno però può in alcun modo redimere il fratello,'); -- 23 49:7
UPDATE "LUZZI" SET text = 'Il riscatto dell''anima dell''uomo è troppo caro e farà mai sempre difetto.' WHERE "verseID" = 101254 AND (text = 'Il riscatto dell''anima dell''uomo è troppo caro'); -- 23 49:8
UPDATE "LUZZI" SET text = 'Non può farsi ch''ei continui a vivere in perpetuo e non vegga la fossa.' WHERE "verseID" = 101255 AND (text = 'Non può farsi ch''ei continui a vivere in perpetuo'); -- 23 49:9
UPDATE "LUZZI" SET text = 'Perché la vedrà. I savi muoiono; periscono del pari il pazzo e lo stolto e lasciano ad altri i loro beni.' WHERE "verseID" = 101256 AND (text = 'Perché la vedrà. I savi muoiono;'); -- 23 49:10
UPDATE "LUZZI" SET text = 'L''intimo lor pensiero è che le loro case dureranno in eterno e le loro abitazioni d''età in età; danno i loro nomi alle loro terre.' WHERE "verseID" = 101257 AND (text = 'L''intimo lor pensiero è che le loro case dureranno in eterno' OR text = 'L''intimo lor pensiero è che le loro case dureranno in eterno e le loro abitazioni d''età in età; dànno i loro nomi alle loro terre.'); -- 23 49:11
UPDATE "LUZZI" SET text = 'Ma l''uomo ch''è in onore non dura; egli è simile alle bestie che periscono.' WHERE "verseID" = 101258 AND (text = 'Ma l''uomo ch''è in onore non dura;'); -- 23 49:12
UPDATE "LUZZI" SET text = 'Questa loro condotta è una follia; eppure i loro successori approvano i lor detti. Sela.' WHERE "verseID" = 101259 AND (text = 'Questa loro condotta è una follia;'); -- 23 49:13
UPDATE "LUZZI" SET text = 'Son cacciati come pecore nel soggiorno de'' morti; la morte è il loro pastore; ed al mattino gli uomini retti li calpestano. La lor gloria ha da consumarsi nel soggiorno de'' morti, né avrà altra dimora.' WHERE "verseID" = 101260 AND (text = 'Son cacciati come pecore nel soggiorno de'' morti;'); -- 23 49:14
UPDATE "LUZZI" SET text = 'Ma Iddio riscatterà l''anima mia dal potere del soggiorno dei morti, perché mi prenderà con sé. Sela.' WHERE "verseID" = 101261 AND (text = 'Ma Iddio riscatterà l''anima mia'); -- 23 49:15
UPDATE "LUZZI" SET text = 'Non temere quand''uno s''arricchisce, quando si accresce la gloria della sua casa.' WHERE "verseID" = 101262 AND (text = 'Non temere quand''uno s''arricchisce,'); -- 23 49:16
UPDATE "LUZZI" SET text = 'Perché, quando morrà, non porterà seco nulla; la sua gloria non scenderà dietro a lui.' WHERE "verseID" = 101263 AND (text = 'Perché, quando morrà, non porterà seco nulla;'); -- 23 49:17
UPDATE "LUZZI" SET text = 'Benché tu, mentre vivi, ti reputi felice, e la gente ti lodi per i godimenti che ti procuri,' WHERE "verseID" = 101264 AND (text = 'Benché tu, mentre vivi, ti reputi felice,'); -- 23 49:18
UPDATE "LUZZI" SET text = 'tu te ne andrai alla generazione de'' tuoi padri, che non vedranno mai più la tua luce.' WHERE "verseID" = 101265 AND (text = 'tu te ne andrai alla generazione de'' tuoi padri,' OR text = 'tu te ne andrai alla generazione de'' tuoi padri, che non vedranno mai più la luce.'); -- 23 49:19
UPDATE "LUZZI" SET text = 'L''uomo ch''è in onore e non ha intendimento è simile alle bestie che periscono.' WHERE "verseID" = 101266 AND (text = 'L''uomo ch''è in onore e non ha intendimentoè simile alle bestie che periscono.'); -- 23 49:20
UPDATE "LUZZI" SET text = 'Salmo di Asaf. Il Potente, Iddio, l''Eterno ha parlato e ha convocato la terra dal sol levante al ponente.' WHERE "verseID" = 101267 AND (text = 'Salmo di Asaf.'); -- 23 50:1
UPDATE "LUZZI" SET text = 'Da Sion, perfetta in bellezza, Dio è apparso nel suo fulgore.' WHERE "verseID" = 101268 AND (text = 'Da Sion, perfetta in bellezza,'); -- 23 50:2
UPDATE "LUZZI" SET text = 'L''Iddio nostro viene e non se ne starà cheto: lo precede un fuoco divorante, lo circonda una fiera tempesta.' WHERE "verseID" = 101269 AND (text = 'L''Iddio nostro viene e non se ne starà cheto:'); -- 23 50:3
UPDATE "LUZZI" SET text = 'Egli chiama i cieli di sopra e la terra per assistere al giudicio del suo popolo:' WHERE "verseID" = 101270 AND (text = 'Egli chiama i cieli di sopra'); -- 23 50:4
UPDATE "LUZZI" SET text = 'Adunatemi, dice, i miei fedeli che han fatto meco un patto mediante sacrifizio.' WHERE "verseID" = 101271 AND (text = 'Adunatemi, dice, i miei fedeli'); -- 23 50:5
UPDATE "LUZZI" SET text = 'E i cieli proclameranno la sua giustizia; perché Dio stesso sta per giudicare. Sela.' WHERE "verseID" = 101272 AND (text = 'E i cieli proclameranno la sua giustizia;'); -- 23 50:6
UPDATE "LUZZI" SET text = 'Ascolta, popolo mio, ed io parlerò; ascolta, o Israele, e io ti farò le mie rimostranze. Io sono Iddio, l''Iddio tuo.' WHERE "verseID" = 101273 AND (text = 'Ascolta, popolo mio, ed io parlerò;'); -- 23 50:7
UPDATE "LUZZI" SET text = 'Io non ti riprenderò a motivo dei tuoi sacrifizi; i tuoi olocausti stanno dinanzi a me del continuo.' WHERE "verseID" = 101274 AND (text = 'Io non ti riprenderò a motivo dei tuoi sacrifizi;'); -- 23 50:8
UPDATE "LUZZI" SET text = 'Io non prenderò giovenchi dalla tua casa né becchi dai tuoi ovili;' WHERE "verseID" = 101275 AND (text = 'Io non prenderò giovenchi dalla tua casa'); -- 23 50:9
UPDATE "LUZZI" SET text = 'perché mie son tutte le bestie della foresta, mio è il bestiame ch''è per i monti a migliaia.' WHERE "verseID" = 101276 AND (text = 'perché mie son tutte le bestie della foresta,'); -- 23 50:10
UPDATE "LUZZI" SET text = 'Io conosco tutti gli uccelli dei monti, e quel che si muove per la campagna è a mia disposizione.' WHERE "verseID" = 101277 AND (text = 'Io conosco tutti gli uccelli dei monti,'); -- 23 50:11
UPDATE "LUZZI" SET text = 'Se avessi fame, non te lo direi, perché il mondo, con tutto quel che contiene, è mio.' WHERE "verseID" = 101278 AND (text = 'Se avessi fame, non te lo direi,'); -- 23 50:12
UPDATE "LUZZI" SET text = 'Mangio io carne di tori, o bevo io sangue di becchi?' WHERE "verseID" = 101279 AND (text = 'Mangio io carne di tori,'); -- 23 50:13
UPDATE "LUZZI" SET text = 'Offri a Dio il sacrifizio della lode, e paga all''Altissimo i tuoi voti;' WHERE "verseID" = 101280 AND (text = 'Offri a Dio il sacrifizio della lode,'); -- 23 50:14
UPDATE "LUZZI" SET text = 'e invocami nel giorno della distretta: io te ne trarrò fuori, e tu mi glorificherai.' WHERE "verseID" = 101281 AND (text = 'e invocami nel giorno della distretta:'); -- 23 50:15
UPDATE "LUZZI" SET text = 'Ma quanto all''empio, Iddio gli dice: Spetta egli a te di parlar de'' miei statuti, e di aver sulle labbra il mio patto?' WHERE "verseID" = 101282 AND (text = 'Ma quanto all''empio, Iddio gli dice:'); -- 23 50:16
UPDATE "LUZZI" SET text = 'A te che odii la correzione e ti getti dietro alle spalle le mie parole?' WHERE "verseID" = 101283 AND (text = 'A te che odii la correzione'); -- 23 50:17
UPDATE "LUZZI" SET text = 'Se vedi un ladro, tu ti diletti nella sua compagnia, e sei il socio degli adulteri.' WHERE "verseID" = 101284 AND (text = 'Se vedi un ladro, tu ti diletti nella sua compagnia,'); -- 23 50:18
UPDATE "LUZZI" SET text = 'Tu abbandoni la tua bocca al male, e la tua lingua intesse frodi.' WHERE "verseID" = 101285 AND (text = 'Tu abbandoni la tua bocca al male,'); -- 23 50:19
UPDATE "LUZZI" SET text = 'Tu siedi e parli contro il tuo fratello, tu diffami il figlio di tua madre.' WHERE "verseID" = 101286 AND (text = 'Tu siedi e parli contro il tuo fratello,'); -- 23 50:20
UPDATE "LUZZI" SET text = 'Tu hai fatto queste cose, ed io mi son taciuto, e tu hai pensato ch''io fossi del tutto come te; ma io ti riprenderò, e ti metterò tutto davanti agli occhi.' WHERE "verseID" = 101287 AND (text = 'Tu hai fatto queste cose, ed io mi son taciuto,'); -- 23 50:21
UPDATE "LUZZI" SET text = 'Deh, intendete questo, voi che dimenticate Iddio; che talora io non vi dilanii e non vi sia chi vi liberi.' WHERE "verseID" = 101288 AND (text = 'Deh, intendete questo, voi che dimenticate Iddio;'); -- 23 50:22
UPDATE "LUZZI" SET text = 'Chi mi offre il sacrifizio della lode mi glorifica, e a chi regola bene la sua condotta, io farò vedere la salvezza di Dio.' WHERE "verseID" = 101289 AND (text = 'Chi mi offre il sacrifizio della lode mi glorifica,e a chi regola bene la sua condotta,io farò vedere la salvezza di Dio.'); -- 23 50:23
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Salmo di Davide, quando il profeta Natan venne a lui, dopo che Davide era stato da Batseba. Abbi pietà di me, o Dio, secondo la tua benignità; secondo la moltitudine delle tue compassioni, cancella i miei misfatti.' WHERE "verseID" = 101290 AND (text = 'Per il Capo de'' musici. Salmo di Davide, quando il profeta Natan venne a lui, dopo che Davide era stato da Batseba.'); -- 23 51:1
UPDATE "LUZZI" SET text = 'Lavami del tutto della mia iniquità e nettami del mio peccato!' WHERE "verseID" = 101291 AND (text = 'Lavami del tutto della mia iniquità'); -- 23 51:2
UPDATE "LUZZI" SET text = 'Poiché io conosco i miei misfatti, e il mio peccato è del continuo davanti a me.' WHERE "verseID" = 101292 AND (text = 'Poiché io conosco i miei misfatti,'); -- 23 51:3
UPDATE "LUZZI" SET text = 'Io ho peccato contro te, contro te solo, e ho fatto ciò ch''è male agli occhi tuoi; lo confesso, affinché tu sia riconosciuto giusto quando parli, e irreprensibile quando giudichi.' WHERE "verseID" = 101293 AND (text = 'Io ho peccato contro te, contro te solo,'); -- 23 51:4
UPDATE "LUZZI" SET text = 'Ecco, io sono stato formato nella iniquità, e la madre mia mi ha concepito nel peccato.' WHERE "verseID" = 101294 AND (text = 'Ecco, io sono stato formato nella iniquità,'); -- 23 51:5
UPDATE "LUZZI" SET text = 'Ecco, tu ami la sincerità nell''interiore; insegnami dunque sapienza nel segreto del cuore.' WHERE "verseID" = 101295 AND (text = 'Ecco, tu ami la sincerità nell''interiore;'); -- 23 51:6
UPDATE "LUZZI" SET text = 'Purificami con l''issopo, e sarò netto; lavami, e sarò più bianco che neve.' WHERE "verseID" = 101296 AND (text = 'Purificami con l''issopo, e sarò netto;'); -- 23 51:7
UPDATE "LUZZI" SET text = 'Fammi udire gioia ed allegrezza; fa'' che le ossa che tu hai tritate festeggino.' WHERE "verseID" = 101297 AND (text = 'Fammi udire gioia ed allegrezza;'); -- 23 51:8
UPDATE "LUZZI" SET text = 'Nascondi la tua faccia dai miei peccati, e cancella tutte le mie iniquità.' WHERE "verseID" = 101298 AND (text = 'Nascondi la tua faccia dai miei peccati,'); -- 23 51:9
UPDATE "LUZZI" SET text = 'O Dio, crea in me un cuor puro e rinnova dentro di me uno spirito ben saldo.' WHERE "verseID" = 101299 AND (text = 'O Dio, crea in me un cuor puro'); -- 23 51:10
UPDATE "LUZZI" SET text = 'Non rigettarmi dalla tua presenza e non togliermi lo spirito tuo santo.' WHERE "verseID" = 101300 AND (text = 'Non rigettarmi dalla tua presenza'); -- 23 51:11
UPDATE "LUZZI" SET text = 'Rendimi la gioia della tua salvezza e fa'' che uno spirito volonteroso mi sostenga.' WHERE "verseID" = 101301 AND (text = 'Rendimi la gioia della tua salvezza'); -- 23 51:12
UPDATE "LUZZI" SET text = 'Io insegnerò le tue vie ai trasgressori, e i peccatori si convertiranno a te.' WHERE "verseID" = 101302 AND (text = 'Io insegnerò le tue vie ai trasgressori,'); -- 23 51:13
UPDATE "LUZZI" SET text = 'Liberami dal sangue versato, o Dio, Dio della mia salvezza, e la mia lingua celebrerà la tua giustizia.' WHERE "verseID" = 101303 AND (text = 'Liberami dal sangue versato, o Dio, Dio della mia salvezza,'); -- 23 51:14
UPDATE "LUZZI" SET text = 'Signore, aprimi le labbra, e la mia bocca pubblicherà la tua lode.' WHERE "verseID" = 101304 AND (text = 'Signore, aprimi le labbra,'); -- 23 51:15
UPDATE "LUZZI" SET text = 'Poiché tu non prendi piacere nei sacrifizi, altrimenti io li offrirei; tu non gradisci olocausto.' WHERE "verseID" = 101305 AND (text = 'Poiché tu non prendi piacere nei sacrifizi,'); -- 23 51:16
UPDATE "LUZZI" SET text = 'I sacrifizi di Dio sono lo spirito rotto; o Dio, tu non sprezzi il cuor rotto e contrito.' WHERE "verseID" = 101306 AND (text = 'I sacrifizi di Dio sono lo spirito rotto;'); -- 23 51:17
UPDATE "LUZZI" SET text = 'Fa'' del bene a Sion, per la tua benevolenza; edifica le mura di Gerusalemme.' WHERE "verseID" = 101307 AND (text = 'Fa'' del bene a Sion, per la tua benevolenza;'); -- 23 51:18
UPDATE "LUZZI" SET text = 'Allora prenderai piacere in sacrifizi di giustizia, in olocausti e in vittime arse per intero; allora si offriranno giovenchi sul tuo altare.' WHERE "verseID" = 101308 AND (text = 'Allora prenderai piacere in sacrifizi di giustizia,in olocausti e in vittime arse per intero;allora si offriranno giovenchi sul tuo altare.'); -- 23 51:19
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Cantico di Davide, quando Doeg l''Edomita venne a riferire a Saul che Davide era entrato in casa di Ahimelec. Perché ti glorii del male, uomo potente? La benignità di Dio dura per sempre.' WHERE "verseID" = 101309 AND (text = 'Per il Capo de'' musici. Cantico di Davide, quando Doeg l''Edomita venne a riferire a Saul che Davide era entrato in casa di Ahimelec.'); -- 23 52:1
UPDATE "LUZZI" SET text = 'La tua lingua medita rovine; essa è simile a un rasoio affilato, o artefice d''inganni.' WHERE "verseID" = 101310 AND (text = 'La tua lingua medita rovine;'); -- 23 52:2
UPDATE "LUZZI" SET text = 'Tu ami il male più che il bene, e la menzogna più che il parlar secondo giustizia. Sela.' WHERE "verseID" = 101311 AND (text = 'Tu ami il male più che il bene,'); -- 23 52:3
UPDATE "LUZZI" SET text = 'Tu ami ogni parola che cagiona distruzione, o lingua fraudolenta!' WHERE "verseID" = 101312 AND (text = 'Tu ami ogni parola che cagiona distruzione,'); -- 23 52:4
UPDATE "LUZZI" SET text = 'Iddio altresì ti distruggerà per sempre; ti afferrerà, ti strapperà dalla tua tenda e ti sradicherà dalla terra de'' viventi. Sela.' WHERE "verseID" = 101313 AND (text = 'Iddio altresì ti distruggerà per sempre;'); -- 23 52:5
UPDATE "LUZZI" SET text = 'I giusti lo vedranno e temeranno e si rideranno di quel tale, dicendo:' WHERE "verseID" = 101314 AND (text = 'I giusti lo vedranno e temeranno'); -- 23 52:6
UPDATE "LUZZI" SET text = 'Ecco l''uomo che non avea fatto di Dio la sua fortezza, ma confidava nell''abbondanza delle sue ricchezze, e si faceva forte della sua perversità!' WHERE "verseID" = 101315 AND (text = 'Ecco l''uomo che non avea fatto di Dio la sua fortezza,'); -- 23 52:7
UPDATE "LUZZI" SET text = 'Ma io sono come un ulivo verdeggiante nella casa di Dio; io confido nella benignità di Dio in sempiterno.' WHERE "verseID" = 101316 AND (text = 'Ma io sono come un ulivo verdeggiante nella casa di Dio;'); -- 23 52:8
UPDATE "LUZZI" SET text = 'Io ti celebrerò del continuo per quel che tu avrai operato, e, nel cospetto dei tuoi fedeli, spererò nel tuo nome, perch''esso è buono.' WHERE "verseID" = 101317 AND (text = 'Io ti celebrerò del continuo per quel che tu avrai operato,e, nel cospetto dei tuoi fedeli,spererò nel tuo nome, perch''esso è buono.'); -- 23 52:9
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Mestamente. Cantico di Davide. Lo stolto ha detto nel suo cuore: Non c''è Dio. Si sono corrotti, si son resi abominevoli con la loro malvagità, non v''è alcuno che faccia il bene.' WHERE "verseID" = 101318 AND (text = 'Al Capo de'' musici. Mestamente. Cantico di Davide.'); -- 23 53:1
UPDATE "LUZZI" SET text = 'Iddio ha riguardato dal cielo sui figliuoli degli uomini per vedere se vi fosse alcuno che avesse intelletto, che cercasse Iddio.' WHERE "verseID" = 101319 AND (text = 'Iddio ha riguardato dal cielo sui figliuoli degli uomini'); -- 23 53:2
UPDATE "LUZZI" SET text = 'Tutti si son tratti indietro, tutti quanti si son corrotti, non v''è alcuno che faccia il bene, neppur uno.' WHERE "verseID" = 101320 AND (text = 'Tutti si son tratti indietro, tutti quanti si son corrotti,'); -- 23 53:3
UPDATE "LUZZI" SET text = 'Son essi senza conoscenza questi operatori d''iniquità, che mangiano il mio popolo come mangiano il pane, e non invocano Iddio?' WHERE "verseID" = 101321 AND (text = 'Son essi senza conoscenza questi operatori d''iniquità,'); -- 23 53:4
UPDATE "LUZZI" SET text = 'Ecco là, son presi da grande spavento, ove prima non c''era spavento; poiché Dio ha disperse le ossa di quelli che ti assediavano; tu li hai coperti di confusione, perché Iddio li disdegna.' WHERE "verseID" = 101322 AND (text = 'Ecco là, son presi da grande spavento,'); -- 23 53:5
UPDATE "LUZZI" SET text = 'Oh chi recherà da Sion la salvezza d''Israele? Quando Iddio farà ritornare gli esuli del suo popolo, Giacobbe festeggerà, Israele si rallegrerà.' WHERE "verseID" = 101323 AND (text = 'Oh chi recherà da Sion la salvezza d''Israele?Quando Iddio farà ritornare gli esuli del suo popolo,Giacobbe festeggerà, Israele si rallegrerà.'); -- 23 53:6
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Per strumenti a corda. Cantico di Davide quando gli Zifei vennero a dire a Saul: Davide non si tiene egli nascosto fra noi? O Dio, salvami per il tuo nome, e fammi giustizia per la tua potenza.' WHERE "verseID" = 101324 AND (text = 'Per il Capo de'' musici. Per strumenti a corda. Cantico di Davide quando gli Zifei vennero a dire a Saul: Davide non si tiene egli nascosto fra noi?'); -- 23 54:1
UPDATE "LUZZI" SET text = 'O Dio, ascolta la mia preghiera, porgi orecchio alle parole della mia bocca!' WHERE "verseID" = 101325 AND (text = 'O Dio, ascolta la mia preghiera,'); -- 23 54:2
UPDATE "LUZZI" SET text = 'Poiché degli stranieri si son levati contro a me e de'' violenti cercano l''anima mia. Essi non tengono Iddio presente innanzi a loro. Sela.' WHERE "verseID" = 101326 AND (text = 'Poiché degli stranieri si son levati contro a me'); -- 23 54:3
UPDATE "LUZZI" SET text = 'Ecco, Iddio è colui che m''aiuta; il Signore è fra quelli che sostengon l''anima mia.' WHERE "verseID" = 101327 AND (text = 'Ecco, Iddio è colui che m''aiuta;'); -- 23 54:4
UPDATE "LUZZI" SET text = 'Egli farà ricadere il male sopra i miei nemici. Nella tua fedeltà, distruggili!' WHERE "verseID" = 101328 AND (text = 'Egli farà ricadere il male sopra i miei nemici.'); -- 23 54:5
UPDATE "LUZZI" SET text = 'Con animo volonteroso io t''offrirò sacrifizi; celebrerò il tuo nome, o Eterno, perch''esso è buono;' WHERE "verseID" = 101329 AND (text = 'Con animo volonteroso io t''offrirò sacrifizi;'); -- 23 54:6
UPDATE "LUZZI" SET text = 'perché m''ha liberato da ogni distretta, e l''occhio mio ha visto sui miei nemici quel che desideravo.' WHERE "verseID" = 101330 AND (text = 'perché m''ha liberato da ogni distretta,e l''occhio mio ha visto sui miei nemici quel che desideravo.'); -- 23 54:7
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Per strumenti a corda. Cantico di Davide. Porgi orecchio alla mia preghiera, o Dio, e non rifiutar di udir la mia supplicazione.' WHERE "verseID" = 101331 AND (text = 'Per il Capo de'' musici. Per strumenti a corda. Cantico di Davide.' OR text = 'Per il Capo de'' musici. Per strumenti a corda. Cantico di Davide. Porgi orecchio alla mia preghiera o Dio, e non rifiutar di udir la mia supplicazione.'); -- 23 55:1
UPDATE "LUZZI" SET text = 'Attendi a me, e rispondimi; io non ho requie nel mio lamento, e gemo,' WHERE "verseID" = 101332 AND (text = 'Attendi a me, e rispondimi;'); -- 23 55:2
UPDATE "LUZZI" SET text = 'per la voce del nemico, per l''oppressione dell''empio; poiché mi gettano addosso delle iniquità e mi perseguitano con furore.' WHERE "verseID" = 101333 AND (text = 'per la voce del nemico,'); -- 23 55:3
UPDATE "LUZZI" SET text = 'Il mio cuore spasima dentro di me e spaventi mortali mi son caduti addosso.' WHERE "verseID" = 101334 AND (text = 'Il mio cuore spasima dentro di me'); -- 23 55:4
UPDATE "LUZZI" SET text = 'Paura e tremito m''hanno assalito, e il terrore mi ha sopraffatto;' WHERE "verseID" = 101335 AND (text = 'Paura e tremito m''hanno assalito,'); -- 23 55:5
UPDATE "LUZZI" SET text = 'onde ho detto: Oh avess''io delle ali come la colomba! me ne volerei via, e troverei riposo.' WHERE "verseID" = 101336 AND (text = 'onde ho detto: Oh avess''io delle ali come la colomba!' OR text = 'onde ho detto: Oh avess''io delle ali come la colomba! Me ne volerei via, e troverei riposo.'); -- 23 55:6
UPDATE "LUZZI" SET text = 'Ecco, me ne fuggirei lontano, andrei a dimorar nel deserto; Sela.' WHERE "verseID" = 101337 AND (text = 'Ecco, me ne fuggirei lontano,'); -- 23 55:7
UPDATE "LUZZI" SET text = 'm''affretterei a ripararmi dal vento impetuoso e dalla tempesta.' WHERE "verseID" = 101338 AND (text = 'm''affretterei a ripararmi'); -- 23 55:8
UPDATE "LUZZI" SET text = 'Annienta, Signore, dividi le loro lingue, poiché io vedo violenza e rissa nella città.' WHERE "verseID" = 101339 AND (text = 'Annienta, Signore, dividi le loro lingue,'); -- 23 55:9
UPDATE "LUZZI" SET text = 'Giorno e notte essi fanno la ronda sulle sue mura; dentro di essa sono iniquità e vessazioni.' WHERE "verseID" = 101340 AND (text = 'Giorno e notte essi fanno la ronda sulle sue mura;'); -- 23 55:10
UPDATE "LUZZI" SET text = 'Malvagità è in mezzo a lei, violenza e frode non si dipartono dalle sue piazze.' WHERE "verseID" = 101341 AND (text = 'Malvagità è in mezzo a lei,'); -- 23 55:11
UPDATE "LUZZI" SET text = 'Poiché non è stato un nemico che mi ha fatto vituperio; altrimenti, l''avrei comportato; non è stato uno che m''odiasse a levarmisi contro; altrimenti, mi sarei nascosto da lui;' WHERE "verseID" = 101342 AND (text = 'Poiché non è stato un nemico che mi ha fatto vituperio;'); -- 23 55:12
UPDATE "LUZZI" SET text = 'ma sei stato tu, l''uomo ch''io stimavo come mio pari, il mio compagno e il mio intimo amico.' WHERE "verseID" = 101343 AND (text = 'ma sei stato tu, l''uomo ch''io stimavo come mio pari,'); -- 23 55:13
UPDATE "LUZZI" SET text = 'Insieme avevamo dolci colloqui, insieme ce n''andavamo tra la folla alla casa di Dio.' WHERE "verseID" = 101344 AND (text = 'Insieme avevamo dolci colloqui,'); -- 23 55:14
UPDATE "LUZZI" SET text = 'Li sorprenda la morte! Scendano vivi nel soggiorno de'' morti! poiché nelle lor dimore e dentro di loro non v''è che malvagità.' WHERE "verseID" = 101345 AND (text = 'Li sorprenda la morte!'); -- 23 55:15
UPDATE "LUZZI" SET text = 'Quanto a me: io griderò a Dio, e l''Eterno mi salverà.' WHERE "verseID" = 101346 AND (text = 'Quanto a me: io griderò a Dio,'); -- 23 55:16
UPDATE "LUZZI" SET text = 'La sera, la mattina e sul mezzodì mi lamenterò e gemerò, ed egli udrà la mia voce.' WHERE "verseID" = 101347 AND (text = 'La sera, la mattina e sul mezzodì mi lamenterò e gemerò,'); -- 23 55:17
UPDATE "LUZZI" SET text = 'Egli darà pace all''anima mia, riscuotendola dall''assalto che m''è dato, perché sono in molti contro di me.' WHERE "verseID" = 101348 AND (text = 'Egli darà pace all''anima mia,'); -- 23 55:18
UPDATE "LUZZI" SET text = 'Iddio udirà e li umilierà, egli che siede sul trono ab antico; Sela. poiché in essi non v''è mutamento, e non temono Iddio.' WHERE "verseID" = 101349 AND (text = 'Iddio udirà e li umilierà,'); -- 23 55:19
UPDATE "LUZZI" SET text = 'Il nemico ha steso la mano contro quelli ch''erano in pace con lui, ha violato il patto concluso.' WHERE "verseID" = 101350 AND (text = 'Il nemico ha steso la mano'); -- 23 55:20
UPDATE "LUZZI" SET text = 'La sua bocca è più dolce del burro, ma nel cuore ha la guerra; le sue parole son più morbide dell''olio, ma son spade sguainate.' WHERE "verseID" = 101351 AND (text = 'La sua bocca è più dolce del burro,' OR text = 'La sua bocca è più dolce del burro, ma nel cuore ha la guerra; le sue parole son più morbide dell''olio, ma sono spade sguainate.'); -- 23 55:21
UPDATE "LUZZI" SET text = 'Getta sull''Eterno il tuo peso, ed egli ti sosterrà; egli non permetterà mai che il giusto sia smosso.' WHERE "verseID" = 101352 AND (text = 'Getta sull''Eterno il tuo peso, ed egli ti sosterrà;'); -- 23 55:22
UPDATE "LUZZI" SET text = 'Ma tu, o Dio, farai cader costoro nel profondo della fossa; gli uomini di sangue e di frode non arriveranno alla metà de'' lor giorni; ma io confiderò in te.' WHERE "verseID" = 101353 AND (text = 'Ma tu, o Dio, farai cader costoro nel profondo della fossa;gli uomini di sangue e di frodenon arriveranno alla metà de'' lor giorni;ma io confiderò in te.'); -- 23 55:23
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Su: ''Colomba de'' terebinti lontani''. Inno di Davide quando i Filistei lo presero in Gat. Abbi pietà di me, o Dio, poiché gli uomini anelano a divorarmi; mi tormentano con una guerra di tutti i giorni;' WHERE "verseID" = 101354 AND (text = 'Per il Capo de'' musici. Su: ''Colomba de'' terebinti lontani''. Inno di Davide quando i Filistei lo presero in Gat.'); -- 23 56:1
UPDATE "LUZZI" SET text = 'i miei nemici anelano del continuo a divorarmi, poiché sono molti quelli che m''assalgono con superbia.' WHERE "verseID" = 101355 AND (text = 'i miei nemici anelano del continuo a divorarmi,'); -- 23 56:2
UPDATE "LUZZI" SET text = 'Nel giorno in cui temerò, io confiderò in te.' WHERE "verseID" = 101356 AND (text = 'Nel giorno in cui temerò,'); -- 23 56:3
UPDATE "LUZZI" SET text = 'Coll''aiuto di Dio celebrerò la sua parola; in Dio confido, e non temerò; che mi può fare il mortale?' WHERE "verseID" = 101357 AND (text = 'Coll''aiuto di Dio celebrerò la sua parola;'); -- 23 56:4
UPDATE "LUZZI" SET text = 'Torcon del continuo le mie parole; tutti i lor pensieri son vòlti a farmi del male.' WHERE "verseID" = 101358 AND (text = 'Torcon del continuo le mie parole;'); -- 23 56:5
UPDATE "LUZZI" SET text = 'Si radunano, stanno in agguato, spiano i miei passi, come gente che vuole la mia vita.' WHERE "verseID" = 101359 AND (text = 'Si radunano, stanno in agguato,'); -- 23 56:6
UPDATE "LUZZI" SET text = 'Rendi loro secondo la loro iniquità! O Dio, abbatti i popoli nella tua ira!' WHERE "verseID" = 101360 AND (text = 'Rendi loro secondo la loro iniquità!'); -- 23 56:7
UPDATE "LUZZI" SET text = 'Tu conti i passi della mia vita errante; raccogli le mie lacrime negli otri tuoi; non sono esse nel tuo registro?' WHERE "verseID" = 101361 AND (text = 'Tu conti i passi della mia vita errante;'); -- 23 56:8
UPDATE "LUZZI" SET text = 'Nel giorno ch''io griderò, i miei nemici indietreggeranno. Questo io so: che Dio è per me.' WHERE "verseID" = 101362 AND (text = 'Nel giorno ch''io griderò,'); -- 23 56:9
UPDATE "LUZZI" SET text = 'Coll''aiuto di Dio celebrerò la sua parola; coll''aiuto dell''Eterno celebrerò la sua parola.' WHERE "verseID" = 101363 AND (text = 'Coll''aiuto di Dio celebrerò la sua parola;'); -- 23 56:10
UPDATE "LUZZI" SET text = 'In Dio confido e non temerò; che mi può far l''uomo?' WHERE "verseID" = 101364 AND (text = 'In Dio confido e non temerò;'); -- 23 56:11
UPDATE "LUZZI" SET text = 'Tengo presenti i voti che t''ho fatti, o Dio; io t''offrirò sacrifizi di lode;' WHERE "verseID" = 101365 AND (text = 'Tengo presenti i voti che t''ho fatti, o Dio;'); -- 23 56:12
UPDATE "LUZZI" SET text = 'poiché tu hai riscosso l''anima mia dalla morte, hai guardato i miei piedi da caduta, ond''io cammini, al cospetto di Dio, nella luce de'' viventi.' WHERE "verseID" = 101366 AND (text = 'poiché tu hai riscosso l''anima mia dalla morte,hai guardato i miei piedi da caduta,ond''io cammini, al cospetto di Dio,nella luce de'' viventi.'); -- 23 56:13
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. ''Non distruggere''. Inno di Davide, quando, perseguitato da Saul, fuggì nella spelonca. Abbi pietà di me, o Dio, abbi pietà di me, perché l''anima mia cerca rifugio in te; e all''ombra delle tue ali io mi rifugio, finché le calamità siano passate.' WHERE "verseID" = 101367 AND (text = 'Per il Capo de'' musici. ''Non distruggere''. Inno di Davide, quando, perseguitato da Saul, fuggì nella spelonca.'); -- 23 57:1
UPDATE "LUZZI" SET text = 'Io griderò all''Iddio altissimo: a Dio, che compie i suoi disegni su me.' WHERE "verseID" = 101368 AND (text = 'Io griderò all''Iddio altissimo:'); -- 23 57:2
UPDATE "LUZZI" SET text = 'Egli manderà dal cielo a salvarmi. Mentre colui che anela a divorarmi m''oltraggia. Sela. Iddio manderà la sua grazia e la sua fedeltà.' WHERE "verseID" = 101369 AND (text = 'Egli manderà dal cielo a salvarmi.' OR text = 'Egli manderà dal cielo a salvarmi. Mentre colui che anela a divorarmi m''oltraggia, Sela. Iddio manderà la sua grazia e la sua fedeltà.'); -- 23 57:3
UPDATE "LUZZI" SET text = 'L''anima mia è in mezzo a leoni; dimoro tra gente che vomita fiamme, in mezzo ad uomini, i cui denti son lance e saette, e la cui lingua è una spada acuta.' WHERE "verseID" = 101370 AND (text = 'L''anima mia è in mezzo a leoni;'); -- 23 57:4
UPDATE "LUZZI" SET text = 'Innàlzati, o Dio, al disopra de'' cieli, risplenda su tutta la terra la tua gloria!' WHERE "verseID" = 101371 AND (text = 'Innàlzati, o Dio, al disopra de'' cieli,'); -- 23 57:5
UPDATE "LUZZI" SET text = 'Essi avevano teso una rete ai miei passi; l''anima mia era accasciata; avevano scavata una fossa dinanzi a me, ma essi vi son caduti dentro. Sela.' WHERE "verseID" = 101372 AND (text = 'Essi avevano teso una rete ai miei passi;'); -- 23 57:6
UPDATE "LUZZI" SET text = 'Il mio cuore è ben disposto, o Dio, il mio cuore è ben disposto; io canterò e salmeggerò.' WHERE "verseID" = 101373 AND (text = 'Il mio cuore è ben disposto,'); -- 23 57:7
UPDATE "LUZZI" SET text = 'Déstati, o gloria mia, destatevi, saltèro e cetra, io voglio risvegliare l''alba.' WHERE "verseID" = 101374 AND (text = 'Déstati, o gloria mia, destatevi, saltèro e cetra,'); -- 23 57:8
UPDATE "LUZZI" SET text = 'Io ti celebrerò fra i popoli, o Signore, a te salmeggerò fra le nazioni,' WHERE "verseID" = 101375 AND (text = 'Io ti celebrerò fra i popoli, o Signore,'); -- 23 57:9
UPDATE "LUZZI" SET text = 'perché grande fino al cielo è la tua benignità, e la tua fedeltà fino alle nuvole.' WHERE "verseID" = 101376 AND (text = 'perché grande fino al cielo è la tua benignità,'); -- 23 57:10
UPDATE "LUZZI" SET text = 'Innàlzati, o Dio, al di sopra de'' cieli, risplenda su tutta la terra la tua gloria!' WHERE "verseID" = 101377 AND (text = 'Innàlzati, o Dio, al di sopra de'' cieli,risplenda su tutta la terra la tua gloria!'); -- 23 57:11
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. ''Non distruggere''. Inno di Davide. È egli proprio secondo giustizia che voi parlate, o potenti? Giudicate voi rettamente i figliuoli degli uomini?' WHERE "verseID" = 101378 AND (text = 'Per il Capo de'' musici. ''Non distruggere''. Inno di Davide.'); -- 23 58:1
UPDATE "LUZZI" SET text = 'Anzi, nel cuore voi commettete delle iniquità; nel paese, voi gettate nella bilancia la violenza delle vostre mani.' WHERE "verseID" = 101379 AND (text = 'Anzi, nel cuore voi commettete delle iniquità;'); -- 23 58:2
UPDATE "LUZZI" SET text = 'Gli empi sono sviati fin dalla matrice, i mentitori son traviati fino dal seno materno.' WHERE "verseID" = 101380 AND (text = 'Gli empi sono sviati fin dalla matrice,'); -- 23 58:3
UPDATE "LUZZI" SET text = 'Han del veleno simile al veleno del serpente, son come l''aspide sordo che si tura le orecchie,' WHERE "verseID" = 101381 AND (text = 'Han del veleno simile al veleno del serpente,'); -- 23 58:4
UPDATE "LUZZI" SET text = 'che non ascolta la voce degl''incantatori, del mago esperto nell''affascinare.' WHERE "verseID" = 101382 AND (text = 'che non ascolta la voce degl''incantatori,'); -- 23 58:5
UPDATE "LUZZI" SET text = 'O Dio, rompi loro i denti in bocca; o Eterno, fracassa i mascellari de'' leoncelli!' WHERE "verseID" = 101383 AND (text = 'O Dio, rompi loro i denti in bocca;'); -- 23 58:6
UPDATE "LUZZI" SET text = 'Si struggano com''acqua che scorre via; quando tirano le loro frecce, sian come spuntate.' WHERE "verseID" = 101384 AND (text = 'Si struggano com''acqua che scorre via;' OR text = 'Si struggano com''acqua che scorre via; quando tirano le lor frecce, sian come spuntate.'); -- 23 58:7
UPDATE "LUZZI" SET text = 'Siano essi come lumaca che si strugge mentre va: come l''aborto d''una donna, non veggano il sole.' WHERE "verseID" = 101385 AND (text = 'Siano essi come lumaca che si strugge mentre va:'); -- 23 58:8
UPDATE "LUZZI" SET text = 'Prima che le vostre pignatte sentano il fuoco del pruno, verde od acceso che sia il legno, lo porti via la bufera.' WHERE "verseID" = 101386 AND (text = 'Prima che le vostre pignatte sentano il fuoco del pruno,'); -- 23 58:9
UPDATE "LUZZI" SET text = 'Il giusto si rallegrerà quando avrà visto la vendetta; si laverà i piedi nel sangue dell''empio;' WHERE "verseID" = 101387 AND (text = 'Il giusto si rallegrerà quando avrà visto la vendetta;'); -- 23 58:10
UPDATE "LUZZI" SET text = 'e la gente dirà: Certo, vi è una ricompensa per il giusto; certo c''è un Dio che giudica sulla terra!' WHERE "verseID" = 101388 AND (text = 'e la gente dirà: Certo, vi è una ricompensa per il giusto;certo c''è un Dio che giudica sulla terra!'); -- 23 58:11
UPDATE "LUZZI" SET text = 'Per il capo de'' musici. ''Non distruggere''. Inno di Davide, quando Saul mandò a guardargli la casa per ucciderlo. Liberami dai miei nemici, o mio Dio; ponimi in luogo alto al sicuro dai miei aggressori.' WHERE "verseID" = 101389 AND (text = 'Per il capo de'' musici. ''Non distruggere''. Inno di Davide, quando Saul mandò a guardargli la casa per ucciderlo.'); -- 23 59:1
UPDATE "LUZZI" SET text = 'Liberami dagli operatori d''iniquità, e salvami dagli uomini di sangue.' WHERE "verseID" = 101390 AND (text = 'Liberami dagli operatori d''iniquità,'); -- 23 59:2
UPDATE "LUZZI" SET text = 'Perché, ecco, essi pongono agguati all''anima mia; uomini potenti si radunano contro a me, senza che in me vi sia misfatto né peccato, o Eterno!' WHERE "verseID" = 101391 AND (text = 'Perché, ecco, essi pongono agguati all''anima mia;'); -- 23 59:3
UPDATE "LUZZI" SET text = 'Senza che in me vi sia iniquità, essi corrono e si preparano. Déstati, vieni a me, e vedi!' WHERE "verseID" = 101392 AND (text = 'Senza che in me vi sia iniquità, essi corrono e si preparano.' OR text = 'Senza che in me vi sia iniquità, essi corrono e si preparano. Dèstati, vieni a me, e vedi!'); -- 23 59:4
UPDATE "LUZZI" SET text = 'Tu, o Eterno, che sei l''Iddio degli eserciti, l''Iddio d''Israele, lèvati a visitare tutte le genti! Non far grazia ad alcuno dei perfidi malfattori! Sela.' WHERE "verseID" = 101393 AND (text = 'Tu, o Eterno, che sei l''Iddio degli eserciti, l''Iddio d''Israele,'); -- 23 59:5
UPDATE "LUZZI" SET text = 'Tornan la sera, urlano come cani e vanno attorno per la città.' WHERE "verseID" = 101394 AND (text = 'Tornan la sera, urlano come cani'); -- 23 59:6
UPDATE "LUZZI" SET text = 'Ecco, vomitano ingiurie dalla lor bocca; hanno delle spade sulle labbra. Tanto, dicono essi, chi ci ode?' WHERE "verseID" = 101395 AND (text = 'Ecco, vomitano ingiurie dalla lor bocca;'); -- 23 59:7
UPDATE "LUZZI" SET text = 'Ma tu, o Eterno, ti riderai di loro; ti farai beffe di tutte le genti.' WHERE "verseID" = 101396 AND (text = 'Ma tu, o Eterno, ti riderai di loro;'); -- 23 59:8
UPDATE "LUZZI" SET text = 'O mia forza, a te io riguarderò, perché Dio è il mio alto ricetto.' WHERE "verseID" = 101397 AND (text = 'O mia forza, a te io riguarderò,'); -- 23 59:9
UPDATE "LUZZI" SET text = 'L''Iddio mio mi verrà incontro colla sua benignità, Iddio mi farà veder sui miei nemici quel che desidero.' WHERE "verseID" = 101398 AND (text = 'L''Iddio mio mi verrà incontro colla sua benignità,'); -- 23 59:10
UPDATE "LUZZI" SET text = 'Non li uccidere, che talora il mio popolo non lo dimentichi: falli, per la tua potenza, andar vagando ed abbattili, o Signore, nostro scudo.' WHERE "verseID" = 101399 AND (text = 'Non li uccidere, che talora il mio popolo non lo dimentichi:'); -- 23 59:11
UPDATE "LUZZI" SET text = 'Ogni parola delle loro labbra è peccato della lor bocca; siano dunque presi nel laccio della lor superbia; siano presi per le maledizioni e le menzogne che proferiscono.' WHERE "verseID" = 101400 AND (text = 'Ogni parola delle loro labbra è peccato della lor bocca;' OR text = 'Ogni parola delle loro labbra è peccato della lor bocca; siano dunque presi nei laccio della lor superbia; siano presi per le maledizioni e le menzogne che proferiscono.'); -- 23 59:12
UPDATE "LUZZI" SET text = 'Distruggili nel tuo furore, distruggili sì che non siano più; e si conoscerà fino alle estremità della terra che Dio signoreggia su Giacobbe. Sela.' WHERE "verseID" = 101401 AND (text = 'Distruggili nel tuo furore, distruggili sì che non siano più;'); -- 23 59:13
UPDATE "LUZZI" SET text = 'Tornino pure la sera, urlino come cani e vadano attorno per la città.' WHERE "verseID" = 101402 AND (text = 'Tornino pure la sera, urlino come cani'); -- 23 59:14
UPDATE "LUZZI" SET text = 'Vadano vagando per trovar da mangiare, e se non trovano da saziarsi, passino così la notte.' WHERE "verseID" = 101403 AND (text = 'Vadano vagando per trovar da mangiare,'); -- 23 59:15
UPDATE "LUZZI" SET text = 'Ma io canterò la tua potenza, e al mattino loderò ad alta voce la tua benignità, perché tu sei stato per me un alto ricetto, un rifugio nel giorno della mia distretta.' WHERE "verseID" = 101404 AND (text = 'Ma io canterò la tua potenza,'); -- 23 59:16
UPDATE "LUZZI" SET text = 'O mia forza, a te salmeggerò, perché Dio è il mio alto ricetto, l''Iddio benigno per me.' WHERE "verseID" = 101405 AND (text = 'O mia forza, a te salmeggerò,perché Dio è il mio alto ricetto, l''Iddio benigno per me.'); -- 23 59:17
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Su ''il giglio della testimonianza''. Inno di Davide da insegnare; quand''egli mosse guerra ai Sirî di Mesopotamia e ai Sirî di Soba, e Joab tornò, e sconfisse 12000 Idumei nella valle del sale. O Dio, tu ci hai rigettati, ci hai dispersi, tu ti sei adirato; deh, ci ristabilisci!' WHERE "verseID" = 101406 AND (text = 'Per il Capo de'' musici. Su ''il giglio della testimonianza''. Inno di Davide da insegnare; quand''egli mosse guerra ai Sirî di Mesopotamia e ai Sirî di Soba, e Joab tornò, e sconfisse 12000 Idumei nella valle del sale.'); -- 23 60:1
UPDATE "LUZZI" SET text = 'Tu hai fatto tremare la terra, tu l''hai schiantata; restaura le sue rotture, perché vacilla.' WHERE "verseID" = 101407 AND (text = 'Tu hai fatto tremare la terra, tu l''hai schiantata;'); -- 23 60:2
UPDATE "LUZZI" SET text = 'Tu hai fatto vedere al tuo popolo cose dure; tu ci hai dato a bere un vino che stordisce.' WHERE "verseID" = 101408 AND (text = 'Tu hai fatto vedere al tuo popolo cose dure;'); -- 23 60:3
UPDATE "LUZZI" SET text = 'Ma tu hai dato a quelli che ti temono una bandiera, perché si levino in favor della verità. Sela.' WHERE "verseID" = 101409 AND (text = 'Ma tu hai dato a quelli che ti temono una bandiera,'); -- 23 60:4
UPDATE "LUZZI" SET text = 'Perché i tuoi diletti sian liberati, salvaci con la tua destra e rispondici.' WHERE "verseID" = 101410 AND (text = 'Perché i tuoi diletti sian liberati,'); -- 23 60:5
UPDATE "LUZZI" SET text = 'Iddio ha parlato nella sua santità: Io trionferò, spartirò Sichem e misurerò la valle di Succot.' WHERE "verseID" = 101411 AND (text = 'Iddio ha parlato nella sua santità:'); -- 23 60:6
UPDATE "LUZZI" SET text = 'Mio è Galaad e mio è Manasse, ed Efraim è la forte difesa del mio capo; Giuda è il mio scettro.' WHERE "verseID" = 101412 AND (text = 'Mio è Galaad e mio è Manasse,'); -- 23 60:7
UPDATE "LUZZI" SET text = 'Moab è il bacino dove mi lavo; sopra Edom getterò il mio sandalo; o Filistia, fammi delle acclamazioni!' WHERE "verseID" = 101413 AND (text = 'Moab è il bacino dove mi lavo;'); -- 23 60:8
UPDATE "LUZZI" SET text = 'Chi mi condurrà nella città forte? Chi mi menerà fino in Edom?' WHERE "verseID" = 101414 AND (text = 'Chi mi condurrà nella città forte?'); -- 23 60:9
UPDATE "LUZZI" SET text = 'Non sarai tu, o Dio, che ci hai rigettati e non esci più, o Dio, coi nostri eserciti?' WHERE "verseID" = 101415 AND (text = 'Non sarai tu, o Dio, che ci hai rigettati'); -- 23 60:10
UPDATE "LUZZI" SET text = 'Dacci aiuto per uscir dalla distretta, poiché vano è il soccorso dell''uomo.' WHERE "verseID" = 101416 AND (text = 'Dacci aiuto per uscir dalla distretta,'); -- 23 60:11
UPDATE "LUZZI" SET text = 'Con Dio noi faremo prodezze, ed egli schiaccerà i nostri nemici.' WHERE "verseID" = 101417 AND (text = 'Con Dio noi faremo prodezze,ed egli schiaccerà i nostri nemici.'); -- 23 60:12
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Per strumenti a corda. Di Davide. O Dio, ascolta il mio grido, attendi alla mia preghiera.' WHERE "verseID" = 101418 AND (text = 'Per il Capo de'' musici. Per strumenti a corda. Di Davide.'); -- 23 61:1
UPDATE "LUZZI" SET text = 'Dall''estremità della terra io grido a te, con cuore abbattuto; conducimi alla ròcca ch''è troppo alta per me;' WHERE "verseID" = 101419 AND (text = 'Dall''estremità della terra io grido a te, con cuore abbattuto;'); -- 23 61:2
UPDATE "LUZZI" SET text = 'poiché tu mi sei stato un rifugio, una forte torre dinanzi al nemico.' WHERE "verseID" = 101420 AND (text = 'poiché tu mi sei stato un rifugio,'); -- 23 61:3
UPDATE "LUZZI" SET text = 'Io dimorerò nel tuo tabernacolo per sempre, mi riparerò all''ombra delle tue ali. Sela.' WHERE "verseID" = 101421 AND (text = 'Io dimorerò nel tuo tabernacolo per sempre,'); -- 23 61:4
UPDATE "LUZZI" SET text = 'Poiché tu, o Dio, hai esaudito i miei voti, m''hai dato l''eredità di quelli che temono il tuo nome.' WHERE "verseID" = 101422 AND (text = 'Poiché tu, o Dio, hai esaudito i miei voti,'); -- 23 61:5
UPDATE "LUZZI" SET text = 'Aggiungi dei giorni ai giorni del re, siano i suoi anni come molte età!' WHERE "verseID" = 101423 AND (text = 'Aggiungi dei giorni ai giorni del re,'); -- 23 61:6
UPDATE "LUZZI" SET text = 'Segga sul trono nel cospetto di Dio in perpetuo! Ordina alla benignità e alla verità di guardarlo;' WHERE "verseID" = 101424 AND (text = 'Segga sul trono nel cospetto di Dio in perpetuo!'); -- 23 61:7
UPDATE "LUZZI" SET text = 'così salmeggerò al tuo nome in perpetuo, e adempirò ogni giorno i miei voti.' WHERE "verseID" = 101425 AND (text = 'così salmeggerò al tuo nome in perpetuo,e adempirò ogni giorno i miei voti.'); -- 23 61:8
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Per Jeduthun. Salmo di Davide. L''anima mia s''acqueta in Dio solo; da lui viene la mia salvezza.' WHERE "verseID" = 101426 AND (text = 'Per il Capo de'' musici. Per Jeduthun. Salmo di Davide.'); -- 23 62:1
UPDATE "LUZZI" SET text = 'Egli solo è la mia rocca e la mia salvezza, il mio alto ricetto; io non sarò grandemente smosso.' WHERE "verseID" = 101427 AND (text = 'Egli solo è la mia rocca e la mia salvezza,'); -- 23 62:2
UPDATE "LUZZI" SET text = 'Fino a quando vi avventerete sopra un uomo e cercherete tutti insieme di abbatterlo come una parete che pende, come un muricciuolo che cede?' WHERE "verseID" = 101428 AND (text = 'Fino a quando vi avventerete sopra un uomo'); -- 23 62:3
UPDATE "LUZZI" SET text = 'Essi non pensano che a farlo cadere dalla sua altezza; prendon piacere nella menzogna; benedicono con la bocca, ma internamente maledicono. Sela.' WHERE "verseID" = 101429 AND (text = 'Essi non pensano che a farlo cadere dalla sua altezza;'); -- 23 62:4
UPDATE "LUZZI" SET text = 'Anima mia, acquétati in Dio solo, poiché da lui viene la mia speranza.' WHERE "verseID" = 101430 AND (text = 'Anima mia, acquétati in Dio solo,'); -- 23 62:5
UPDATE "LUZZI" SET text = 'Egli solo è la mia ròcca e la mia salvezza; egli è il mio alto ricetto; io non sarò smosso.' WHERE "verseID" = 101431 AND (text = 'Egli solo è la mia ròcca e la mia salvezza;'); -- 23 62:6
UPDATE "LUZZI" SET text = 'In Dio è la mia salvezza e la mia gloria; la mia forte ròcca e il mio rifugio sono in Dio.' WHERE "verseID" = 101432 AND (text = 'In Dio è la mia salvezza e la mia gloria;'); -- 23 62:7
UPDATE "LUZZI" SET text = 'Confida in lui ogni tempo, o popolo; espandi il tuo cuore nel suo cospetto; Dio è il nostro rifugio. Sela.' WHERE "verseID" = 101433 AND (text = 'Confida in lui ogni tempo, o popolo;'); -- 23 62:8
UPDATE "LUZZI" SET text = 'Gli uomini del volgo non sono che vanità, e i nobili non sono che menzogna; messi sulla bilancia vanno su, tutti assieme son più leggeri della vanità.' WHERE "verseID" = 101434 AND (text = 'Gli uomini del volgo non sono che vanità,'); -- 23 62:9
UPDATE "LUZZI" SET text = 'Non confidate nell''oppressione, e non mettete vane speranze nella rapina; se le ricchezze abbondano, non vi mettete il cuore.' WHERE "verseID" = 101435 AND (text = 'Non confidate nell''oppressione,'); -- 23 62:10
UPDATE "LUZZI" SET text = 'Dio ha parlato una volta, due volte ho udito questo: Che la potenza appartiene a Dio;' WHERE "verseID" = 101436 AND (text = 'Dio ha parlato una volta,' OR text = 'Dio ha parlato una volta, due volte ho udito questo: che la potenza appartiene a Dio;'); -- 23 62:11
UPDATE "LUZZI" SET text = 'e a te pure, o Signore, appartiene la misericordia; perché tu renderai a ciascuno secondo le sue opere.' WHERE "verseID" = 101437 AND (text = 'e a te pure, o Signore, appartiene la misericordia;perché tu renderai a ciascuno secondo le sue opere.'); -- 23 62:12
UPDATE "LUZZI" SET text = 'Salmo di Davide: quand''era nel deserto di Giuda. O Dio, tu sei l''Iddio mio, io ti cerco dall''alba; l''anima mia è assetata di te, la mia carne ti brama in una terra arida, che langue, senz''acqua.' WHERE "verseID" = 101438 AND (text = 'Salmo di Davide: quand''era nel deserto di Giuda.'); -- 23 63:1
UPDATE "LUZZI" SET text = 'Così t''ho io mirato nel santuario per veder la tua forza e la tua gloria.' WHERE "verseID" = 101439 AND (text = 'Così t''ho io mirato nel santuario'); -- 23 63:2
UPDATE "LUZZI" SET text = 'Poiché la tua benignità val meglio della vita; le mie labbra ti loderanno.' WHERE "verseID" = 101440 AND (text = 'Poiché la tua benignità val meglio della vita;'); -- 23 63:3
UPDATE "LUZZI" SET text = 'Così ti benedirò finché io viva, e alzerò le mani invocando il tuo nome.' WHERE "verseID" = 101441 AND (text = 'Così ti benedirò finché io viva,'); -- 23 63:4
UPDATE "LUZZI" SET text = 'L''anima mia sarà saziata come di midollo e di grasso, e la mia bocca ti loderà con labbra giubilanti.' WHERE "verseID" = 101442 AND (text = 'L''anima mia sarà saziata come di midollo e di grasso,'); -- 23 63:5
UPDATE "LUZZI" SET text = 'Quand''io mi ricordo di te sul mio letto, medito di te nelle veglie della notte.' WHERE "verseID" = 101443 AND (text = 'Quand''io mi ricordo di te sul mio letto,'); -- 23 63:6
UPDATE "LUZZI" SET text = 'Poiché tu sei stato il mio aiuto, ed io giubilo all''ombra delle tue ali.' WHERE "verseID" = 101444 AND (text = 'Poiché tu sei stato il mio aiuto,'); -- 23 63:7
UPDATE "LUZZI" SET text = 'L''anima mia s''attacca a te per seguirti; la tua destra mi sostiene.' WHERE "verseID" = 101445 AND (text = 'L''anima mia s''attacca a te per seguirti;'); -- 23 63:8
UPDATE "LUZZI" SET text = 'Ma costoro che cercano la rovina dell''anima mia, entreranno nelle parti più basse della terra.' WHERE "verseID" = 101446 AND (text = 'Ma costoro che cercano la rovina dell''anima mia,'); -- 23 63:9
UPDATE "LUZZI" SET text = 'Saran dati in balìa della spada, saranno la preda degli sciacalli.' WHERE "verseID" = 101447 AND (text = 'Saran dati in balìa della spada,'); -- 23 63:10
UPDATE "LUZZI" SET text = 'Ma il re si rallegrerà in Dio; chiunque giura per lui si glorierà, perché la bocca di quelli che dicon menzogne sarà turata.' WHERE "verseID" = 101448 AND (text = 'Ma il re si rallegrerà in Dio;chiunque giura per lui si glorierà,perché la bocca di quelli che dicon menzogne sarà turata.'); -- 23 63:11
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Salmo di Davide. O Dio, ascolta la mia voce nel mio lamento! Guarda la mia vita dallo spavento del nemico.' WHERE "verseID" = 101449 AND (text = 'Per il Capo de'' musici. Salmo di Davide.'); -- 23 64:1
UPDATE "LUZZI" SET text = 'Mettimi al coperto dalle trame de'' maligni, dalla turba degli operatori d''iniquità,' WHERE "verseID" = 101450 AND (text = 'Mettimi al coperto dalle trame de'' maligni,'); -- 23 64:2
UPDATE "LUZZI" SET text = 'che hanno aguzzato la loro lingua come una spada e hanno scoccato come frecce le loro parole amare,' WHERE "verseID" = 101451 AND (text = 'che hanno aguzzato la loro lingua come una spada'); -- 23 64:3
UPDATE "LUZZI" SET text = 'per colpire da luoghi nascosti l''uomo integro; lo colpiscono all''improvviso, e non hanno paura.' WHERE "verseID" = 101452 AND (text = 'per colpire da luoghi nascosti l''uomo integro;'); -- 23 64:4
UPDATE "LUZZI" SET text = 'S''incoraggiano a vicenda in un''impresa malvagia; concertano di tender lacci di nascosto; e dicono: Chi li vedrà?' WHERE "verseID" = 101453 AND (text = 'S''incoraggiano a vicenda in un''impresa malvagia;'); -- 23 64:5
UPDATE "LUZZI" SET text = 'Divisano nequizia e dicono: Abbiam compiuto il nostro divisamento. L''intimo pensiero e il cuore d''ognun di loro è un abisso.' WHERE "verseID" = 101454 AND (text = 'Divisano nequizia e dicono:'); -- 23 64:6
UPDATE "LUZZI" SET text = 'Ma Dio scoccherà contro di essi le sue frecce, e subito saran coperti di ferite;' WHERE "verseID" = 101455 AND (text = 'Ma Dio scoccherà contro di essi le sue frecce,'); -- 23 64:7
UPDATE "LUZZI" SET text = 'saranno fatti cadere; e il male fatto dalle loro lingue ricadrà su loro. Tutti quelli che li vedranno scrolleranno il capo,' WHERE "verseID" = 101456 AND (text = 'saranno fatti cadere;'); -- 23 64:8
UPDATE "LUZZI" SET text = 'e tutti gli uomini temeranno, e racconteranno l''opera di Dio, e considereranno quello ch''egli avrà fatto.' WHERE "verseID" = 101457 AND (text = 'e tutti gli uomini temeranno,'); -- 23 64:9
UPDATE "LUZZI" SET text = 'Il giusto si rallegrerà nell''Eterno e in lui cercherà rifugio; e tutti i diritti di cuore si glorieranno.' WHERE "verseID" = 101458 AND (text = 'Il giusto si rallegrerà nell''Eterno e in lui cercherà rifugio;e tutti i diritti di cuore si glorieranno.'); -- 23 64:10
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Salmo di Davide. Canto. A te, o Dio, nel raccoglimento, sale la lode in Sion, a te l''omaggio dei voti che si compiono.' WHERE "verseID" = 101459 AND (text = 'Per il Capo de'' musici. Salmo di Davide. Canto.'); -- 23 65:1
UPDATE "LUZZI" SET text = 'O tu ch''esaudisci la preghiera, ogni carne verrà a te.' WHERE "verseID" = 101460 AND (text = 'O tu ch''esaudisci la preghiera,'); -- 23 65:2
UPDATE "LUZZI" SET text = 'Le iniquità mi hanno sopraffatto, ma tu farai l''espiazione delle nostre trasgressioni.' WHERE "verseID" = 101461 AND (text = 'Le iniquità mi hanno sopraffatto,'); -- 23 65:3
UPDATE "LUZZI" SET text = 'Beato colui che tu eleggi e fai accostare a te perché abiti ne'' tuoi cortili! Noi sarem saziati de'' beni della tua casa, della santità del tuo tempio.' WHERE "verseID" = 101462 AND (text = 'Beato colui che tu eleggi e fai accostare a te'); -- 23 65:4
UPDATE "LUZZI" SET text = 'In modi tremendi tu ci rispondi, nella tua giustizia, o Dio della nostra salvezza, confidanza di tutte le estremità della terra e dei mari lontani.' WHERE "verseID" = 101463 AND (text = 'In modi tremendi tu ci rispondi, nella tua giustizia,'); -- 23 65:5
UPDATE "LUZZI" SET text = 'Egli con la sua potenza rende stabili i monti; egli è cinto di forza.' WHERE "verseID" = 101464 AND (text = 'Egli con la sua potenza rende stabili i monti;'); -- 23 65:6
UPDATE "LUZZI" SET text = 'Egli acqueta il rumore de'' mari, il rumore de'' loro flutti, e il tumulto de'' popoli.' WHERE "verseID" = 101465 AND (text = 'Egli acqueta il rumore de'' mari, il rumore de'' loro flutti,'); -- 23 65:7
UPDATE "LUZZI" SET text = 'Perciò quelli che abitano alle estremità della terra temono alla vista de'' tuoi prodigi; tu fai giubilare i luoghi ond''escono la mattina e la sera.' WHERE "verseID" = 101466 AND (text = 'Perciò quelli che abitano alle estremità della terra temono'); -- 23 65:8
UPDATE "LUZZI" SET text = 'Tu visiti la terra e l''adacqui, tu l''arricchisci grandemente. I ruscelli di Dio son pieni d''acqua; tu prepari agli uomini il grano, quando prepari così la terra;' WHERE "verseID" = 101467 AND (text = 'Tu visiti la terra e l''adacqui,'); -- 23 65:9
UPDATE "LUZZI" SET text = 'tu adacqui largamente i suoi solchi, ne pareggi le zolle, l''ammollisci con le piogge, ne benedici i germogli.' WHERE "verseID" = 101468 AND (text = 'tu adacqui largamente i suoi solchi,'); -- 23 65:10
UPDATE "LUZZI" SET text = 'Tu coroni de'' tuoi beni l''annata, e dove passa il tuo carro stilla il grasso.' WHERE "verseID" = 101469 AND (text = 'Tu coroni de'' tuoi beni l''annata,'); -- 23 65:11
UPDATE "LUZZI" SET text = 'Esso stilla sui pascoli del deserto, e i colli son cinti di gioia.' WHERE "verseID" = 101470 AND (text = 'Esso stilla sui pascoli del deserto,'); -- 23 65:12
UPDATE "LUZZI" SET text = 'I pascoli si riveston di greggi, e le valli si copron di frumento; dan voci di allegrezza e cantano.' WHERE "verseID" = 101471 AND (text = 'I pascoli si riveston di greggi,e le valli si copron di frumento;dan voci di allegrezza e cantano.'); -- 23 65:13
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Canto. Salmo. Fate acclamazioni a Dio, voi tutti abitanti della terra!' WHERE "verseID" = 101472 AND (text = 'Al Capo de'' musici. Canto. Salmo.'); -- 23 66:1
UPDATE "LUZZI" SET text = 'Cantate la gloria del suo nome, rendete gloriosa la sua lode!' WHERE "verseID" = 101473 AND (text = 'Cantate la gloria del suo nome,'); -- 23 66:2
UPDATE "LUZZI" SET text = 'Dite a Dio: Come son tremende le opere tue! Per la grandezza della tua forza i tuoi nemici ti aduleranno.' WHERE "verseID" = 101474 AND (text = 'Dite a Dio: Come son tremende le opere tue!'); -- 23 66:3
UPDATE "LUZZI" SET text = 'Tutta la terra si prostrerà dinanzi a te e a te salmeggerà, salmeggerà al tuo nome. Sela.' WHERE "verseID" = 101475 AND (text = 'Tutta la terra si prostrerà dinanzi a te'); -- 23 66:4
UPDATE "LUZZI" SET text = 'Venite e mirate le opere di Dio; egli è tremendo ne'' suoi atti verso i figliuoli degli uomini.' WHERE "verseID" = 101476 AND (text = 'Venite e mirate le opere di Dio;'); -- 23 66:5
UPDATE "LUZZI" SET text = 'Egli mutò il mare in terra asciutta; il popolo passò il fiume a piedi; quivi ci rallegrammo in lui.' WHERE "verseID" = 101477 AND (text = 'Egli mutò il mare in terra asciutta;'); -- 23 66:6
UPDATE "LUZZI" SET text = 'Egli, con la sua potenza, signoreggia in eterno; i suoi occhi osservan le nazioni; i ribelli non facciano i superbi! Sela.' WHERE "verseID" = 101478 AND (text = 'Egli, con la sua potenza, signoreggia in eterno;'); -- 23 66:7
UPDATE "LUZZI" SET text = 'Benedite il nostro Dio, o popoli, e fate risonar la voce della sua lode!' WHERE "verseID" = 101479 AND (text = 'Benedite il nostro Dio, o popoli,'); -- 23 66:8
UPDATE "LUZZI" SET text = 'Egli ha conservato in vita l''anima nostra, e non ha permesso che il nostro piè vacillasse.' WHERE "verseID" = 101480 AND (text = 'Egli ha conservato in vita l''anima nostra,' OR text = 'Egli ha conservato in vita l''anima nostra, non ha permesso che il nostro piè vacillasse.'); -- 23 66:9
UPDATE "LUZZI" SET text = 'Poiché tu ci hai provati, o Dio, ci hai passati al crogiuolo come l''argento.' WHERE "verseID" = 101481 AND (text = 'Poiché tu ci hai provati, o Dio,'); -- 23 66:10
UPDATE "LUZZI" SET text = 'Ci hai fatti entrar nella rete, hai posto un grave peso sulle nostre reni.' WHERE "verseID" = 101482 AND (text = 'Ci hai fatti entrar nella rete,'); -- 23 66:11
UPDATE "LUZZI" SET text = 'Hai fatto cavalcar degli uomini sul nostro capo; siamo entrati nel fuoco e nell''acqua, ma tu ci traesti fuori in luogo di refrigerio.' WHERE "verseID" = 101483 AND (text = 'Hai fatto cavalcar degli uomini sul nostro capo;'); -- 23 66:12
UPDATE "LUZZI" SET text = 'Io entrerò nella tua casa con olocausti, ti pagherò i miei voti,' WHERE "verseID" = 101484 AND (text = 'Io entrerò nella tua casa con olocausti,'); -- 23 66:13
UPDATE "LUZZI" SET text = 'i voti che le mie labbra han proferito, che la mia bocca ha pronunziato nella mia distretta.' WHERE "verseID" = 101485 AND (text = 'i voti che le mie labbra han proferito,'); -- 23 66:14
UPDATE "LUZZI" SET text = 'Io t''offrirò olocausti di bestie grasse, con profumo di montoni; sacrificherò buoi e becchi. Sela.' WHERE "verseID" = 101486 AND (text = 'Io t''offrirò olocausti di bestie grasse,'); -- 23 66:15
UPDATE "LUZZI" SET text = 'Venite e ascoltate, o voi tutti che temete Iddio! Io vi racconterò quel ch''egli ha fatto per l''anima mia.' WHERE "verseID" = 101487 AND (text = 'Venite e ascoltate, o voi tutti che temete Iddio!'); -- 23 66:16
UPDATE "LUZZI" SET text = 'Io gridai a lui con la mia bocca, ed egli fu esaltato dalla mia lingua.' WHERE "verseID" = 101488 AND (text = 'Io gridai a lui con la mia bocca,'); -- 23 66:17
UPDATE "LUZZI" SET text = 'Se nel mio cuore avessi avuto di mira l''iniquità, il Signore non m''avrebbe ascoltato.' WHERE "verseID" = 101489 AND (text = 'Se nel mio cuore avessi avuto di mira l''iniquità,'); -- 23 66:18
UPDATE "LUZZI" SET text = 'Ma certo Iddio m''ha ascoltato; egli ha atteso alla voce della mia preghiera.' WHERE "verseID" = 101490 AND (text = 'Ma certo Iddio m''ha ascoltato;'); -- 23 66:19
UPDATE "LUZZI" SET text = 'Benedetto sia Iddio, che non ha rigettato la mia preghiera, né m''ha ritirato la sua benignità.' WHERE "verseID" = 101491 AND (text = 'Benedetto sia Iddio,che non ha rigettato la mia preghiera,né m''ha ritirato la sua benignità.'); -- 23 66:20
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Per strumenti a corda. Salmo. Canto. Iddio abbia mercé di noi, e ci benedica, Iddio faccia risplendere il suo volto su noi; Sela.' WHERE "verseID" = 101492 AND (text = 'Per il Capo de'' musici. Per strumenti a corda. Salmo. Canto.'); -- 23 67:1
UPDATE "LUZZI" SET text = 'affinché la tua via sia conosciuta sulla terra, e la tua salvezza fra tutte le genti.' WHERE "verseID" = 101493 AND (text = 'affinché la tua via sia conosciuta sulla terra,'); -- 23 67:2
UPDATE "LUZZI" SET text = 'Ti celebrino i popoli, o Dio, tutti quanti i popoli ti celebrino!' WHERE "verseID" = 101494 AND (text = 'Ti celebrino i popoli, o Dio,'); -- 23 67:3
UPDATE "LUZZI" SET text = 'Le nazioni si rallegrino e giubilino, perché tu giudichi i popoli con equità, e sei la guida delle nazioni sulla terra. Sela.' WHERE "verseID" = 101495 AND (text = 'Le nazioni si rallegrino e giubilino,'); -- 23 67:4
UPDATE "LUZZI" SET text = 'Ti celebrino i popoli, o Dio, tutti quanti i popoli ti celebrino!' WHERE "verseID" = 101496 AND (text = 'Ti celebrino i popoli, o Dio,'); -- 23 67:5
UPDATE "LUZZI" SET text = 'La terra ha prodotto il suo frutto; Dio, l''Iddio nostro, ci benedirà.' WHERE "verseID" = 101497 AND (text = 'La terra ha prodotto il suo frutto;'); -- 23 67:6
UPDATE "LUZZI" SET text = 'Iddio ci benedirà, e tutte le estremità della terra lo temeranno.' WHERE "verseID" = 101498 AND (text = 'Iddio ci benedirà,e tutte le estremità della terra lo temeranno.'); -- 23 67:7
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Di Davide. Salmo. Canto. Lèvisi Iddio, e i suoi nemici saranno dispersi, e quelli che l''odiano fuggiranno dinanzi a lui.' WHERE "verseID" = 101499 AND (text = 'Al Capo de'' musici. Di Davide. Salmo. Canto.'); -- 23 68:1
UPDATE "LUZZI" SET text = 'Tu li dissiperai come si dissipa il fumo; come la cera si strugge dinanzi al fuoco, così periranno gli empi dinanzi a Dio.' WHERE "verseID" = 101500 AND (text = 'Tu li dissiperai come si dissipa il fumo;'); -- 23 68:2
UPDATE "LUZZI" SET text = 'Ma i giusti si rallegreranno, esulteranno nel cospetto di Dio, e gioiranno con letizia.' WHERE "verseID" = 101501 AND (text = 'Ma i giusti si rallegreranno, esulteranno nel cospetto di Dio,'); -- 23 68:3
UPDATE "LUZZI" SET text = 'Cantate a Dio, salmeggiate al suo nome, preparate la via a colui che cavalca attraverso i deserti; il suo nome è: l''Eterno, ed esultate dinanzi a lui.' WHERE "verseID" = 101502 AND (text = 'Cantate a Dio, salmeggiate al suo nome,'); -- 23 68:4
UPDATE "LUZZI" SET text = 'Padre degli orfani e difensore delle vedove è Iddio nella dimora della sua santità;' WHERE "verseID" = 101503 AND (text = 'Padre degli orfani e difensore delle vedove è Iddio'); -- 23 68:5
UPDATE "LUZZI" SET text = 'Iddio dona al solitario una famiglia, trae fuori i prigionieri e dà loro prosperità; solo i ribelli dimorano in terra arida.' WHERE "verseID" = 101504 AND (text = 'Iddio dona al solitario una famiglia,'); -- 23 68:6
UPDATE "LUZZI" SET text = 'O Dio, quando tu uscisti davanti al tuo popolo, quando ti avanzasti attraverso il deserto, Sela.' WHERE "verseID" = 101505 AND (text = 'O Dio, quando tu uscisti davanti al tuo popolo,'); -- 23 68:7
UPDATE "LUZZI" SET text = 'la terra tremò; anche i cieli si strussero in pioggia per la presenza di Dio; lo stesso Sinai tremò alla presenza di Dio, dell''Iddio d''Israele.' WHERE "verseID" = 101506 AND (text = 'la terra tremò;'); -- 23 68:8
UPDATE "LUZZI" SET text = 'O Dio, tu spandesti una pioggia di benefizî sulla tua eredità; quand''essa era sfinita, tu la ristorasti.' WHERE "verseID" = 101507 AND (text = 'O Dio, tu spandesti una pioggia di benefizî sulla tua eredità;'); -- 23 68:9
UPDATE "LUZZI" SET text = 'La tua greggia prese dimora nel paese, che tu avevi, o Dio, preparato nella tua bontà pei miseri.' WHERE "verseID" = 101508 AND (text = 'La tua greggia prese dimora nel paese,'); -- 23 68:10
UPDATE "LUZZI" SET text = 'Il Signore dà un ordine: le messaggere di buone novelle sono una grande schiera.' WHERE "verseID" = 101509 AND (text = 'Il Signore dà un ordine:'); -- 23 68:11
UPDATE "LUZZI" SET text = 'I re degli eserciti fuggono, fuggono, e la rimasta a casa divide le spoglie.' WHERE "verseID" = 101510 AND (text = 'I re degli eserciti fuggono, fuggono,'); -- 23 68:12
UPDATE "LUZZI" SET text = 'Quando vi siete riposati tra gli ovili, le ali della colomba si son coperte d''argento, e le sue penne hanno preso il giallo dell''oro.' WHERE "verseID" = 101511 AND (text = 'Quando vi siete riposati tra gli ovili,'); -- 23 68:13
UPDATE "LUZZI" SET text = 'Quando l''Onnipotente disperse i re nel paese, lo Tsalmon si coperse di neve.' WHERE "verseID" = 101512 AND (text = 'Quando l''Onnipotente disperse i re nel paese,'); -- 23 68:14
UPDATE "LUZZI" SET text = 'O monte di Dio, o monte di Basan, o monte dalle molte cime, o monte di Basan,' WHERE "verseID" = 101513 AND (text = 'O monte di Dio, o monte di Basan,'); -- 23 68:15
UPDATE "LUZZI" SET text = 'perché, o monti dalle molte cime, guardate con invidia al monte che Dio s''è scelto per sua dimora? Sì, l''Eterno vi abiterà in perpetuo.' WHERE "verseID" = 101514 AND (text = 'perché, o monti dalle molte cime, guardate con invidia'); -- 23 68:16
UPDATE "LUZZI" SET text = 'I carri di Dio si contano a miriadi e miriadi, a migliaia di migliaia; il Signore viene dal Sinai nel santuario.' WHERE "verseID" = 101515 AND (text = 'I carri di Dio si contano a miriadi e miriadi,'); -- 23 68:17
UPDATE "LUZZI" SET text = 'Tu sei salito in alto, hai menato in cattività dei prigioni, hai preso doni dagli uomini, anche dai ribelli, per far quivi la tua dimora, o Eterno Iddio.' WHERE "verseID" = 101516 AND (text = 'Tu sei salito in alto, hai menato in cattività dei prigioni,'); -- 23 68:18
UPDATE "LUZZI" SET text = 'Sia benedetto il Signore! Giorno per giorno porta per noi il nostro peso; egli ch''è l''Iddio della nostra salvezza. Sela.' WHERE "verseID" = 101517 AND (text = 'Sia benedetto il Signore! Giorno per giorno'); -- 23 68:19
UPDATE "LUZZI" SET text = 'Iddio è per noi l''Iddio delle liberazioni; e all''Eterno, al Signore, appartiene il preservar dalla morte.' WHERE "verseID" = 101518 AND (text = 'Iddio è per noi l''Iddio delle liberazioni;'); -- 23 68:20
UPDATE "LUZZI" SET text = 'Ma Dio schiaccerà il capo de'' suoi nemici, la testa chiomata di colui che cammina nelle sue colpe.' WHERE "verseID" = 101519 AND (text = 'Ma Dio schiaccerà il capo de'' suoi nemici,'); -- 23 68:21
UPDATE "LUZZI" SET text = 'Il Signore ha detto: Io ti ritrarrò da Basan, ti ritrarrò dalle profondità del mare,' WHERE "verseID" = 101520 AND (text = 'Il Signore ha detto: Io ti ritrarrò da Basan,'); -- 23 68:22
UPDATE "LUZZI" SET text = 'affinché tu affondi il tuo piè nel sangue, e la lingua de'' tuoi cani abbia la sua parte de'' tuoi nemici.' WHERE "verseID" = 101521 AND (text = 'affinché tu affondi il tuo piè nel sangue,'); -- 23 68:23
UPDATE "LUZZI" SET text = 'Essi han veduto la tua entrata, o Dio, l''entrata del mio Dio, del mio Re, nel santuario.' WHERE "verseID" = 101522 AND (text = 'Essi han veduto la tua entrata, o Dio,'); -- 23 68:24
UPDATE "LUZZI" SET text = 'Precedevano i cantori, dietro venivano i sonatori, in mezzo alle fanciulle, che battevano i tamburi.' WHERE "verseID" = 101523 AND (text = 'Precedevano i cantori, dietro venivano i sonatori,'); -- 23 68:25
UPDATE "LUZZI" SET text = 'Benedite Iddio nelle raunanze, benedite il Signore, voi che siete della fonte d''Israele!' WHERE "verseID" = 101524 AND (text = 'Benedite Iddio nelle raunanze,'); -- 23 68:26
UPDATE "LUZZI" SET text = 'Ecco il piccolo Beniamino, che domina gli altri; i principi di Giuda e la loro schiera, i principi di Zabulon, i principi di Neftali.' WHERE "verseID" = 101525 AND (text = 'Ecco il piccolo Beniamino, che domina gli altri;'); -- 23 68:27
UPDATE "LUZZI" SET text = 'Il tuo Dio ha ordinato la tua forza; rafferma, o Dio, ciò che hai operato per noi!' WHERE "verseID" = 101526 AND (text = 'Il tuo Dio ha ordinato la tua forza;'); -- 23 68:28
UPDATE "LUZZI" SET text = 'Nel tuo tempio, ch''è sopra Gerusalemme, i re ti recheranno doni.' WHERE "verseID" = 101527 AND (text = 'Nel tuo tempio, ch''è sopra Gerusalemme,'); -- 23 68:29
UPDATE "LUZZI" SET text = 'Minaccia la bestia de'' canneti, la moltitudine de'' tori coi giovenchi de'' popoli, che si prostrano recando verghe d''argento. Dissipa i popoli che si dilettano in guerre.' WHERE "verseID" = 101528 AND (text = 'Minaccia la bestia de'' canneti,'); -- 23 68:30
UPDATE "LUZZI" SET text = 'Gran signori verranno dall''Egitto, l''Etiopia s''affretterà a tender le mani verso Dio.' WHERE "verseID" = 101529 AND (text = 'Gran signori verranno dall''Egitto,'); -- 23 68:31
UPDATE "LUZZI" SET text = 'O regni della terra, cantate a Dio, salmeggiate al Signore, Sela.' WHERE "verseID" = 101530 AND (text = 'O regni della terra, cantate a Dio,'); -- 23 68:32
UPDATE "LUZZI" SET text = 'a colui che cavalca sui cieli dei cieli eterni! Ecco, egli fa risonar la sua voce, la sua voce potente.' WHERE "verseID" = 101531 AND (text = 'a colui che cavalca sui cieli dei cieli eterni!'); -- 23 68:33
UPDATE "LUZZI" SET text = 'Riconoscete la potenza di Dio; la sua maestà è sopra Israele, e la sua potenza è ne'' cieli.' WHERE "verseID" = 101532 AND (text = 'Riconoscete la potenza di Dio;'); -- 23 68:34
UPDATE "LUZZI" SET text = 'O Dio, tu sei tremendo dai tuoi santuari! L''Iddio d''Israele è quel che dà forza e potenza al suo popolo. Benedetto sia Iddio!' WHERE "verseID" = 101533 AND (text = 'O Dio, tu sei tremendo dai tuoi santuari!L''Iddio d''Israele è quel che dà forza e potenza al suo popolo.Benedetto sia Iddio!'); -- 23 68:35
UPDATE "LUZZI" SET text = 'Al Capo de'' musici. Sopra ''i gigli''. Di Davide. Salvami, o Dio, poiché le acque mi son giunte fino all''anima.' WHERE "verseID" = 101534 AND (text = 'Al Capo de'' musici. Sopra ''i gigli''. Di Davide.'); -- 23 69:1
UPDATE "LUZZI" SET text = 'Io sono affondato in un profondo pantano, ove non v''è da fermare il piede; son giunto in acque profonde e la corrente mi sommerge.' WHERE "verseID" = 101535 AND (text = 'Io sono affondato in un profondo pantano,'); -- 23 69:2
UPDATE "LUZZI" SET text = 'Sono stanco di gridare, la mia gola è riarsa; gli occhi mi vengon meno, mentre aspetto il mio Dio.' WHERE "verseID" = 101536 AND (text = 'Sono stanco di gridare, la mia gola è riarsa;'); -- 23 69:3
UPDATE "LUZZI" SET text = 'Quelli che m''odiano senza cagione sono più numerosi de'' capelli del mio capo; sono potenti quelli che mi vorrebbero distrutto e che a torto mi sono nemici; perfino quello che non avevo preso, l''ho dovuto restituire.' WHERE "verseID" = 101537 AND (text = 'Quelli che m''odiano senza cagione'); -- 23 69:4
UPDATE "LUZZI" SET text = 'O Dio, tu conosci la mia follia, e le mie colpe non ti sono occulte.' WHERE "verseID" = 101538 AND (text = 'O Dio, tu conosci la mia follia,'); -- 23 69:5
UPDATE "LUZZI" SET text = 'Non sian confusi, per cagion mia, quelli che sperano in te, o Signore, Eterno degli eserciti! Non siano svergognati per cagion mia, quelli che ti cercano, o Dio d''Israele!' WHERE "verseID" = 101539 AND (text = 'Non sian confusi, per cagion mia, quelli che sperano in te,'); -- 23 69:6
UPDATE "LUZZI" SET text = 'Perché per amor tuo io porto il vituperio, e la vergogna mi copre la faccia.' WHERE "verseID" = 101540 AND (text = 'Perché per amor tuo io porto il vituperio,'); -- 23 69:7
UPDATE "LUZZI" SET text = 'Io son divenuto un estraneo ai miei fratelli, e un forestiero, ai figliuoli di mia madre.' WHERE "verseID" = 101541 AND (text = 'Io son divenuto un estraneo ai miei fratelli,' OR text = 'Io son divenuto un estraneo ai miei fratelli, e un forestiero ai figliuoli di mia madre.'); -- 23 69:8
UPDATE "LUZZI" SET text = 'Poiché lo zelo della tua casa mi ha roso, e i vituperî di quelli che ti vituperano son caduti su me.' WHERE "verseID" = 101542 AND (text = 'Poiché lo zelo della tua casa mi ha roso,' OR text = 'Poiché lo zelo della tua casa mi ha roso, e i vituperi di quelli che ti vituperano son caduti su me.'); -- 23 69:9
UPDATE "LUZZI" SET text = 'Io ho pianto, ho afflitto l''anima mia col digiuno, ma questo è divenuto un motivo d''obbrobrio.' WHERE "verseID" = 101543 AND (text = 'Io ho pianto, ho afflitto l''anima mia col digiuno,'); -- 23 69:10
UPDATE "LUZZI" SET text = 'Ho fatto d''un cilicio il mio vestito, ma son diventato il loro ludibrio.' WHERE "verseID" = 101544 AND (text = 'Ho fatto d''un cilicio il mio vestito,'); -- 23 69:11
UPDATE "LUZZI" SET text = 'Quelli che seggono alla porta discorron di me e sono oggetto di canzone ai bevitori di cervogia.' WHERE "verseID" = 101545 AND (text = 'Quelli che seggono alla porta discorron di me' OR text = 'Quelli che seggono alla porta discorron di me, e sono oggetto di canzone ai bevitori di cervogia.'); -- 23 69:12
UPDATE "LUZZI" SET text = 'Ma, quanto a me, la mia preghiera sale a te, o Eterno, nel tempo accettevole; o Dio, nella grandezza della tua misericordia, rispondimi, secondo la verità della tua salvezza.' WHERE "verseID" = 101546 AND (text = 'Ma, quanto a me, la mia preghiera sale a te,'); -- 23 69:13
UPDATE "LUZZI" SET text = 'Tirami fuor del pantano, e ch''io non affondi! Fa'' ch''io sia liberato da quelli che m''odiano, e dalle acque profonde.' WHERE "verseID" = 101547 AND (text = 'Tirami fuor del pantano, e ch''io non affondi!'); -- 23 69:14
UPDATE "LUZZI" SET text = 'Non mi sommerga la corrente delle acque, non m''inghiottisca il gorgo, e non chiuda il pozzo la sua bocca su di me!' WHERE "verseID" = 101548 AND (text = 'Non mi sommerga la corrente delle acque,'); -- 23 69:15
UPDATE "LUZZI" SET text = 'Rispondimi, o Eterno, perché la tua grazia è piena di bontà; secondo la grandezza delle tue compassioni vòlgiti a me.' WHERE "verseID" = 101549 AND (text = 'Rispondimi, o Eterno, perché la tua grazia è piena di bontà;' OR text = 'Rispondimi, o Eterno, perché la tua grazia è piena di bontà; secondo la grandezza delle tue compassioni, volgiti a me.'); -- 23 69:16
UPDATE "LUZZI" SET text = 'E non nascondere il tuo volto dal tuo servo, perché sono in distretta; affrettati a rispondermi.' WHERE "verseID" = 101550 AND (text = 'E non nascondere il tuo volto dal tuo servo,'); -- 23 69:17
UPDATE "LUZZI" SET text = 'Accostati all''anima mia, e redimila; riscattami per cagion de'' miei nemici.' WHERE "verseID" = 101551 AND (text = 'Accostati all''anima mia, e redimila;'); -- 23 69:18
UPDATE "LUZZI" SET text = 'Tu conosci il mio vituperio, la mia onta e la mia ignominia; i miei nemici son tutti davanti a te.' WHERE "verseID" = 101552 AND (text = 'Tu conosci il mio vituperio, la mia onta e la mia ignominia;'); -- 23 69:19
UPDATE "LUZZI" SET text = 'Il vituperio m''ha spezzato il cuore e son tutto dolente; ho aspettato chi si condolesse meco, non v''è stato alcuno; ho aspettato dei consolatori, ma non ne ho trovati.' WHERE "verseID" = 101553 AND (text = 'Il vituperio m''ha spezzato il cuore e son tutto dolente;'); -- 23 69:20
UPDATE "LUZZI" SET text = 'Anzi mi han dato del fiele per cibo, e, nella mia sete, m''han dato a ber dell''aceto.' WHERE "verseID" = 101554 AND (text = 'Anzi mi han dato del fiele per cibo,'); -- 23 69:21
UPDATE "LUZZI" SET text = 'Sia la mensa, che sta loro dinanzi, un laccio per essi; e, quando si credon sicuri, sia per loro un tranello!' WHERE "verseID" = 101555 AND (text = 'Sia la mensa, che sta loro dinanzi, un laccio per essi;'); -- 23 69:22
UPDATE "LUZZI" SET text = 'gli occhi loro si oscurino, sì che non veggan più, e fa'' loro del continuo vacillare i lombi.' WHERE "verseID" = 101556 AND (text = 'gli occhi loro si oscurino, sì che non veggan più,'); -- 23 69:23
UPDATE "LUZZI" SET text = 'Spandi l''ira tua su loro, e l''ardore del tuo corruccio li colga.' WHERE "verseID" = 101557 AND (text = 'Spandi l''ira tua su loro,'); -- 23 69:24
UPDATE "LUZZI" SET text = 'La loro dimora sia desolata, nessuno abiti nelle loro tende.' WHERE "verseID" = 101558 AND (text = 'La loro dimora sia desolata,'); -- 23 69:25
UPDATE "LUZZI" SET text = 'Poiché perseguitano colui che tu hai percosso, e si raccontano i dolori di quelli che tu hai feriti.' WHERE "verseID" = 101559 AND (text = 'Poiché perseguitano colui che tu hai percosso,'); -- 23 69:26
UPDATE "LUZZI" SET text = 'Aggiungi iniquità alla loro iniquità, e non abbian parte alcuna nella tua giustizia.' WHERE "verseID" = 101560 AND (text = 'Aggiungi iniquità alla loro iniquità,'); -- 23 69:27
UPDATE "LUZZI" SET text = 'Sian cancellati dal libro della vita, e non siano iscritti con i giusti.' WHERE "verseID" = 101561 AND (text = 'Sian cancellati dal libro della vita,'); -- 23 69:28
UPDATE "LUZZI" SET text = 'Quanto a me, io son misero e addolorato; la tua salvezza, o Dio, mi levi ad alto.' WHERE "verseID" = 101562 AND (text = 'Quanto a me, io son misero e addolorato;' OR text = 'Quanto a me, io son misero e addolorato; la tua salvezza, o Dio, mi levi in alto.'); -- 23 69:29
UPDATE "LUZZI" SET text = 'Io celebrerò il nome di Dio con un canto, e lo magnificherò con le mie lodi.' WHERE "verseID" = 101563 AND (text = 'Io celebrerò il nome di Dio con un canto,'); -- 23 69:30
UPDATE "LUZZI" SET text = 'E ciò sarà accettevole all''Eterno più d''un bue, più d''un giovenco con corna ed unghie.' WHERE "verseID" = 101564 AND (text = 'E ciò sarà accettevole all''Eterno più d''un bue,'); -- 23 69:31
UPDATE "LUZZI" SET text = 'I mansueti lo vedranno e si rallegreranno; o voi che cercate Iddio, il cuor vostro riviva!' WHERE "verseID" = 101565 AND (text = 'I mansueti lo vedranno e si rallegreranno;'); -- 23 69:32
UPDATE "LUZZI" SET text = 'Poiché l''Eterno ascolta i bisognosi, e non sprezza i suoi prigionieri.' WHERE "verseID" = 101566 AND (text = 'Poiché l''Eterno ascolta i bisognosi,' OR text = 'Poiché l''Eterno ascolta i bisognosi, non sprezza i suoi prigionieri.'); -- 23 69:33
UPDATE "LUZZI" SET text = 'Lo lodino i cieli e la terra, i mari e tutto ciò che si muove in essi!' WHERE "verseID" = 101567 AND (text = 'Lo lodino i cieli e la terra,'); -- 23 69:34
UPDATE "LUZZI" SET text = 'Poiché Dio salverà Sion, e riedificherà le città di Giuda; il suo popolo abiterà in Sion e la possederà.' WHERE "verseID" = 101568 AND (text = 'Poiché Dio salverà Sion, e riedificherà le città di Giuda;'); -- 23 69:35
UPDATE "LUZZI" SET text = 'Anche la progenie de'' suoi servitori l''avrà per sua eredità, e quelli che amano il suo nome vi abiteranno.' WHERE "verseID" = 101569 AND (text = 'Anche la progenie de'' suoi servitori l''avrà per sua eredità,e quelli che amano il suo nome vi abiteranno.'); -- 23 69:36
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Di Davide; per far ricordare. Affrettati, o Dio, a liberarmi! O Eterno, affrettati in mio aiuto!' WHERE "verseID" = 101570 AND (text = 'Per il Capo de'' musici. Di Davide; per far ricordare.'); -- 23 70:1
UPDATE "LUZZI" SET text = 'Sian confusi e svergognati quelli che cercano l''anima mia! Voltin le spalle e sian coperti d''onta quelli che prendon piacere nel mio male!' WHERE "verseID" = 101571 AND (text = 'Sian confusi e svergognati'); -- 23 70:2
UPDATE "LUZZI" SET text = 'Indietreggino, in premio del loro vituperio, quelli che dicono: Ah! Ah!...' WHERE "verseID" = 101572 AND (text = 'Indietreggino, in premio del loro vituperio,' OR text = 'Indietreggino, in premio del loro vituperio, quelli che dicono: Ah! Ah!…'); -- 23 70:3
UPDATE "LUZZI" SET text = 'Gioiscano e si rallegrino in te, tutti quelli che ti cercano; e quelli che amano la tua salvezza dicano del continuo: Sia magnificato Iddio!' WHERE "verseID" = 101573 AND (text = 'Gioiscano e si rallegrino in te, tutti quelli che ti cercano;'); -- 23 70:4
UPDATE "LUZZI" SET text = 'Quanto a me son misero e bisognoso; o Dio, affrettati a venire a me; tu sei il mio aiuto e il mio liberatore, o Eterno, non tardare!' WHERE "verseID" = 101574 AND (text = 'Quanto a me son misero e bisognoso;o Dio, affrettati a venire a me;tu sei il mio aiuto e il mio liberatore,o Eterno, non tardare!'); -- 23 70:5
UPDATE "LUZZI" SET text = 'In te, o Eterno, io mi confido, fa'' ch''io non sia giammai confuso.' WHERE "verseID" = 101575 AND (text = 'In te, o Eterno, io mi confido,'); -- 23 71:1
UPDATE "LUZZI" SET text = 'Per la tua giustizia, liberami, fammi scampare! Inchina a me il tuo orecchio, e salvami!' WHERE "verseID" = 101576 AND (text = 'Per la tua giustizia, liberami, fammi scampare!'); -- 23 71:2
UPDATE "LUZZI" SET text = 'Siimi una ròcca, una dimora ove io possa sempre rifugiarmi! Tu hai prescritto ch''io sia salvato, perché sei la mia rupe e la mia fortezza.' WHERE "verseID" = 101577 AND (text = 'Siimi una ròcca, una dimora'); -- 23 71:3
UPDATE "LUZZI" SET text = 'O mio Dio, liberami dalla man dell''empio, dalla man del perverso e del violento!' WHERE "verseID" = 101578 AND (text = 'O mio Dio, liberami dalla man dell''empio,'); -- 23 71:4
UPDATE "LUZZI" SET text = 'Poiché tu sei la mia speranza, o Signore, o Eterno, la mia fiducia fin dalla mia fanciullezza.' WHERE "verseID" = 101579 AND (text = 'Poiché tu sei la mia speranza, o Signore, o Eterno,'); -- 23 71:5
UPDATE "LUZZI" SET text = 'Tu sei stato il mio sostegno fin dal seno materno, sei tu che m''hai tratto dalle viscere di mia madre; tu sei del continuo l''oggetto della mia lode.' WHERE "verseID" = 101580 AND (text = 'Tu sei stato il mio sostegno fin dal seno materno,'); -- 23 71:6
UPDATE "LUZZI" SET text = 'Io son per molti come un prodigio, ma tu sei il mio forte ricetto.' WHERE "verseID" = 101581 AND (text = 'Io son per molti come un prodigio,'); -- 23 71:7
UPDATE "LUZZI" SET text = 'Sia la mia bocca ripiena della tua lode, e celebri ogni giorno la tua gloria!' WHERE "verseID" = 101582 AND (text = 'Sia la mia bocca ripiena della tua lode,'); -- 23 71:8
UPDATE "LUZZI" SET text = 'Non rigettarmi al tempo della vecchiezza, non abbandonarmi quando le mie forze declinano.' WHERE "verseID" = 101583 AND (text = 'Non rigettarmi al tempo della vecchiezza,'); -- 23 71:9
UPDATE "LUZZI" SET text = 'Perché i miei nemici parlan di me, e quelli che spiano l''anima mia cospirano assieme,' WHERE "verseID" = 101584 AND (text = 'Perché i miei nemici parlan di me,'); -- 23 71:10
UPDATE "LUZZI" SET text = 'dicendo: Iddio l''ha abbandonato; inseguitelo e prendetelo, perché non c''è alcuno che lo liberi.' WHERE "verseID" = 101585 AND (text = 'dicendo: Iddio l''ha abbandonato;'); -- 23 71:11
UPDATE "LUZZI" SET text = 'O Dio, non allontanarti da me, mio Dio, affrettati in mio aiuto!' WHERE "verseID" = 101586 AND (text = 'O Dio, non allontanarti da me,'); -- 23 71:12
UPDATE "LUZZI" SET text = 'Sian confusi, siano consumati gli avversari dell''anima mia, sian coperti d''onta e di vituperio quelli che cercano il mio male!' WHERE "verseID" = 101587 AND (text = 'Sian confusi, siano consumati gli avversari dell''anima mia,'); -- 23 71:13
UPDATE "LUZZI" SET text = 'Ma io spererò del continuo, e a tutte le tue lodi ne aggiungerò delle altre.' WHERE "verseID" = 101588 AND (text = 'Ma io spererò del continuo,'); -- 23 71:14
UPDATE "LUZZI" SET text = 'La mia bocca racconterà tuttodì la tua giustizia e le tue liberazioni, perché non ne conosco il numero.' WHERE "verseID" = 101589 AND (text = 'La mia bocca racconterà tuttodì'); -- 23 71:15
UPDATE "LUZZI" SET text = 'Io mi farò innanzi a dir de'' potenti atti del Signore, dell''Eterno, ricorderò la tua giustizia, la tua soltanto.' WHERE "verseID" = 101590 AND (text = 'Io mi farò innanzi a dir de'' potenti atti del Signore, dell''Eterno,'); -- 23 71:16
UPDATE "LUZZI" SET text = 'O Dio, tu m''hai ammaestrato dalla mia fanciullezza, ed io, fino ad ora, ho annunziato le tue maraviglie.' WHERE "verseID" = 101591 AND (text = 'O Dio, tu m''hai ammaestrato dalla mia fanciullezza,'); -- 23 71:17
UPDATE "LUZZI" SET text = 'Ed anche quando sia giunto alla vecchiaia ed alla canizie, o Dio, non abbandonarmi, finché non abbia fatto conoscere il tuo braccio a questa generazione, e la tua potenza a quelli che verranno.' WHERE "verseID" = 101592 AND (text = 'Ed anche quando sia giunto alla vecchiaia ed alla canizie,'); -- 23 71:18
UPDATE "LUZZI" SET text = 'Anche la tua giustizia, o Dio, è eccelsa; tu hai fatto cose grandi; o Dio, chi è pari a te?' WHERE "verseID" = 101593 AND (text = 'Anche la tua giustizia, o Dio, è eccelsa;'); -- 23 71:19
UPDATE "LUZZI" SET text = 'Tu, che ci hai fatto veder molte e gravi distrette, ci darai di nuovo la vita e ci trarrai di nuovo dagli abissi della terra;' WHERE "verseID" = 101594 AND (text = 'Tu, che ci hai fatto veder molte e gravi distrette,'); -- 23 71:20
UPDATE "LUZZI" SET text = 'tu accrescerai la mia grandezza, e ti volgerai di nuovo a me per consolarmi.' WHERE "verseID" = 101595 AND (text = 'tu accrescerai la mia grandezza,'); -- 23 71:21
UPDATE "LUZZI" SET text = 'Io altresì ti celebrerò col saltèro, celebrerò la tua verità, o mio Dio! A te salmeggerò con la cetra, o Santo d''Israele!' WHERE "verseID" = 101596 AND (text = 'Io altresì ti celebrerò col saltèro,'); -- 23 71:22
UPDATE "LUZZI" SET text = 'Le mie labbra giubileranno, quando salmeggerò a te e l''anima mia pure, che tu hai riscattata.' WHERE "verseID" = 101597 AND (text = 'Le mie labbra giubileranno, quando salmeggerò a te'); -- 23 71:23
UPDATE "LUZZI" SET text = 'Anche la mia lingua parlerà tuttodì della tua giustizia, perché sono stati svergognati, sono stati confusi quelli che cercavano il mio male.' WHERE "verseID" = 101598 AND (text = 'Anche la mia lingua parlerà tuttodì della tua giustizia,perché sono stati svergognati, sono stati confusiquelli che cercavano il mio male.'); -- 23 71:24
UPDATE "LUZZI" SET text = 'Di Salomone. O Dio, da'' i tuoi giudizi al re, e la tua giustizia al figliuolo del re;' WHERE "verseID" = 101599 AND (text = 'Di Salomone.'); -- 23 72:1
UPDATE "LUZZI" SET text = 'ed egli giudicherà il tuo popolo con giustizia, e i tuoi miseri con equità!' WHERE "verseID" = 101600 AND (text = 'ed egli giudicherà il tuo popolo con giustizia,'); -- 23 72:2
UPDATE "LUZZI" SET text = 'I monti produrranno pace al popolo, e i colli pure, mediante la giustizia!' WHERE "verseID" = 101601 AND (text = 'I monti produrranno pace al popolo,'); -- 23 72:3
UPDATE "LUZZI" SET text = 'Egli farà ragione ai miseri del popolo, salverà i figliuoli del bisognoso, e fiaccherà l''oppressore!' WHERE "verseID" = 101602 AND (text = 'Egli farà ragione ai miseri del popolo,'); -- 23 72:4
UPDATE "LUZZI" SET text = 'Ti temeranno fin che duri il sole, finché duri la luna, per ogni età!' WHERE "verseID" = 101603 AND (text = 'Ti temeranno fin che duri il sole,'); -- 23 72:5
UPDATE "LUZZI" SET text = 'Ei scenderà come pioggia sul prato segato, come acquazzone che adacqua la terra.' WHERE "verseID" = 101604 AND (text = 'Ei scenderà come pioggia sul prato segato,'); -- 23 72:6
UPDATE "LUZZI" SET text = 'Ai dì d''esso il giusto fiorirà, e vi sarà abbondanza di pace finché non vi sia più luna.' WHERE "verseID" = 101605 AND (text = 'Ai dì d''esso il giusto fiorirà,'); -- 23 72:7
UPDATE "LUZZI" SET text = 'Egli signoreggerà da un mare all''altro, e dal fiume fino all''estremità della terra.' WHERE "verseID" = 101606 AND (text = 'Egli signoreggerà da un mare all''altro,'); -- 23 72:8
UPDATE "LUZZI" SET text = 'Davanti a lui s''inchineranno gli abitanti del deserto e i suoi nemici leccheranno la polvere.' WHERE "verseID" = 101607 AND (text = 'Davanti a lui s''inchineranno gli abitanti del deserto'); -- 23 72:9
UPDATE "LUZZI" SET text = 'I re di Tarsis e le isole gli pagheranno il tributo, i re di Sceba e di Seba gli offriranno doni;' WHERE "verseID" = 101608 AND (text = 'I re di Tarsis e le isole gli pagheranno il tributo,'); -- 23 72:10
UPDATE "LUZZI" SET text = 'e tutti i re gli si prostreranno dinanzi, tutte le nazioni lo serviranno.' WHERE "verseID" = 101609 AND (text = 'e tutti i re gli si prostreranno dinanzi,'); -- 23 72:11
UPDATE "LUZZI" SET text = 'Poich''egli libererà il bisognoso che grida, e il misero che non ha chi l''aiuti.' WHERE "verseID" = 101610 AND (text = 'Poich''egli libererà il bisognoso che grida,'); -- 23 72:12
UPDATE "LUZZI" SET text = 'Egli avrà compassione dell''infelice e del bisognoso, e salverà l''anima dei poveri.' WHERE "verseID" = 101611 AND (text = 'Egli avrà compassione dell''infelice e del bisognoso,' OR text = 'Egli avrà compassione dell''infelice e del bisognoso, e salverà l''anima de'' poveri.'); -- 23 72:13
UPDATE "LUZZI" SET text = 'Egli redimerà l''anima loro dall''oppressione e dalla violenza, e il loro sangue sarà prezioso agli occhi suoi.' WHERE "verseID" = 101612 AND (text = 'Egli redimerà l''anima loro dall''oppressione e dalla violenza,'); -- 23 72:14
UPDATE "LUZZI" SET text = 'Egli vivrà; e a lui sarà dato dell''oro di Sceba, e la gente pregherà per lui tuttodì, lo benedirà del continuo.' WHERE "verseID" = 101613 AND (text = 'Egli vivrà; e a lui sarà dato dell''oro di Sceba,'); -- 23 72:15
UPDATE "LUZZI" SET text = 'Vi sarà abbondanza di grano nel paese, sulla sommità dei monti. Ondeggeranno le spighe come fanno gli alberi del Libano, e gli abitanti delle città fioriranno come l''erba della terra!' WHERE "verseID" = 101614 AND (text = 'Vi sarà abbondanza di grano nel paese,'); -- 23 72:16
UPDATE "LUZZI" SET text = 'Il suo nome durerà in eterno, il suo nome sarà perpetuato finché duri il sole; e gli uomini si benediranno a vicenda in lui; tutte le nazioni lo chiameranno beato!' WHERE "verseID" = 101615 AND (text = 'Il suo nome durerà in eterno,'); -- 23 72:17
UPDATE "LUZZI" SET text = 'SIA BENEDETTO L''ETERNO IDDIO, L''IDDIO D''ISRAELE, IL QUALE SOLO FA MARAVIGLIE!' WHERE "verseID" = 101616 AND (text = 'SIA BENEDETTO L''ETERNO IDDIO, L''IDDIO D''ISRAELE,'); -- 23 72:18
UPDATE "LUZZI" SET text = 'SIA BENEDETTO IN ETERNO IL SUO NOME GLORIOSO, E TUTTA LA TERRA SIA RIPIENA DELLA SUA GLORIA! AMEN! AMEN!' WHERE "verseID" = 101617 AND (text = 'SIA BENEDETTO IN ETERNO IL SUO NOME GLORIOSO,' OR text = 'SIA BENEDETTO IN ETERNO IL SUO NOME GLORIOSO, E TUTTA LA TERRA SIA RIPIENA DELLA GLORIA! AMEN! AMEN!'); -- 23 72:19
UPDATE "LUZZI" SET text = 'Salmo di Asaf. Certo, Iddio è buono verso Israele, verso quelli che son puri di cuore.' WHERE "verseID" = 101619 AND (text = 'Salmo di Asaf.'); -- 23 73:1
UPDATE "LUZZI" SET text = 'Ma, quant''è a me, quasi inciamparono i miei piedi; poco mancò che i miei passi non sdrucciolassero.' WHERE "verseID" = 101620 AND (text = 'Ma, quant''è a me, quasi inciamparono i miei piedi;'); -- 23 73:2
UPDATE "LUZZI" SET text = 'Poiché io portavo invidia agli orgogliosi, vedendo la prosperità degli empi.' WHERE "verseID" = 101621 AND (text = 'Poiché io portavo invidia agli orgogliosi,'); -- 23 73:3
UPDATE "LUZZI" SET text = 'Poiché per loro non vi son dolori, il loro corpo è sano e pingue.' WHERE "verseID" = 101622 AND (text = 'Poiché per loro non vi son dolori,'); -- 23 73:4
UPDATE "LUZZI" SET text = 'Non son travagliati come gli altri mortali, né son colpiti come gli altri uomini.' WHERE "verseID" = 101623 AND (text = 'Non son travagliati come gli altri mortali,'); -- 23 73:5
UPDATE "LUZZI" SET text = 'Perciò la superbia li cinge a guisa di collana, la violenza li cuopre a guisa di vestito.' WHERE "verseID" = 101624 AND (text = 'Perciò la superbia li cinge a guisa di collana,'); -- 23 73:6
UPDATE "LUZZI" SET text = 'Dal loro cuore insensibile esce l''iniquità; le immaginazioni del cuor loro traboccano.' WHERE "verseID" = 101625 AND (text = 'Dal loro cuore insensibile esce l''iniquità;'); -- 23 73:7
UPDATE "LUZZI" SET text = 'Sbeffeggiano e malvagiamente ragionan d''opprimere; parlano altezzosamente.' WHERE "verseID" = 101626 AND (text = 'Sbeffeggiano e malvagiamente ragionan d''opprimere;'); -- 23 73:8
UPDATE "LUZZI" SET text = 'Metton la loro bocca nel cielo, e la loro lingua passeggia per la terra.' WHERE "verseID" = 101627 AND (text = 'Metton la loro bocca nel cielo,'); -- 23 73:9
UPDATE "LUZZI" SET text = 'Perciò il popolo si volge dalla loro parte, e beve copiosamente alla loro sorgente,' WHERE "verseID" = 101628 AND (text = 'Perciò il popolo si volge dalla loro parte,'); -- 23 73:10
UPDATE "LUZZI" SET text = 'e dice: Com''è possibile che Dio sappia ogni cosa, che vi sia conoscenza nell''Altissimo?' WHERE "verseID" = 101629 AND (text = 'e dice: Com''è possibile che Dio sappia ogni cosa,'); -- 23 73:11
UPDATE "LUZZI" SET text = 'Ecco, costoro sono empi: eppure, tranquilli sempre, essi accrescono i loro averi.' WHERE "verseID" = 101630 AND (text = 'Ecco, costoro sono empi:'); -- 23 73:12
UPDATE "LUZZI" SET text = 'Invano dunque ho purificato il mio cuore, e ho lavato le mie mani nell''innocenza!' WHERE "verseID" = 101631 AND (text = 'Invano dunque ho purificato il mio cuore,'); -- 23 73:13
UPDATE "LUZZI" SET text = 'Poiché son percosso ogni giorno, e il mio castigo si rinnova ogni mattina.' WHERE "verseID" = 101632 AND (text = 'Poiché son percosso ogni giorno,'); -- 23 73:14
UPDATE "LUZZI" SET text = 'Se avessi detto: Parlerò a quel modo, ecco, sarei stato infedele alla schiatta de'' tuoi figliuoli.' WHERE "verseID" = 101633 AND (text = 'Se avessi detto: Parlerò a quel modo,'); -- 23 73:15
UPDATE "LUZZI" SET text = 'Ho voluto riflettere per intender questo, ma la cosa mi è parsa molto ardua,' WHERE "verseID" = 101634 AND (text = 'Ho voluto riflettere per intender questo,'); -- 23 73:16
UPDATE "LUZZI" SET text = 'finché non sono entrato nel santuario di Dio, e non ho considerata la fine di costoro.' WHERE "verseID" = 101635 AND (text = 'finché non sono entrato nel santuario di Dio,'); -- 23 73:17
UPDATE "LUZZI" SET text = 'Certo, tu li metti in luoghi sdrucciolevoli, tu li fai cadere in rovina.' WHERE "verseID" = 101636 AND (text = 'Certo, tu li metti in luoghi sdrucciolevoli,'); -- 23 73:18
UPDATE "LUZZI" SET text = 'Come sono stati distrutti in un momento, portati via, consumati per casi spaventevoli!' WHERE "verseID" = 101637 AND (text = 'Come sono stati distrutti in un momento,'); -- 23 73:19
UPDATE "LUZZI" SET text = 'Come avviene d''un sogno quand''uno si sveglia, così tu, o Signore, quando ti desterai, sprezzerai la loro vana apparenza.' WHERE "verseID" = 101638 AND (text = 'Come avviene d''un sogno quand''uno si sveglia,'); -- 23 73:20
UPDATE "LUZZI" SET text = 'Quando il mio cuore s''inacerbiva ed io mi sentivo trafitto internamente,' WHERE "verseID" = 101639 AND (text = 'Quando il mio cuore s''inacerbiva'); -- 23 73:21
UPDATE "LUZZI" SET text = 'ero insensato e senza conoscimento; io ero verso di te come una bestia.' WHERE "verseID" = 101640 AND (text = 'ero insensato e senza conoscimento;'); -- 23 73:22
UPDATE "LUZZI" SET text = 'Ma pure, io resto del continuo con te; tu m''hai preso per la man destra;' WHERE "verseID" = 101641 AND (text = 'Ma pure, io resto del continuo con te;'); -- 23 73:23
UPDATE "LUZZI" SET text = 'tu mi condurrai col tuo consiglio, e poi mi riceverai in gloria.' WHERE "verseID" = 101642 AND (text = 'tu mi condurrai col tuo consiglio,'); -- 23 73:24
UPDATE "LUZZI" SET text = 'Chi ho io in cielo fuori di te? E sulla terra non desidero che te.' WHERE "verseID" = 101643 AND (text = 'Chi ho io in cielo fuori di te?'); -- 23 73:25
UPDATE "LUZZI" SET text = 'La mia carne e il mio cuore posson venir meno, ma Dio è la ròcca del mio cuore e la mia parte in eterno.' WHERE "verseID" = 101644 AND (text = 'La mia carne e il mio cuore posson venir meno,'); -- 23 73:26
UPDATE "LUZZI" SET text = 'Poiché, ecco, quelli che s''allontanan da te periranno; tu distruggi chiunque, fornicando, ti abbandona.' WHERE "verseID" = 101645 AND (text = 'Poiché, ecco, quelli che s''allontanan da te periranno;'); -- 23 73:27
UPDATE "LUZZI" SET text = 'Ma quanto a me, il mio bene è d''accostarmi a Dio; io ho fatto del Signore, dell''Eterno, il mio rifugio, per raccontare, o Dio, tutte le opere tue.' WHERE "verseID" = 101646 AND (text = 'Ma quanto a me, il mio bene è d''accostarmi a Dio;io ho fatto del Signore, dell''Eterno, il mio rifugio,per raccontare, o Dio, tutte le opere tue.'); -- 23 73:28
UPDATE "LUZZI" SET text = 'Cantico di Asaf. O Dio, perché ci hai rigettati per sempre? Perché arde l''ira tua contro il gregge del tuo pasco?' WHERE "verseID" = 101647 AND (text = 'Cantico di Asaf.'); -- 23 74:1
UPDATE "LUZZI" SET text = 'Ricordati della tua raunanza che acquistasti in antico, che redimesti per esser la tribù della tua eredità; ricordati del monte di Sion, di cui hai fatto la tua dimora!' WHERE "verseID" = 101648 AND (text = 'Ricordati della tua raunanza che acquistasti in antico,'); -- 23 74:2
UPDATE "LUZZI" SET text = 'Dirigi i tuoi passi verso le ruine perpetue; il nemico ha tutto devastato nel tuo santuario.' WHERE "verseID" = 101649 AND (text = 'Dirigi i tuoi passi verso le ruine perpetue;'); -- 23 74:3
UPDATE "LUZZI" SET text = 'I tuoi avversari hanno ruggito dentro al luogo delle tue raunanze; vi hanno posto le loro insegne per emblemi.' WHERE "verseID" = 101650 AND (text = 'I tuoi avversari hanno ruggito'); -- 23 74:4
UPDATE "LUZZI" SET text = 'Parevano uomini levanti in alto le scuri nel folto d''un bosco.' WHERE "verseID" = 101651 AND (text = 'Parevano uomini levanti in alto le scuri'); -- 23 74:5
UPDATE "LUZZI" SET text = 'E invero con l''ascia e col martello, hanno spezzato tutte le sculture della tua casa.' WHERE "verseID" = 101652 AND (text = 'E invero con l''ascia e col martello,'); -- 23 74:6
UPDATE "LUZZI" SET text = 'Hanno appiccato il fuoco al tuo santuario, han profanato, gettandola a terra, la dimora del tuo nome.' WHERE "verseID" = 101653 AND (text = 'Hanno appiccato il fuoco al tuo santuario,'); -- 23 74:7
UPDATE "LUZZI" SET text = 'Han detto in cuor loro: Distruggiamo tutto! Hanno arso tutti i luoghi delle raunanze divine nel paese.' WHERE "verseID" = 101654 AND (text = 'Han detto in cuor loro: Distruggiamo tutto!'); -- 23 74:8
UPDATE "LUZZI" SET text = 'Noi non vediam più i nostri emblemi; non v''è più profeta, né v''è fra noi alcuno che sappia fino a quando.' WHERE "verseID" = 101655 AND (text = 'Noi non vediam più i nostri emblemi;'); -- 23 74:9
UPDATE "LUZZI" SET text = 'Fino a quando, o Dio, oltraggerà l''avversario? Il nemico sprezzerà egli il tuo nome in perpetuo?' WHERE "verseID" = 101656 AND (text = 'Fino a quando, o Dio, oltraggerà l''avversario?'); -- 23 74:10
UPDATE "LUZZI" SET text = 'Perché ritiri la tua mano, la tua destra? Traila fuori dal tuo seno, e distruggili!' WHERE "verseID" = 101657 AND (text = 'Perché ritiri la tua mano, la tua destra?'); -- 23 74:11
UPDATE "LUZZI" SET text = 'Ma Dio è il mio Re ab antico, colui che opera liberazioni in mezzo alla terra.' WHERE "verseID" = 101658 AND (text = 'Ma Dio è il mio Re ab antico,'); -- 23 74:12
UPDATE "LUZZI" SET text = 'Tu, con la tua forza, spartisti il mare, tu spezzasti il capo ai mostri marini sulle acque,' WHERE "verseID" = 101659 AND (text = 'Tu, con la tua forza, spartisti il mare,'); -- 23 74:13
UPDATE "LUZZI" SET text = 'tu spezzasti il capo del leviatan, tu lo desti in pasto al popolo del deserto.' WHERE "verseID" = 101660 AND (text = 'tu spezzasti il capo del leviatan,'); -- 23 74:14
UPDATE "LUZZI" SET text = 'Tu facesti sgorgare fonti e torrenti, tu asciugasti fiumi perenni.' WHERE "verseID" = 101661 AND (text = 'Tu facesti sgorgare fonti e torrenti,'); -- 23 74:15
UPDATE "LUZZI" SET text = 'Tuo è il giorno, la notte pure è tua; tu hai stabilito la luna e il sole.' WHERE "verseID" = 101662 AND (text = 'Tuo è il giorno, la notte pure è tua;'); -- 23 74:16
UPDATE "LUZZI" SET text = 'Tu hai fissato tutti i confini della terra, tu hai fatto l''estate e l''inverno.' WHERE "verseID" = 101663 AND (text = 'Tu hai fissato tutti i confini della terra,'); -- 23 74:17
UPDATE "LUZZI" SET text = 'Ricordati questo: che il nemico ha oltraggiato l''Eterno, e che un popolo stolto ha sprezzato il tuo nome.' WHERE "verseID" = 101664 AND (text = 'Ricordati questo: che il nemico ha oltraggiato l''Eterno,'); -- 23 74:18
UPDATE "LUZZI" SET text = 'Non dare alle fiere la vita della tua tortora, non dimenticare per sempre il gregge dei tuoi poveri afflitti!' WHERE "verseID" = 101665 AND (text = 'Non dare alle fiere la vita della tua tortora,'); -- 23 74:19
UPDATE "LUZZI" SET text = 'Abbi riguardo al patto, poiché i luoghi tenebrosi della terra son pieni di ricetti di violenza.' WHERE "verseID" = 101666 AND (text = 'Abbi riguardo al patto,'); -- 23 74:20
UPDATE "LUZZI" SET text = 'L''oppresso non se ne torni svergognato; fa'' che il misero e il bisognoso lodino il tuo nome.' WHERE "verseID" = 101667 AND (text = 'L''oppresso non se ne torni svergognato;'); -- 23 74:21
UPDATE "LUZZI" SET text = 'Lèvati, o Dio, difendi la tua causa! Ricordati dell''oltraggio che ti è fatto del continuo dallo stolto.' WHERE "verseID" = 101668 AND (text = 'Lèvati, o Dio, difendi la tua causa!'); -- 23 74:22
UPDATE "LUZZI" SET text = 'Non dimenticare il grido de'' tuoi nemici, lo strepito incessante di quelli che si levano contro di te.' WHERE "verseID" = 101669 AND (text = 'Non dimenticare il grido de'' tuoi nemici,lo strepito incessante di quelli che si levano contro di te.'); -- 23 74:23
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. ''Non distruggere''. Salmo di Asaf. Canto. Noi ti celebriamo, o Dio, ti celebriamo; quelli che invocano il tuo nome narrano le tue maraviglie.' WHERE "verseID" = 101670 AND (text = 'Per il Capo de'' musici. ''Non distruggere''. Salmo di Asaf. Canto.'); -- 23 75:1
UPDATE "LUZZI" SET text = 'Quando verrà il tempo che avrò fissato, io giudicherò dirittamente.' WHERE "verseID" = 101671 AND (text = 'Quando verrà il tempo che avrò fissato,'); -- 23 75:2
UPDATE "LUZZI" SET text = 'Si dissolva la terra con tutti i suoi abitanti, io ne rendo stabili le colonne. Sela.' WHERE "verseID" = 101672 AND (text = 'Si dissolva la terra con tutti i suoi abitanti,'); -- 23 75:3
UPDATE "LUZZI" SET text = 'Io dico agli orgogliosi: Non vi gloriate! e agli empi: Non alzate il corno!' WHERE "verseID" = 101673 AND (text = 'Io dico agli orgogliosi: Non vi gloriate!' OR text = 'Io dico agli orgogliosi: Non vi gloriate! e agli empi: non alzate il corno!'); -- 23 75:4
UPDATE "LUZZI" SET text = 'Non levate il vostro corno in alto, non parlate col collo duro!' WHERE "verseID" = 101674 AND (text = 'Non levate il vostro corno in alto,'); -- 23 75:5
UPDATE "LUZZI" SET text = 'Poiché non è dal levante né dal ponente, né dal mezzogiorno che vien l''elevazione;' WHERE "verseID" = 101675 AND (text = 'Poiché non è dal levante né dal ponente,'); -- 23 75:6
UPDATE "LUZZI" SET text = 'ma Dio è quel che giudica; egli abbassa l''uno ed innalza l''altro.' WHERE "verseID" = 101676 AND (text = 'ma Dio è quel che giudica;'); -- 23 75:7
UPDATE "LUZZI" SET text = 'L''Eterno ha in mano una coppa, ove spumeggia un vino pien di mistura. Egli ne mesce; certo, tutti gli empi della terra ne succeranno e berranno le fecce.' WHERE "verseID" = 101677 AND (text = 'L''Eterno ha in mano una coppa,'); -- 23 75:8
UPDATE "LUZZI" SET text = 'Ma io proclamerò del continuo queste cose, salmeggerò all''Iddio di Giacobbe;' WHERE "verseID" = 101678 AND (text = 'Ma io proclamerò del continuo queste cose,'); -- 23 75:9
UPDATE "LUZZI" SET text = 'spezzerò tutta la potenza degli empi, ma la potenza dei giusti sarà accresciuta.' WHERE "verseID" = 101679 AND (text = 'spezzerò tutta la potenza degli empi,ma la potenza dei giusti sarà accresciuta.'); -- 23 75:10
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Per strumenti a corda. Salmo di Asaf. Canto. Iddio è conosciuto in Giuda; il suo nome è grande in Israele.' WHERE "verseID" = 101680 AND (text = 'Per il Capo de'' musici. Per strumenti a corda. Salmo di Asaf. Canto.'); -- 23 76:1
UPDATE "LUZZI" SET text = 'Il suo tabernacolo è in Salem, e la sua dimora in Sion.' WHERE "verseID" = 101681 AND (text = 'Il suo tabernacolo è in Salem,'); -- 23 76:2
UPDATE "LUZZI" SET text = 'Quivi ha spezzato le saette dell''arco, lo scudo, la spada e gli arnesi di guerra. Sela.' WHERE "verseID" = 101682 AND (text = 'Quivi ha spezzato le saette dell''arco,'); -- 23 76:3
UPDATE "LUZZI" SET text = 'Tremendo sei tu, o Potente, quando ritorni dalle montagne di preda.' WHERE "verseID" = 101683 AND (text = 'Tremendo sei tu, o Potente,'); -- 23 76:4
UPDATE "LUZZI" SET text = 'Gli animosi sono stati spogliati, han dormito il loro ultimo sonno, e tutti gli uomini prodi sono stati ridotti all''impotenza.' WHERE "verseID" = 101684 AND (text = 'Gli animosi sono stati spogliati,'); -- 23 76:5
UPDATE "LUZZI" SET text = 'Alla tua minaccia, o Dio di Giacobbe, carri e cavalli sono stati presi da torpore.' WHERE "verseID" = 101685 AND (text = 'Alla tua minaccia, o Dio di Giacobbe,'); -- 23 76:6
UPDATE "LUZZI" SET text = 'Tu, tu sei tremendo; e chi può reggere davanti a te quando t''adiri?' WHERE "verseID" = 101686 AND (text = 'Tu, tu sei tremendo;'); -- 23 76:7
UPDATE "LUZZI" SET text = 'Dal cielo facesti udir la tua sentenza; la terra temette e tacque,' WHERE "verseID" = 101687 AND (text = 'Dal cielo facesti udir la tua sentenza;'); -- 23 76:8
UPDATE "LUZZI" SET text = 'quando Iddio si levò per far giudicio, per salvare tutti gl''infelici della terra. Sela.' WHERE "verseID" = 101688 AND (text = 'quando Iddio si levò per far giudicio,'); -- 23 76:9
UPDATE "LUZZI" SET text = 'Certo, il furore degli uomini ridonderà alla tua lode; ti cingerai degli ultimi avanzi dei loro furori.' WHERE "verseID" = 101689 AND (text = 'Certo, il furore degli uomini ridonderà alla tua lode;'); -- 23 76:10
UPDATE "LUZZI" SET text = 'Fate voti all''Eterno, all''Iddio vostro, e adempiteli; tutti quelli che gli stanno attorno portin doni al Tremendo.' WHERE "verseID" = 101690 AND (text = 'Fate voti all''Eterno, all''Iddio vostro, e adempiteli;'); -- 23 76:11
UPDATE "LUZZI" SET text = 'Egli recide lo spirito dei principi, egli è tremendo ai re della terra.' WHERE "verseID" = 101691 AND (text = 'Egli recide lo spirito dei principi,egli è tremendo ai re della terra.'); -- 23 76:12
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Secondo Jeduthun. Salmo di Asaf. La mia voce s''eleva a Dio, e io grido; la mia voce s''eleva a Dio, ed egli mi porge l''orecchio.' WHERE "verseID" = 101692 AND (text = 'Per il Capo de'' musici. Secondo Jeduthun. Salmo di Asaf.'); -- 23 77:1
UPDATE "LUZZI" SET text = 'Nel giorno della mia distretta, io ho cercato il Signore; la mia mano è stata tesa durante la notte senza stancarsi, l''anima mia ha rifiutato d''essere consolata.' WHERE "verseID" = 101693 AND (text = 'Nel giorno della mia distretta, io ho cercato il Signore;' OR text = 'Nel giorno della mia distretta, io ho cercato il Signore; la mia mano è stata tesa durante la notte senza stancarsi, l''anima mia ha rifiutato d''esser consolata.'); -- 23 77:2
UPDATE "LUZZI" SET text = 'Io mi ricordo di Dio, e gemo; medito, e il mio spirito è abbattuto. Sela.' WHERE "verseID" = 101694 AND (text = 'Io mi ricordo di Dio, e gemo;'); -- 23 77:3
UPDATE "LUZZI" SET text = 'Tu tieni desti gli occhi miei, sono turbato e non posso parlare.' WHERE "verseID" = 101695 AND (text = 'Tu tieni desti gli occhi miei,'); -- 23 77:4
UPDATE "LUZZI" SET text = 'Ripenso ai giorni antichi, agli anni da lungo tempo passati.' WHERE "verseID" = 101696 AND (text = 'Ripenso ai giorni antichi,'); -- 23 77:5
UPDATE "LUZZI" SET text = 'Mi ricordo de'' miei canti durante la notte, medito nel mio cuore, e lo spirito mio va investigando:' WHERE "verseID" = 101697 AND (text = 'Mi ricordo de'' miei canti durante la notte,'); -- 23 77:6
UPDATE "LUZZI" SET text = 'Il Signore ripudia egli in perpetuo? E non mostrerà egli più il suo favore?' WHERE "verseID" = 101698 AND (text = 'Il Signore ripudia egli in perpetuo?'); -- 23 77:7
UPDATE "LUZZI" SET text = 'È la sua benignità venuta meno per sempre? La sua parola ha ella cessato per ogni età?' WHERE "verseID" = 101699 AND (text = 'È la sua benignità venuta meno per sempre?'); -- 23 77:8
UPDATE "LUZZI" SET text = 'Iddio ha egli dimenticato d''aver pietà? Ha egli nell''ira chiuse le sue compassioni? Sela.' WHERE "verseID" = 101700 AND (text = 'Iddio ha egli dimenticato d''aver pietà?'); -- 23 77:9
UPDATE "LUZZI" SET text = 'E ho detto: La mia afflizione sta in questo, che la destra dell''Altissimo è mutata.' WHERE "verseID" = 101701 AND (text = 'E ho detto: La mia afflizione sta in questo,'); -- 23 77:10
UPDATE "LUZZI" SET text = 'Io rievocherò la memoria delle opere dell''Eterno; sì, ricorderò le tue maraviglie antiche,' WHERE "verseID" = 101702 AND (text = 'Io rievocherò la memoria delle opere dell''Eterno;'); -- 23 77:11
UPDATE "LUZZI" SET text = 'mediterò su tutte le opere tue, e ripenserò alle tue gesta.' WHERE "verseID" = 101703 AND (text = 'mediterò su tutte le opere tue,'); -- 23 77:12
UPDATE "LUZZI" SET text = 'O Dio, le tue vie son sante; qual è l''Iddio grande come Dio?' WHERE "verseID" = 101704 AND (text = 'O Dio, le tue vie son sante;'); -- 23 77:13
UPDATE "LUZZI" SET text = 'Tu sei l''Iddio che fai maraviglie; tu hai fatto conoscere la tua forza fra i popoli.' WHERE "verseID" = 101705 AND (text = 'Tu sei l''Iddio che fai maraviglie;'); -- 23 77:14
UPDATE "LUZZI" SET text = 'Tu hai, col tuo braccio, redento il tuo popolo, i figliuoli di Giacobbe e di Giuseppe. Sela.' WHERE "verseID" = 101706 AND (text = 'Tu hai, col tuo braccio, redento il tuo popolo,'); -- 23 77:15
UPDATE "LUZZI" SET text = 'Le acque ti videro, o Dio; le acque ti videro e furono spaventate; anche gli abissi tremarono.' WHERE "verseID" = 101707 AND (text = 'Le acque ti videro, o Dio;'); -- 23 77:16
UPDATE "LUZZI" SET text = 'Le nubi versarono diluvi d''acqua; i cieli tuonarono; ed anche i tuoi strali volarono da ogni parte.' WHERE "verseID" = 101708 AND (text = 'Le nubi versarono diluvi d''acqua;'); -- 23 77:17
UPDATE "LUZZI" SET text = 'La voce del tuo tuono era nel turbine; i lampi illuminarono il mondo; la terra fu scossa e tremò.' WHERE "verseID" = 101709 AND (text = 'La voce del tuo tuono era nel turbine;'); -- 23 77:18
UPDATE "LUZZI" SET text = 'La tua via fu in mezzo al mare, i tuoi sentieri in mezzo alle grandi acque, e le tue orme non furon riconosciute.' WHERE "verseID" = 101710 AND (text = 'La tua via fu in mezzo al mare,'); -- 23 77:19
UPDATE "LUZZI" SET text = 'Tu conducesti il tuo popolo come un gregge, per mano di Mosè e d''Aaronne.' WHERE "verseID" = 101711 AND (text = 'Tu conducesti il tuo popolo come un gregge,per mano di Mosè e d''Aaronne.'); -- 23 77:20
UPDATE "LUZZI" SET text = 'Cantico di Asaf. Ascolta, popolo mio, il mio insegnamento; porgete gli orecchi alle parole della mia bocca!' WHERE "verseID" = 101712 AND (text = 'Cantico di Asaf.'); -- 23 78:1
UPDATE "LUZZI" SET text = 'Io aprirò la mia bocca per proferir parabole, esporrò i misteri de'' tempi antichi.' WHERE "verseID" = 101713 AND (text = 'Io aprirò la mia bocca per proferir parabole,'); -- 23 78:2
UPDATE "LUZZI" SET text = 'Quel che noi abbiamo udito e conosciuto, e che i nostri padri ci hanno raccontato,' WHERE "verseID" = 101714 AND (text = 'Quel che noi abbiamo udito e conosciuto,'); -- 23 78:3
UPDATE "LUZZI" SET text = 'non lo celeremo ai loro figliuoli; diremo alla generazione avvenire le lodi dell''Eterno, e la sua potenza e le maraviglie ch''egli ha operato.' WHERE "verseID" = 101715 AND (text = 'non lo celeremo ai loro figliuoli;'); -- 23 78:4
UPDATE "LUZZI" SET text = 'Egli stabilì una testimonianza in Giacobbe, e pose una legge in Israele, ch''egli ordinò ai nostri padri di far conoscere ai loro figliuoli,' WHERE "verseID" = 101716 AND (text = 'Egli stabilì una testimonianza in Giacobbe,'); -- 23 78:5
UPDATE "LUZZI" SET text = 'perché fossero note alla generazione avvenire, ai figliuoli che nascerebbero, i quali alla loro volta le narrerebbero ai loro figliuoli,' WHERE "verseID" = 101717 AND (text = 'perché fossero note alla generazione avvenire,'); -- 23 78:6
UPDATE "LUZZI" SET text = 'ond''essi ponessero in Dio la loro speranza e non dimenticassero le opere di Dio, ma osservassero i suoi comandamenti;' WHERE "verseID" = 101718 AND (text = 'ond''essi ponessero in Dio la loro speranza'); -- 23 78:7
UPDATE "LUZZI" SET text = 'e non fossero come i loro padri, una generazione caparbia e ribelle, una generazione dal cuore incostante, e il cui spirito non fu fedele a Dio.' WHERE "verseID" = 101719 AND (text = 'e non fossero come i loro padri,'); -- 23 78:8
UPDATE "LUZZI" SET text = 'I figliuoli di Efraim, gente di guerra, buoni arcieri, voltaron le spalle il dì della battaglia.' WHERE "verseID" = 101720 AND (text = 'I figliuoli di Efraim, gente di guerra, buoni arcieri,'); -- 23 78:9
UPDATE "LUZZI" SET text = 'Non osservarono il patto di Dio, e ricusarono di camminar secondo la sua legge;' WHERE "verseID" = 101721 AND (text = 'Non osservarono il patto di Dio,'); -- 23 78:10
UPDATE "LUZZI" SET text = 'e dimenticarono le sue opere e i prodigi ch''egli avea loro fatto vedere.' WHERE "verseID" = 101722 AND (text = 'e dimenticarono le sue opere'); -- 23 78:11
UPDATE "LUZZI" SET text = 'Egli aveva compiuto maraviglie in presenza de'' loro padri, nel paese d''Egitto, nelle campagne di Zoan.' WHERE "verseID" = 101723 AND (text = 'Egli aveva compiuto maraviglie in presenza de'' loro padri,'); -- 23 78:12
UPDATE "LUZZI" SET text = 'Fendé il mare e li fece passare, e fermò le acque come in un mucchio.' WHERE "verseID" = 101724 AND (text = 'Fendé il mare e li fece passare,'); -- 23 78:13
UPDATE "LUZZI" SET text = 'Di giorno li guidò con una nuvola, e tutta la notte con una luce di fuoco.' WHERE "verseID" = 101725 AND (text = 'Di giorno li guidò con una nuvola,'); -- 23 78:14
UPDATE "LUZZI" SET text = 'Schiantò rupi nel deserto, e li abbeverò copiosamente, come da gorghi.' WHERE "verseID" = 101726 AND (text = 'Schiantò rupi nel deserto,'); -- 23 78:15
UPDATE "LUZZI" SET text = 'Fece scaturire ruscelli dalla roccia e ne fece scender dell''acqua a guisa di fiumi.' WHERE "verseID" = 101727 AND (text = 'Fece scaturire ruscelli dalla roccia' OR text = 'Fece scaturire ruscelli dalla roccia e ne fece scender dell''acque a guisa di fiumi.'); -- 23 78:16
UPDATE "LUZZI" SET text = 'Ma essi continuarono a peccare contro di lui, a ribellarsi contro l''Altissimo, nel deserto;' WHERE "verseID" = 101728 AND (text = 'Ma essi continuarono a peccare contro di lui,'); -- 23 78:17
UPDATE "LUZZI" SET text = 'e tentarono Dio in cuor loro, chiedendo cibo a lor voglia.' WHERE "verseID" = 101729 AND (text = 'e tentarono Dio in cuor loro,'); -- 23 78:18
UPDATE "LUZZI" SET text = 'E parlarono contro Dio, dicendo: Potrebbe Dio imbandirci una mensa nel deserto?' WHERE "verseID" = 101730 AND (text = 'E parlarono contro Dio,'); -- 23 78:19
UPDATE "LUZZI" SET text = 'Ecco, egli percosse la roccia e ne colarono acque, ne traboccaron torrenti; potrebb''egli darci anche del pane, e provveder di carne il suo popolo?' WHERE "verseID" = 101731 AND (text = 'Ecco, egli percosse la roccia e ne colarono acque,'); -- 23 78:20
UPDATE "LUZZI" SET text = 'Perciò l''Eterno, avendoli uditi, s''adirò fieramente, e un fuoco s''accese contro Giacobbe, e l''ira sua si levò contro Israele,' WHERE "verseID" = 101732 AND (text = 'Perciò l''Eterno, avendoli uditi, s''adirò fieramente,'); -- 23 78:21
UPDATE "LUZZI" SET text = 'perché non aveano creduto in Dio, né avevano avuto fiducia nella sua salvazione;' WHERE "verseID" = 101733 AND (text = 'perché non aveano creduto in Dio,'); -- 23 78:22
UPDATE "LUZZI" SET text = 'eppure egli comandò alle nuvole di sopra, e aprì le porte del cielo,' WHERE "verseID" = 101734 AND (text = 'eppure egli comandò alle nuvole di sopra,'); -- 23 78:23
UPDATE "LUZZI" SET text = 'e fece piover su loro manna da mangiare, e dette loro del frumento del cielo.' WHERE "verseID" = 101735 AND (text = 'e fece piover su loro manna da mangiare,'); -- 23 78:24
UPDATE "LUZZI" SET text = 'L''uomo mangiò del pane dei potenti; egli mandò loro del cibo a sazietà.' WHERE "verseID" = 101736 AND (text = 'L''uomo mangiò del pane dei potenti;'); -- 23 78:25
UPDATE "LUZZI" SET text = 'Fece levare in cielo il vento orientale, e con la sua potenza addusse il vento di mezzodì;' WHERE "verseID" = 101737 AND (text = 'Fece levare in cielo il vento orientale,'); -- 23 78:26
UPDATE "LUZZI" SET text = 'fece piover su loro della carne come polvere, degli uccelli alati, numerosi come la rena del mare;' WHERE "verseID" = 101738 AND (text = 'fece piover su loro della carne come polvere,'); -- 23 78:27
UPDATE "LUZZI" SET text = 'e li fece cadere in mezzo al loro campo, d''intorno alle loro tende.' WHERE "verseID" = 101739 AND (text = 'e li fece cadere in mezzo al loro campo,'); -- 23 78:28
UPDATE "LUZZI" SET text = 'Così essi mangiarono e furon ben satollati, e Dio mandò loro quel che aveano bramato.' WHERE "verseID" = 101740 AND (text = 'Così essi mangiarono e furon ben satollati,'); -- 23 78:29
UPDATE "LUZZI" SET text = 'Non si erano ancora distolti dalle loro brame, avevano ancora il loro cibo in bocca,' WHERE "verseID" = 101741 AND (text = 'Non si erano ancora distolti dalle loro brame,'); -- 23 78:30
UPDATE "LUZZI" SET text = 'quando l''ira di Dio si levò contro a loro, e ne uccise tra i più fiorenti, e abbatté i giovani d''Israele.' WHERE "verseID" = 101742 AND (text = 'quando l''ira di Dio si levò contro a loro,'); -- 23 78:31
UPDATE "LUZZI" SET text = 'Con tutto ciò peccarono ancora, e non credettero alle sue maraviglie.' WHERE "verseID" = 101743 AND (text = 'Con tutto ciò peccarono ancora,'); -- 23 78:32
UPDATE "LUZZI" SET text = 'Ond''egli consumò i loro giorni in vanità, e i loro anni in ispaventi.' WHERE "verseID" = 101744 AND (text = 'Ond''egli consumò i loro giorni in vanità,'); -- 23 78:33
UPDATE "LUZZI" SET text = 'Quand''ei li uccideva, essi lo ricercavano e tornavano bramosi di ritrovare Iddio;' WHERE "verseID" = 101745 AND (text = 'Quand''ei li uccideva, essi lo ricercavano'); -- 23 78:34
UPDATE "LUZZI" SET text = 'e si ricordavano che Dio era la loro ròcca, e l''Iddio altissimo il loro redentore.' WHERE "verseID" = 101746 AND (text = 'e si ricordavano che Dio era la loro ròcca,' OR text = 'e si ricordavano che Dio era la loro ròcca, l''Iddio altissimo il loro redentore.'); -- 23 78:35
UPDATE "LUZZI" SET text = 'Essi però lo lusingavano con la loro bocca, e gli mentivano con la loro lingua.' WHERE "verseID" = 101747 AND (text = 'Essi però lo lusingavano con la loro bocca,'); -- 23 78:36
UPDATE "LUZZI" SET text = 'Il loro cuore non era diritto verso lui, e non eran fedeli al suo patto.' WHERE "verseID" = 101748 AND (text = 'Il loro cuore non era diritto verso lui,'); -- 23 78:37
UPDATE "LUZZI" SET text = 'Ma egli, che è pietoso, che perdona l''iniquità e non distrugge il peccatore, più volte rattenne la sua ira, e non lasciò divampare tutto il suo cruccio.' WHERE "verseID" = 101749 AND (text = 'Ma egli, che è pietoso, che perdona l''iniquità'); -- 23 78:38
UPDATE "LUZZI" SET text = 'Ei si ricordò ch''essi erano carne, un fiato che passa e non ritorna.' WHERE "verseID" = 101750 AND (text = 'Ei si ricordò ch''essi erano carne,'); -- 23 78:39
UPDATE "LUZZI" SET text = 'Quante volte si ribellarono a lui nel deserto, e lo contristarono nella solitudine!' WHERE "verseID" = 101751 AND (text = 'Quante volte si ribellarono a lui nel deserto,'); -- 23 78:40
UPDATE "LUZZI" SET text = 'E tornarono a tentare Iddio e a provocare il Santo d''Israele.' WHERE "verseID" = 101752 AND (text = 'E tornarono a tentare Iddio'); -- 23 78:41
UPDATE "LUZZI" SET text = 'Non si ricordaron più della sua mano, del giorno in cui egli li liberò dal nemico,' WHERE "verseID" = 101753 AND (text = 'Non si ricordaron più della sua mano,'); -- 23 78:42
UPDATE "LUZZI" SET text = 'quando operò i suoi miracoli in Egitto, e i suoi prodigi nelle campagne di Zoan;' WHERE "verseID" = 101754 AND (text = 'quando operò i suoi miracoli in Egitto,'); -- 23 78:43
UPDATE "LUZZI" SET text = 'mutò i loro fiumi in sangue, e i loro rivi in guisa che non potean più bere;' WHERE "verseID" = 101755 AND (text = 'mutò i loro fiumi in sangue,'); -- 23 78:44
UPDATE "LUZZI" SET text = 'mandò contro loro mosche velenose che li divoravano, e rane che li distruggevano;' WHERE "verseID" = 101756 AND (text = 'mandò contro loro mosche velenose che li divoravano,'); -- 23 78:45
UPDATE "LUZZI" SET text = 'dette il loro raccolto ai bruchi, e la loro fatica alle locuste;' WHERE "verseID" = 101757 AND (text = 'dette il loro raccolto ai bruchi,'); -- 23 78:46
UPDATE "LUZZI" SET text = 'distrusse le loro vigne con la gragnuola e i loro sicomori coi grossi chicchi d''essa;' WHERE "verseID" = 101758 AND (text = 'distrusse le loro vigne con la gragnuola'); -- 23 78:47
UPDATE "LUZZI" SET text = 'abbandonò il loro bestiame alla grandine e le lor gregge ai fulmini.' WHERE "verseID" = 101759 AND (text = 'abbandonò il loro bestiame alla grandine'); -- 23 78:48
UPDATE "LUZZI" SET text = 'Scatenò su loro l''ardore del suo cruccio, ira, indignazione e distretta, una torma di messaggeri di malanni.' WHERE "verseID" = 101760 AND (text = 'Scatenò su loro l''ardore del suo cruccio,'); -- 23 78:49
UPDATE "LUZZI" SET text = 'Dette libero corso alla sua ira; non preservò dalla morte la loro anima, ma abbandonò la loro vita alla pestilenza.' WHERE "verseID" = 101761 AND (text = 'Dette libero corso alla sua ira;'); -- 23 78:50
UPDATE "LUZZI" SET text = 'Percosse tutti i primogeniti d''Egitto, le primizie del vigore nelle tende di Cham;' WHERE "verseID" = 101762 AND (text = 'Percosse tutti i primogeniti d''Egitto,'); -- 23 78:51
UPDATE "LUZZI" SET text = 'ma fece partire il suo popolo a guisa di pecore, e lo condusse a traverso il deserto come una mandra.' WHERE "verseID" = 101763 AND (text = 'ma fece partire il suo popolo a guisa di pecore,'); -- 23 78:52
UPDATE "LUZZI" SET text = 'Lo guidò sicuramente sì che non ebbero da spaventarsi; mentre il mare inghiottiva i loro nemici.' WHERE "verseID" = 101764 AND (text = 'Lo guidò sicuramente sì che non ebbero da spaventarsi;'); -- 23 78:53
UPDATE "LUZZI" SET text = 'Li fece arrivare alla sua santa frontiera, alla montagna che la sua destra avea conquistato.' WHERE "verseID" = 101765 AND (text = 'Li fece arrivare alla sua santa frontiera,'); -- 23 78:54
UPDATE "LUZZI" SET text = 'Scacciò le nazioni dinanzi a loro, ne assegnò loro a sorte il paese quale eredità, e nelle tende d''esse fece abitare le tribù d''Israele.' WHERE "verseID" = 101766 AND (text = 'Scacciò le nazioni dinanzi a loro,'); -- 23 78:55
UPDATE "LUZZI" SET text = 'E nondimeno tentarono l''Iddio altissimo e si ribellarono e non osservarono le sue testimonianze.' WHERE "verseID" = 101767 AND (text = 'E nondimeno tentarono l''Iddio altissimo e si ribellarono'); -- 23 78:56
UPDATE "LUZZI" SET text = 'Si trassero indietro e furono sleali come i loro padri; si rivoltarono come un arco fallace;' WHERE "verseID" = 101768 AND (text = 'Si trassero indietro e furono sleali come i loro padri;'); -- 23 78:57
UPDATE "LUZZI" SET text = 'lo provocarono ad ira coi loro alti luoghi, lo mossero a gelosia con le loro sculture.' WHERE "verseID" = 101769 AND (text = 'lo provocarono ad ira coi loro alti luoghi,'); -- 23 78:58
UPDATE "LUZZI" SET text = 'Dio udì questo, e si adirò, prese Israele in grande avversione,' WHERE "verseID" = 101770 AND (text = 'Dio udì questo, e si adirò,'); -- 23 78:59
UPDATE "LUZZI" SET text = 'onde abbandonò il tabernacolo di Silo, la tenda ov''era dimorato fra gli uomini;' WHERE "verseID" = 101771 AND (text = 'onde abbandonò il tabernacolo di Silo,'); -- 23 78:60
UPDATE "LUZZI" SET text = 'e lasciò menare la sua Forza in cattività e lasciò cader la sua Gloria in mano del nemico.' WHERE "verseID" = 101772 AND (text = 'e lasciò menare la sua Forza in cattività' OR text = 'e lasciò menare la sua Forza in cattività, e lasciò cader la sua Gloria in man del nemico.'); -- 23 78:61
UPDATE "LUZZI" SET text = 'Abbandonò il suo popolo alla spada, e s''adirò contro la sua eredità.' WHERE "verseID" = 101773 AND (text = 'Abbandonò il suo popolo alla spada,'); -- 23 78:62
UPDATE "LUZZI" SET text = 'Il fuoco consumò i loro giovani, e le loro vergini non ebber canto nuziale.' WHERE "verseID" = 101774 AND (text = 'Il fuoco consumò i loro giovani,'); -- 23 78:63
UPDATE "LUZZI" SET text = 'I loro sacerdoti caddero per la spada, e le loro vedove non fecer lamento.' WHERE "verseID" = 101775 AND (text = 'I loro sacerdoti caddero per la spada,'); -- 23 78:64
UPDATE "LUZZI" SET text = 'Poi il Signore si risvegliò come uno che dormisse, come un prode che grida eccitato dal vino.' WHERE "verseID" = 101776 AND (text = 'Poi il Signore si risvegliò come uno che dormisse,'); -- 23 78:65
UPDATE "LUZZI" SET text = 'E percosse i suoi nemici alle spalle, e mise loro addosso un eterno vituperio.' WHERE "verseID" = 101777 AND (text = 'E percosse i suoi nemici alle spalle,'); -- 23 78:66
UPDATE "LUZZI" SET text = 'Ma ripudiò la tenda di Giuseppe, e non elesse la tribù di Efraim;' WHERE "verseID" = 101778 AND (text = 'Ma ripudiò la tenda di Giuseppe,'); -- 23 78:67
UPDATE "LUZZI" SET text = 'ma elesse la tribù di Giuda, il monte di Sion ch''egli amava.' WHERE "verseID" = 101779 AND (text = 'ma elesse la tribù di Giuda,'); -- 23 78:68
UPDATE "LUZZI" SET text = 'Edificò il suo santuario a guisa de'' luoghi eccelsi, come la terra ch''egli ha fondata per sempre.' WHERE "verseID" = 101780 AND (text = 'Edificò il suo santuario a guisa de'' luoghi eccelsi,'); -- 23 78:69
UPDATE "LUZZI" SET text = 'Elesse Davide, suo servitore, lo prese dagli ovili;' WHERE "verseID" = 101781 AND (text = 'Elesse Davide, suo servitore,'); -- 23 78:70
UPDATE "LUZZI" SET text = 'lo trasse di dietro alle pecore lattanti, per pascere Giacobbe suo popolo, ed Israele sua eredità.' WHERE "verseID" = 101782 AND (text = 'lo trasse di dietro alle pecore lattanti,'); -- 23 78:71
UPDATE "LUZZI" SET text = 'Ed egli li pasturò secondo l''integrità del suo cuore, e li guidò con mano assennata.' WHERE "verseID" = 101783 AND (text = 'Ed egli li pasturò secondo l''integrità del suo cuore,e li guidò con mano assennata.'); -- 23 78:72
UPDATE "LUZZI" SET text = 'Salmo di Asaf. O Dio, le nazioni sono entrate nella tua eredità, hanno contaminato il tempio della tua santità, han ridotto Gerusalemme in un mucchio di rovine;' WHERE "verseID" = 101784 AND (text = 'Salmo di Asaf.'); -- 23 79:1
UPDATE "LUZZI" SET text = 'hanno dato i cadaveri de'' tuoi servitori in pasto agli uccelli del cielo, la carne de'' tuoi santi alle fiere della terra.' WHERE "verseID" = 101785 AND (text = 'hanno dato i cadaveri de'' tuoi servitori'); -- 23 79:2
UPDATE "LUZZI" SET text = 'Hanno sparso il loro sangue come acqua intorno a Gerusalemme, e non v''è stato alcuno che li seppellisse.' WHERE "verseID" = 101786 AND (text = 'Hanno sparso il loro sangue come acqua'); -- 23 79:3
UPDATE "LUZZI" SET text = 'Noi siam diventati un vituperio per i nostri vicini, un oggetto di scherno e di derisione per quelli che ci circondano.' WHERE "verseID" = 101787 AND (text = 'Noi siam diventati un vituperio per i nostri vicini,'); -- 23 79:4
UPDATE "LUZZI" SET text = 'Fino a quando, o Eterno? Sarai tu adirato per sempre? La tua gelosia arderà essa come un fuoco?' WHERE "verseID" = 101788 AND (text = 'Fino a quando, o Eterno? Sarai tu adirato per sempre?'); -- 23 79:5
UPDATE "LUZZI" SET text = 'Spandi l''ira tua sulle nazioni che non ti conoscono, e sopra i regni che non invocano il tuo nome.' WHERE "verseID" = 101789 AND (text = 'Spandi l''ira tua sulle nazioni che non ti conoscono,'); -- 23 79:6
UPDATE "LUZZI" SET text = 'Poiché hanno divorato Giacobbe, e hanno desolato la sua dimora.' WHERE "verseID" = 101790 AND (text = 'Poiché hanno divorato Giacobbe,'); -- 23 79:7
UPDATE "LUZZI" SET text = 'Non ricordare contro noi le iniquità de'' nostri antenati; affréttati, ci vengano incontro le tue compassioni, poiché siamo in molto misero stato.' WHERE "verseID" = 101791 AND (text = 'Non ricordare contro noi le iniquità de'' nostri antenati;' OR text = 'Non ricordare contro noi le iniquità de'' nostri antenati; affrettati, ci vengano incontro le tue compassioni, poiché siamo in molto misero stato.'); -- 23 79:8
UPDATE "LUZZI" SET text = 'Soccorrici, o Dio della nostra salvezza, per la gloria del tuo nome, e liberaci, e perdona i nostri peccati, per amor del tuo nome.' WHERE "verseID" = 101792 AND (text = 'Soccorrici, o Dio della nostra salvezza,'); -- 23 79:9
UPDATE "LUZZI" SET text = 'Perché direbbero le nazioni: Dov''è l''Iddio loro? Fa'' che la vendetta del sangue sparso de'' tuoi servitori sia nota fra le nazioni, dinanzi agli occhi nostri.' WHERE "verseID" = 101793 AND (text = 'Perché direbbero le nazioni: Dov''è l''Iddio loro?'); -- 23 79:10
UPDATE "LUZZI" SET text = 'Giunga dinanzi a te il gemito de'' prigionieri; secondo la potenza del tuo braccio, scampa quelli che son condannati a morte.' WHERE "verseID" = 101794 AND (text = 'Giunga dinanzi a te il gemito de'' prigionieri;'); -- 23 79:11
UPDATE "LUZZI" SET text = 'E rendi ai nostri vicini a sette doppi in seno di vituperio che t''hanno fatto, o Signore!' WHERE "verseID" = 101795 AND (text = 'E rendi ai nostri vicini a sette doppi in seno' OR text = 'E rendi ai nostri vicini a sette doppi in seno il vituperio che t''hanno fatto, o Signore!'); -- 23 79:12
UPDATE "LUZZI" SET text = 'E noi, tuo popolo e gregge del tuo pasco, ti celebreremo in perpetuo, pubblicheremo la tua lode per ogni età.' WHERE "verseID" = 101796 AND (text = 'E noi, tuo popolo e gregge del tuo pasco,ti celebreremo in perpetuo,pubblicheremo la tua lode per ogni età.'); -- 23 79:13
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Sopra ''i gigli della testimonianza''. Salmo di Asaf. Porgi orecchio, o Pastore d''Israele, che guidi Giuseppe come un gregge; o tu che siedi sopra i cherubini, fa'' risplender la tua gloria!' WHERE "verseID" = 101797 AND (text = 'Per il Capo de'' musici. Sopra ''i gigli della testimonianza''. Salmo di Asaf.'); -- 23 80:1
UPDATE "LUZZI" SET text = 'Dinanzi ad Efraim, a Beniamino ed a Manasse, risveglia la tua potenza, e vieni a salvarci!' WHERE "verseID" = 101798 AND (text = 'Dinanzi ad Efraim, a Beniamino ed a Manasse,'); -- 23 80:2
UPDATE "LUZZI" SET text = 'O Dio, ristabiliscici, fa'' risplendere il tuo volto, e saremo salvati.' WHERE "verseID" = 101799 AND (text = 'O Dio, ristabiliscici,'); -- 23 80:3
UPDATE "LUZZI" SET text = 'O Eterno, Dio degli eserciti, fino a quando sarai tu irritato contro la preghiera del tuo popolo?' WHERE "verseID" = 101800 AND (text = 'O Eterno, Dio degli eserciti,'); -- 23 80:4
UPDATE "LUZZI" SET text = 'Tu li hai cibati di pan di pianto, e li hai abbeverati di lagrime in larga misura.' WHERE "verseID" = 101801 AND (text = 'Tu li hai cibati di pan di pianto,'); -- 23 80:5
UPDATE "LUZZI" SET text = 'Tu fai di noi un oggetto di contesa per i nostri vicini, e i nostri nemici ridon di noi fra loro.' WHERE "verseID" = 101802 AND (text = 'Tu fai di noi un oggetto di contesa per i nostri vicini,'); -- 23 80:6
UPDATE "LUZZI" SET text = 'O Dio degli eserciti, ristabiliscici, fa'' risplendere il tuo volto, e saremo salvati.' WHERE "verseID" = 101803 AND (text = 'O Dio degli eserciti, ristabiliscici,'); -- 23 80:7
UPDATE "LUZZI" SET text = 'Tu trasportasti dall''Egitto una vite; cacciasti le nazioni e la piantasti;' WHERE "verseID" = 101804 AND (text = 'Tu trasportasti dall''Egitto una vite;'); -- 23 80:8
UPDATE "LUZZI" SET text = 'tu sgombrasti il terreno dinanzi a lei, ed essa mise radici, ed empì la terra.' WHERE "verseID" = 101805 AND (text = 'tu sgombrasti il terreno dinanzi a lei,'); -- 23 80:9
UPDATE "LUZZI" SET text = 'I monti furon coperti della sua ombra, e i suoi tralci furon come cedri di Dio.' WHERE "verseID" = 101806 AND (text = 'I monti furon coperti della sua ombra,'); -- 23 80:10
UPDATE "LUZZI" SET text = 'Stese i suoi rami fino al mare, e i suoi rampolli fino al fiume.' WHERE "verseID" = 101807 AND (text = 'Stese i suoi rami fino al mare,'); -- 23 80:11
UPDATE "LUZZI" SET text = 'Perché hai tu rotto i suoi ripari, sì che tutti i passanti la spogliano?' WHERE "verseID" = 101808 AND (text = 'Perché hai tu rotto i suoi ripari,'); -- 23 80:12
UPDATE "LUZZI" SET text = 'Il cinghiale del bosco la devasta, e le bestie della campagna ne fanno il loro pascolo.' WHERE "verseID" = 101809 AND (text = 'Il cinghiale del bosco la devasta,'); -- 23 80:13
UPDATE "LUZZI" SET text = 'O Dio degli eserciti, deh, ritorna; riguarda dal cielo, e vedi, e visita questa vigna;' WHERE "verseID" = 101810 AND (text = 'O Dio degli eserciti, deh, ritorna;'); -- 23 80:14
UPDATE "LUZZI" SET text = 'proteggi quel che la tua destra ha piantato, e il rampollo che hai fatto crescer forte per te.' WHERE "verseID" = 101811 AND (text = 'proteggi quel che la tua destra ha piantato,'); -- 23 80:15
UPDATE "LUZZI" SET text = 'Essa è arsa dal fuoco, è recisa; il popolo perisce alla minaccia del tuo volto.' WHERE "verseID" = 101812 AND (text = 'Essa è arsa dal fuoco, è recisa;'); -- 23 80:16
UPDATE "LUZZI" SET text = 'Sia la tua mano sull''uomo della tua destra, sul figliuol dell''uomo che hai reso forte per te,' WHERE "verseID" = 101813 AND (text = 'Sia la tua mano sull''uomo della tua destra,'); -- 23 80:17
UPDATE "LUZZI" SET text = 'e noi non ci ritrarremo da te. Facci rivivere, e noi invocheremo il tuo nome.' WHERE "verseID" = 101814 AND (text = 'e noi non ci ritrarremo da te.'); -- 23 80:18
UPDATE "LUZZI" SET text = 'O Eterno, Iddio degli eserciti, ristabiliscici, fa'' risplendere il tuo volto, e sarem salvati.' WHERE "verseID" = 101815 AND (text = 'O Eterno, Iddio degli eserciti, ristabiliscici,fa'' risplendere il tuo volto, e sarem salvati.'); -- 23 80:19
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Sulla Ghittea. Salmo di Asaf. Cantate con gioia a Dio nostra forza; mandate grida di allegrezza all''Iddio di Giacobbe!' WHERE "verseID" = 101816 AND (text = 'Per il Capo de'' musici. Sulla Ghittea. Salmo di Asaf.'); -- 23 81:1
UPDATE "LUZZI" SET text = 'Intonate un salmo e fate risonare il cembalo, l''arpa deliziosa, col saltèro.' WHERE "verseID" = 101817 AND (text = 'Intonate un salmo e fate risonare il cembalo,'); -- 23 81:2
UPDATE "LUZZI" SET text = 'Sonate la tromba alla nuova luna, alla luna piena, al giorno della nostra festa.' WHERE "verseID" = 101818 AND (text = 'Sonate la tromba alla nuova luna,'); -- 23 81:3
UPDATE "LUZZI" SET text = 'Poiché questo è uno statuto per Israele, una legge dell''Iddio di Giacobbe.' WHERE "verseID" = 101819 AND (text = 'Poiché questo è uno statuto per Israele,'); -- 23 81:4
UPDATE "LUZZI" SET text = 'Egli lo stabilì come una testimonianza in Giuseppe, quando uscì contro il paese d''Egitto. Io udii allora il linguaggio di uno che m''era ignoto:' WHERE "verseID" = 101820 AND (text = 'Egli lo stabilì come una testimonianza in Giuseppe,'); -- 23 81:5
UPDATE "LUZZI" SET text = 'O Israele, io sottrassi le tue spalle ai pesi, le tue mani han lasciato le corbe.' WHERE "verseID" = 101821 AND (text = 'O Israele, io sottrassi le tue spalle ai pesi,'); -- 23 81:6
UPDATE "LUZZI" SET text = 'Nella distretta gridasti a me ed io ti liberai; ti risposi nascosto in mezzo ai tuoni, ti provai alle acque di Meriba. Sela.' WHERE "verseID" = 101822 AND (text = 'Nella distretta gridasti a me ed io ti liberai;'); -- 23 81:7
UPDATE "LUZZI" SET text = 'Ascolta, o popolo mio, ed io ti darò degli ammonimenti; o Israele, volessi tu pure ascoltarmi!' WHERE "verseID" = 101823 AND (text = 'Ascolta, o popolo mio, ed io ti darò degli ammonimenti;'); -- 23 81:8
UPDATE "LUZZI" SET text = 'Non vi sia nel mezzo di te alcun dio straniero, e non adorare alcun dio forestiero:' WHERE "verseID" = 101824 AND (text = 'Non vi sia nel mezzo di te alcun dio straniero,'); -- 23 81:9
UPDATE "LUZZI" SET text = 'Io sono l''Eterno, l''Iddio tuo, che ti fece risalire dal paese d''Egitto; allarga la tua bocca, ed io l''empirò.' WHERE "verseID" = 101825 AND (text = 'Io sono l''Eterno, l''Iddio tuo,'); -- 23 81:10
UPDATE "LUZZI" SET text = 'Ma il mio popolo non ha ascoltato la mia voce, e Israele non mi ha ubbidito.' WHERE "verseID" = 101826 AND (text = 'Ma il mio popolo non ha ascoltato la mia voce,'); -- 23 81:11
UPDATE "LUZZI" SET text = 'Ond''io li abbandonai alla durezza del cuor loro, perché camminassero secondo i loro consigli.' WHERE "verseID" = 101827 AND (text = 'Ond''io li abbandonai alla durezza del cuor loro,'); -- 23 81:12
UPDATE "LUZZI" SET text = 'Oh se il mio popolo volesse ascoltarmi, se Israele volesse camminare nelle mie vie!' WHERE "verseID" = 101828 AND (text = 'Oh se il mio popolo volesse ascoltarmi,' OR text = 'Oh se il mio popolo volesse ascoltarmi, se Israele volesse camminar nelle mie vie!'); -- 23 81:13
UPDATE "LUZZI" SET text = 'Tosto farei piegare i loro nemici, e rivolgerei la mia mano contro i loro avversari.' WHERE "verseID" = 101829 AND (text = 'Tosto farei piegare i loro nemici,'); -- 23 81:14
UPDATE "LUZZI" SET text = 'Quelli che odiano l''Eterno dovrebbero sottomettersi a lui, ma la loro durata sarebbe in perpetuo.' WHERE "verseID" = 101830 AND (text = 'Quelli che odiano l''Eterno dovrebbero sottomettersi a lui,'); -- 23 81:15
UPDATE "LUZZI" SET text = 'Io li nutrirei del fior di frumento, e li sazierei di miele stillante dalla roccia.' WHERE "verseID" = 101831 AND (text = 'Io li nutrirei del fior di frumento,e li sazierei di miele stillante dalla roccia.'); -- 23 81:16
UPDATE "LUZZI" SET text = 'Salmo di Asaf. Iddio sta nella raunanza di Dio; egli giudica in mezzo agli dèi.' WHERE "verseID" = 101832 AND (text = 'Salmo di Asaf.'); -- 23 82:1
UPDATE "LUZZI" SET text = 'Fino a quando giudicherete ingiustamente, e avrete riguardo alle persone degli empi? Sela.' WHERE "verseID" = 101833 AND (text = 'Fino a quando giudicherete ingiustamente,'); -- 23 82:2
UPDATE "LUZZI" SET text = 'Fate ragione al misero e all''orfano, rendete giustizia all''afflitto e al povero!' WHERE "verseID" = 101834 AND (text = 'Fate ragione al misero e all''orfano,'); -- 23 82:3
UPDATE "LUZZI" SET text = 'Liberate il misero ed il bisognoso, salvatelo dalla mano degli empi!' WHERE "verseID" = 101835 AND (text = 'Liberate il misero ed il bisognoso,'); -- 23 82:4
UPDATE "LUZZI" SET text = 'Essi non conoscono né intendono nulla; camminano nelle tenebre; tutti i fondamenti della terra sono smossi.' WHERE "verseID" = 101836 AND (text = 'Essi non conoscono né intendono nulla;'); -- 23 82:5
UPDATE "LUZZI" SET text = 'Io ho detto: Voi siete dii, siete tutti figliuoli dell''Altissimo.' WHERE "verseID" = 101837 AND (text = 'Io ho detto: Voi siete dii,'); -- 23 82:6
UPDATE "LUZZI" SET text = 'Nondimeno morrete come gli altri uomini, e cadrete come qualunque altro dei principi.' WHERE "verseID" = 101838 AND (text = 'Nondimeno morrete come gli altri uomini,' OR text = 'Nondimeno morrete come gli altri uomini, e cadrete come qualunque altro de'' principi.'); -- 23 82:7
UPDATE "LUZZI" SET text = 'Lèvati, o Dio, giudica la terra, poiché tutte le nazioni hanno da esser la tua eredità.' WHERE "verseID" = 101839 AND (text = 'Lèvati, o Dio, giudica la terra,poiché tutte le nazioni hanno da esser la tua eredità.'); -- 23 82:8
UPDATE "LUZZI" SET text = 'Canto. Salmo di Asaf. O Dio, non startene cheto; non rimaner muto ed inerte, o Dio!' WHERE "verseID" = 101840 AND (text = 'Canto. Salmo di Asaf.'); -- 23 83:1
UPDATE "LUZZI" SET text = 'Poiché, ecco, i tuoi nemici si agitano rumorosamente, e quelli che t''odiano alzano il capo.' WHERE "verseID" = 101841 AND (text = 'Poiché, ecco, i tuoi nemici si agitano rumorosamente,'); -- 23 83:2
UPDATE "LUZZI" SET text = 'Tramano astuti disegni contro il tuo popolo, e si concertano contro quelli che tu nascondi presso di te.' WHERE "verseID" = 101842 AND (text = 'Tramano astuti disegni contro il tuo popolo,'); -- 23 83:3
UPDATE "LUZZI" SET text = 'Dicono: Venite, distruggiamoli come nazione, e il nome d''Israele non sia più ricordato.' WHERE "verseID" = 101843 AND (text = 'Dicono: Venite, distruggiamoli come nazione,'); -- 23 83:4
UPDATE "LUZZI" SET text = 'Poiché si sono concertati con uno stesso sentimento, fanno un patto contro di te:' WHERE "verseID" = 101844 AND (text = 'Poiché si sono concertati con uno stesso sentimento,'); -- 23 83:5
UPDATE "LUZZI" SET text = 'le tende di Edom e gl''Ismaeliti; Moab e gli Hagareni;' WHERE "verseID" = 101845 AND (text = 'le tende di Edom e gl''Ismaeliti;'); -- 23 83:6
UPDATE "LUZZI" SET text = 'Ghebal, Ammon ed Amalek; la Filistia con gli abitanti di Tiro;' WHERE "verseID" = 101846 AND (text = 'Ghebal, Ammon ed Amalek;'); -- 23 83:7
UPDATE "LUZZI" SET text = 'anche l''Assiria s''è aggiunta a loro; prestano il loro braccio ai figliuoli di Lot. Sela.' WHERE "verseID" = 101847 AND (text = 'anche l''Assiria s''è aggiunta a loro;'); -- 23 83:8
UPDATE "LUZZI" SET text = 'Fa'' a loro come facesti a Midian, a Sisera, a Jabin presso al torrente di Chison,' WHERE "verseID" = 101848 AND (text = 'Fa'' a loro come facesti a Midian,'); -- 23 83:9
UPDATE "LUZZI" SET text = 'i quali furon distrutti a Endor, e serviron di letame alla terra.' WHERE "verseID" = 101849 AND (text = 'i quali furon distrutti a Endor,'); -- 23 83:10
UPDATE "LUZZI" SET text = 'Rendi i loro capi simili ad Oreb e Zeeb, e tutti i loro principi simili a Zeba e Tsalmunna;' WHERE "verseID" = 101850 AND (text = 'Rendi i loro capi simili ad Oreb e Zeeb,'); -- 23 83:11
UPDATE "LUZZI" SET text = 'poiché dicono: Impossessiamoci delle dimore di Dio.' WHERE "verseID" = 101851 AND (text = 'poiché dicono: Impossessiamoci'); -- 23 83:12
UPDATE "LUZZI" SET text = 'Dio mio, rendili simili al turbine, simili a stoppia dinanzi al vento.' WHERE "verseID" = 101852 AND (text = 'Dio mio, rendili simili al turbine,'); -- 23 83:13
UPDATE "LUZZI" SET text = 'Come il fuoco brucia la foresta, e come la fiamma incendia i monti,' WHERE "verseID" = 101853 AND (text = 'Come il fuoco brucia la foresta,'); -- 23 83:14
UPDATE "LUZZI" SET text = 'così perseguitali con la tua tempesta, e spaventali col tuo uragano.' WHERE "verseID" = 101854 AND (text = 'così perseguitali con la tua tempesta,'); -- 23 83:15
UPDATE "LUZZI" SET text = 'Cuopri la loro faccia di vituperio, onde cerchino il tuo nome, o Eterno!' WHERE "verseID" = 101855 AND (text = 'Cuopri la loro faccia di vituperio,'); -- 23 83:16
UPDATE "LUZZI" SET text = 'Siano svergognati, e costernati in perpetuo, siano confusi e periscano!' WHERE "verseID" = 101856 AND (text = 'Siano svergognati, e costernati in perpetuo,'); -- 23 83:17
UPDATE "LUZZI" SET text = 'E conoscano che tu, il cui nome è l''Eterno, sei il solo Altissimo sopra tutta la terra.' WHERE "verseID" = 101857 AND (text = 'E conoscano che tu, il cui nome è l''Eterno,sei il solo Altissimo sopra tutta la terra.'); -- 23 83:18
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Sulla Ghittea. Salmo de'' figliuoli di Kore. Oh quanto sono amabili le tue dimore, o Eterno degli eserciti!' WHERE "verseID" = 101858 AND (text = 'Per il Capo de'' musici. Sulla Ghittea. Salmo de'' figliuoli di Kore.'); -- 23 84:1
UPDATE "LUZZI" SET text = 'L''anima mia langue e vien meno, bramando i cortili dell''Eterno; il mio cuore e la mia carne mandan grida di gioia all''Iddio vivente.' WHERE "verseID" = 101859 AND (text = 'L''anima mia langue e vien meno,'); -- 23 84:2
UPDATE "LUZZI" SET text = 'Anche il passero si trova una casa e la rondine un nido ove posare i suoi piccini... I tuoi altari, o Eterno degli eserciti, Re mio, Dio mio!...' WHERE "verseID" = 101860 AND (text = 'Anche il passero si trova una casa' OR text = 'Anche il passero si trova una casa e la rondine un nido ove posare i suoi piccini… I tuoi altari, o Eterno degli eserciti, Re mio, Dio mio!…'); -- 23 84:3
UPDATE "LUZZI" SET text = 'Beati quelli che abitano nella tua casa, e ti lodano del continuo! Sela.' WHERE "verseID" = 101861 AND (text = 'Beati quelli che abitano nella tua casa,'); -- 23 84:4
UPDATE "LUZZI" SET text = 'Beati quelli che hanno in te la loro forza, che hanno il cuore alle vie del Santuario!' WHERE "verseID" = 101862 AND (text = 'Beati quelli che hanno in te la loro forza,'); -- 23 84:5
UPDATE "LUZZI" SET text = 'Quando attraversano la valle di Baca essi la trasformano in luogo di fonti; e la pioggia d''autunno la cuopre di benedizioni.' WHERE "verseID" = 101863 AND (text = 'Quando attraversano la valle di Baca'); -- 23 84:6
UPDATE "LUZZI" SET text = 'Essi vanno di forza in forza, e compariscono alfine davanti a Dio in Sion.' WHERE "verseID" = 101864 AND (text = 'Essi vanno di forza in forza,'); -- 23 84:7
UPDATE "LUZZI" SET text = 'O Eterno, Iddio degli eserciti, ascolta la mia preghiera; porgi l''orecchio, o Dio di Giacobbe! Sela.' WHERE "verseID" = 101865 AND (text = 'O Eterno, Iddio degli eserciti, ascolta la mia preghiera;'); -- 23 84:8
UPDATE "LUZZI" SET text = 'O Dio, scudo nostro, vedi e riguarda la faccia del tuo unto!' WHERE "verseID" = 101866 AND (text = 'O Dio, scudo nostro, vedi'); -- 23 84:9
UPDATE "LUZZI" SET text = 'Poiché un giorno ne'' tuoi cortili val meglio che mille altrove. Io vorrei piuttosto starmene sulla soglia della casa del mio Dio, che abitare nelle tende degli empi.' WHERE "verseID" = 101867 AND (text = 'Poiché un giorno ne'' tuoi cortili val meglio che mille altrove.'); -- 23 84:10
UPDATE "LUZZI" SET text = 'Perché l''Eterno Iddio è sole e scudo; l''Eterno darà grazia e gloria. Egli non ricuserà alcun bene a quelli che camminano nella integrità.' WHERE "verseID" = 101868 AND (text = 'Perché l''Eterno Iddio è sole e scudo;'); -- 23 84:11
UPDATE "LUZZI" SET text = 'O Eterno degli eserciti, beato l''uomo che confida in te!' WHERE "verseID" = 101869 AND (text = 'O Eterno degli eserciti,beato l''uomo che confida in te!'); -- 23 84:12
UPDATE "LUZZI" SET text = 'Per il Capo de'' musici. Salmo dei figliuoli di Kore. O Eterno, tu sei stato propizio alla tua terra, tu hai ricondotto Giacobbe dalla cattività.' WHERE "verseID" = 101870 AND (text = 'Per il Capo de'' musici. Salmo dei figliuoli di Kore.'); -- 23 85:1
UPDATE "LUZZI" SET text = 'Tu hai perdonato l''iniquità del tuo popolo, hai coperto tutti i loro peccati. Sela.' WHERE "verseID" = 101871 AND (text = 'Tu hai perdonato l''iniquità del tuo popolo,'); -- 23 85:2
UPDATE "LUZZI" SET text = 'Tu hai acquietato tutto il tuo cruccio, ti sei distolto dall''ardore della tua ira.' WHERE "verseID" = 101872 AND (text = 'Tu hai acquietato tutto il tuo cruccio,'); -- 23 85:3
UPDATE "LUZZI" SET text = 'Ristabiliscici, o Dio della nostra salvezza, e fa'' cessar la tua indignazione contro di noi.' WHERE "verseID" = 101873 AND (text = 'Ristabiliscici, o Dio della nostra salvezza,'); -- 23 85:4
UPDATE "LUZZI" SET text = 'Sarai tu adirato contro di noi in perpetuo? Farai tu durar l''ira tua d''età in età?' WHERE "verseID" = 101874 AND (text = 'Sarai tu adirato contro di noi in perpetuo?'); -- 23 85:5
UPDATE "LUZZI" SET text = 'Non tornerai tu a ravvivarci, onde il tuo popolo si rallegri in te?' WHERE "verseID" = 101875 AND (text = 'Non tornerai tu a ravvivarci,'); -- 23 85:6
UPDATE "LUZZI" SET text = 'Mostraci la tua benignità, o Eterno, e dacci la tua salvezza.' WHERE "verseID" = 101876 AND (text = 'Mostraci la tua benignità, o Eterno,'); -- 23 85:7
UPDATE "LUZZI" SET text = 'Io ascolterò quel che dirà Iddio, l''Eterno, poiché egli parlerà di pace al suo popolo ed ai suoi fedeli; ma non ritornino più alla follia!' WHERE "verseID" = 101877 AND (text = 'Io ascolterò quel che dirà Iddio, l''Eterno,'); -- 23 85:8
UPDATE "LUZZI" SET text = 'Certo, la sua salvezza è vicina a quelli che lo temono, affinché la gloria abiti nel nostro paese.' WHERE "verseID" = 101878 AND (text = 'Certo, la sua salvezza è vicina a quelli che lo temono,'); -- 23 85:9
UPDATE "LUZZI" SET text = 'La benignità e la verità si sono incontrate, la giustizia e la pace si son baciate.' WHERE "verseID" = 101879 AND (text = 'La benignità e la verità si sono incontrate,'); -- 23 85:10
UPDATE "LUZZI" SET text = 'La verità germoglia dalla terra, e la giustizia riguarda dal cielo.' WHERE "verseID" = 101880 AND (text = 'La verità germoglia dalla terra,'); -- 23 85:11
UPDATE "LUZZI" SET text = 'Anche l''Eterno largirà ogni bene, e la nostra terra produrrà il suo frutto.' WHERE "verseID" = 101881 AND (text = 'Anche l''Eterno largirà ogni bene,'); -- 23 85:12
UPDATE "LUZZI" SET text = 'La giustizia camminerà dinanzi a lui, e seguirà la via dei suoi passi.' WHERE "verseID" = 101882 AND (text = 'La giustizia camminerà dinanzi a lui,e seguirà la via dei suoi passi.'); -- 23 85:13
UPDATE "LUZZI" SET text = 'Preghiera di Davide. Inclina l''orecchio tuo, o Eterno, e rispondimi, perché io sono afflitto e misero.' WHERE "verseID" = 101883 AND (text = 'Preghiera di Davide.'); -- 23 86:1
UPDATE "LUZZI" SET text = 'Proteggi l''anima mia, perché sono di quelli che t''amano. Tu, mio Dio, salva il tuo servitore che confida in te!' WHERE "verseID" = 101884 AND (text = 'Proteggi l''anima mia, perché sono di quelli che t''amano.'); -- 23 86:2
UPDATE "LUZZI" SET text = 'Abbi pietà di me, o Signore, perché io grido a te tutto il giorno.' WHERE "verseID" = 101885 AND (text = 'Abbi pietà di me, o Signore,'); -- 23 86:3
UPDATE "LUZZI" SET text = 'Rallegra l''anima del tuo servitore, perché a te, o Signore, io elevo l''anima mia.' WHERE "verseID" = 101886 AND (text = 'Rallegra l''anima del tuo servitore,'); -- 23 86:4
UPDATE "LUZZI" SET text = 'Poiché tu, o Signore, sei buono, pronto a perdonare, e di gran benignità verso tutti quelli che t''invocano.' WHERE "verseID" = 101887 AND (text = 'Poiché tu, o Signore, sei buono, pronto a perdonare,'); -- 23 86:5
UPDATE "LUZZI" SET text = 'Porgi l''orecchio, o Eterno, alla mia preghiera, e sii attento alla voce delle mie supplicazioni.' WHERE "verseID" = 101888 AND (text = 'Porgi l''orecchio, o Eterno, alla mia preghiera,'); -- 23 86:6
UPDATE "LUZZI" SET text = 'Io t''invoco nel giorno della mia distretta, perché tu mi risponderai.' WHERE "verseID" = 101889 AND (text = 'Io t''invoco nel giorno della mia distretta,'); -- 23 86:7
UPDATE "LUZZI" SET text = 'Non v''è nessuno pari a te fra gli dèi, o Signore, né vi sono alcune opere pari alle tue.' WHERE "verseID" = 101890 AND (text = 'Non v''è nessuno pari a te fra gli dèi, o Signore,'); -- 23 86:8
UPDATE "LUZZI" SET text = 'Tutte le nazioni che tu hai fatte verranno ad adorare nel tuo cospetto, o Signore, e glorificheranno il tuo nome.' WHERE "verseID" = 101891 AND (text = 'Tutte le nazioni che tu hai fatte'); -- 23 86:9
UPDATE "LUZZI" SET text = 'Poiché tu sei grande e fai maraviglie; tu solo sei Dio.' WHERE "verseID" = 101892 AND (text = 'Poiché tu sei grande e fai maraviglie;'); -- 23 86:10
UPDATE "LUZZI" SET text = 'O Eterno, insegnami la tua via; io camminerò nella tua verità; unisci il mio cuore al timor del tuo nome.' WHERE "verseID" = 101893 AND (text = 'O Eterno, insegnami la tua via;'); -- 23 86:11
UPDATE "LUZZI" SET text = 'Io ti celebrerò, Signore, Iddio mio, con tutto il mio cuore, e glorificherò il tuo nome in perpetuo.' WHERE "verseID" = 101894 AND (text = 'Io ti celebrerò, Signore, Iddio mio, con tutto il mio cuore,'); -- 23 86:12
UPDATE "LUZZI" SET text = 'Perché grande è la tua benignità verso me, e tu hai riscossa l''anima mia dal fondo del soggiorno de'' morti.' WHERE "verseID" = 101895 AND (text = 'Perché grande è la tua benignità verso me,'); -- 23 86:13
UPDATE "LUZZI" SET text = 'O Dio, gente superba s''è levata contro di me, e una turba di violenti cerca l''anima mia, e non pongono te davanti agli occhi loro.' WHERE "verseID" = 101896 AND (text = 'O Dio, gente superba s''è levata contro di me,'); -- 23 86:14
UPDATE "LUZZI" SET text = 'Ma tu, o Signore, sei un Dio pietoso e misericordioso, lento all''ira e grande in benignità e in verità.' WHERE "verseID" = 101897 AND (text = 'Ma tu, o Signore, sei un Dio pietoso e misericordioso,'); -- 23 86:15
UPDATE "LUZZI" SET text = 'Volgiti a me, ed abbi pietà di me; da'' la tua forza al tuo servitore, e salva il figliuolo della tua servente.' WHERE "verseID" = 101898 AND (text = 'Volgiti a me, ed abbi pietà di me;'); -- 23 86:16
UPDATE "LUZZI" SET text = 'Mostrami un segno del tuo favore, onde quelli che m''odiano lo veggano e sian confusi, perché tu, o Eterno, m''avrai soccorso e consolato.' WHERE "verseID" = 101899 AND (text = 'Mostrami un segno del tuo favore,onde quelli che m''odiano lo veggano e sian confusi,perché tu, o Eterno, m''avrai soccorso e consolato.'); -- 23 86:17
UPDATE "LUZZI" SET text = 'Salmo dei figliuoli di Kore. Canto. L''Eterno ha fondato la sua città sui monti santi.' WHERE "verseID" = 101900 AND (text = 'Salmo dei figliuoli di Kore. Canto.'); -- 23 87:1
UPDATE "LUZZI" SET text = 'Egli ama le porte di Sion più di tutte le dimore di Giacobbe.' WHERE "verseID" = 101901 AND (text = 'Egli ama le porte di Sion'); -- 23 87:2
UPDATE "LUZZI" SET text = 'Cose gloriose son dette di te, o città di Dio! Sela.' WHERE "verseID" = 101902 AND (text = 'Cose gloriose son dette di te,'); -- 23 87:3
UPDATE "LUZZI" SET text = 'Io mentoverò l''Egitto e Babilonia fra quelli che mi conoscono: Ecco la Filistia e Tiro con l''Etiopia: ciascun d''essi è nato in Sion!' WHERE "verseID" = 101903 AND (text = 'Io mentoverò l''Egitto e Babilonia fra quelli che mi conoscono:' OR text = 'Io mentoverò l''Egitto e Babilonia fra quelli che mi conoscono: Ecco la Filistia e Tiro, con l''Etiopia: Ciascun d''essi è nato in Sion!'); -- 23 87:4
UPDATE "LUZZI" SET text = 'E si dirà di Sion: Questo qui e quello là son nati in lei; e l''Altissimo stesso la renderà stabile.' WHERE "verseID" = 101904 AND (text = 'E si dirà di Sion: Questo qui e quello là son nati in lei;'); -- 23 87:5
UPDATE "LUZZI" SET text = 'L''Eterno iscriverà, passando in rassegna i popoli: Questo è nato là. Sela.' WHERE "verseID" = 101905 AND (text = 'L''Eterno iscriverà, passando in rassegna i popoli:'); -- 23 87:6
UPDATE "LUZZI" SET text = 'E cantando e danzando diranno: Tutte le fonti della mia gioia sono in te.' WHERE "verseID" = 101906 AND (text = 'E cantando e danzando diranno:Tutte le fonti della mia gioia sono in te.'); -- 23 87:7
UPDATE "LUZZI" SET text = 'Canto. Salmo dei figliuoli di Kore. Per il Capo de'' musici. Da cantarsi mestamente. Cantico di Heman, l''Ezrahita. O Eterno, Dio della mia salvezza, io grido giorno e notte nel tuo cospetto.' WHERE "verseID" = 101907 AND (text = 'Canto. Salmo dei figliuoli di Kore. Per il Capo de'' musici. Da cantarsi mestamente. Cantico di Heman, l''Ezrahita.'); -- 23 88:1
UPDATE "LUZZI" SET text = 'Venga la mia preghiera dinanzi a te, inclina il tuo orecchio al mio grido;' WHERE "verseID" = 101908 AND (text = 'Venga la mia preghiera dinanzi a te,'); -- 23 88:2
UPDATE "LUZZI" SET text = 'poiché l''anima mia è sazia di mali, e la mia vita è giunta presso al soggiorno dei morti.' WHERE "verseID" = 101909 AND (text = 'poiché l''anima mia è sazia di mali,'); -- 23 88:3
UPDATE "LUZZI" SET text = 'Io son contato fra quelli che scendon nella fossa; son come un uomo che non ha più forza.' WHERE "verseID" = 101910 AND (text = 'Io son contato fra quelli che scendon nella fossa;'); -- 23 88:4
UPDATE "LUZZI" SET text = 'Prostrato sto fra i morti, come gli uccisi che giaccion nella tomba, de'' quali tu non ti ricordi più, e che son fuor della portata della tua mano.' WHERE "verseID" = 101911 AND (text = 'Prostrato sto fra i morti,'); -- 23 88:5
UPDATE "LUZZI" SET text = 'Tu m''hai posto nella fossa più profonda, in luoghi tenebrosi, negli abissi.' WHERE "verseID" = 101912 AND (text = 'Tu m''hai posto nella fossa più profonda,'); -- 23 88:6
UPDATE "LUZZI" SET text = 'L''ira tua pesa su me, e tu m''hai abbattuto con tutti i tuoi flutti. Sela.' WHERE "verseID" = 101913 AND (text = 'L''ira tua pesa su me,'); -- 23 88:7
UPDATE "LUZZI" SET text = 'Tu hai allontanato da me i miei conoscenti, m''hai reso un''abominazione per loro. Io son rinchiuso e non posso uscire.' WHERE "verseID" = 101914 AND (text = 'Tu hai allontanato da me i miei conoscenti,'); -- 23 88:8
UPDATE "LUZZI" SET text = 'L''occhio mio si consuma per l''afflizione; io t''invoco ogni giorno, o Eterno, stendo verso te le mie mani.' WHERE "verseID" = 101915 AND (text = 'L''occhio mio si consuma per l''afflizione;'); -- 23 88:9
UPDATE "LUZZI" SET text = 'Opererai tu qualche miracolo per i morti? I trapassati risorgeranno essi a celebrarti? Sela.' WHERE "verseID" = 101916 AND (text = 'Opererai tu qualche miracolo per i morti?'); -- 23 88:10
UPDATE "LUZZI" SET text = 'La tua benignità sarà ella narrata nel sepolcro, o la tua fedeltà nel luogo della distruzione?' WHERE "verseID" = 101917 AND (text = 'La tua benignità sarà ella narrata nel sepolcro,'); -- 23 88:11
UPDATE "LUZZI" SET text = 'Le tue maraviglie saranno esse note nelle tenebre, e la tua giustizia nella terra dell''oblìo?' WHERE "verseID" = 101918 AND (text = 'Le tue maraviglie saranno esse note nelle tenebre,'); -- 23 88:12
UPDATE "LUZZI" SET text = 'Ma, quant''è a me, o Eterno, io grido a te, e la mattina la mia preghiera ti viene incontro.' WHERE "verseID" = 101919 AND (text = 'Ma, quant''è a me, o Eterno, io grido a te,'); -- 23 88:13
UPDATE "LUZZI" SET text = 'Perché, o Eterno, rigetti tu l''anima mia? Perché nascondi il tuo volto da me?' WHERE "verseID" = 101920 AND (text = 'Perché, o Eterno, rigetti tu l''anima mia?'); -- 23 88:14
UPDATE "LUZZI" SET text = 'Io sono afflitto, e morente fin da giovane; io porto il peso dei tuoi terrori e sono smarrito.' WHERE "verseID" = 101921 AND (text = 'Io sono afflitto, e morente fin da giovane;'); -- 23 88:15
UPDATE "LUZZI" SET text = 'I tuoi furori mi son passati addosso; i tuoi terrori m''annientano,' WHERE "verseID" = 101922 AND (text = 'I tuoi furori mi son passati addosso;'); -- 23 88:16
UPDATE "LUZZI" SET text = 'mi circondano come acque ogni giorno, mi attornian tutti assieme.' WHERE "verseID" = 101923 AND (text = 'mi circondano come acque ogni giorno,'); -- 23 88:17
UPDATE "LUZZI" SET text = 'Hai allontanato da me amici e compagni; i miei conoscenti sono le tenebre.' WHERE "verseID" = 101924 AND (text = 'Hai allontanato da me amici e compagni;i miei conoscenti sono le tenebre.'); -- 23 88:18
UPDATE "LUZZI" SET text = 'Cantico di Etan l''Ezrahita. Io canterò in perpetuo le benignità dell''Eterno; con la mia bocca farò nota la tua fedeltà d''età in età.' WHERE "verseID" = 101925 AND (text = 'Cantico di Etan l''Ezrahita.'); -- 23 89:1
UPDATE "LUZZI" SET text = 'Poiché ho detto: La tua benignità sarà stabile in eterno; nei cieli stessi tu stabilisci la tua fedeltà.' WHERE "verseID" = 101926 AND (text = 'Poiché ho detto: La tua benignità sarà stabile in eterno;'); -- 23 89:2
UPDATE "LUZZI" SET text = 'Io, dice l''Eterno, ho fatto un patto col mio eletto; ho fatto questo giuramento a Davide, mio servitore:' WHERE "verseID" = 101927 AND (text = 'Io, dice l''Eterno, ho fatto un patto col mio eletto;'); -- 23 89:3
UPDATE "LUZZI" SET text = 'Io stabilirò la tua progenie in eterno, ed edificherò il tuo trono per ogni età. Sela.' WHERE "verseID" = 101928 AND (text = 'Io stabilirò la tua progenie in eterno,'); -- 23 89:4
UPDATE "LUZZI" SET text = 'Anche i cieli celebrano le tue maraviglie, o Eterno, la tua fedeltà nell''assemblea dei santi.' WHERE "verseID" = 101929 AND (text = 'Anche i cieli celebrano le tue maraviglie, o Eterno,' OR text = 'Anche i cieli celebrano le tue maraviglie, o Eterno, e la tua fedeltà nell''assemblea dei santi.'); -- 23 89:5
UPDATE "LUZZI" SET text = 'Poiché chi, nei cieli, è paragonabile all''Eterno? Chi è simile all''Eterno tra i figli di Dio?' WHERE "verseID" = 101930 AND (text = 'Poiché chi, nei cieli, è paragonabile all''Eterno?'); -- 23 89:6
UPDATE "LUZZI" SET text = 'Iddio è molto terribile nell''assemblea dei santi, e più tremendo di tutti quelli che l''attorniano.' WHERE "verseID" = 101931 AND (text = 'Iddio è molto terribile nell''assemblea dei santi,'); -- 23 89:7
UPDATE "LUZZI" SET text = 'O Eterno, Iddio degli eserciti, chi è potente come te, o Eterno? E la tua fedeltà ti circonda da ogni parte.' WHERE "verseID" = 101932 AND (text = 'O Eterno, Iddio degli eserciti,'); -- 23 89:8
UPDATE "LUZZI" SET text = 'Tu domi l''orgoglio del mare; quando le sue onde s''innalzano, tu le acqueti.' WHERE "verseID" = 101933 AND (text = 'Tu domi l''orgoglio del mare;'); -- 23 89:9
UPDATE "LUZZI" SET text = 'Tu hai fiaccato l''Egitto, ferendolo a morte; col tuo braccio potente, hai disperso i tuoi nemici.' WHERE "verseID" = 101934 AND (text = 'Tu hai fiaccato l''Egitto, ferendolo a morte;'); -- 23 89:10
UPDATE "LUZZI" SET text = 'I cieli son tuoi, tua pure è la terra; tu hai fondato il mondo e tutto ciò ch''è in esso.' WHERE "verseID" = 101935 AND (text = 'I cieli son tuoi, tua pure è la terra;'); -- 23 89:11
UPDATE "LUZZI" SET text = 'Hai creato il settentrione e il mezzodì; il Tabor e l''Hermon mandan grida di gioia al tuo nome.' WHERE "verseID" = 101936 AND (text = 'Hai creato il settentrione e il mezzodì;'); -- 23 89:12
UPDATE "LUZZI" SET text = 'Tu hai un braccio potente; la tua mano è forte, alta è la tua destra.' WHERE "verseID" = 101937 AND (text = 'Tu hai un braccio potente;'); -- 23 89:13
UPDATE "LUZZI" SET text = 'Giustizia e diritto son la base del tuo trono, benignità e verità van davanti alla tua faccia.' WHERE "verseID" = 101938 AND (text = 'Giustizia e diritto son la base del tuo trono,'); -- 23 89:14
UPDATE "LUZZI" SET text = 'Beato il popolo che conosce il grido di giubilo; esso cammina, o Eterno, alla luce del tuo volto;' WHERE "verseID" = 101939 AND (text = 'Beato il popolo che conosce il grido di giubilo;'); -- 23 89:15
UPDATE "LUZZI" SET text = 'festeggia del continuo nel tuo nome, ed è esaltato dalla tua giustizia.' WHERE "verseID" = 101940 AND (text = 'festeggia del continuo nel tuo nome,'); -- 23 89:16
UPDATE "LUZZI" SET text = 'Perché tu sei la gloria della loro forza; e la nostra potenza è esaltata dal tuo favore.' WHERE "verseID" = 101941 AND (text = 'Perché tu sei la gloria della loro forza;'); -- 23 89:17
UPDATE "LUZZI" SET text = 'Poiché il nostro scudo appartiene all''Eterno, e il nostro re al Santo d''Israele.' WHERE "verseID" = 101942 AND (text = 'Poiché il nostro scudo appartiene all''Eterno,'); -- 23 89:18
UPDATE "LUZZI" SET text = 'Tu parlasti già in visione al tuo diletto, e dicesti: Ho prestato aiuto a un prode, ho innalzato un eletto d''infra il popolo.' WHERE "verseID" = 101943 AND (text = 'Tu parlasti già in visione al tuo diletto,'); -- 23 89:19
UPDATE "LUZZI" SET text = 'Ho trovato Davide, mio servitore, l''ho unto con l''olio mio santo;' WHERE "verseID" = 101944 AND (text = 'Ho trovato Davide, mio servitore,'); -- 23 89:20
UPDATE "LUZZI" SET text = 'la mia mano sarà salda nel sostenerlo, e il mio braccio lo fortificherà.' WHERE "verseID" = 101945 AND (text = 'la mia mano sarà salda nel sostenerlo,'); -- 23 89:21
UPDATE "LUZZI" SET text = 'Il nemico non lo sorprenderà, e il perverso non l''opprimerà.' WHERE "verseID" = 101946 AND (text = 'Il nemico non lo sorprenderà,'); -- 23 89:22
UPDATE "LUZZI" SET text = 'Io fiaccherò dinanzi a lui i suoi nemici, e sconfiggerò quelli che l''odiano.' WHERE "verseID" = 101947 AND (text = 'Io fiaccherò dinanzi a lui i suoi nemici,'); -- 23 89:23
UPDATE "LUZZI" SET text = 'La mia fedeltà e la mia benignità saranno con lui, e nel mio nome la sua potenza sarà esaltata.' WHERE "verseID" = 101948 AND (text = 'La mia fedeltà e la mia benignità saranno con lui,'); -- 23 89:24
UPDATE "LUZZI" SET text = 'E stenderò la sua mano sul mare, e la sua destra sui fiumi.' WHERE "verseID" = 101949 AND (text = 'E stenderò la sua mano sul mare,'); -- 23 89:25
UPDATE "LUZZI" SET text = 'Egli m''invocherà, dicendo: Tu sei il mio Padre, il mio Dio, e la ròcca della mia salvezza.' WHERE "verseID" = 101950 AND (text = 'Egli m''invocherà, dicendo: Tu sei il mio Padre,'); -- 23 89:26
UPDATE "LUZZI" SET text = 'Io altresì lo farò il primogenito, il più eccelso dei re della terra.' WHERE "verseID" = 101951 AND (text = 'Io altresì lo farò il primogenito,'); -- 23 89:27
UPDATE "LUZZI" SET text = 'Io gli conserverò la mia benignità in perpetuo, e il mio patto rimarrà fermo con lui.' WHERE "verseID" = 101952 AND (text = 'Io gli conserverò la mia benignità in perpetuo,'); -- 23 89:28
UPDATE "LUZZI" SET text = 'Io renderò la sua progenie eterna, e il suo trono simile ai giorni dei cieli.' WHERE "verseID" = 101953 AND (text = 'Io renderò la sua progenie eterna,' OR text = 'Io renderò la sua progenie eterna, e il suo trono simile ai giorni de'' cieli.'); -- 23 89:29
UPDATE "LUZZI" SET text = 'Se i suoi figliuoli abbandonan la mia legge e non camminano secondo i miei ordini,' WHERE "verseID" = 101954 AND (text = 'Se i suoi figliuoli abbandonan la mia legge'); -- 23 89:30
UPDATE "LUZZI" SET text = 'se violano i miei statuti e non osservano i miei comandamenti,' WHERE "verseID" = 101955 AND (text = 'se violano i miei statuti'); -- 23 89:31
UPDATE "LUZZI" SET text = 'io punirò la loro trasgressione con la verga, e la loro iniquità con percosse;' WHERE "verseID" = 101956 AND (text = 'io punirò la loro trasgressione con la verga,'); -- 23 89:32
UPDATE "LUZZI" SET text = 'ma non gli ritirerò la mia benignità, e non smentirò la mia fedeltà.' WHERE "verseID" = 101957 AND (text = 'ma non gli ritirerò la mia benignità,'); -- 23 89:33
UPDATE "LUZZI" SET text = 'Io non violerò il mio patto, e non muterò ciò ch''è uscito dalle mie labbra.' WHERE "verseID" = 101958 AND (text = 'Io non violerò il mio patto,'); -- 23 89:34
UPDATE "LUZZI" SET text = 'Una cosa ho giurata per la mia santità, e non mentirò a Davide:' WHERE "verseID" = 101959 AND (text = 'Una cosa ho giurata per la mia santità,'); -- 23 89:35
UPDATE "LUZZI" SET text = 'La sua progenie durerà in eterno, e il suo trono sarà davanti a me come il sole,' WHERE "verseID" = 101960 AND (text = 'La sua progenie durerà in eterno,'); -- 23 89:36
UPDATE "LUZZI" SET text = 'sarà stabile in perpetuo come la luna; e il testimone ch''è nei cieli è fedele. Sela.' WHERE "verseID" = 101961 AND (text = 'sarà stabile in perpetuo come la luna;'); -- 23 89:37
UPDATE "LUZZI" SET text = 'Eppure tu l''hai reietto e sprezzato, ti sei gravemente adirato contro il tuo unto.' WHERE "verseID" = 101962 AND (text = 'Eppure tu l''hai reietto e sprezzato,'); -- 23 89:38
UPDATE "LUZZI" SET text = 'Tu hai rinnegato il patto stretto col tuo servitore, hai profanato la sua corona gettandola a terra.' WHERE "verseID" = 101963 AND (text = 'Tu hai rinnegato il patto stretto col tuo servitore,'); -- 23 89:39
UPDATE "LUZZI" SET text = 'Tu hai rotto i suoi ripari, hai ridotto in ruine le sue fortezze.' WHERE "verseID" = 101964 AND (text = 'Tu hai rotto i suoi ripari,'); -- 23 89:40
UPDATE "LUZZI" SET text = 'Tutti i passanti l''han saccheggiato, è diventato il vituperio de'' suoi vicini.' WHERE "verseID" = 101965 AND (text = 'Tutti i passanti l''han saccheggiato,'); -- 23 89:41
UPDATE "LUZZI" SET text = 'Tu hai esaltato la destra de'' suoi avversari, hai rallegrato tutti i suoi nemici.' WHERE "verseID" = 101966 AND (text = 'Tu hai esaltato la destra de'' suoi avversari,'); -- 23 89:42
UPDATE "LUZZI" SET text = 'Tu hai fatto ripiegare il taglio della sua spada, e non l''hai sostenuto nella battaglia.' WHERE "verseID" = 101967 AND (text = 'Tu hai fatto ripiegare il taglio della sua spada,'); -- 23 89:43
UPDATE "LUZZI" SET text = 'Tu hai fatto cessare il suo splendore, e hai gettato a terra il suo trono.' WHERE "verseID" = 101968 AND (text = 'Tu hai fatto cessare il suo splendore,'); -- 23 89:44
UPDATE "LUZZI" SET text = 'Tu hai scorciato i giorni della sua giovinezza, l''hai coperto di vergogna. Sela.' WHERE "verseID" = 101969 AND (text = 'Tu hai scorciato i giorni della sua giovinezza,'); -- 23 89:45
UPDATE "LUZZI" SET text = 'Fino a quando, o Eterno, ti nasconderai tu del continuo, e l''ira tua arderà come un fuoco?' WHERE "verseID" = 101970 AND (text = 'Fino a quando, o Eterno, ti nasconderai tu del continuo,'); -- 23 89:46
UPDATE "LUZZI" SET text = 'Ricordati quant''è fugace la mia vita, per qual nulla tu hai creato tutti i figliuoli degli uomini!' WHERE "verseID" = 101971 AND (text = 'Ricordati quant''è fugace la mia vita,'); -- 23 89:47
UPDATE "LUZZI" SET text = 'Qual è l''uomo che viva senza veder la morte? che scampi l''anima sua dal potere del soggiorno de'' morti? Sela.' WHERE "verseID" = 101972 AND (text = 'Qual è l''uomo che viva senza veder la morte?'); -- 23 89:48
UPDATE "LUZZI" SET text = 'Signore, dove sono le tue benignità antiche, le quali giurasti a Davide nella tua fedeltà?' WHERE "verseID" = 101973 AND (text = 'Signore, dove sono le tue benignità antiche,'); -- 23 89:49
UPDATE "LUZZI" SET text = 'Ricorda, o Signore, il vituperio fatto ai tuoi servitori: ricordati ch''io porto in seno quello di tutti i grandi popoli,' WHERE "verseID" = 101974 AND (text = 'Ricorda, o Signore, il vituperio fatto ai tuoi servitori:'); -- 23 89:50
UPDATE "LUZZI" SET text = 'il vituperio di cui t''hanno coperto i tuoi nemici, o Eterno, il vituperio che han gettato sui passi del tuo unto.' WHERE "verseID" = 101975 AND (text = 'il vituperio di cui t''hanno coperto i tuoi nemici, o Eterno,'); -- 23 89:51
UPDATE "LUZZI" SET text = 'BENEDETTO SIA L''ETERNO IN PERPETUO. AMEN, AMEN!' WHERE "verseID" = 101976 AND (text = 'BENEDETTO SIA L''ETERNO IN PERPETUO.AMEN, AMEN!'); -- 23 89:52
UPDATE "LUZZI" SET text = 'Preghiera di Mosè, uomo di Dio. O Signore, tu sei stato per noi un rifugio d''età in età.' WHERE "verseID" = 101977 AND (text = 'Preghiera di Mosè, uomo di Dio.'); -- 23 90:1
UPDATE "LUZZI" SET text = 'Avanti che i monti fossero nati e che tu avessi formato la terra e il mondo, anzi, ab eterno in eterno, tu sei Dio.' WHERE "verseID" = 101978 AND (text = 'Avanti che i monti fossero nati'); -- 23 90:2
UPDATE "LUZZI" SET text = 'Tu fai tornare i mortali in polvere e dici: Ritornate, o figliuoli degli uomini.' WHERE "verseID" = 101979 AND (text = 'Tu fai tornare i mortali in polvere'); -- 23 90:3
UPDATE "LUZZI" SET text = 'Perché mille anni, agli occhi tuoi, sono come il giorno d''ieri quand''è passato, e come una veglia nella notte.' WHERE "verseID" = 101980 AND (text = 'Perché mille anni, agli occhi tuoi,'); -- 23 90:4
UPDATE "LUZZI" SET text = 'Tu li porti via come in una piena; son come un sogno. Son come l''erba che verdeggia la mattina;' WHERE "verseID" = 101981 AND (text = 'Tu li porti via come in una piena; son come un sogno.'); -- 23 90:5
UPDATE "LUZZI" SET text = 'la mattina essa fiorisce e verdeggia, la sera è segata e si secca.' WHERE "verseID" = 101982 AND (text = 'la mattina essa fiorisce e verdeggia,'); -- 23 90:6
UPDATE "LUZZI" SET text = 'Poiché noi siam consumati per la tua ira, e siamo atterriti per il tuo cruccio.' WHERE "verseID" = 101983 AND (text = 'Poiché noi siam consumati per la tua ira,'); -- 23 90:7
UPDATE "LUZZI" SET text = 'Tu metti le nostre iniquità davanti a te, e i nostri peccati occulti, alla luce della tua faccia.' WHERE "verseID" = 101984 AND (text = 'Tu metti le nostre iniquità davanti a te,'); -- 23 90:8
UPDATE "LUZZI" SET text = 'Tutti i nostri giorni spariscono per il tuo cruccio; noi finiamo gli anni nostri come un soffio.' WHERE "verseID" = 101985 AND (text = 'Tutti i nostri giorni spariscono per il tuo cruccio;'); -- 23 90:9
UPDATE "LUZZI" SET text = 'I giorni de'' nostri anni arrivano a settant''anni; o, per i più forti, a ottant''anni; e quel che ne fa l''orgoglio, non è che travaglio e vanità; perché passa presto, e noi ce ne voliam via.' WHERE "verseID" = 101986 AND (text = 'I giorni de'' nostri anni arrivano a settant''anni;'); -- 23 90:10
UPDATE "LUZZI" SET text = 'Chi conosce la forza della tua ira e il tuo cruccio secondo il timore che t''è dovuto?' WHERE "verseID" = 101987 AND (text = 'Chi conosce la forza della tua ira'); -- 23 90:11
UPDATE "LUZZI" SET text = 'Insegnaci dunque a così contare i nostri giorni, che acquistiamo un cuor savio.' WHERE "verseID" = 101988 AND (text = 'Insegnaci dunque a così contare i nostri giorni,'); -- 23 90:12
UPDATE "LUZZI" SET text = 'Ritorna, o Eterno; fino a quando? e muoviti a pietà dei tuoi servitori.' WHERE "verseID" = 101989 AND (text = 'Ritorna, o Eterno; fino a quando?'); -- 23 90:13
UPDATE "LUZZI" SET text = 'Saziaci al mattino della tua benignità, e noi giubileremo, ci rallegreremo tutti i dì nostri.' WHERE "verseID" = 101990 AND (text = 'Saziaci al mattino della tua benignità,'); -- 23 90:14
UPDATE "LUZZI" SET text = 'Rallegraci in proporzione de'' giorni che ci hai afflitti, e degli anni che abbiam sentito il male.' WHERE "verseID" = 101991 AND (text = 'Rallegraci in proporzione de'' giorni che ci hai afflitti,'); -- 23 90:15
UPDATE "LUZZI" SET text = 'Apparisca l''opera tua a pro de'' tuoi servitori, e la tua gloria sui loro figliuoli.' WHERE "verseID" = 101992 AND (text = 'Apparisca l''opera tua a pro de'' tuoi servitori,'); -- 23 90:16
UPDATE "LUZZI" SET text = 'La grazia del Signore Iddio nostro sia sopra noi, e rendi stabile l''opera delle nostre mani; sì, l''opera delle nostre mani rendila stabile.' WHERE "verseID" = 101993 AND (text = 'La grazia del Signore Iddio nostro sia sopra noi,e rendi stabile l''opera delle nostre mani;sì, l''opera delle nostre mani rendila stabile.'); -- 23 90:17
UPDATE "LUZZI" SET text = 'Chi dimora nel ritiro dell''Altissimo alberga all''ombra dell''Onnipotente.' WHERE "verseID" = 101994 AND (text = 'Chi dimora nel ritiro dell''Altissimo'); -- 23 91:1
UPDATE "LUZZI" SET text = 'Io dico all''Eterno: Tu sei il mio rifugio e la mia fortezza, il mio Dio, in cui confido!' WHERE "verseID" = 101995 AND (text = 'Io dico all''Eterno: Tu sei il mio rifugio e la mia fortezza,'); -- 23 91:2
UPDATE "LUZZI" SET text = 'Certo egli ti libererà dal laccio dell''uccellatore e dalla peste mortifera.' WHERE "verseID" = 101996 AND (text = 'Certo egli ti libererà dal laccio dell''uccellatore'); -- 23 91:3
UPDATE "LUZZI" SET text = 'Egli ti coprirà con le sue penne, e sotto le sue ali troverai rifugio. La sua fedeltà ti è scudo e targa.' WHERE "verseID" = 101997 AND (text = 'Egli ti coprirà con le sue penne,'); -- 23 91:4
UPDATE "LUZZI" SET text = 'Tu non temerai lo spavento notturno, né la saetta che vola di giorno,' WHERE "verseID" = 101998 AND (text = 'Tu non temerai lo spavento notturno,'); -- 23 91:5
UPDATE "LUZZI" SET text = 'né la peste che va attorno nelle tenebre, né lo sterminio che infierisce in pien mezzodì.' WHERE "verseID" = 101999 AND (text = 'né la peste che va attorno nelle tenebre,'); -- 23 91:6
UPDATE "LUZZI" SET text = 'Mille te ne cadranno al fianco, e diecimila alla destra; ma tu non ne sarai colpito.' WHERE "verseID" = 102000 AND (text = 'Mille te ne cadranno al fianco,'); -- 23 91:7
UPDATE "LUZZI" SET text = 'Solo contemplerai coi tuoi occhi e vedrai la retribuzione degli empi.' WHERE "verseID" = 102001 AND (text = 'Solo contemplerai coi tuoi occhi'); -- 23 91:8
UPDATE "LUZZI" SET text = 'Poiché tu hai detto: O Eterno, tu sei il mio rifugio; tu hai preso l''Altissimo per il tuo asilo,' WHERE "verseID" = 102002 AND (text = 'Poiché tu hai detto: O Eterno, tu sei il mio rifugio;'); -- 23 91:9
UPDATE "LUZZI" SET text = 'male alcuno non ti coglierà, né piaga alcuna s''accosterà alla tua tenda.' WHERE "verseID" = 102003 AND (text = 'male alcuno non ti coglierà,'); -- 23 91:10
UPDATE "LUZZI" SET text = 'Poiché egli comanderà ai suoi angeli di guardarti in tutte le tue vie.' WHERE "verseID" = 102004 AND (text = 'Poiché egli comanderà ai suoi angeli'); -- 23 91:11
