UPDATE "LUZZI" SET text = 'Tu camminerai sul leone e sull''aspide, calpesterai il leoncello e il serpente.' WHERE "verseID" = 102006 AND (text = 'Tu camminerai sul leone e sull''aspide,'); -- 23 91:13
UPDATE "LUZZI" SET text = 'Poich''egli ha posta in me la sua affezione io lo libererò; lo leverò in alto, perché conosce il mio nome.' WHERE "verseID" = 102007 AND (text = 'Poich''egli ha posta in me la sua affezione io lo libererò;'); -- 23 91:14
UPDATE "LUZZI" SET text = 'Egli m''invocherà, ed io gli risponderò; sarò con lui nella distretta; lo libererò, e lo glorificherò.' WHERE "verseID" = 102008 AND (text = 'Egli m''invocherà, ed io gli risponderò;'); -- 23 91:15
UPDATE "LUZZI" SET text = 'Lo sazierò di lunga vita, e gli farò vedere la mia salvezza.' WHERE "verseID" = 102009 AND (text = 'Lo sazierò di lunga vita,e gli farò vedere la mia salvezza.'); -- 23 91:16
UPDATE "LUZZI" SET text = 'Salmo. Canto per il giorno del sabato. Buona cosa è celebrare l''Eterno, e salmeggiare al tuo nome, o Altissimo;' WHERE "verseID" = 102010 AND (text = 'Salmo. Canto per il giorno del sabato.'); -- 23 92:1
UPDATE "LUZZI" SET text = 'proclamare la mattina la tua benignità, e la tua fedeltà ogni notte,' WHERE "verseID" = 102011 AND (text = 'proclamare la mattina la tua benignità,'); -- 23 92:2
UPDATE "LUZZI" SET text = 'sul decacordo e sul saltèro, con l''accordo solenne dell''arpa!' WHERE "verseID" = 102012 AND (text = 'sul decacordo e sul saltèro,'); -- 23 92:3
UPDATE "LUZZI" SET text = 'Poiché, o Eterno, tu m''hai rallegrato col tuo operare; io celebro con giubilo le opere delle tue mani.' WHERE "verseID" = 102013 AND (text = 'Poiché, o Eterno, tu m''hai rallegrato col tuo operare;'); -- 23 92:4
UPDATE "LUZZI" SET text = 'Come son grandi le tue opere, o Eterno! I tuoi pensieri sono immensamente profondi.' WHERE "verseID" = 102014 AND (text = 'Come son grandi le tue opere, o Eterno!'); -- 23 92:5
UPDATE "LUZZI" SET text = 'L''uomo insensato non conosce e il pazzo non intende questo:' WHERE "verseID" = 102015 AND (text = 'L''uomo insensato non conosce'); -- 23 92:6
