UPDATE "LUZZI" SET text = 'Poiché, ecco, i tuoi nemici, o Eterno, ecco, i tuoi nemici periranno, tutti gli operatori d''iniquità saranno dispersi.' WHERE "verseID" = 102018 AND (text = 'Poiché, ecco, i tuoi nemici, o Eterno,'); -- 23 92:9
