UPDATE "LUZZI" SET text = 'Porteranno ancora del frutto nella vecchiaia; saranno pieni di vigore e verdeggianti,' WHERE "verseID" = 102023 AND (text = 'Porteranno ancora del frutto nella vecchiaia;'); -- 23 92:14
UPDATE "LUZZI" SET text = 'per annunziare che l''Eterno è giusto; egli è la mia ròcca, e non v''è ingiustizia in lui.' WHERE "verseID" = 102024 AND (text = 'per annunziare che l''Eterno è giusto;egli è la mia ròcca, e non v''è ingiustizia in lui.'); -- 23 92:15
