UPDATE "LUZZI" SET text = 'Più delle voci delle grandi, delle potenti acque, più dei flutti del mare, l''Eterno è potente ne'' luoghi alti.' WHERE "verseID" = 102028 AND (text = 'Più delle voci delle grandi, delle potenti acque,'); -- 23 93:4
UPDATE "LUZZI" SET text = 'Le tue testimonianze sono perfettamente veraci; la santità s''addice alla tua casa, o Eterno, in perpetuo.' WHERE "verseID" = 102029 AND (text = 'Le tue testimonianze sono perfettamente veraci;la santità s''addice alla tua casa,o Eterno, in perpetuo.'); -- 23 93:5
