UPDATE "LUZZI" SET text = 'Lèvati, o giudice della terra, rendi ai superbi la loro retribuzione!' WHERE "verseID" = 102031 AND (text = 'Lèvati, o giudice della terra,'); -- 23 94:2
UPDATE "LUZZI" SET text = 'Fino a quando gli empi, o Eterno, fino a quando gli empi trionferanno?' WHERE "verseID" = 102032 AND (text = 'Fino a quando gli empi, o Eterno,'); -- 23 94:3
