UPDATE "LUZZI" SET text = 'Uccidono la vedova e lo straniero, ammazzano gli orfani,' WHERE "verseID" = 102035 AND (text = 'Uccidono la vedova e lo straniero,'); -- 23 94:6
UPDATE "LUZZI" SET text = 'e dicono: L''Eterno non vede, l''Iddio di Giacobbe non ci fa attenzione.' WHERE "verseID" = 102036 AND (text = 'e dicono: L''Eterno non vede,'); -- 23 94:7
UPDATE "LUZZI" SET text = 'Abbiate intendimento, voi gli stolti fra il popolo! E voi, pazzi, quando sarete savi?' WHERE "verseID" = 102037 AND (text = 'Abbiate intendimento, voi gli stolti fra il popolo!'); -- 23 94:8
UPDATE "LUZZI" SET text = 'Colui che ha piantato l''orecchio non udirà egli? Colui che ha formato l''occhio non vedrà egli?' WHERE "verseID" = 102038 AND (text = 'Colui che ha piantato l''orecchio non udirà egli?'); -- 23 94:9
