UPDATE "LUZZI" SET text = 'Beato l''uomo che tu correggi, o Eterno, ed ammaestri con la tua legge' WHERE "verseID" = 102041 AND (text = 'Beato l''uomo che tu correggi, o Eterno,'); -- 23 94:12
UPDATE "LUZZI" SET text = 'per dargli requie dai giorni dell''avversità, finché la fossa sia scavata per l''empio.' WHERE "verseID" = 102042 AND (text = 'per dargli requie dai giorni dell''avversità,'); -- 23 94:13
UPDATE "LUZZI" SET text = 'Poiché l''Eterno non rigetterà il suo popolo, e non abbandonerà la sua eredità.' WHERE "verseID" = 102043 AND (text = 'Poiché l''Eterno non rigetterà il suo popolo,'); -- 23 94:14
