UPDATE "LUZZI" SET text = 'Se l''Eterno non fosse stato il mio aiuto, a quest''ora l''anima mia abiterebbe il luogo del silenzio.' WHERE "verseID" = 102046 AND (text = 'Se l''Eterno non fosse stato il mio aiuto,'); -- 23 94:17
UPDATE "LUZZI" SET text = 'Quand''ho detto: il mio piè vacilla, la tua benignità, o Eterno, m''ha sostenuto.' WHERE "verseID" = 102047 AND (text = 'Quand''ho detto: il mio piè vacilla,'); -- 23 94:18
UPDATE "LUZZI" SET text = 'Quando sono stato in grandi pensieri dentro di me, le tue consolazioni han rallegrato l''anima mia.' WHERE "verseID" = 102048 AND (text = 'Quando sono stato in grandi pensieri dentro di me,'); -- 23 94:19
UPDATE "LUZZI" SET text = 'Il trono della nequizia t''avrà egli per complice? esso, che ordisce oppressioni in nome della legge?' WHERE "verseID" = 102049 AND (text = 'Il trono della nequizia t''avrà egli per complice?'); -- 23 94:20
UPDATE "LUZZI" SET text = 'Essi si gettano assieme contro l''anima del giusto, e condannano il sangue innocente.' WHERE "verseID" = 102050 AND (text = 'Essi si gettano assieme contro l''anima del giusto,'); -- 23 94:21
UPDATE "LUZZI" SET text = 'Ma l''Eterno è il mio alto ricetto, e il mio Dio è la ròcca in cui mi rifugio.' WHERE "verseID" = 102051 AND (text = 'Ma l''Eterno è il mio alto ricetto,'); -- 23 94:22
UPDATE "LUZZI" SET text = 'Egli farà ricader sovr''essi la loro propria iniquità, e li distruggerà mediante la loro propria malizia; l''Eterno, il nostro Dio, li distruggerà.' WHERE "verseID" = 102052 AND (text = 'Egli farà ricader sovr''essi la loro propria iniquità,e li distruggerà mediante la loro propria malizia;l''Eterno, il nostro Dio, li distruggerà.'); -- 23 94:23
UPDATE "LUZZI" SET text = 'Venite, cantiamo con giubilo all''Eterno, mandiamo grida di gioia alla ròcca della nostra salvezza!' WHERE "verseID" = 102053 AND (text = 'Venite, cantiamo con giubilo all''Eterno,'); -- 23 95:1
UPDATE "LUZZI" SET text = 'Presentiamoci a lui con lodi, celebriamolo con salmi!' WHERE "verseID" = 102054 AND (text = 'Presentiamoci a lui con lodi,'); -- 23 95:2
UPDATE "LUZZI" SET text = 'Poiché l''Eterno è un Dio grande, e un gran Re sopra tutti gli dèi.' WHERE "verseID" = 102055 AND (text = 'Poiché l''Eterno è un Dio grande,'); -- 23 95:3
UPDATE "LUZZI" SET text = 'Nelle sue mani stanno le profondità della terra, e le altezze de'' monti son sue.' WHERE "verseID" = 102056 AND (text = 'Nelle sue mani stanno le profondità della terra,'); -- 23 95:4
UPDATE "LUZZI" SET text = 'Suo è il mare perch''egli l''ha fatto, e le sue mani han formato la terra asciutta.' WHERE "verseID" = 102057 AND (text = 'Suo è il mare perch''egli l''ha fatto,'); -- 23 95:5
UPDATE "LUZZI" SET text = 'Venite, adoriamo e inchiniamoci, inginocchiamoci davanti all''Eterno che ci ha fatti!' WHERE "verseID" = 102058 AND (text = 'Venite, adoriamo e inchiniamoci,'); -- 23 95:6
UPDATE "LUZZI" SET text = 'Poich''egli è il nostro Dio, e noi siamo il popolo ch''egli pasce, e il gregge che la sua mano conduce.' WHERE "verseID" = 102059 AND (text = 'Poich''egli è il nostro Dio,'); -- 23 95:7
UPDATE "LUZZI" SET text = 'Oggi, se udite la sua voce, non indurate il vostro cuore come a Meriba, come nel giorno di Massa nel deserto,' WHERE "verseID" = 102060 AND (text = 'Oggi, se udite la sua voce,'); -- 23 95:8
UPDATE "LUZZI" SET text = 'quando i vostri padri mi tentarono, mi provarono e videro l''opera mia.' WHERE "verseID" = 102061 AND (text = 'quando i vostri padri mi tentarono,'); -- 23 95:9
UPDATE "LUZZI" SET text = 'Quarant''anni ebbi in disgusto quella generazione, e dissi: È un popolo sviato di cuore, e non han conosciute le mie vie.' WHERE "verseID" = 102062 AND (text = 'Quarant''anni ebbi in disgusto quella generazione,' OR text = 'Quarant''anni ebbi in disgusto quella generazione, e dissi: È un popolo sviato di cuore, e non han conosciuto le mie vie.'); -- 23 95:10
UPDATE "LUZZI" SET text = 'Perciò giurai nell''ira mia: Non entreranno nel mio riposo!' WHERE "verseID" = 102063 AND (text = 'Perciò giurai nell''ira mia:Non entreranno nel mio riposo!'); -- 23 95:11
UPDATE "LUZZI" SET text = 'Cantate all''Eterno un cantico nuovo, cantate all''Eterno, abitanti di tutta la terra!' WHERE "verseID" = 102064 AND (text = 'Cantate all''Eterno un cantico nuovo,'); -- 23 96:1
