UPDATE "LUZZI" SET text = 'Poiché tutti gli dèi dei popoli son idoli vani, ma l''Eterno ha fatto i cieli.' WHERE "verseID" = 102068 AND (text = 'Poiché tutti gli dèi dei popoli son idoli vani,'); -- 23 96:5
UPDATE "LUZZI" SET text = 'Splendore e maestà stanno dinanzi a lui, forza e bellezza stanno nel suo santuario.' WHERE "verseID" = 102069 AND (text = 'Splendore e maestà stanno dinanzi a lui,'); -- 23 96:6
