UPDATE "LUZZI" SET text = 'Date all''Eterno la gloria dovuta al suo nome, portategli offerte e venite ne'' suoi cortili.' WHERE "verseID" = 102071 AND (text = 'Date all''Eterno la gloria dovuta al suo nome,'); -- 23 96:8
UPDATE "LUZZI" SET text = 'Prostratevi dinanzi all''Eterno vestiti di sacri ornamenti, tremate dinanzi a lui, o abitanti di tutta la terra!' WHERE "verseID" = 102072 AND (text = 'Prostratevi dinanzi all''Eterno vestiti di sacri ornamenti,'); -- 23 96:9
UPDATE "LUZZI" SET text = 'Dite fra le nazioni: l''Eterno regna; il mondo quindi è stabile e non sarà smosso; l''Eterno giudicherà i popoli con rettitudine.' WHERE "verseID" = 102073 AND (text = 'Dite fra le nazioni: l''Eterno regna;'); -- 23 96:10
UPDATE "LUZZI" SET text = 'Si rallegrino i cieli e gioisca la terra; risuoni il mare e quel ch''esso contiene;' WHERE "verseID" = 102074 AND (text = 'Si rallegrino i cieli e gioisca la terra;'); -- 23 96:11
UPDATE "LUZZI" SET text = 'festeggi la campagna e tutto quello ch''è in essa; tutti gli alberi delle foreste dian voci di gioia' WHERE "verseID" = 102075 AND (text = 'festeggi la campagna e tutto quello ch''è in essa;'); -- 23 96:12
UPDATE "LUZZI" SET text = 'nel cospetto dell''Eterno; poich''egli viene, viene a giudicare la terra. Egli giudicherà il mondo con giustizia, e i popoli secondo la sua fedeltà.' WHERE "verseID" = 102076 AND (text = 'nel cospetto dell''Eterno; poich''egli viene,viene a giudicare la terra.Egli giudicherà il mondo con giustizia,e i popoli secondo la sua fedeltà.'); -- 23 96:13
UPDATE "LUZZI" SET text = 'L''Eterno regna, gioisca la terra, la moltitudine delle isole si rallegri.' WHERE "verseID" = 102077 AND (text = 'L''Eterno regna, gioisca la terra,'); -- 23 97:1
