UPDATE "LUZZI" SET text = 'Un fuoco lo precede e consuma i suoi nemici d''ogn''intorno.' WHERE "verseID" = 102079 AND (text = 'Un fuoco lo precede'); -- 23 97:3
UPDATE "LUZZI" SET text = 'I suoi lampi illuminano il mondo; la terra lo vede e trema.' WHERE "verseID" = 102080 AND (text = 'I suoi lampi illuminano il mondo;'); -- 23 97:4
UPDATE "LUZZI" SET text = 'I monti si struggono come cera alla presenza dell''Eterno, alla presenza del Signore di tutta la terra.' WHERE "verseID" = 102081 AND (text = 'I monti si struggono come cera alla presenza dell''Eterno,'); -- 23 97:5
UPDATE "LUZZI" SET text = 'I cieli annunziano la sua giustizia, e tutti i popoli vedono la sua gloria.' WHERE "verseID" = 102082 AND (text = 'I cieli annunziano la sua giustizia,'); -- 23 97:6
UPDATE "LUZZI" SET text = 'Son confusi tutti quelli che adoran le immagini, che si glorian degl''idoli; si prostrano dinanzi a lui tutti gli dèi.' WHERE "verseID" = 102083 AND (text = 'Son confusi tutti quelli che adoran le immagini,'); -- 23 97:7
UPDATE "LUZZI" SET text = 'Sion l''ha udito e si è rallegrata, e le figliuole di Giuda hanno esultato per i tuoi giudizi, o Eterno!' WHERE "verseID" = 102084 AND (text = 'Sion l''ha udito e si è rallegrata,'); -- 23 97:8
UPDATE "LUZZI" SET text = 'Poiché tu, o Eterno, sei l''Altissimo su tutta la terra; tu sei sommamente elevato sopra tutti gli dèi.' WHERE "verseID" = 102085 AND (text = 'Poiché tu, o Eterno, sei l''Altissimo su tutta la terra;'); -- 23 97:9
UPDATE "LUZZI" SET text = 'O voi che amate l''Eterno, odiate il male! Egli custodisce le anime dei suoi fedeli, li libera dalla mano degli empi.' WHERE "verseID" = 102086 AND (text = 'O voi che amate l''Eterno, odiate il male!' OR text = 'O voi che amate l''Eterno, odiate il male! Egli custodisce le anime de'' suoi fedeli, li libera dalla mano degli empi.'); -- 23 97:10
UPDATE "LUZZI" SET text = 'La luce è seminata per il giusto, e la gioia per i diritti di cuore.' WHERE "verseID" = 102087 AND (text = 'La luce è seminata per il giusto,'); -- 23 97:11
UPDATE "LUZZI" SET text = 'Rallegratevi nell''Eterno, o giusti, e lodate il santo suo nome!' WHERE "verseID" = 102088 AND (text = 'Rallegratevi nell''Eterno, o giusti,e lodate il santo suo nome!'); -- 23 97:12
UPDATE "LUZZI" SET text = 'Salmo. Cantate all''Eterno un cantico nuovo, perch''egli ha compiuto maraviglie; la sua destra e il braccio suo santo l''hanno reso vittorioso.' WHERE "verseID" = 102089 AND (text = 'Salmo.'); -- 23 98:1
UPDATE "LUZZI" SET text = 'L''Eterno ha fatto conoscere la sua salvezza, ha manifestato la sua giustizia nel cospetto delle nazioni.' WHERE "verseID" = 102090 AND (text = 'L''Eterno ha fatto conoscere la sua salvezza,'); -- 23 98:2
UPDATE "LUZZI" SET text = 'Si è ricordato della sua bontà e della sua fedeltà verso la casa d''Israele; tutte le estremità della terra han veduto la salvezza del nostro Dio.' WHERE "verseID" = 102091 AND (text = 'Si è ricordato della sua bontà'); -- 23 98:3
UPDATE "LUZZI" SET text = 'Acclamate l''Eterno, abitanti di tutta la terra, date in canti di giubilo e salmeggiate,' WHERE "verseID" = 102092 AND (text = 'Acclamate l''Eterno, abitanti di tutta la terra,'); -- 23 98:4
UPDATE "LUZZI" SET text = 'salmeggiate all''Eterno con la cetra, con la cetra e la voce del canto.' WHERE "verseID" = 102093 AND (text = 'salmeggiate all''Eterno con la cetra,'); -- 23 98:5
UPDATE "LUZZI" SET text = 'Con trombe e col suono del corno, fate acclamazioni al Re, all''Eterno.' WHERE "verseID" = 102094 AND (text = 'Con trombe e col suono del corno,'); -- 23 98:6
UPDATE "LUZZI" SET text = 'Risuoni il mare e tutto ciò ch''è in esso; il mondo ed i suoi abitanti.' WHERE "verseID" = 102095 AND (text = 'Risuoni il mare e tutto ciò ch''è in esso;'); -- 23 98:7
UPDATE "LUZZI" SET text = 'I fiumi battan le mani, i monti cantino assieme per gioia, dinanzi all''Eterno. Poich''egli viene a giudicare la terra; egli giudicherà il mondo con giustizia, e i popoli con rettitudine.' WHERE "verseID" = 102096 AND (text = 'I fiumi battan le mani,i monti cantino assieme per gioia,dinanzi all''Eterno. Poich''egli viene a giudicare la terra;egli giudicherà il mondo con giustizia,e i popoli con rettitudine.'); -- 23 98:8
UPDATE "LUZZI" SET text = 'L''Eterno regna; tremino i popoli; egli siede sui cherubini, la terra sia scossa.' WHERE "verseID" = 102097 AND (text = 'L''Eterno regna; tremino i popoli;'); -- 23 99:1
UPDATE "LUZZI" SET text = 'L''Eterno è grande in Sion, ed eccelso sopra tutti i popoli.' WHERE "verseID" = 102098 AND (text = 'L''Eterno è grande in Sion,'); -- 23 99:2
UPDATE "LUZZI" SET text = 'Lodino essi il tuo nome grande e tremendo. Egli è santo.' WHERE "verseID" = 102099 AND (text = 'Lodino essi il tuo nome grande e tremendo.'); -- 23 99:3
UPDATE "LUZZI" SET text = 'Lodino la forza del Re che ama la giustizia; sei tu che hai fondato il diritto, che hai esercitato in Giacobbe il giudicio e la giustizia.' WHERE "verseID" = 102100 AND (text = 'Lodino la forza del Re che ama la giustizia;'); -- 23 99:4
UPDATE "LUZZI" SET text = 'Esaltate l''Eterno, l''Iddio nostro, e prostratevi dinanzi allo sgabello de'' suoi piedi. Egli è santo.' WHERE "verseID" = 102101 AND (text = 'Esaltate l''Eterno, l''Iddio nostro,'); -- 23 99:5
UPDATE "LUZZI" SET text = 'Mosè ed Aaronne fra i suoi sacerdoti, e Samuele fra quelli che invocavano il suo nome, invocaron l''Eterno, ed egli rispose loro.' WHERE "verseID" = 102102 AND (text = 'Mosè ed Aaronne fra i suoi sacerdoti,'); -- 23 99:6
UPDATE "LUZZI" SET text = 'Parlò loro dalla colonna della nuvola; essi osservarono le sue testimonianze e gli statuti che diede loro.' WHERE "verseID" = 102103 AND (text = 'Parlò loro dalla colonna della nuvola;'); -- 23 99:7
UPDATE "LUZZI" SET text = 'Tu li esaudisti, o Eterno, Iddio nostro! Fosti per loro un Dio perdonatore, benché tu punissi le loro male azioni.' WHERE "verseID" = 102104 AND (text = 'Tu li esaudisti, o Eterno, Iddio nostro!'); -- 23 99:8
UPDATE "LUZZI" SET text = 'Esaltate l''Eterno, l''Iddio nostro, e adorate sul monte della sua santità; perché l''Eterno, l''Iddio nostro, è santo.' WHERE "verseID" = 102105 AND (text = 'Esaltate l''Eterno, l''Iddio nostro,e adorate sul monte della sua santità;perché l''Eterno, l''Iddio nostro, è santo.'); -- 23 99:9
UPDATE "LUZZI" SET text = 'Salmo di lode. Mandate gridi di gioia all''Eterno, o abitanti di tutta la terra!' WHERE "verseID" = 102106 AND (text = 'Salmo di lode.'); -- 23 100:1
UPDATE "LUZZI" SET text = 'Servite l''Eterno con gioia, venite al suo cospetto con canti!' WHERE "verseID" = 102107 AND (text = 'Servite l''Eterno con gioia,'); -- 23 100:2
UPDATE "LUZZI" SET text = 'Riconoscete che l''Eterno è Dio; è lui che ci ha fatti, e noi siam suoi; siamo il suo popolo e il gregge ch''egli pasce.' WHERE "verseID" = 102108 AND (text = 'Riconoscete che l''Eterno è Dio;'); -- 23 100:3
UPDATE "LUZZI" SET text = 'Entrate nelle sue porte con ringraziamento, e nei suoi cortili con lode; celebratelo, benedite il suo nome.' WHERE "verseID" = 102109 AND (text = 'Entrate nelle sue porte con ringraziamento,'); -- 23 100:4
UPDATE "LUZZI" SET text = 'Poiché l''Eterno è buono; la sua benignità dura in perpetuo, e la sua fedeltà per ogni età.' WHERE "verseID" = 102110 AND (text = 'Poiché l''Eterno è buono; la sua benignità dura in perpetuo,e la sua fedeltà per ogni età.'); -- 23 100:5
UPDATE "LUZZI" SET text = 'Salmo di Davide. Io canterò la benignità e la giustizia; a te, o Eterno, salmeggerò.' WHERE "verseID" = 102111 AND (text = 'Salmo di Davide.'); -- 23 101:1
UPDATE "LUZZI" SET text = 'Io m''applicherò a seguire la via perfetta; quando verrai a me?... Io camminerò con integrità di cuore, in seno alla mia casa.' WHERE "verseID" = 102112 AND (text = 'Io m''applicherò a seguire la via perfetta;' OR text = 'Io m''applicherò a seguire la via perfetta; quando verrai a me?… Io camminerò con integrità di cuore, in seno alla mia casa.'); -- 23 101:2
UPDATE "LUZZI" SET text = 'Non mi proporrò cosa alcuna scellerata; io odio il fare degli sviati; esso non mi s''attaccherà.' WHERE "verseID" = 102113 AND (text = 'Non mi proporrò cosa alcuna scellerata;'); -- 23 101:3
UPDATE "LUZZI" SET text = 'Il cuor perverso s''allontanerà da me; il malvagio non lo conoscerò.' WHERE "verseID" = 102114 AND (text = 'Il cuor perverso s''allontanerà da me;'); -- 23 101:4
UPDATE "LUZZI" SET text = 'Io sterminerò chi sparla in segreto del suo prossimo; e chi ha l''occhio altero ed il cuor gonfio non lo sopporterò.' WHERE "verseID" = 102115 AND (text = 'Io sterminerò chi sparla in segreto del suo prossimo;'); -- 23 101:5
UPDATE "LUZZI" SET text = 'Avrò gli occhi sui fedeli del paese perché dimorino meco; chi cammina per la via dell''integrità, quello sarà mio servitore.' WHERE "verseID" = 102116 AND (text = 'Avrò gli occhi sui fedeli del paese perché dimorino meco;'); -- 23 101:6
UPDATE "LUZZI" SET text = 'Chi pratica la frode non abiterà nella mia casa; chi proferisce menzogna non sussisterà davanti agli occhi miei.' WHERE "verseID" = 102117 AND (text = 'Chi pratica la frode non abiterà nella mia casa;'); -- 23 101:7
UPDATE "LUZZI" SET text = 'Ogni mattina distruggerò tutti gli empi del paese per estirpare dalla città dell''Eterno tutti gli operatori d''iniquità.' WHERE "verseID" = 102118 AND (text = 'Ogni mattina distruggerò tutti gli empi del paeseper estirpare dalla città dell''Eterno tutti gli operatori d''iniquità.'); -- 23 101:8
UPDATE "LUZZI" SET text = 'Preghiera dell''afflitto quand''è abbattuto e spande il suo lamento dinanzi all''Eterno. Deh ascolta la mia preghiera, o Eterno, e venga fino a te il mio grido!' WHERE "verseID" = 102119 AND (text = 'Preghiera dell''afflitto quand''è abbattuto e spande il suo lamento dinanzi all''Eterno.'); -- 23 102:1
UPDATE "LUZZI" SET text = 'Non mi nasconder la tua faccia nel dì della mia distretta; inclina a me il tuo orecchio; nel giorno che io grido, affrettati a rispondermi.' WHERE "verseID" = 102120 AND (text = 'Non mi nasconder la tua faccia nel dì della mia distretta;'); -- 23 102:2
UPDATE "LUZZI" SET text = 'Poiché i miei giorni svaniscono come fumo, e le mie ossa si consumano come un tizzone.' WHERE "verseID" = 102121 AND (text = 'Poiché i miei giorni svaniscono come fumo,'); -- 23 102:3
UPDATE "LUZZI" SET text = 'Colpito è il mio cuore come l''erba, si è seccato; perché ho dimenticato perfino di mangiare il mio pane.' WHERE "verseID" = 102122 AND (text = 'Colpito è il mio cuore come l''erba, si è seccato;'); -- 23 102:4
UPDATE "LUZZI" SET text = 'A cagion della voce dei miei gemiti, le mie ossa s''attaccano alla mia carne.' WHERE "verseID" = 102123 AND (text = 'A cagion della voce dei miei gemiti,'); -- 23 102:5
UPDATE "LUZZI" SET text = 'Son simile al pellicano del deserto, son come il gufo de'' luoghi desolati.' WHERE "verseID" = 102124 AND (text = 'Son simile al pellicano del deserto,'); -- 23 102:6
UPDATE "LUZZI" SET text = 'I miei nemici m''oltraggiano ogni giorno; quelli che son furibondi contro di me si servon del mio nome per imprecare.' WHERE "verseID" = 102126 AND (text = 'I miei nemici m''oltraggiano ogni giorno;'); -- 23 102:8
UPDATE "LUZZI" SET text = 'Poiché io mangio cenere come fosse pane, e mescolo con lagrime la mia bevanda,' WHERE "verseID" = 102127 AND (text = 'Poiché io mangio cenere come fosse pane,'); -- 23 102:9
UPDATE "LUZZI" SET text = 'a cagione della tua indignazione e del tuo cruccio; poiché m''hai levato in alto e gettato via.' WHERE "verseID" = 102128 AND (text = 'a cagione della tua indignazione e del tuo cruccio;'); -- 23 102:10
UPDATE "LUZZI" SET text = 'I miei giorni son come l''ombra che s''allunga, e io son disseccato come l''erba.' WHERE "verseID" = 102129 AND (text = 'I miei giorni son come l''ombra che s''allunga,'); -- 23 102:11
UPDATE "LUZZI" SET text = 'Ma tu, o Eterno, dimori in perpetuo, e la tua memoria dura per ogni età.' WHERE "verseID" = 102130 AND (text = 'Ma tu, o Eterno, dimori in perpetuo,'); -- 23 102:12
UPDATE "LUZZI" SET text = 'Tu ti leverai ed avrai compassione di Sion, poiché è tempo d''averne pietà; il tempo fissato è giunto.' WHERE "verseID" = 102131 AND (text = 'Tu ti leverai ed avrai compassione di Sion,'); -- 23 102:13
UPDATE "LUZZI" SET text = 'Perché i tuoi servitori hanno affezione alle sue pietre, ed hanno pietà della sua polvere.' WHERE "verseID" = 102132 AND (text = 'Perché i tuoi servitori hanno affezione alle sue pietre,'); -- 23 102:14
UPDATE "LUZZI" SET text = 'Allora le nazioni temeranno il nome dell''Eterno, e tutti i re della terra la tua gloria,' WHERE "verseID" = 102133 AND (text = 'Allora le nazioni temeranno il nome dell''Eterno,'); -- 23 102:15
UPDATE "LUZZI" SET text = 'quando l''Eterno avrà riedificata Sion, sarà apparso nella sua gloria,' WHERE "verseID" = 102134 AND (text = 'quando l''Eterno avrà riedificata Sion,'); -- 23 102:16
UPDATE "LUZZI" SET text = 'avrà avuto riguardo alla preghiera dei desolati, e non avrà sprezzato la loro supplicazione.' WHERE "verseID" = 102135 AND (text = 'avrà avuto riguardo alla preghiera dei desolati,'); -- 23 102:17
UPDATE "LUZZI" SET text = 'Questo sarà scritto per l''età a venire, e il popolo che sarà creato loderà l''Eterno,' WHERE "verseID" = 102136 AND (text = 'Questo sarà scritto per l''età a venire,'); -- 23 102:18
UPDATE "LUZZI" SET text = 'perch''egli avrà guardato dall''alto del suo santuario; dal cielo l''Eterno avrà mirato la terra' WHERE "verseID" = 102137 AND (text = 'perch''egli avrà guardato dall''alto del suo santuario;'); -- 23 102:19
UPDATE "LUZZI" SET text = 'per udire i gemiti de'' prigionieri, per liberare i condannati a morte,' WHERE "verseID" = 102138 AND (text = 'per udire i gemiti de'' prigionieri,'); -- 23 102:20
UPDATE "LUZZI" SET text = 'affinché pubblichino il nome dell''Eterno in Sion e la sua lode in Gerusalemme,' WHERE "verseID" = 102139 AND (text = 'affinché pubblichino il nome dell''Eterno in Sion'); -- 23 102:21
UPDATE "LUZZI" SET text = 'quando i popoli e i regni si raduneranno insieme per servire l''Eterno.' WHERE "verseID" = 102140 AND (text = 'quando i popoli e i regni si raduneranno'); -- 23 102:22
UPDATE "LUZZI" SET text = 'Egli ha abbattuto le mie forze durante il mio cammino; ha accorciato i miei giorni.' WHERE "verseID" = 102141 AND (text = 'Egli ha abbattuto le mie forze durante il mio cammino;'); -- 23 102:23
UPDATE "LUZZI" SET text = 'Io ho detto: Dio mio, non mi portar via nel mezzo dei miei giorni; i tuoi anni durano per ogni età.' WHERE "verseID" = 102142 AND (text = 'Io ho detto: Dio mio,'); -- 23 102:24
UPDATE "LUZZI" SET text = 'Tu fondasti ab antico la terra, e i cieli son l''opera delle tue mani.' WHERE "verseID" = 102143 AND (text = 'Tu fondasti ab antico la terra,'); -- 23 102:25
UPDATE "LUZZI" SET text = 'Essi periranno, ma tu rimani; tutti quanti si logoreranno come un vestito; tu li muterai come una veste e saranno mutati.' WHERE "verseID" = 102144 AND (text = 'Essi periranno, ma tu rimani;'); -- 23 102:26
UPDATE "LUZZI" SET text = 'Ma tu sei sempre lo stesso, e gli anni tuoi non avranno mai fine.' WHERE "verseID" = 102145 AND (text = 'Ma tu sei sempre lo stesso,'); -- 23 102:27
UPDATE "LUZZI" SET text = 'I figliuoli de'' tuoi servitori avranno una dimora, e la loro progenie sarà stabilita nel tuo cospetto.' WHERE "verseID" = 102146 AND (text = 'I figliuoli de'' tuoi servitori avranno una dimora,e la loro progenie sarà stabilita nel tuo cospetto.'); -- 23 102:28
UPDATE "LUZZI" SET text = 'Di Davide. Benedici, anima mia, l''Eterno; e tutto quello ch''è in me, benedica il nome suo santo.' WHERE "verseID" = 102147 AND (text = 'Di Davide.'); -- 23 103:1
UPDATE "LUZZI" SET text = 'Benedici, anima mia, l''Eterno, e non dimenticare alcuno de'' suoi benefici.' WHERE "verseID" = 102148 AND (text = 'Benedici, anima mia, l''Eterno,'); -- 23 103:2
UPDATE "LUZZI" SET text = 'Egli è quel che ti perdona tutte le tue iniquità, che sana tutte le tue infermità,' WHERE "verseID" = 102149 AND (text = 'Egli è quel che ti perdona tutte le tue iniquità,'); -- 23 103:3
UPDATE "LUZZI" SET text = 'che redime la tua vita dalla fossa, che ti corona di benignità e di compassioni,' WHERE "verseID" = 102150 AND (text = 'che redime la tua vita dalla fossa,'); -- 23 103:4
UPDATE "LUZZI" SET text = 'che sazia di beni la tua bocca, che ti fa ringiovanire come l''aquila.' WHERE "verseID" = 102151 AND (text = 'che sazia di beni la tua bocca,'); -- 23 103:5
UPDATE "LUZZI" SET text = 'L''Eterno fa giustizia e ragione a tutti quelli che sono oppressi.' WHERE "verseID" = 102152 AND (text = 'L''Eterno fa giustizia'); -- 23 103:6
UPDATE "LUZZI" SET text = 'Egli fece conoscere a Mosè le sue vie e ai figliuoli d''Israele le sue opere.' WHERE "verseID" = 102153 AND (text = 'Egli fece conoscere a Mosè le sue vie'); -- 23 103:7
UPDATE "LUZZI" SET text = 'L''Eterno è pietoso e clemente, lento all''ira e di gran benignità.' WHERE "verseID" = 102154 AND (text = 'L''Eterno è pietoso e clemente,'); -- 23 103:8
UPDATE "LUZZI" SET text = 'Egli non contende in eterno, né serba l''ira sua in perpetuo.' WHERE "verseID" = 102155 AND (text = 'Egli non contende in eterno,'); -- 23 103:9
UPDATE "LUZZI" SET text = 'Egli non ci ha trattato secondo i nostri peccati, né ci ha retribuiti secondo le nostre iniquità.' WHERE "verseID" = 102156 AND (text = 'Egli non ci ha trattato secondo i nostri peccati,'); -- 23 103:10
UPDATE "LUZZI" SET text = 'Poiché quanto i cieli sono alti al disopra della terra, tanto è grande la sua benignità verso quelli che lo temono.' WHERE "verseID" = 102157 AND (text = 'Poiché quanto i cieli sono alti al disopra della terra,'); -- 23 103:11
UPDATE "LUZZI" SET text = 'Quanto è lontano il levante dal ponente, tanto ha egli allontanato da noi le nostre trasgressioni.' WHERE "verseID" = 102158 AND (text = 'Quanto è lontano il levante dal ponente,'); -- 23 103:12
UPDATE "LUZZI" SET text = 'Come un padre è pietoso verso i suoi figliuoli, così è pietoso l''Eterno verso quelli che lo temono.' WHERE "verseID" = 102159 AND (text = 'Come un padre è pietoso verso i suoi figliuoli,'); -- 23 103:13
UPDATE "LUZZI" SET text = 'Poiché egli conosce la nostra natura; egli si ricorda che siam polvere.' WHERE "verseID" = 102160 AND (text = 'Poiché egli conosce la nostra natura;'); -- 23 103:14
UPDATE "LUZZI" SET text = 'I giorni dell''uomo son come l''erba; egli fiorisce come il fiore del campo;' WHERE "verseID" = 102161 AND (text = 'I giorni dell''uomo son come l''erba;'); -- 23 103:15
UPDATE "LUZZI" SET text = 'se un vento gli passa sopra ei non è più, e il luogo dov''era non lo riconosce più.' WHERE "verseID" = 102162 AND (text = 'se un vento gli passa sopra ei non è più,'); -- 23 103:16
UPDATE "LUZZI" SET text = 'Ma la benignità dell''Eterno dura ab eterno e in eterno, sopra quelli che lo temono, e la sua giustizia sopra i figliuoli de'' figliuoli' WHERE "verseID" = 102163 AND (text = 'Ma la benignità dell''Eterno dura ab eterno e in eterno,'); -- 23 103:17
UPDATE "LUZZI" SET text = 'di quelli che osservano il suo patto, e si ricordano de'' suoi comandamenti per metterli in opra.' WHERE "verseID" = 102164 AND (text = 'di quelli che osservano il suo patto,'); -- 23 103:18
UPDATE "LUZZI" SET text = 'L''Eterno ha stabilito il suo trono ne'' cieli, e il suo regno signoreggia su tutto.' WHERE "verseID" = 102165 AND (text = 'L''Eterno ha stabilito il suo trono ne'' cieli,'); -- 23 103:19
UPDATE "LUZZI" SET text = 'Benedite l''Eterno, voi suoi angeli, potenti e forti, che fate ciò ch''egli dice, ubbidendo alla voce della sua parola!' WHERE "verseID" = 102166 AND (text = 'Benedite l''Eterno, voi suoi angeli,'); -- 23 103:20
UPDATE "LUZZI" SET text = 'Benedite l''Eterno, voi tutti gli eserciti suoi, che siete suoi ministri, e fate ciò che gli piace!' WHERE "verseID" = 102167 AND (text = 'Benedite l''Eterno, voi tutti gli eserciti suoi,'); -- 23 103:21
UPDATE "LUZZI" SET text = 'Benedite l''Eterno, voi tutte le opere sue, in tutti i luoghi della sua signoria! Anima mia, benedici l''Eterno!' WHERE "verseID" = 102168 AND (text = 'Benedite l''Eterno, voi tutte le opere sue,in tutti i luoghi della sua signoria!Anima mia, benedici l''Eterno!'); -- 23 103:22
UPDATE "LUZZI" SET text = 'Anima mia, benedici l''Eterno! o Eterno, mio Dio, tu sei sommamente grande; sei vestito di splendore e di maestà.' WHERE "verseID" = 102169 AND (text = 'Anima mia, benedici l''Eterno!' OR text = 'Anima mia, benedici l''Eterno! O Eterno, mio Dio, tu sei sommamente grande; sei vestito di splendore e di maestà.'); -- 23 104:1
UPDATE "LUZZI" SET text = 'Egli s''ammanta di luce come d''una veste; distende i cieli come un padiglione;' WHERE "verseID" = 102170 AND (text = 'Egli s''ammanta di luce come d''una veste;'); -- 23 104:2
UPDATE "LUZZI" SET text = 'egli costruisce le sue alte stanze nelle acque; fa delle nuvole il suo carro, s''avanza sulle ali del vento;' WHERE "verseID" = 102171 AND (text = 'egli costruisce le sue alte stanze nelle acque;'); -- 23 104:3
UPDATE "LUZZI" SET text = 'fa dei venti i suoi messaggeri, delle fiamme di fuoco i suoi ministri.' WHERE "verseID" = 102172 AND (text = 'fa dei venti i suoi messaggeri,'); -- 23 104:4
UPDATE "LUZZI" SET text = 'Egli ha fondato la terra sulle sue basi; non sarà smossa mai in perpetuo.' WHERE "verseID" = 102173 AND (text = 'Egli ha fondato la terra sulle sue basi;'); -- 23 104:5
UPDATE "LUZZI" SET text = 'Tu l''avevi coperta dell''abisso come d''una veste, le acque s''erano fermate sui monti.' WHERE "verseID" = 102174 AND (text = 'Tu l''avevi coperta dell''abisso come d''una veste,'); -- 23 104:6
UPDATE "LUZZI" SET text = 'Alla tua minaccia esse si ritirarono, alla voce del tuo tuono fuggirono spaventate.' WHERE "verseID" = 102175 AND (text = 'Alla tua minaccia esse si ritirarono,'); -- 23 104:7
UPDATE "LUZZI" SET text = 'Le montagne sorsero, le valli s''abbassarono nel luogo che tu avevi stabilito per loro.' WHERE "verseID" = 102176 AND (text = 'Le montagne sorsero, le valli s''abbassarono'); -- 23 104:8
UPDATE "LUZZI" SET text = 'Tu hai posto alle acque un limite che non trapasseranno; esse non torneranno a coprire la terra.' WHERE "verseID" = 102177 AND (text = 'Tu hai posto alle acque un limite che non trapasseranno;'); -- 23 104:9
UPDATE "LUZZI" SET text = 'Egli manda fonti nelle valli, ed esse scorrono fra le montagne;' WHERE "verseID" = 102178 AND (text = 'Egli manda fonti nelle valli,'); -- 23 104:10
UPDATE "LUZZI" SET text = 'abbeverano tutte le bestie della campagna, gli asini salvatici vi si dissetano.' WHERE "verseID" = 102179 AND (text = 'abbeverano tutte le bestie della campagna,' OR text = 'abbeverano tutte le bestie della campagna, gli asini selvatici vi si dissetano.'); -- 23 104:11
UPDATE "LUZZI" SET text = 'Presso a quelle si riparano gli uccelli del cielo; di mezzo alle fronde fanno udir la loro voce.' WHERE "verseID" = 102180 AND (text = 'Presso a quelle si riparano gli uccelli del cielo;'); -- 23 104:12
UPDATE "LUZZI" SET text = 'Egli adacqua i monti dall''alto delle sue stanze, la terra è saziata col frutto delle tue opere.' WHERE "verseID" = 102181 AND (text = 'Egli adacqua i monti dall''alto delle sue stanze,'); -- 23 104:13
UPDATE "LUZZI" SET text = 'Egli fa germogliar l''erba per il bestiame e le piante per il servizio dell''uomo, facendo uscir dalla terra il nutrimento,' WHERE "verseID" = 102182 AND (text = 'Egli fa germogliar l''erba per il bestiame'); -- 23 104:14
UPDATE "LUZZI" SET text = 'e il vino che rallegra il cuor dell''uomo, e l''olio che gli fa risplender la faccia, e il pane che sostenta il cuore dei mortali.' WHERE "verseID" = 102183 AND (text = 'e il vino che rallegra il cuor dell''uomo,'); -- 23 104:15
UPDATE "LUZZI" SET text = 'Gli alberi dell''Eterno sono saziati, i cedri del Libano, ch''egli ha piantati.' WHERE "verseID" = 102184 AND (text = 'Gli alberi dell''Eterno sono saziati,'); -- 23 104:16
UPDATE "LUZZI" SET text = 'Gli uccelli vi fanno i loro nidi; la cicogna fa dei cipressi la sua dimora;' WHERE "verseID" = 102185 AND (text = 'Gli uccelli vi fanno i loro nidi;'); -- 23 104:17
UPDATE "LUZZI" SET text = 'le alte montagne son per i camosci, le rocce sono il rifugio de'' conigli.' WHERE "verseID" = 102186 AND (text = 'le alte montagne son per i camosci,'); -- 23 104:18
UPDATE "LUZZI" SET text = 'Egli ha fatto la luna per le stagioni; il sole conosce il suo tramonto.' WHERE "verseID" = 102187 AND (text = 'Egli ha fatto la luna per le stagioni;'); -- 23 104:19
UPDATE "LUZZI" SET text = 'Tu mandi le tenebre e vien la notte, nella quale tutte le bestie delle foreste si mettono in moto.' WHERE "verseID" = 102188 AND (text = 'Tu mandi le tenebre e vien la notte,'); -- 23 104:20
UPDATE "LUZZI" SET text = 'I leoncelli ruggono dietro la preda e chiedono il loro pasto a Dio.' WHERE "verseID" = 102189 AND (text = 'I leoncelli ruggono dietro la preda'); -- 23 104:21
UPDATE "LUZZI" SET text = 'Si leva il sole, esse si ritirano e vanno a giacere nei loro covi.' WHERE "verseID" = 102190 AND (text = 'Si leva il sole, esse si ritirano'); -- 23 104:22
UPDATE "LUZZI" SET text = 'L''uomo esce all''opera sua e al suo lavoro fino alla sera.' WHERE "verseID" = 102191 AND (text = 'L''uomo esce all''opera sua'); -- 23 104:23
UPDATE "LUZZI" SET text = 'Quanto son numerose le tue opere, o Eterno! Tu le hai fatte tutte con sapienza; la terra è piena delle tue ricchezze.' WHERE "verseID" = 102192 AND (text = 'Quanto son numerose le tue opere, o Eterno!'); -- 23 104:24
UPDATE "LUZZI" SET text = 'Ecco il mare, grande ed ampio, dove si muovon creature senza numero, animali piccoli e grandi.' WHERE "verseID" = 102193 AND (text = 'Ecco il mare, grande ed ampio,'); -- 23 104:25
UPDATE "LUZZI" SET text = 'Là vogano le navi e quel leviatan che hai creato per scherzare in esso.' WHERE "verseID" = 102194 AND (text = 'Là vogano le navi'); -- 23 104:26
UPDATE "LUZZI" SET text = 'Tutti quanti sperano in te che tu dia loro il lor cibo a suo tempo.' WHERE "verseID" = 102195 AND (text = 'Tutti quanti sperano in te'); -- 23 104:27
UPDATE "LUZZI" SET text = 'Tu lo dai loro ed essi lo raccolgono; tu apri la mano ed essi son saziati di beni.' WHERE "verseID" = 102196 AND (text = 'Tu lo dai loro ed essi lo raccolgono;'); -- 23 104:28
UPDATE "LUZZI" SET text = 'Tu nascondi la tua faccia, essi sono smarriti; tu ritiri il loro fiato, ed essi muoiono e tornano nella loro polvere.' WHERE "verseID" = 102197 AND (text = 'Tu nascondi la tua faccia, essi sono smarriti;'); -- 23 104:29
UPDATE "LUZZI" SET text = 'Tu mandi il tuo spirito, essi sono creati, e tu rinnovi la faccia della terra.' WHERE "verseID" = 102198 AND (text = 'Tu mandi il tuo spirito, essi sono creati,'); -- 23 104:30
UPDATE "LUZZI" SET text = 'Duri in perpetuo la gloria dell''Eterno, si rallegri l''Eterno nelle opere sue!' WHERE "verseID" = 102199 AND (text = 'Duri in perpetuo la gloria dell''Eterno,'); -- 23 104:31
UPDATE "LUZZI" SET text = 'Egli riguarda la terra, ed essa trema; egli tocca i monti, ed essi fumano.' WHERE "verseID" = 102200 AND (text = 'Egli riguarda la terra, ed essa trema;'); -- 23 104:32
UPDATE "LUZZI" SET text = 'Io canterò all''Eterno finché io viva; salmeggerò al mio Dio finché io esista.' WHERE "verseID" = 102201 AND (text = 'Io canterò all''Eterno finché io viva;'); -- 23 104:33
UPDATE "LUZZI" SET text = 'Possa la mia meditazione essergli gradita! Io mi rallegrerò nell''Eterno.' WHERE "verseID" = 102202 AND (text = 'Possa la mia meditazione essergli gradita!'); -- 23 104:34
UPDATE "LUZZI" SET text = 'Spariscano i peccatori dalla terra, e gli empi non sian più! Anima mia, benedici l''Eterno. Alleluia.' WHERE "verseID" = 102203 AND (text = 'Spariscano i peccatori dalla terra,e gli empi non sian più!Anima mia, benedici l''Eterno.Alleluia.'); -- 23 104:35
UPDATE "LUZZI" SET text = 'Celebrate l''Eterno, invocate il suo nome; fate conoscere le sue gesta fra i popoli.' WHERE "verseID" = 102204 AND (text = 'Celebrate l''Eterno, invocate il suo nome;' OR text = 'Celebrate l''Eterno, invocate il suo nome; fate conoscere le sue gesta fra popoli.'); -- 23 105:1
UPDATE "LUZZI" SET text = 'Cantategli, salmeggiategli, meditate su tutte le sue maraviglie.' WHERE "verseID" = 102205 AND (text = 'Cantategli, salmeggiategli,'); -- 23 105:2
