UPDATE "LUZZI" SET text = 'Cercate l''Eterno e la sua forza, cercate del continuo la sua faccia!' WHERE "verseID" = 102207 AND (text = 'Cercate l''Eterno e la sua forza,'); -- 23 105:4
UPDATE "LUZZI" SET text = 'Ricordatevi delle maraviglie ch''egli ha fatte, de'' suoi miracoli e dei giudizi della sua bocca,' WHERE "verseID" = 102208 AND (text = 'Ricordatevi delle maraviglie ch''egli ha fatte,'); -- 23 105:5
