UPDATE "LUZZI" SET text = 'dicendo: Io ti darò il paese di Canaan per vostra parte di eredità.' WHERE "verseID" = 102214 AND (text = 'dicendo: Io ti darò il paese di Canaan'); -- 23 105:11
