UPDATE "LUZZI" SET text = 'e andavano da una nazione all''altra, da un regno a un altro popolo.' WHERE "verseID" = 102216 AND (text = 'e andavano da una nazione all''altra,'); -- 23 105:13
UPDATE "LUZZI" SET text = 'Egli non permise che alcuno li opprimesse; anzi, castigò dei re per amor loro,' WHERE "verseID" = 102217 AND (text = 'Egli non permise che alcuno li opprimesse;' OR text = 'Egli non permise che alcuno li opprimesse; anzi, castigò dei re per amor loro'); -- 23 105:14
UPDATE "LUZZI" SET text = 'dicendo: Non toccate i miei unti, e non fate alcun male ai miei profeti.' WHERE "verseID" = 102218 AND (text = 'dicendo: Non toccate i miei unti,'); -- 23 105:15
UPDATE "LUZZI" SET text = 'Poi chiamò la fame sul paese, e fece mancar del tutto il sostegno del pane.' WHERE "verseID" = 102219 AND (text = 'Poi chiamò la fame sul paese,'); -- 23 105:16
