UPDATE "LUZZI" SET text = 'fino al tempo che avvenne quello che avea detto, e la parola dell''Eterno, nella prova, gli rese giustizia.' WHERE "verseID" = 102222 AND (text = 'fino al tempo che avvenne quello che avea detto,'); -- 23 105:19
