UPDATE "LUZZI" SET text = 'lo costituì signore della sua casa e governatore di tutti i suoi beni' WHERE "verseID" = 102224 AND (text = 'lo costituì signore della sua casa'); -- 23 105:21
UPDATE "LUZZI" SET text = 'per incatenare i principi a suo talento, e insegnare ai suoi anziani la sapienza.' WHERE "verseID" = 102225 AND (text = 'per incatenare i principi a suo talento,'); -- 23 105:22
UPDATE "LUZZI" SET text = 'Allora Israele venne in Egitto, e Giacobbe soggiornò nel paese di Cham.' WHERE "verseID" = 102226 AND (text = 'Allora Israele venne in Egitto,'); -- 23 105:23
