UPDATE "LUZZI" SET text = 'Mandò le tenebre e fece oscurar l''aria, eppur non osservarono le sue parole.' WHERE "verseID" = 102231 AND (text = 'Mandò le tenebre e fece oscurar l''aria,' OR text = 'Mandò le tenebre e fece oscurar l''aria, eppure non osservarono le sue parole.'); -- 23 105:28
