UPDATE "LUZZI" SET text = 'La loro terra brulicò di rane, fin nelle camere dei loro re.' WHERE "verseID" = 102233 AND (text = 'La loro terra brulicò di rane,'); -- 23 105:30
UPDATE "LUZZI" SET text = 'Egli parlò, e vennero mosche velenose e zanzare in tutto il loro territorio.' WHERE "verseID" = 102234 AND (text = 'Egli parlò, e vennero mosche velenose'); -- 23 105:31
