UPDATE "LUZZI" SET text = 'Poi percosse tutti i primogeniti nel loro paese, le primizie d''ogni loro forza.' WHERE "verseID" = 102239 AND (text = 'Poi percosse tutti i primogeniti nel loro paese,'); -- 23 105:36
UPDATE "LUZZI" SET text = 'E fece uscire gli Israeliti con argento ed oro, e non vi fu alcuno, fra le sue tribù, che fosse fiacco.' WHERE "verseID" = 102240 AND (text = 'E fece uscire gli Israeliti con argento ed oro,'); -- 23 105:37
