UPDATE "LUZZI" SET text = 'Poiché egli si ricordò della sua parola santa e d''Abrahamo, suo servitore;' WHERE "verseID" = 102245 AND (text = 'Poiché egli si ricordò della sua parola santa'); -- 23 105:42
UPDATE "LUZZI" SET text = 'e trasse fuori il suo popolo con allegrezza, i suoi eletti con giubilo.' WHERE "verseID" = 102246 AND (text = 'e trasse fuori il suo popolo con allegrezza,' OR text = 'e trasse fuori il suo popolo con allegrezza, e i suoi eletti con giubilo.'); -- 23 105:43
