UPDATE "LUZZI" SET text = 'perché osservassero i suoi statuti e ubbidissero alle sue leggi. Alleluia.' WHERE "verseID" = 102248 AND (text = 'perché osservassero i suoi statutie ubbidissero alle sue leggi.Alleluia.'); -- 23 105:45
