UPDATE "LUZZI" SET text = 'O Eterno, ricordati di me, con la benevolenza che usi verso il tuo popolo; visitami con la tua salvazione,' WHERE "verseID" = 102252 AND (text = 'O Eterno, ricordati di me,'); -- 23 106:4
UPDATE "LUZZI" SET text = 'affinché io vegga il bene de'' tuoi eletti, mi rallegri dell''allegrezza della tua nazione, e mi glorî con la tua eredità.' WHERE "verseID" = 102253 AND (text = 'affinché io vegga il bene de'' tuoi eletti,' OR text = 'affinché io vegga il bene de'' tuoi eletti, mi rallegri dell''allegrezza della tua nazione, e mi glori con la tua eredità.'); -- 23 106:5
UPDATE "LUZZI" SET text = 'Noi e i nostri padri abbiamo peccato, abbiamo commesso l''iniquità, abbiamo agito empiamente.' WHERE "verseID" = 102254 AND (text = 'Noi e i nostri padri abbiamo peccato,'); -- 23 106:6
UPDATE "LUZZI" SET text = 'I nostri padri non prestarono attenzione alle tue maraviglie in Egitto; non si ricordarono della moltitudine delle tue benignità, ma si ribellarono presso al mare, al Mar rosso.' WHERE "verseID" = 102255 AND (text = 'I nostri padri non prestarono attenzione'); -- 23 106:7
UPDATE "LUZZI" SET text = 'Nondimeno egli li salvò per amor del suo nome, per far conoscere la sua potenza.' WHERE "verseID" = 102256 AND (text = 'Nondimeno egli li salvò per amor del suo nome,'); -- 23 106:8
UPDATE "LUZZI" SET text = 'Sgridò il Mar rosso ed esso si seccò; li condusse attraverso gli abissi come attraverso un deserto.' WHERE "verseID" = 102257 AND (text = 'Sgridò il Mar rosso ed esso si seccò;'); -- 23 106:9
UPDATE "LUZZI" SET text = 'E li salvò dalla mano di chi li odiava, e li redense dalla mano del nemico.' WHERE "verseID" = 102258 AND (text = 'E li salvò dalla mano di chi li odiava,'); -- 23 106:10
UPDATE "LUZZI" SET text = 'E le acque copersero i loro avversari; non ne scampò neppur uno.' WHERE "verseID" = 102259 AND (text = 'E le acque copersero i loro avversari;'); -- 23 106:11
UPDATE "LUZZI" SET text = 'Allora credettero alle sue parole, e cantarono la sua lode.' WHERE "verseID" = 102260 AND (text = 'Allora credettero alle sue parole,'); -- 23 106:12
