UPDATE "LUZZI" SET text = 'ma si accesero di cupidigia nel deserto, e tentarono Dio nella solitudine.' WHERE "verseID" = 102262 AND (text = 'ma si accesero di cupidigia nel deserto,'); -- 23 106:14
