UPDATE "LUZZI" SET text = 'Fecero un vitello in Horeb, e adorarono un''immagine di getto;' WHERE "verseID" = 102267 AND (text = 'Fecero un vitello in Horeb,'); -- 23 106:19
UPDATE "LUZZI" SET text = 'così mutarono la loro gloria nella figura d''un bue che mangia l''erba.' WHERE "verseID" = 102268 AND (text = 'così mutarono la loro gloria'); -- 23 106:20
UPDATE "LUZZI" SET text = 'Dimenticarono Dio, loro salvatore, che avea fatto cose grandi in Egitto,' WHERE "verseID" = 102269 AND (text = 'Dimenticarono Dio, loro salvatore,'); -- 23 106:21
UPDATE "LUZZI" SET text = 'cose maravigliose nel paese di Cham, cose tremende al Mar rosso.' WHERE "verseID" = 102270 AND (text = 'cose maravigliose nel paese di Cham,'); -- 23 106:22
UPDATE "LUZZI" SET text = 'Ond''egli parlò di sterminarli; ma Mosè, suo eletto, stette sulla breccia dinanzi a lui per stornar l''ira sua onde non li distruggesse.' WHERE "verseID" = 102271 AND (text = 'Ond''egli parlò di sterminarli;'); -- 23 106:23
UPDATE "LUZZI" SET text = 'Essi disdegnarono il paese delizioso, non credettero alla sua parola;' WHERE "verseID" = 102272 AND (text = 'Essi disdegnarono il paese delizioso,'); -- 23 106:24
UPDATE "LUZZI" SET text = 'e mormorarono nelle loro tende, e non dettero ascolto alla voce dell''Eterno.' WHERE "verseID" = 102273 AND (text = 'e mormorarono nelle loro tende,'); -- 23 106:25
UPDATE "LUZZI" SET text = 'Ond''egli, alzando la mano, giurò loro che li farebbe cader nel deserto,' WHERE "verseID" = 102274 AND (text = 'Ond''egli, alzando la mano,'); -- 23 106:26
UPDATE "LUZZI" SET text = 'che farebbe perire la loro progenie fra le nazioni e li disperderebbe per tutti i paesi.' WHERE "verseID" = 102275 AND (text = 'che farebbe perire la loro progenie fra le nazioni'); -- 23 106:27
