UPDATE "LUZZI" SET text = 'Ma Fineas si levò e fece giustizia, e il flagello fu arrestato.' WHERE "verseID" = 102278 AND (text = 'Ma Fineas si levò e fece giustizia,'); -- 23 106:30
UPDATE "LUZZI" SET text = 'E ciò gli fu imputato come giustizia per ogni età, in perpetuo.' WHERE "verseID" = 102279 AND (text = 'E ciò gli fu imputato come giustizia'); -- 23 106:31
UPDATE "LUZZI" SET text = 'Lo provocarono ad ira anche alle acque di Meriba, e venne del male a Mosè per cagion loro;' WHERE "verseID" = 102280 AND (text = 'Lo provocarono ad ira anche alle acque di Meriba,'); -- 23 106:32
UPDATE "LUZZI" SET text = 'perché inasprirono il suo spirito ed egli parlò sconsigliatamente con le sue labbra.' WHERE "verseID" = 102281 AND (text = 'perché inasprirono il suo spirito'); -- 23 106:33
UPDATE "LUZZI" SET text = 'Essi non distrussero i popoli, come l''Eterno avea loro comandato;' WHERE "verseID" = 102282 AND (text = 'Essi non distrussero i popoli,'); -- 23 106:34
UPDATE "LUZZI" SET text = 'ma si mescolarono con le nazioni, e impararono le opere d''esse:' WHERE "verseID" = 102283 AND (text = 'ma si mescolarono con le nazioni,'); -- 23 106:35
UPDATE "LUZZI" SET text = 'e servirono ai loro idoli, i quali divennero per essi un laccio;' WHERE "verseID" = 102284 AND (text = 'e servirono ai loro idoli,'); -- 23 106:36
UPDATE "LUZZI" SET text = 'e sacrificarono i loro figliuoli e le loro figliuole ai demoni,' WHERE "verseID" = 102285 AND (text = 'e sacrificarono i loro figliuoli'); -- 23 106:37
UPDATE "LUZZI" SET text = 'e sparsero il sangue innocente, il sangue dei loro figliuoli e delle loro figliuole, che sacrificarono agl''idoli di Canaan; e il paese fu profanato dal sangue versato.' WHERE "verseID" = 102286 AND (text = 'e sparsero il sangue innocente,'); -- 23 106:38
UPDATE "LUZZI" SET text = 'Essi si contaminarono con le loro opere, e si prostituirono coi loro atti.' WHERE "verseID" = 102287 AND (text = 'Essi si contaminarono con le loro opere,'); -- 23 106:39
