UPDATE "LUZZI" SET text = 'E li dette nelle mani delle nazioni, e quelli che li odiavano li signoreggiarono.' WHERE "verseID" = 102289 AND (text = 'E li dette nelle mani delle nazioni,'); -- 23 106:41
UPDATE "LUZZI" SET text = 'E i loro nemici li oppressero, e furono umiliati sotto la loro mano.' WHERE "verseID" = 102290 AND (text = 'E i loro nemici li oppressero,'); -- 23 106:42
UPDATE "LUZZI" SET text = 'Molte volte li liberò, ma essi si ribellavano, seguendo i loro propri voleri, e si rovinavano per la loro iniquità.' WHERE "verseID" = 102291 AND (text = 'Molte volte li liberò,'); -- 23 106:43
UPDATE "LUZZI" SET text = 'Tuttavia, volse a loro lo sguardo quando furono in distretta, quando udì il loro grido;' WHERE "verseID" = 102292 AND (text = 'Tuttavia, volse a loro lo sguardo quando furono in distretta,'); -- 23 106:44
UPDATE "LUZZI" SET text = 'e si ricordò per loro del suo patto, e si pentì secondo la moltitudine delle sue benignità.' WHERE "verseID" = 102293 AND (text = 'e si ricordò per loro del suo patto,'); -- 23 106:45
UPDATE "LUZZI" SET text = 'Fece loro anche trovar compassione presso tutti quelli che li avevano menati in cattività.' WHERE "verseID" = 102294 AND (text = 'Fece loro anche trovar compassione' OR text = 'Fece loro anche trovar compassione presso tutti quelli che li aveano menati in cattività.'); -- 23 106:46
