UPDATE "LUZZI" SET text = 'Tal sia, da parte dell''Eterno, la ricompensa dei miei avversari, e di quelli che proferiscono del male contro l''anima mia.' WHERE "verseID" = 102372 AND (text = 'Tal sia, da parte dell''Eterno, la ricompensa dei miei avversari,'); -- 23 109:20
