UPDATE "LUZZI" SET text = 'Grandi sono le opere dell''Eterno, ricercate da tutti quelli che si dilettano in esse.' WHERE "verseID" = 102392 AND (text = 'Grandi sono le opere dell''Eterno,'); -- 23 111:2
