UPDATE "LUZZI" SET text = 'Egli ha dato da vivere a quelli che lo temono, egli si ricorda in eterno del suo patto.' WHERE "verseID" = 102395 AND (text = 'Egli ha dato da vivere a quelli che lo temono,'); -- 23 111:5
