UPDATE "LUZZI" SET text = 'Le opere delle sue mani sono verità e giustizia; tutti i suoi precetti sono fermi,' WHERE "verseID" = 102397 AND (text = 'Le opere delle sue mani sono verità e giustizia;'); -- 23 111:7
UPDATE "LUZZI" SET text = 'stabili in sempiterno, fatti con verità e con dirittura.' WHERE "verseID" = 102398 AND (text = 'stabili in sempiterno,'); -- 23 111:8
UPDATE "LUZZI" SET text = 'Egli ha mandato la redenzione al suo popolo, ha stabilito il suo patto per sempre; santo e tremendo è il suo nome.' WHERE "verseID" = 102399 AND (text = 'Egli ha mandato la redenzione al suo popolo,'); -- 23 111:9
UPDATE "LUZZI" SET text = 'Il timor dell''Eterno è il principio della sapienza; buon senno hanno tutti quelli che mettono in pratica la sua legge. La sua lode dimora in perpetuo.' WHERE "verseID" = 102400 AND (text = 'Il timor dell''Eterno è il principio della sapienza;buon senno hanno tutti quelliche mettono in pratica la sua legge.La sua lode dimora in perpetuo.'); -- 23 111:10
UPDATE "LUZZI" SET text = 'Alleluia. Beato l''uomo che teme l''Eterno, che si diletta grandemente nei suoi comandamenti.' WHERE "verseID" = 102401 AND (text = 'Alleluia.'); -- 23 112:1
UPDATE "LUZZI" SET text = 'Forte sulla terra sarà la sua progenie; la generazione degli uomini retti sarà benedetta.' WHERE "verseID" = 102402 AND (text = 'Forte sulla terra sarà la sua progenie;'); -- 23 112:2
UPDATE "LUZZI" SET text = 'Abbondanza e ricchezze sono nella sua casa, e la sua giustizia dimora in perpetuo.' WHERE "verseID" = 102403 AND (text = 'Abbondanza e ricchezze sono nella sua casa,'); -- 23 112:3
UPDATE "LUZZI" SET text = 'La luce si leva nelle tenebre per quelli che son retti, per chi è misericordioso, pietoso e giusto.' WHERE "verseID" = 102404 AND (text = 'La luce si leva nelle tenebre per quelli che son retti,'); -- 23 112:4
UPDATE "LUZZI" SET text = 'Felice l''uomo che ha compassione e presta! Egli guadagnerà la sua causa in giudizio,' WHERE "verseID" = 102405 AND (text = 'Felice l''uomo che ha compassione e presta!'); -- 23 112:5
UPDATE "LUZZI" SET text = 'poiché non sarà mai smosso; la memoria del giusto sarà perpetua.' WHERE "verseID" = 102406 AND (text = 'poiché non sarà mai smosso;'); -- 23 112:6
