UPDATE "LUZZI" SET text = 'Egli ha sparso, ha dato ai bisognosi, la sua giustizia dimora in perpetuo, la sua potenza s''innalzerà gloriosa.' WHERE "verseID" = 102409 AND (text = 'Egli ha sparso, ha dato ai bisognosi,'); -- 23 112:9
UPDATE "LUZZI" SET text = 'L''empio lo vedrà e ne avrà dispetto, digrignerà i denti e si struggerà; il desiderio degli empi perirà.' WHERE "verseID" = 102410 AND (text = 'L''empio lo vedrà e ne avrà dispetto,digrignerà i denti e si struggerà;il desiderio degli empi perirà.'); -- 23 112:10
UPDATE "LUZZI" SET text = 'Alleluia. Lodate, o servi dell''Eterno, lodate il nome dell''Eterno!' WHERE "verseID" = 102411 AND (text = 'Alleluia.'); -- 23 113:1
