UPDATE "LUZZI" SET text = 'L''Eterno è eccelso sopra tutte le nazioni, e la sua gloria è al disopra dei cieli.' WHERE "verseID" = 102414 AND (text = 'L''Eterno è eccelso sopra tutte le nazioni,'); -- 23 113:4
UPDATE "LUZZI" SET text = 'Chi è simile all''Eterno, all''Iddio nostro, che siede sul trono in alto,' WHERE "verseID" = 102415 AND (text = 'Chi è simile all''Eterno, all''Iddio nostro,'); -- 23 113:5
UPDATE "LUZZI" SET text = 'che s''abbassa a riguardare nei cieli e sulla terra?' WHERE "verseID" = 102416 AND (text = 'che s''abbassa a riguardare'); -- 23 113:6
