UPDATE "LUZZI" SET text = 'Quando Israele uscì dall''Egitto, e la casa di Giacobbe di fra un popolo dal linguaggio strano,' WHERE "verseID" = 102420 AND (text = 'Quando Israele uscì dall''Egitto,'); -- 23 114:1
UPDATE "LUZZI" SET text = 'Giuda divenne il santuario dell''Eterno; Israele, suo dominio.' WHERE "verseID" = 102421 AND (text = 'Giuda divenne il santuario dell''Eterno;'); -- 23 114:2
UPDATE "LUZZI" SET text = 'Il mare lo vide e fuggì, il Giordano tornò addietro.' WHERE "verseID" = 102422 AND (text = 'Il mare lo vide e fuggì,'); -- 23 114:3
UPDATE "LUZZI" SET text = 'I monti saltarono come montoni, i colli come agnelli.' WHERE "verseID" = 102423 AND (text = 'I monti saltarono come montoni,'); -- 23 114:4
