UPDATE "LUZZI" SET text = 'Trema, o terra, alla presenza del Signore, alla presenza dell''Iddio di Giacobbe,' WHERE "verseID" = 102426 AND (text = 'Trema, o terra, alla presenza del Signore,'); -- 23 114:7
UPDATE "LUZZI" SET text = 'che mutò la roccia in istagno, il macigno in sorgente d''acqua.' WHERE "verseID" = 102427 AND (text = 'che mutò la roccia in istagno,il macigno in sorgente d''acqua.'); -- 23 114:8
