UPDATE "LUZZI" SET text = 'Hanno bocca e non parlano, hanno occhi e non vedono,' WHERE "verseID" = 102432 AND (text = 'Hanno bocca e non parlano,'); -- 23 115:5
UPDATE "LUZZI" SET text = 'hanno orecchi e non odono, hanno naso e non odorano,' WHERE "verseID" = 102433 AND (text = 'hanno orecchi e non odono,'); -- 23 115:6
