UPDATE "LUZZI" SET text = 'O casa d''Aaronne, confida nell''Eterno! - Egli è il loro aiuto e il loro scudo.' WHERE "verseID" = 102437 AND (text = 'O casa d''Aaronne, confida nell''Eterno!' OR text = 'O casa d''Aaronne, confida nell''Eterno! Egli è il loro aiuto e il loro scudo.'); -- 23 115:10
UPDATE "LUZZI" SET text = 'O voi che temete l''Eterno, confidate nell''Eterno! - Egli è il loro aiuto e il loro scudo.' WHERE "verseID" = 102438 AND (text = 'O voi che temete l''Eterno, confidate nell''Eterno!' OR text = 'O voi che temete l''Eterno, confidate nell''Eterno! Egli è il loro aiuto e il loro scudo.'); -- 23 115:11
UPDATE "LUZZI" SET text = 'L''Eterno si è ricordato di noi; egli benedirà, sì, benedirà la casa d''Israele, benedirà la casa d''Aaronne,' WHERE "verseID" = 102439 AND (text = 'L''Eterno si è ricordato di noi; egli benedirà,'); -- 23 115:12
UPDATE "LUZZI" SET text = 'benedirà quelli che temono l''Eterno, piccoli e grandi.' WHERE "verseID" = 102440 AND (text = 'benedirà quelli che temono l''Eterno,'); -- 23 115:13
UPDATE "LUZZI" SET text = 'L''Eterno vi moltiplichi le sue grazie, a voi ed ai vostri figliuoli.' WHERE "verseID" = 102441 AND (text = 'L''Eterno vi moltiplichi le sue grazie,'); -- 23 115:14
UPDATE "LUZZI" SET text = 'Siate benedetti dall''Eterno, che ha fatto il cielo e la terra.' WHERE "verseID" = 102442 AND (text = 'Siate benedetti dall''Eterno,'); -- 23 115:15
