UPDATE "LUZZI" SET text = 'Non sono i morti che lodano l''Eterno, né alcuno di quelli che scendono nel luogo del silenzio;' WHERE "verseID" = 102444 AND (text = 'Non sono i morti che lodano l''Eterno,'); -- 23 115:17
UPDATE "LUZZI" SET text = 'ma noi benediremo l''Eterno da ora in perpetuo. Alleluia.' WHERE "verseID" = 102445 AND (text = 'ma noi benediremo l''Eternoda ora in perpetuo.Alleluia.'); -- 23 115:18
UPDATE "LUZZI" SET text = 'Io amo l''Eterno perch''egli ha udito la mia voce e le mie supplicazioni.' WHERE "verseID" = 102446 AND (text = 'Io amo l''Eterno perch''egli ha udito'); -- 23 116:1
UPDATE "LUZZI" SET text = 'Poiché egli ha inclinato verso me il suo orecchio, io lo invocherò per tutto il corso dei miei giorni.' WHERE "verseID" = 102447 AND (text = 'Poiché egli ha inclinato verso me il suo orecchio,'); -- 23 116:2
UPDATE "LUZZI" SET text = 'I legami della morte mi aveano circondato, le angosce del soggiorno dei morti m''aveano còlto; io avevo incontrato distretta e cordoglio.' WHERE "verseID" = 102448 AND (text = 'I legami della morte mi aveano circondato,'); -- 23 116:3
UPDATE "LUZZI" SET text = 'Ma io invocai il nome dell''Eterno: Deh, o Eterno, libera l''anima mia!' WHERE "verseID" = 102449 AND (text = 'Ma io invocai il nome dell''Eterno:'); -- 23 116:4
UPDATE "LUZZI" SET text = 'L''Eterno è pietoso e giusto, e il nostro Dio è misericordioso.' WHERE "verseID" = 102450 AND (text = 'L''Eterno è pietoso e giusto,'); -- 23 116:5
UPDATE "LUZZI" SET text = 'L''Eterno protegge i semplici; io ero ridotto in misero stato, egli mi ha salvato.' WHERE "verseID" = 102451 AND (text = 'L''Eterno protegge i semplici;'); -- 23 116:6
UPDATE "LUZZI" SET text = 'Ritorna, anima mia, al tuo riposo, perché l''Eterno t''ha colmata di beni.' WHERE "verseID" = 102452 AND (text = 'Ritorna, anima mia, al tuo riposo,'); -- 23 116:7
UPDATE "LUZZI" SET text = 'Poiché tu hai liberata l''anima mia dalla morte, gli occhi miei da lacrime, i miei piedi da caduta.' WHERE "verseID" = 102453 AND (text = 'Poiché tu hai liberata l''anima mia dalla morte,'); -- 23 116:8
UPDATE "LUZZI" SET text = 'Io camminerò nel cospetto dell''Eterno, sulla terra dei viventi.' WHERE "verseID" = 102454 AND (text = 'Io camminerò nel cospetto dell''Eterno,'); -- 23 116:9
UPDATE "LUZZI" SET text = 'Io ho creduto, perciò parlerò. Io ero grandemente afflitto.' WHERE "verseID" = 102455 AND (text = 'Io ho creduto, perciò parlerò.'); -- 23 116:10
UPDATE "LUZZI" SET text = 'Io dicevo nel mio smarrimento: Ogni uomo è bugiardo.' WHERE "verseID" = 102456 AND (text = 'Io dicevo nel mio smarrimento:'); -- 23 116:11
UPDATE "LUZZI" SET text = 'Che renderò io all''Eterno? tutti i suoi benefizi son sopra me.' WHERE "verseID" = 102457 AND (text = 'Che renderò io all''Eterno?'); -- 23 116:12
UPDATE "LUZZI" SET text = 'Io prenderò il calice della salvezza e invocherò il nome dell''Eterno.' WHERE "verseID" = 102458 AND (text = 'Io prenderò il calice della salvezza'); -- 23 116:13
UPDATE "LUZZI" SET text = 'Io compirò i miei voti all''Eterno, e lo farò in presenza di tutto il suo popolo.' WHERE "verseID" = 102459 AND (text = 'Io compirò i miei voti all''Eterno,'); -- 23 116:14
UPDATE "LUZZI" SET text = 'Cosa di gran momento è agli occhi dell''Eterno la morte de'' suoi diletti.' WHERE "verseID" = 102460 AND (text = 'Cosa di gran momento è agli occhi dell''Eterno'); -- 23 116:15
UPDATE "LUZZI" SET text = 'Sì, o Eterno, io son tuo servitore, son tuo servitore, figliuolo della tua servente; tu hai sciolto i miei legami.' WHERE "verseID" = 102461 AND (text = 'Sì, o Eterno, io son tuo servitore,'); -- 23 116:16
UPDATE "LUZZI" SET text = 'Io t''offrirò il sacrifizio di lode e invocherò il nome dell''Eterno.' WHERE "verseID" = 102462 AND (text = 'Io t''offrirò il sacrifizio di lode'); -- 23 116:17
UPDATE "LUZZI" SET text = 'Io compirò i miei voti all''Eterno, e lo farò in presenza di tutto il suo popolo,' WHERE "verseID" = 102463 AND (text = 'Io compirò i miei voti all''Eterno,'); -- 23 116:18
UPDATE "LUZZI" SET text = 'nei cortili della casa dell''Eterno, in mezzo a te, o Gerusalemme. Alleluia.' WHERE "verseID" = 102464 AND (text = 'nei cortili della casa dell''Eterno,in mezzo a te, o Gerusalemme.Alleluia.'); -- 23 116:19
UPDATE "LUZZI" SET text = 'Lodate l''Eterno, voi nazioni tutte! Celebratelo, voi tutti i popoli!' WHERE "verseID" = 102465 AND (text = 'Lodate l''Eterno, voi nazioni tutte!'); -- 23 117:1
UPDATE "LUZZI" SET text = 'Poiché la sua benignità verso noi è grande, e la fedeltà dell''Eterno dura in perpetuo. Alleluia.' WHERE "verseID" = 102466 AND (text = 'Poiché la sua benignità verso noi è grande,e la fedeltà dell''Eterno dura in perpetuo.Alleluia.'); -- 23 117:2
UPDATE "LUZZI" SET text = 'Celebrate l''Eterno, poiché egli è buono, perché la sua benignità dura in eterno.' WHERE "verseID" = 102467 AND (text = 'Celebrate l''Eterno, poiché egli è buono,'); -- 23 118:1
UPDATE "LUZZI" SET text = 'Sì, dica Israele: La sua benignità dura in eterno.' WHERE "verseID" = 102468 AND (text = 'Sì, dica Israele:'); -- 23 118:2
UPDATE "LUZZI" SET text = 'Sì, dica la casa d''Aaronne: La sua benignità dura in eterno.' WHERE "verseID" = 102469 AND (text = 'Sì, dica la casa d''Aaronne:'); -- 23 118:3
UPDATE "LUZZI" SET text = 'Sì, dicano quelli che temono l''Eterno: La sua benignità dura in eterno.' WHERE "verseID" = 102470 AND (text = 'Sì, dicano quelli che temono l''Eterno:'); -- 23 118:4
UPDATE "LUZZI" SET text = 'Dal fondo della mia distretta invocai l''Eterno; l''Eterno mi rispose e mi mise al largo.' WHERE "verseID" = 102471 AND (text = 'Dal fondo della mia distretta invocai l''Eterno;'); -- 23 118:5
UPDATE "LUZZI" SET text = 'L''Eterno è per me; io non temerò; che cosa mi può far l''uomo?' WHERE "verseID" = 102472 AND (text = 'L''Eterno è per me; io non temerò;'); -- 23 118:6
UPDATE "LUZZI" SET text = 'L''Eterno è per me, fra quelli che mi soccorrono; ed io vedrò quel che desidero su quelli che m''odiano.' WHERE "verseID" = 102473 AND (text = 'L''Eterno è per me, fra quelli che mi soccorrono;'); -- 23 118:7
UPDATE "LUZZI" SET text = 'È meglio rifugiarsi nell''Eterno che confidare nell''uomo;' WHERE "verseID" = 102474 AND (text = 'È meglio rifugiarsi nell''Eterno'); -- 23 118:8
UPDATE "LUZZI" SET text = 'è meglio rifugiarsi nell''Eterno che confidare nei principi.' WHERE "verseID" = 102475 AND (text = 'è meglio rifugiarsi nell''Eterno'); -- 23 118:9
UPDATE "LUZZI" SET text = 'Tutte le nazioni m''hanno circondato; nel nome dell''Eterno, eccole da me sconfitte.' WHERE "verseID" = 102476 AND (text = 'Tutte le nazioni m''hanno circondato;'); -- 23 118:10
UPDATE "LUZZI" SET text = 'M''hanno circondato, sì, m''hanno accerchiato; nel nome dell''Eterno, eccole da me sconfitte.' WHERE "verseID" = 102477 AND (text = 'M''hanno circondato, sì, m''hanno accerchiato;'); -- 23 118:11
UPDATE "LUZZI" SET text = 'M''hanno circondato come api, ma sono state spente come fuoco di spine; nel nome dell''Eterno io le ho sconfitte.' WHERE "verseID" = 102478 AND (text = 'M''hanno circondato come api,'); -- 23 118:12
UPDATE "LUZZI" SET text = 'Tu m''hai spinto con violenza per farmi cadere, ma l''Eterno mi ha soccorso.' WHERE "verseID" = 102479 AND (text = 'Tu m''hai spinto con violenza per farmi cadere,'); -- 23 118:13
UPDATE "LUZZI" SET text = 'L''Eterno è la mia forza e il mio cantico, ed è stato la mia salvezza.' WHERE "verseID" = 102480 AND (text = 'L''Eterno è la mia forza e il mio cantico,'); -- 23 118:14
UPDATE "LUZZI" SET text = 'Un grido d''esultanza e di vittoria risuona nelle tende dei giusti: La destra dell''Eterno fa prodezze.' WHERE "verseID" = 102481 AND (text = 'Un grido d''esultanza e di vittoria risuona nelle tende dei giusti:'); -- 23 118:15
UPDATE "LUZZI" SET text = 'La destra dell''Eterno è levata in alto, la destra dell''Eterno fa prodezze.' WHERE "verseID" = 102482 AND (text = 'La destra dell''Eterno è levata in alto,'); -- 23 118:16
UPDATE "LUZZI" SET text = 'Io non morrò, anzi vivrò, e racconterò le opere dell''Eterno.' WHERE "verseID" = 102483 AND (text = 'Io non morrò, anzi vivrò,'); -- 23 118:17
UPDATE "LUZZI" SET text = 'Certo, l''Eterno mi ha castigato, ma non mi ha dato in balìa della morte.' WHERE "verseID" = 102484 AND (text = 'Certo, l''Eterno mi ha castigato,'); -- 23 118:18
UPDATE "LUZZI" SET text = 'Apritemi le porte della giustizia; io entrerò per esse, e celebrerò l''Eterno.' WHERE "verseID" = 102485 AND (text = 'Apritemi le porte della giustizia;'); -- 23 118:19
UPDATE "LUZZI" SET text = 'Questa è la porta dell''Eterno; i giusti entreranno per essa.' WHERE "verseID" = 102486 AND (text = 'Questa è la porta dell''Eterno;'); -- 23 118:20
UPDATE "LUZZI" SET text = 'Io ti celebrerò perché tu m''hai risposto, e sei stato la mia salvezza.' WHERE "verseID" = 102487 AND (text = 'Io ti celebrerò perché tu m''hai risposto,'); -- 23 118:21
UPDATE "LUZZI" SET text = 'La pietra che gli edificatori avevano rigettata è divenuta la pietra angolare.' WHERE "verseID" = 102488 AND (text = 'La pietra che gli edificatori avevano rigettata'); -- 23 118:22
UPDATE "LUZZI" SET text = 'Questa è opera dell''Eterno, è cosa maravigliosa agli occhi nostri.' WHERE "verseID" = 102489 AND (text = 'Questa è opera dell''Eterno,'); -- 23 118:23
UPDATE "LUZZI" SET text = 'Questo è il giorno che l''Eterno ha fatto; festeggiamo e rallegriamoci in esso.' WHERE "verseID" = 102490 AND (text = 'Questo è il giorno che l''Eterno ha fatto;'); -- 23 118:24
UPDATE "LUZZI" SET text = 'Deh, o Eterno, salva! Deh, o Eterno, facci prosperare!' WHERE "verseID" = 102491 AND (text = 'Deh, o Eterno, salva!'); -- 23 118:25
UPDATE "LUZZI" SET text = 'Benedetto colui che viene nel nome dell''Eterno! Noi vi benediciamo dalla casa dell''Eterno.' WHERE "verseID" = 102492 AND (text = 'Benedetto colui che viene nel nome dell''Eterno!'); -- 23 118:26
UPDATE "LUZZI" SET text = 'L''Eterno è Dio ed ha fatto risplender su noi la sua luce; legate con funi la vittima della solennità, e menatela ai corni dell''altare.' WHERE "verseID" = 102493 AND (text = 'L''Eterno è Dio ed ha fatto risplender su noi la sua luce;'); -- 23 118:27
UPDATE "LUZZI" SET text = 'Tu sei il mio Dio, io ti celebrerò; tu sei il mio Dio, io ti esalterò.' WHERE "verseID" = 102494 AND (text = 'Tu sei il mio Dio, io ti celebrerò;'); -- 23 118:28
UPDATE "LUZZI" SET text = 'Celebrate l''Eterno, perch''egli è buono, perché la sua benignità dura in eterno.' WHERE "verseID" = 102495 AND (text = 'Celebrate l''Eterno, perch''egli è buono,perché la sua benignità dura in eterno.'); -- 23 118:29
UPDATE "LUZZI" SET text = 'Beati quelli che sono integri nelle loro vie, che camminano secondo la legge dell''Eterno.' WHERE "verseID" = 102496 AND (text = 'Beati quelli che sono integri nelle loro vie,'); -- 23 119:1
UPDATE "LUZZI" SET text = 'Beati quelli che osservano le sue testimonianze, che lo cercano con tutto il cuore,' WHERE "verseID" = 102497 AND (text = 'Beati quelli che osservano le sue testimonianze,'); -- 23 119:2
UPDATE "LUZZI" SET text = 'ed anche non operano iniquità, ma camminano nelle sue vie.' WHERE "verseID" = 102498 AND (text = 'ed anche non operano iniquità,'); -- 23 119:3
UPDATE "LUZZI" SET text = 'Tu hai ordinato i tuoi precetti perché siano osservati con cura.' WHERE "verseID" = 102499 AND (text = 'Tu hai ordinato i tuoi precetti'); -- 23 119:4
