UPDATE "LUZZI" SET text = 'Io ho inclinato il mio cuore a praticare i tuoi statuti, in perpetuo, sino alla fine.' WHERE "verseID" = 102607 AND (text = 'Io ho inclinato il mio cuore a praticare i tuoi statuti,'); -- 23 119:112
UPDATE "LUZZI" SET text = 'Io odio gli uomini dal cuor doppio, ma amo la tua legge.' WHERE "verseID" = 102608 AND (text = 'Io odio gli uomini dal cuor doppio,'); -- 23 119:113
UPDATE "LUZZI" SET text = 'Tu sei il mio rifugio ed il mio scudo; io spero nella tua parola.' WHERE "verseID" = 102609 AND (text = 'Tu sei il mio rifugio ed il mio scudo;'); -- 23 119:114
UPDATE "LUZZI" SET text = 'Dipartitevi da me, o malvagi, ed io osserverò i comandamenti del mio Dio.' WHERE "verseID" = 102610 AND (text = 'Dipartitevi da me, o malvagi,'); -- 23 119:115
UPDATE "LUZZI" SET text = 'Sostienimi secondo la tua parola, ond''io viva, e non rendermi confuso nella mia speranza.' WHERE "verseID" = 102611 AND (text = 'Sostienimi secondo la tua parola, ond''io viva,'); -- 23 119:116
UPDATE "LUZZI" SET text = 'Sii il mio sostegno, e sarò salvo, e terrò del continuo i tuoi statuti dinanzi agli occhi.' WHERE "verseID" = 102612 AND (text = 'Sii il mio sostegno, e sarò salvo,'); -- 23 119:117
UPDATE "LUZZI" SET text = 'Tu disprezzi tutti quelli che deviano dai tuoi statuti, perché la loro frode è falsità.' WHERE "verseID" = 102613 AND (text = 'Tu disprezzi tutti quelli che deviano dai tuoi statuti,'); -- 23 119:118
UPDATE "LUZZI" SET text = 'Tu togli via come schiuma tutti gli empi dalla terra; perciò amo le tue testimonianze.' WHERE "verseID" = 102614 AND (text = 'Tu togli via come schiuma tutti gli empi dalla terra;'); -- 23 119:119
UPDATE "LUZZI" SET text = 'La mia carne rabbrividisce per lo spavento di te, e io temo i tuoi giudizi.' WHERE "verseID" = 102615 AND (text = 'La mia carne rabbrividisce per lo spavento di te,'); -- 23 119:120
UPDATE "LUZZI" SET text = 'Io ho fatto ciò che è diritto e giusto; non abbandonarmi ai miei oppressori.' WHERE "verseID" = 102616 AND (text = 'Io ho fatto ciò che è diritto e giusto;'); -- 23 119:121
UPDATE "LUZZI" SET text = 'Da'' sicurtà per il bene del tuo servitore, e non lasciare che i superbi m''opprimano.' WHERE "verseID" = 102617 AND (text = 'Da'' sicurtà per il bene del tuo servitore,'); -- 23 119:122
UPDATE "LUZZI" SET text = 'Gli occhi miei vengon meno, bramando la tua salvezza e la parola della tua giustizia.' WHERE "verseID" = 102618 AND (text = 'Gli occhi miei vengon meno, bramando la tua salvezza'); -- 23 119:123
UPDATE "LUZZI" SET text = 'Opera verso il tuo servitore secondo la tua benignità, e insegnami i tuoi statuti.' WHERE "verseID" = 102619 AND (text = 'Opera verso il tuo servitore secondo la tua benignità,'); -- 23 119:124
UPDATE "LUZZI" SET text = 'Io sono tuo servitore; dammi intelletto, perché possa conoscere le tue testimonianze.' WHERE "verseID" = 102620 AND (text = 'Io sono tuo servitore; dammi intelletto,'); -- 23 119:125
UPDATE "LUZZI" SET text = 'È tempo che l''Eterno operi; essi hanno annullato la tua legge.' WHERE "verseID" = 102621 AND (text = 'È tempo che l''Eterno operi;'); -- 23 119:126
UPDATE "LUZZI" SET text = 'Perciò io amo i tuoi comandamenti più dell''oro, più dell''oro finissimo.' WHERE "verseID" = 102622 AND (text = 'Perciò io amo i tuoi comandamenti'); -- 23 119:127
UPDATE "LUZZI" SET text = 'Perciò ritengo diritti tutti i tuoi precetti, e odio ogni sentiero di menzogna.' WHERE "verseID" = 102623 AND (text = 'Perciò ritengo diritti tutti i tuoi precetti,'); -- 23 119:128
UPDATE "LUZZI" SET text = 'Le tue testimonianze sono maravigliose; perciò l''anima mia le osserva.' WHERE "verseID" = 102624 AND (text = 'Le tue testimonianze sono maravigliose;'); -- 23 119:129
UPDATE "LUZZI" SET text = 'La dichiarazione delle tue parole illumina; dà intelletto ai semplici.' WHERE "verseID" = 102625 AND (text = 'La dichiarazione delle tue parole illumina;'); -- 23 119:130
UPDATE "LUZZI" SET text = 'Io ho aperto la bocca e ho sospirato perché ho bramato i tuoi comandamenti.' WHERE "verseID" = 102626 AND (text = 'Io ho aperto la bocca e ho sospirato'); -- 23 119:131
UPDATE "LUZZI" SET text = 'Volgiti a me ed abbi pietà di me, com''è giusto che tu faccia a chi ama il tuo nome.' WHERE "verseID" = 102627 AND (text = 'Volgiti a me ed abbi pietà di me,'); -- 23 119:132
UPDATE "LUZZI" SET text = 'Rafferma i miei passi nella tua parola, e non lasciare che alcuna iniquità mi domini.' WHERE "verseID" = 102628 AND (text = 'Rafferma i miei passi nella tua parola,'); -- 23 119:133
UPDATE "LUZZI" SET text = 'Liberami dall''oppressione degli uomini, ed io osserverò i tuoi precetti.' WHERE "verseID" = 102629 AND (text = 'Liberami dall''oppressione degli uomini,'); -- 23 119:134
UPDATE "LUZZI" SET text = 'Fa'' risplendere il tuo volto sul tuo servitore, e insegnami i tuoi statuti.' WHERE "verseID" = 102630 AND (text = 'Fa'' risplendere il tuo volto sul tuo servitore,'); -- 23 119:135
UPDATE "LUZZI" SET text = 'Rivi di lacrime mi scendon giù dagli occhi, perché la tua legge non è osservata.' WHERE "verseID" = 102631 AND (text = 'Rivi di lacrime mi scendon giù dagli occhi,'); -- 23 119:136
UPDATE "LUZZI" SET text = 'Tu sei giusto, o Eterno, e diritti sono i tuoi giudizi.' WHERE "verseID" = 102632 AND (text = 'Tu sei giusto, o Eterno,'); -- 23 119:137
UPDATE "LUZZI" SET text = 'Tu hai prescritto le tue testimonianze con giustizia e con grande fedeltà.' WHERE "verseID" = 102633 AND (text = 'Tu hai prescritto le tue testimonianze con giustizia'); -- 23 119:138
UPDATE "LUZZI" SET text = 'Il mio zelo mi consuma perché i miei nemici han dimenticato le tue parole.' WHERE "verseID" = 102634 AND (text = 'Il mio zelo mi consuma'); -- 23 119:139
UPDATE "LUZZI" SET text = 'La tua parola è pura d''ogni scoria; perciò il tuo servitore l''ama.' WHERE "verseID" = 102635 AND (text = 'La tua parola è pura d''ogni scoria;'); -- 23 119:140
UPDATE "LUZZI" SET text = 'Io son piccolo e sprezzato, ma non dimentico i tuoi precetti.' WHERE "verseID" = 102636 AND (text = 'Io son piccolo e sprezzato,'); -- 23 119:141
UPDATE "LUZZI" SET text = 'La tua giustizia è una giustizia eterna, e la tua legge è verità.' WHERE "verseID" = 102637 AND (text = 'La tua giustizia è una giustizia eterna,'); -- 23 119:142
UPDATE "LUZZI" SET text = 'Distretta e tribolazione m''hanno còlto, ma i tuoi comandamenti sono il mio diletto.' WHERE "verseID" = 102638 AND (text = 'Distretta e tribolazione m''hanno còlto,'); -- 23 119:143
UPDATE "LUZZI" SET text = 'Le tue testimonianze sono giuste in eterno; dammi intelletto ed io vivrò.' WHERE "verseID" = 102639 AND (text = 'Le tue testimonianze sono giuste in eterno;'); -- 23 119:144
UPDATE "LUZZI" SET text = 'Io grido con tutto il cuore; rispondimi, o Eterno! Io osserverò i tuoi statuti.' WHERE "verseID" = 102640 AND (text = 'Io grido con tutto il cuore; rispondimi, o Eterno!'); -- 23 119:145
UPDATE "LUZZI" SET text = 'Io t''invoco; salvami, e osserverò le tue testimonianze.' WHERE "verseID" = 102641 AND (text = 'Io t''invoco; salvami,'); -- 23 119:146
UPDATE "LUZZI" SET text = 'Io prevengo l''alba e grido; io spero nella tua parola.' WHERE "verseID" = 102642 AND (text = 'Io prevengo l''alba e grido;'); -- 23 119:147
UPDATE "LUZZI" SET text = 'Gli occhi miei prevengono le vigilie della notte, per meditare la tua parola.' WHERE "verseID" = 102643 AND (text = 'Gli occhi miei prevengono le vigilie della notte,'); -- 23 119:148
UPDATE "LUZZI" SET text = 'Ascolta la mia voce secondo la tua benignità; o Eterno, vivificami secondo la tua giustizia.' WHERE "verseID" = 102644 AND (text = 'Ascolta la mia voce secondo la tua benignità;'); -- 23 119:149
UPDATE "LUZZI" SET text = 'Si accostano a me quelli che van dietro alla scelleratezza; essi son lontani dalla tua legge.' WHERE "verseID" = 102645 AND (text = 'Si accostano a me quelli che van dietro alla scelleratezza;'); -- 23 119:150
UPDATE "LUZZI" SET text = 'Tu sei vicino, o Eterno, e tutti i tuoi comandamenti son verità.' WHERE "verseID" = 102646 AND (text = 'Tu sei vicino, o Eterno,'); -- 23 119:151
UPDATE "LUZZI" SET text = 'Da lungo tempo so dalle tue testimonianze che tu le hai stabilite in eterno.' WHERE "verseID" = 102647 AND (text = 'Da lungo tempo so dalle tue testimonianze'); -- 23 119:152
UPDATE "LUZZI" SET text = 'Considera la mia afflizione, e liberami; perché non ho dimenticato la tua legge.' WHERE "verseID" = 102648 AND (text = 'Considera la mia afflizione, e liberami;'); -- 23 119:153
UPDATE "LUZZI" SET text = 'Difendi tu la mia causa e riscattami; vivificami secondo la tua parola.' WHERE "verseID" = 102649 AND (text = 'Difendi tu la mia causa e riscattami;'); -- 23 119:154
UPDATE "LUZZI" SET text = 'La salvezza è lungi dagli empi, perché non cercano i tuoi statuti.' WHERE "verseID" = 102650 AND (text = 'La salvezza è lungi dagli empi,'); -- 23 119:155
UPDATE "LUZZI" SET text = 'Le tue compassioni son grandi, o Eterno; vivificami secondo i tuoi giudizi.' WHERE "verseID" = 102651 AND (text = 'Le tue compassioni son grandi, o Eterno;'); -- 23 119:156
UPDATE "LUZZI" SET text = 'I miei persecutori e i miei avversari son molti, ma io non devio dalle tue testimonianze.' WHERE "verseID" = 102652 AND (text = 'I miei persecutori e i miei avversari son molti,' OR text = 'I miei persecutori e i miei avversari son molti, ma io non devìo dalle tue testimonianze.'); -- 23 119:157
UPDATE "LUZZI" SET text = 'Io ho veduto gli sleali e ne ho provato orrore; perché non osservano la tua parola.' WHERE "verseID" = 102653 AND (text = 'Io ho veduto gli sleali e ne ho provato orrore;'); -- 23 119:158
UPDATE "LUZZI" SET text = 'Vedi come amo i tuoi precetti! O Eterno, vivificami secondo la tua benignità.' WHERE "verseID" = 102654 AND (text = 'Vedi come amo i tuoi precetti!'); -- 23 119:159
UPDATE "LUZZI" SET text = 'La somma della tua parola è verità; e tutti i giudizi della tua giustizia durano in eterno.' WHERE "verseID" = 102655 AND (text = 'La somma della tua parola è verità;'); -- 23 119:160
UPDATE "LUZZI" SET text = 'I principi m''hanno perseguitato senza ragione, ma il mio cuore ha timore delle tue parole.' WHERE "verseID" = 102656 AND (text = 'I principi m''hanno perseguitato senza ragione,'); -- 23 119:161
UPDATE "LUZZI" SET text = 'Io mi rallegro della tua parola, come uno che trova grandi spoglie.' WHERE "verseID" = 102657 AND (text = 'Io mi rallegro della tua parola,'); -- 23 119:162
UPDATE "LUZZI" SET text = 'Io odio e abomino la menzogna, ma amo la tua legge.' WHERE "verseID" = 102658 AND (text = 'Io odio e abomino la menzogna,'); -- 23 119:163
UPDATE "LUZZI" SET text = 'Io ti lodo sette volte al giorno per i giudizi della tua giustizia.' WHERE "verseID" = 102659 AND (text = 'Io ti lodo sette volte al giorno'); -- 23 119:164
UPDATE "LUZZI" SET text = 'Gran pace hanno quelli che amano la tua legge, e non c''è nulla che possa farli cadere.' WHERE "verseID" = 102660 AND (text = 'Gran pace hanno quelli che amano la tua legge,'); -- 23 119:165
UPDATE "LUZZI" SET text = 'Io ho sperato nella tua salvezza, o Eterno, e ho messo in pratica i tuoi comandamenti.' WHERE "verseID" = 102661 AND (text = 'Io ho sperato nella tua salvezza, o Eterno,'); -- 23 119:166
UPDATE "LUZZI" SET text = 'L''anima mia ha osservato le tue testimonianze, ed io le amo grandemente.' WHERE "verseID" = 102662 AND (text = 'L''anima mia ha osservato le tue testimonianze,'); -- 23 119:167
UPDATE "LUZZI" SET text = 'Io ho osservato i tuoi precetti e le tue testimonianze, perché tutte le mie vie ti stanno dinanzi.' WHERE "verseID" = 102663 AND (text = 'Io ho osservato i tuoi precetti e le tue testimonianze,'); -- 23 119:168
UPDATE "LUZZI" SET text = 'Giunga il mio grido dinanzi a te, o Eterno; dammi intelletto secondo la tua parola.' WHERE "verseID" = 102664 AND (text = 'Giunga il mio grido dinanzi a te, o Eterno;'); -- 23 119:169
UPDATE "LUZZI" SET text = 'Giunga la mia supplicazione in tua presenza; liberami secondo la tua parola.' WHERE "verseID" = 102665 AND (text = 'Giunga la mia supplicazione in tua presenza;'); -- 23 119:170
UPDATE "LUZZI" SET text = 'Le mie labbra esprimeranno la tua lode, perché tu m''insegni i tuoi statuti.' WHERE "verseID" = 102666 AND (text = 'Le mie labbra esprimeranno la tua lode,'); -- 23 119:171
UPDATE "LUZZI" SET text = 'La mia lingua celebrerà la tua parola, perché tutti i tuoi comandamenti sono giustizia.' WHERE "verseID" = 102667 AND (text = 'La mia lingua celebrerà la tua parola,'); -- 23 119:172
UPDATE "LUZZI" SET text = 'La tua mano mi aiuti, perché ho scelto i tuoi precetti.' WHERE "verseID" = 102668 AND (text = 'La tua mano mi aiuti,'); -- 23 119:173
UPDATE "LUZZI" SET text = 'Io bramo la tua salvezza, o Eterno, e la tua legge è il mio diletto.' WHERE "verseID" = 102669 AND (text = 'Io bramo la tua salvezza, o Eterno,'); -- 23 119:174
UPDATE "LUZZI" SET text = 'L''anima mia viva, ed essa ti loderà; e mi soccorrano i tuoi giudizi.' WHERE "verseID" = 102670 AND (text = 'L''anima mia viva, ed essa ti loderà;'); -- 23 119:175
UPDATE "LUZZI" SET text = 'Io vo errando come pecora smarrita; cerca il tuo servitore, perché io non dimentico i tuoi comandamenti.' WHERE "verseID" = 102671 AND (text = 'Io vo errando come pecora smarrita; cerca il tuo servitore,perché io non dimentico i tuoi comandamenti.'); -- 23 119:176
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Nella mia distretta ho invocato l''Eterno, ed egli m''ha risposto.' WHERE "verseID" = 102672 AND (text = 'Canto dei pellegrinaggi.'); -- 23 120:1
UPDATE "LUZZI" SET text = 'O Eterno, libera l''anima mia dalle labbra bugiarde, dalla lingua fraudolenta.' WHERE "verseID" = 102673 AND (text = 'O Eterno, libera l''anima mia dalle labbra bugiarde,'); -- 23 120:2
UPDATE "LUZZI" SET text = 'Che ti sarà dato e che ti sarà aggiunto, o lingua fraudolenta?' WHERE "verseID" = 102674 AND (text = 'Che ti sarà dato e che ti sarà aggiunto,'); -- 23 120:3
UPDATE "LUZZI" SET text = 'Frecce di guerriero, acute, con carboni di ginepro.' WHERE "verseID" = 102675 AND (text = 'Frecce di guerriero, acute,'); -- 23 120:4
UPDATE "LUZZI" SET text = 'Misero me che soggiorno in Mesec, e dimoro fra le tende di Kedar!' WHERE "verseID" = 102676 AND (text = 'Misero me che soggiorno in Mesec,'); -- 23 120:5
UPDATE "LUZZI" SET text = 'L''anima mia troppo a lungo ha dimorato con colui che odia la pace!' WHERE "verseID" = 102677 AND (text = 'L''anima mia troppo a lungo ha dimorato'); -- 23 120:6
UPDATE "LUZZI" SET text = 'Io sono per la pace; ma, non appena parlo, essi sono per la guerra.' WHERE "verseID" = 102678 AND (text = 'Io sono per la pace;ma, non appena parlo, essi sono per la guerra.'); -- 23 120:7
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Io alzo gli occhi ai monti... Donde mi verrà l''aiuto?' WHERE "verseID" = 102679 AND (text = 'Canto dei pellegrinaggi.' OR text = 'Canto dei pellegrinaggi. Io alzo gli occhi ai monti… Donde mi verrà l''aiuto?'); -- 23 121:1
UPDATE "LUZZI" SET text = 'Il mio aiuto vien dall''Eterno che ha fatto il cielo e la terra.' WHERE "verseID" = 102680 AND (text = 'Il mio aiuto vien dall''Eterno'); -- 23 121:2
UPDATE "LUZZI" SET text = 'Egli non permetterà che il tuo piè vacilli; colui che ti protegge non sonnecchierà.' WHERE "verseID" = 102681 AND (text = 'Egli non permetterà che il tuo piè vacilli;'); -- 23 121:3
UPDATE "LUZZI" SET text = 'Ecco, colui che protegge Israele non sonnecchierà né dormirà.' WHERE "verseID" = 102682 AND (text = 'Ecco, colui che protegge Israele'); -- 23 121:4
UPDATE "LUZZI" SET text = 'L''Eterno è colui che ti protegge; l''Eterno è la tua ombra; egli sta alla tua destra.' WHERE "verseID" = 102683 AND (text = 'L''Eterno è colui che ti protegge;'); -- 23 121:5
UPDATE "LUZZI" SET text = 'Di giorno il sole non ti colpirà, né la luna di notte.' WHERE "verseID" = 102684 AND (text = 'Di giorno il sole non ti colpirà,'); -- 23 121:6
UPDATE "LUZZI" SET text = 'L''Eterno ti proteggerà da ogni male; egli proteggerà l''anima tua.' WHERE "verseID" = 102685 AND (text = 'L''Eterno ti proteggerà da ogni male;'); -- 23 121:7
UPDATE "LUZZI" SET text = 'L''Eterno proteggerà il tuo uscire e il tuo entrare da ora in eterno.' WHERE "verseID" = 102686 AND (text = 'L''Eterno proteggerà il tuo uscire e il tuo entrareda ora in eterno.'); -- 23 121:8
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Di Davide. Io mi son rallegrato quando m''han detto: Andiamo alla casa dell''Eterno.' WHERE "verseID" = 102687 AND (text = 'Canto dei pellegrinaggi. Di Davide.' OR text = 'Canto dei pellegrinaggi. Di Davide. Io mi sono rallegrato quando m''han detto: Andiamo alla casa dell''Eterno.'); -- 23 122:1
UPDATE "LUZZI" SET text = 'I nostri passi si son fermati entro le tue porte, o Gerusalemme;' WHERE "verseID" = 102688 AND (text = 'I nostri passi si son fermati'); -- 23 122:2
UPDATE "LUZZI" SET text = 'Gerusalemme, che sei edificata, come una città ben compatta,' WHERE "verseID" = 102689 AND (text = 'Gerusalemme, che sei edificata,'); -- 23 122:3
UPDATE "LUZZI" SET text = 'dove salgono le tribù, le tribù dell''Eterno, secondo l''ingiunzione fattane ad Israele, per celebrare il nome dell''Eterno.' WHERE "verseID" = 102690 AND (text = 'dove salgono le tribù, le tribù dell''Eterno,'); -- 23 122:4
UPDATE "LUZZI" SET text = 'Perché quivi sono posti i troni per il giudizio, i troni della casa di Davide.' WHERE "verseID" = 102691 AND (text = 'Perché quivi sono posti i troni per il giudizio,'); -- 23 122:5
UPDATE "LUZZI" SET text = 'Pregate per la pace di Gerusalemme! Prosperino quelli che t''amano!' WHERE "verseID" = 102692 AND (text = 'Pregate per la pace di Gerusalemme!'); -- 23 122:6
UPDATE "LUZZI" SET text = 'Pace sia entro i tuoi bastioni, e tranquillità nei tuoi palazzi!' WHERE "verseID" = 102693 AND (text = 'Pace sia entro i tuoi bastioni,'); -- 23 122:7
UPDATE "LUZZI" SET text = 'Per amore dei miei fratelli e dei miei amici, io dirò adesso: Sia pace in te!' WHERE "verseID" = 102694 AND (text = 'Per amore dei miei fratelli e dei miei amici,'); -- 23 122:8
UPDATE "LUZZI" SET text = 'Per amore della casa dell''Eterno, dell''Iddio nostro, io procaccerò il tuo bene.' WHERE "verseID" = 102695 AND (text = 'Per amore della casa dell''Eterno, dell''Iddio nostro,io procaccerò il tuo bene.'); -- 23 122:9
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. A te io alzo gli occhi miei o tu che siedi nei cieli!' WHERE "verseID" = 102696 AND (text = 'Canto dei pellegrinaggi.'); -- 23 123:1
UPDATE "LUZZI" SET text = 'Ecco, come gli occhi dei servi guardano la mano del loro padrone, come gli occhi della serva guardano la mano della sua padrona,' WHERE "verseID" = 102697 AND (text = 'Ecco, come gli occhi dei servi'); -- 23 123:2
UPDATE "LUZZI" SET text = 'così gli occhi nostri guardano all''Eterno, all''Iddio nostro, finché egli abbia pietà di noi.' WHERE "verseID" = 102698 AND (text = 'così gli occhi nostri guardano all''Eterno, all''Iddio nostro,'); -- 23 123:3
UPDATE "LUZZI" SET text = 'Abbi pietà di noi, o Eterno, abbi pietà di noi, perché siamo più che sazi di disprezzo.' WHERE "verseID" = 102699 AND (text = 'Abbi pietà di noi, o Eterno, abbi pietà di noi,'); -- 23 123:4
UPDATE "LUZZI" SET text = 'L''anima nostra è più che sazia dello scherno della gente agiata e del disprezzo dei superbi.' WHERE "verseID" = 102700 AND (text = 'L''anima nostra è più che saziadello scherno della gente agiatae del disprezzo dei superbi.'); -- 23 123:5
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Di Davide. Se non fosse stato l''Eterno che fu per noi, lo dica pure ora Israele,' WHERE "verseID" = 102701 AND (text = 'Canto dei pellegrinaggi. Di Davide.'); -- 23 124:1
UPDATE "LUZZI" SET text = 'se non fosse stato l''Eterno che fu per noi, quando gli uomini si levarono contro noi,' WHERE "verseID" = 102702 AND (text = 'se non fosse stato l''Eterno che fu per noi,'); -- 23 124:2
UPDATE "LUZZI" SET text = 'allora ci avrebbero inghiottiti tutti vivi, quando l''ira loro ardeva contro noi;' WHERE "verseID" = 102703 AND (text = 'allora ci avrebbero inghiottiti tutti vivi,'); -- 23 124:3
UPDATE "LUZZI" SET text = 'allora le acque ci avrebbero sommerso, il torrente sarebbe passato sull''anima nostra;' WHERE "verseID" = 102704 AND (text = 'allora le acque ci avrebbero sommerso,'); -- 23 124:4
UPDATE "LUZZI" SET text = 'Benedetto sia l''Eterno che non ci ha dato in preda ai loro denti!' WHERE "verseID" = 102706 AND (text = 'Benedetto sia l''Eterno'); -- 23 124:6
UPDATE "LUZZI" SET text = 'L''anima nostra è scampata, come un uccello dal laccio degli uccellatori; il laccio è stato rotto, e noi siamo scampati.' WHERE "verseID" = 102707 AND (text = 'L''anima nostra è scampata,'); -- 23 124:7
UPDATE "LUZZI" SET text = 'Il nostro aiuto è nel nome dell''Eterno, che ha fatto il cielo e la terra.' WHERE "verseID" = 102708 AND (text = 'Il nostro aiuto è nel nome dell''Eterno,che ha fatto il cielo e la terra.'); -- 23 124:8
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Quelli che confidano nell''Eterno sono come il monte di Sion, che non può essere smosso, ma dimora in perpetuo.' WHERE "verseID" = 102709 AND (text = 'Canto dei pellegrinaggi.'); -- 23 125:1
UPDATE "LUZZI" SET text = 'Gerusalemme è circondata dai monti; e così l''Eterno circonda il suo popolo, da ora in perpetuo.' WHERE "verseID" = 102710 AND (text = 'Gerusalemme è circondata dai monti;'); -- 23 125:2
UPDATE "LUZZI" SET text = 'Poiché lo scettro dell''empietà non sempre rimarrà sulla eredità dei giusti, onde i giusti non mettan mano all''iniquità.' WHERE "verseID" = 102711 AND (text = 'Poiché lo scettro dell''empietà'); -- 23 125:3
UPDATE "LUZZI" SET text = 'O Eterno, fa'' del bene a quelli che son buoni, e a quelli che son retti nel loro cuore.' WHERE "verseID" = 102712 AND (text = 'O Eterno, fa'' del bene a quelli che son buoni,'); -- 23 125:4
UPDATE "LUZZI" SET text = 'Ma quanto a quelli che deviano per le loro vie tortuose, l''Eterno li farà andare con gli operatori d''iniquità. Pace sia sopra Israele.' WHERE "verseID" = 102713 AND (text = 'Ma quanto a quelli che deviano per le loro vie tortuose,l''Eterno li farà andare con gli operatori d''iniquità.Pace sia sopra Israele.'); -- 23 125:5
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Quando l''Eterno fece tornare i reduci di Sion, ci pareva di sognare.' WHERE "verseID" = 102714 AND (text = 'Canto dei pellegrinaggi.'); -- 23 126:1
UPDATE "LUZZI" SET text = 'Allora la nostra bocca fu piena di sorrisi, e la nostra lingua di canti d''allegrezza. Allora fu detto fra le nazioni: L''Eterno ha fatto cose grandi per loro.' WHERE "verseID" = 102715 AND (text = 'Allora la nostra bocca fu piena di sorrisi,'); -- 23 126:2
UPDATE "LUZZI" SET text = 'L''Eterno ha fatto cose grandi per noi, e noi siamo nella gioia.' WHERE "verseID" = 102716 AND (text = 'L''Eterno ha fatto cose grandi per noi,'); -- 23 126:3
UPDATE "LUZZI" SET text = 'O Eterno, fa'' tornare i nostri che sono in cattività, come tornano i rivi nella terra del Mezzodì.' WHERE "verseID" = 102717 AND (text = 'O Eterno, fa'' tornare i nostri che sono in cattività,'); -- 23 126:4
UPDATE "LUZZI" SET text = 'Ben va piangendo colui che porta il seme da spargere, ma tornerà con canti di gioia quando porterà i suoi covoni.' WHERE "verseID" = 102719 AND (text = 'Ben va piangendo colui che porta il seme da spargere,ma tornerà con canti di gioia quando porterà i suoi covoni.'); -- 23 126:6
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Di Salomone. Se l''Eterno non edifica la casa, invano vi si affaticano gli edificatori; se l''Eterno non guarda la città, invano vegliano le guardie.' WHERE "verseID" = 102720 AND (text = 'Canto dei pellegrinaggi. Di Salomone.'); -- 23 127:1
UPDATE "LUZZI" SET text = 'Invano vi levate di buon''ora e tardi andate a riposare e mangiate il pan di doglie; egli dà altrettanto ai suoi diletti, mentr''essi dormono.' WHERE "verseID" = 102721 AND (text = 'Invano vi levate di buon''ora e tardi andate a riposare'); -- 23 127:2
UPDATE "LUZZI" SET text = 'Ecco, i figliuoli sono un''eredità che viene dall''Eterno; il frutto del seno materno è un premio.' WHERE "verseID" = 102722 AND (text = 'Ecco, i figliuoli sono un''eredità che viene dall''Eterno;'); -- 23 127:3
UPDATE "LUZZI" SET text = 'Quali le frecce in man d''un prode, tali sono i figliuoli della giovinezza.' WHERE "verseID" = 102723 AND (text = 'Quali le frecce in man d''un prode,'); -- 23 127:4
UPDATE "LUZZI" SET text = 'Beati coloro che ne hanno il turcasso pieno! Non saranno confusi quando parleranno coi loro nemici alla porta.' WHERE "verseID" = 102724 AND (text = 'Beati coloro che ne hanno il turcasso pieno!Non saranno confusiquando parleranno coi loro nemici alla porta.'); -- 23 127:5
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Beato chiunque teme l''Eterno e cammina nelle sue vie!' WHERE "verseID" = 102725 AND (text = 'Canto dei pellegrinaggi.'); -- 23 128:1
UPDATE "LUZZI" SET text = 'Tu allora mangerai della fatica delle tue mani; sarai felice e prospererai.' WHERE "verseID" = 102726 AND (text = 'Tu allora mangerai della fatica delle tue mani;'); -- 23 128:2
UPDATE "LUZZI" SET text = 'La tua moglie sarà come una vigna fruttifera nell''interno della tua casa; i tuoi figliuoli, come piante d''ulivo intorno alla tua tavola.' WHERE "verseID" = 102727 AND (text = 'La tua moglie sarà come una vigna fruttifera'); -- 23 128:3
UPDATE "LUZZI" SET text = 'Ecco, così sarà benedetto l''uomo che teme l''Eterno.' WHERE "verseID" = 102728 AND (text = 'Ecco, così sarà benedetto l''uomo'); -- 23 128:4
UPDATE "LUZZI" SET text = 'L''Eterno ti benedica da Sion, e vedrai il bene di Gerusalemme tutti i giorni della tua vita,' WHERE "verseID" = 102729 AND (text = 'L''Eterno ti benedica da Sion,'); -- 23 128:5
UPDATE "LUZZI" SET text = 'e vedrai i figliuoli dei tuoi figliuoli. Pace sia sopra Israele.' WHERE "verseID" = 102730 AND (text = 'e vedrai i figliuoli dei tuoi figliuoli.Pace sia sopra Israele.'); -- 23 128:6
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Molte volte m''hanno oppresso dalla mia giovinezza! Lo dica pure Israele:' WHERE "verseID" = 102731 AND (text = 'Canto dei pellegrinaggi.'); -- 23 129:1
UPDATE "LUZZI" SET text = 'Molte volte m''hanno oppresso dalla mia giovinezza; eppure, non hanno potuto vincermi.' WHERE "verseID" = 102732 AND (text = 'Molte volte m''hanno oppresso dalla mia giovinezza;'); -- 23 129:2
UPDATE "LUZZI" SET text = 'Degli aratori hanno arato sul mio dorso, v''hanno tracciato i loro lunghi solchi.' WHERE "verseID" = 102733 AND (text = 'Degli aratori hanno arato sul mio dorso,'); -- 23 129:3
UPDATE "LUZZI" SET text = 'L''Eterno è giusto; egli ha tagliato le funi degli empi.' WHERE "verseID" = 102734 AND (text = 'L''Eterno è giusto;'); -- 23 129:4
UPDATE "LUZZI" SET text = 'Siano confusi e voltin le spalle tutti quelli che odiano Sion!' WHERE "verseID" = 102735 AND (text = 'Siano confusi e voltin le spalle'); -- 23 129:5
UPDATE "LUZZI" SET text = 'Siano come l''erba dei tetti, che secca prima di crescere!' WHERE "verseID" = 102736 AND (text = 'Siano come l''erba dei tetti,'); -- 23 129:6
UPDATE "LUZZI" SET text = 'Non se n''empie la mano il mietitore, né le braccia chi lega i covoni;' WHERE "verseID" = 102737 AND (text = 'Non se n''empie la mano il mietitore,'); -- 23 129:7
UPDATE "LUZZI" SET text = 'e i passanti non dicono: La benedizione dell''Eterno sia sopra voi; noi vi benediciamo nel nome dell''Eterno!' WHERE "verseID" = 102738 AND (text = 'e i passanti non dicono:La benedizione dell''Eterno sia sopra voi;noi vi benediciamo nel nome dell''Eterno!'); -- 23 129:8
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. O Eterno, io grido a te da luoghi profondi!' WHERE "verseID" = 102739 AND (text = 'Canto dei pellegrinaggi.'); -- 23 130:1
UPDATE "LUZZI" SET text = 'Signore, ascolta il mio grido; siano le tue orecchie attente alla voce delle mie supplicazioni!' WHERE "verseID" = 102740 AND (text = 'Signore, ascolta il mio grido;'); -- 23 130:2
UPDATE "LUZZI" SET text = 'O Eterno, se tu poni mente alle iniquità, Signore, chi potrà reggere?' WHERE "verseID" = 102741 AND (text = 'O Eterno, se tu poni mente alle iniquità,'); -- 23 130:3
UPDATE "LUZZI" SET text = 'Ma presso te v''è perdono affinché tu sia temuto.' WHERE "verseID" = 102742 AND (text = 'Ma presso te v''è perdono'); -- 23 130:4
UPDATE "LUZZI" SET text = 'Io aspetto l''Eterno, l''anima mia l''aspetta, ed io spero nella sua parola.' WHERE "verseID" = 102743 AND (text = 'Io aspetto l''Eterno, l''anima mia l''aspetta,'); -- 23 130:5
UPDATE "LUZZI" SET text = 'L''anima mia anela al Signore più che le guardie non anelino al mattino, più che le guardie al mattino.' WHERE "verseID" = 102744 AND (text = 'L''anima mia anela al Signore'); -- 23 130:6
UPDATE "LUZZI" SET text = 'O Israele, spera nell''Eterno, poiché presso l''Eterno è benignità e presso di lui è abbondanza di redenzione.' WHERE "verseID" = 102745 AND (text = 'O Israele, spera nell''Eterno,'); -- 23 130:7
UPDATE "LUZZI" SET text = 'Ed egli redimerà Israele da tutte le sue iniquità.' WHERE "verseID" = 102746 AND (text = 'Ed egli redimerà Israeleda tutte le sue iniquità.'); -- 23 130:8
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Di Davide. O Eterno, il mio cuore non è gonfio di superbia, e i miei occhi non sono altèri; non attendo a cose troppo grandi e troppo alte per me.' WHERE "verseID" = 102747 AND (text = 'Canto dei pellegrinaggi. Di Davide.' OR text = 'Canto dei pellegrinaggi. Di Davide. O Eterno, il mio cuore non è gonfio li superbia, e i miei occhi non sono alteri; non attendo a cose troppo grandi e troppo alte per me.'); -- 23 131:1
UPDATE "LUZZI" SET text = 'In verità ho calmata e quietata l''anima mia com''è quieto il bimbo divezzato sul seno di sua madre. Quale è il bimbo divezzato, tale è in me l''anima mia.' WHERE "verseID" = 102748 AND (text = 'In verità ho calmata e quietata l''anima mia' OR text = 'In verità ho calmata e quietata l''anima mia, com''è quieto il bimbo divezzato sul seno di sua madre. Quale è il bimbo divezzato, tale è in me l''anima mia.'); -- 23 131:2
UPDATE "LUZZI" SET text = 'O Israele, spera nell''Eterno, da ora in perpetuo.' WHERE "verseID" = 102749 AND (text = 'O Israele, spera nell''Eterno,da ora in perpetuo.'); -- 23 131:3
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Ricordati, o Eterno, a favor di Davide, di tutte le sue fatiche:' WHERE "verseID" = 102750 AND (text = 'Canto dei pellegrinaggi.'); -- 23 132:1
UPDATE "LUZZI" SET text = 'com''egli giurò all''Eterno e fece voto al Potente di Giacobbe, dicendo:' WHERE "verseID" = 102751 AND (text = 'com''egli giurò all''Eterno'); -- 23 132:2
UPDATE "LUZZI" SET text = 'Certo, non entrerò nella tenda della mia casa, né salirò sul tetto ove mi corico,' WHERE "verseID" = 102752 AND (text = 'Certo, non entrerò nella tenda della mia casa,' OR text = 'Certo, non entrerò nella tenda della mia casa, né salirò sul letto ove mi corico,'); -- 23 132:3
UPDATE "LUZZI" SET text = 'non darò sonno ai miei occhi, né riposo alle mie palpebre,' WHERE "verseID" = 102753 AND (text = 'non darò sonno ai miei occhi,'); -- 23 132:4
UPDATE "LUZZI" SET text = 'finché abbia trovato un luogo per l''Eterno, una dimora per il Potente di Giacobbe.' WHERE "verseID" = 102754 AND (text = 'finché abbia trovato un luogo per l''Eterno,'); -- 23 132:5
UPDATE "LUZZI" SET text = 'Ecco abbiamo udito che l''Arca era in Efrata; l''abbiam trovata nei campi di Jaar.' WHERE "verseID" = 102755 AND (text = 'Ecco abbiamo udito che l''Arca era in Efrata;'); -- 23 132:6
UPDATE "LUZZI" SET text = 'Andiamo nella dimora dell''Eterno, adoriamo dinanzi allo sgabello de'' suoi piedi!' WHERE "verseID" = 102756 AND (text = 'Andiamo nella dimora dell''Eterno,'); -- 23 132:7
UPDATE "LUZZI" SET text = 'Lèvati, o Eterno, vieni al luogo del tuo riposo, tu e l''Arca della tua forza.' WHERE "verseID" = 102757 AND (text = 'Lèvati, o Eterno, vieni al luogo del tuo riposo,'); -- 23 132:8
UPDATE "LUZZI" SET text = 'I tuoi sacerdoti siano rivestiti di giustizia, e giubilino i tuoi fedeli.' WHERE "verseID" = 102758 AND (text = 'I tuoi sacerdoti siano rivestiti di giustizia,'); -- 23 132:9
UPDATE "LUZZI" SET text = 'Per amor di Davide tuo servitore, non respingere la faccia del tuo unto.' WHERE "verseID" = 102759 AND (text = 'Per amor di Davide tuo servitore,'); -- 23 132:10
UPDATE "LUZZI" SET text = 'L''Eterno ha fatto a Davide questo giuramento di verità, e non lo revocherà: Io metterò sul tuo trono un frutto delle tue viscere.' WHERE "verseID" = 102760 AND (text = 'L''Eterno ha fatto a Davide questo giuramento di verità,'); -- 23 132:11
UPDATE "LUZZI" SET text = 'Se i tuoi figliuoli osserveranno il mio patto e la mia testimonianza che insegnerò loro, anche i loro figliuoli sederanno sul tuo trono in perpetuo.' WHERE "verseID" = 102761 AND (text = 'Se i tuoi figliuoli osserveranno il mio patto'); -- 23 132:12
UPDATE "LUZZI" SET text = 'Poiché l''Eterno ha scelto Sion, l''ha desiderata per sua dimora.' WHERE "verseID" = 102762 AND (text = 'Poiché l''Eterno ha scelto Sion,'); -- 23 132:13
UPDATE "LUZZI" SET text = 'Questo è il mio luogo di riposo in eterno; qui abiterò, perché l''ho desiderata.' WHERE "verseID" = 102763 AND (text = 'Questo è il mio luogo di riposo in eterno;'); -- 23 132:14
UPDATE "LUZZI" SET text = 'Io benedirò largamente i suoi viveri, sazierò di pane i suoi poveri.' WHERE "verseID" = 102764 AND (text = 'Io benedirò largamente i suoi viveri,'); -- 23 132:15
UPDATE "LUZZI" SET text = 'I suoi sacerdoti li vestirò di salvezza, e i suoi fedeli giubileranno con gran gioia.' WHERE "verseID" = 102765 AND (text = 'I suoi sacerdoti li vestirò di salvezza,'); -- 23 132:16
UPDATE "LUZZI" SET text = 'Quivi farò crescere la potenza di Davide, e quivi terrò accesa una lampada al mio unto.' WHERE "verseID" = 102766 AND (text = 'Quivi farò crescere la potenza di Davide,'); -- 23 132:17
UPDATE "LUZZI" SET text = 'I suoi nemici li vestirò di vergogna, ma su di lui fiorirà la sua corona.' WHERE "verseID" = 102767 AND (text = 'I suoi nemici li vestirò di vergogna,ma su di lui fiorirà la sua corona.'); -- 23 132:18
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Di Davide. Ecco, quant''è buono e quant''è piacevole che fratelli dimorino assieme!' WHERE "verseID" = 102768 AND (text = 'Canto dei pellegrinaggi. Di Davide.'); -- 23 133:1
UPDATE "LUZZI" SET text = 'È come l''olio squisito che, sparso sul capo, scende sulla barba, sulla barba d''Aaronne, che scende fino all''orlo de'' suoi vestimenti;' WHERE "verseID" = 102769 AND (text = 'È come l''olio squisito che, sparso sul capo,'); -- 23 133:2
UPDATE "LUZZI" SET text = 'è come la rugiada dell''Hermon, che scende sui monti di Sion; poiché quivi l''Eterno ha ordinato che sia la benedizione, la vita in eterno.' WHERE "verseID" = 102770 AND (text = 'è come la rugiada dell''Hermon,che scende sui monti di Sion;poiché quivi l''Eterno ha ordinato che sia la benedizione,la vita in eterno.'); -- 23 133:3
UPDATE "LUZZI" SET text = 'Canto dei pellegrinaggi. Ecco, benedite l''Eterno, voi tutti servitori dell''Eterno, che state durante la notte nella casa dell''Eterno!' WHERE "verseID" = 102771 AND (text = 'Canto dei pellegrinaggi.'); -- 23 134:1
UPDATE "LUZZI" SET text = 'Levate le vostre mani verso il santuario, e benedite l''Eterno!' WHERE "verseID" = 102772 AND (text = 'Levate le vostre mani verso il santuario,'); -- 23 134:2
UPDATE "LUZZI" SET text = 'L''Eterno ti benedica da Sion, egli che ha fatto il cielo e la terra.' WHERE "verseID" = 102773 AND (text = 'L''Eterno ti benedica da Sion,egli che ha fatto il cielo e la terra.'); -- 23 134:3
UPDATE "LUZZI" SET text = 'Alleluia. Lodate il nome dell''Eterno. Lodatelo, o servi dell''Eterno,' WHERE "verseID" = 102774 AND (text = 'Alleluia.'); -- 23 135:1
UPDATE "LUZZI" SET text = 'che state nella casa dell''Eterno, nei cortili della casa del nostro Dio.' WHERE "verseID" = 102775 AND (text = 'che state nella casa dell''Eterno,'); -- 23 135:2
UPDATE "LUZZI" SET text = 'Lodate l''Eterno, perché l''Eterno è buono; salmeggiate al suo nome, perché è amabile.' WHERE "verseID" = 102776 AND (text = 'Lodate l''Eterno, perché l''Eterno è buono;'); -- 23 135:3
UPDATE "LUZZI" SET text = 'Poiché l''Eterno ha scelto per sé Giacobbe, ha scelto Israele per suo speciale possesso.' WHERE "verseID" = 102777 AND (text = 'Poiché l''Eterno ha scelto per sé Giacobbe,'); -- 23 135:4
UPDATE "LUZZI" SET text = 'Sì, io conosco che l''Eterno è grande e che il nostro Signore è al disopra di tutti gli dèi.' WHERE "verseID" = 102778 AND (text = 'Sì, io conosco che l''Eterno è grande' OR text = 'Sì, io conosco che l''Eterno è grande, e che il nostro Signore è al disopra di tutti gli dèi.'); -- 23 135:5
UPDATE "LUZZI" SET text = 'L''Eterno fa tutto ciò che gli piace, in cielo e in terra, nei mari e in tutti gli abissi.' WHERE "verseID" = 102779 AND (text = 'L''Eterno fa tutto ciò che gli piace,'); -- 23 135:6
UPDATE "LUZZI" SET text = 'Egli fa salire i vapori dalle estremità della terra, fa i lampi per la pioggia, fa uscire il vento dai suoi tesori.' WHERE "verseID" = 102780 AND (text = 'Egli fa salire i vapori dalle estremità della terra,'); -- 23 135:7
UPDATE "LUZZI" SET text = 'Egli percosse i primogeniti d''Egitto, così degli uomini come degli animali.' WHERE "verseID" = 102781 AND (text = 'Egli percosse i primogeniti d''Egitto,'); -- 23 135:8
UPDATE "LUZZI" SET text = 'Mandò segni e prodigi in mezzo a te, o Egitto, su Faraone e su tutti i suoi servitori.' WHERE "verseID" = 102782 AND (text = 'Mandò segni e prodigi in mezzo a te, o Egitto,'); -- 23 135:9
UPDATE "LUZZI" SET text = 'Egli percosse grandi nazioni, e uccise re potenti:' WHERE "verseID" = 102783 AND (text = 'Egli percosse grandi nazioni,'); -- 23 135:10
UPDATE "LUZZI" SET text = 'Sihon, re degli Amorei, e Og, re di Basan, e tutti i regni di Canaan.' WHERE "verseID" = 102784 AND (text = 'Sihon, re degli Amorei,'); -- 23 135:11
UPDATE "LUZZI" SET text = 'E dette il loro paese in eredità, in eredità a Israele, suo popolo.' WHERE "verseID" = 102785 AND (text = 'E dette il loro paese in eredità,'); -- 23 135:12
UPDATE "LUZZI" SET text = 'O Eterno, il tuo nome dura in perpetuo; la memoria di te, o Eterno, dura per ogni età.' WHERE "verseID" = 102786 AND (text = 'O Eterno, il tuo nome dura in perpetuo;'); -- 23 135:13
UPDATE "LUZZI" SET text = 'Poiché l''Eterno farà giustizia al suo popolo, ed avrà compassione dei suoi servitori.' WHERE "verseID" = 102787 AND (text = 'Poiché l''Eterno farà giustizia al suo popolo,'); -- 23 135:14
UPDATE "LUZZI" SET text = 'Gl''idoli delle nazioni sono argento e oro, opera di mano d''uomo.' WHERE "verseID" = 102788 AND (text = 'Gl''idoli delle nazioni sono argento e oro,'); -- 23 135:15
UPDATE "LUZZI" SET text = 'Hanno bocca e non parlano; hanno occhi e non vedono;' WHERE "verseID" = 102789 AND (text = 'Hanno bocca e non parlano;'); -- 23 135:16
UPDATE "LUZZI" SET text = 'hanno orecchi e non odono, e non hanno fiato alcuno nella loro bocca.' WHERE "verseID" = 102790 AND (text = 'hanno orecchi e non odono,'); -- 23 135:17
UPDATE "LUZZI" SET text = 'Simili ad essi siano quelli che li fanno, tutti quelli che in essi confidano.' WHERE "verseID" = 102791 AND (text = 'Simili ad essi siano quelli che li fanno,'); -- 23 135:18
UPDATE "LUZZI" SET text = 'Casa d''Israele, benedite l''Eterno! Casa d''Aaronne, benedite l''Eterno!' WHERE "verseID" = 102792 AND (text = 'Casa d''Israele, benedite l''Eterno!'); -- 23 135:19
UPDATE "LUZZI" SET text = 'Casa di Levi, benedite l''Eterno! Voi che temete l''Eterno, benedite l''Eterno!' WHERE "verseID" = 102793 AND (text = 'Casa di Levi, benedite l''Eterno!'); -- 23 135:20
UPDATE "LUZZI" SET text = 'Sia benedetto da Sion l''Eterno, che abita in Gerusalemme! Alleluia.' WHERE "verseID" = 102794 AND (text = 'Sia benedetto da Sion l''Eterno,che abita in Gerusalemme!Alleluia.'); -- 23 135:21
UPDATE "LUZZI" SET text = 'Celebrate l''Eterno, perché egli è buono, perché la sua benignità dura in eterno.' WHERE "verseID" = 102795 AND (text = 'Celebrate l''Eterno, perché egli è buono,'); -- 23 136:1
UPDATE "LUZZI" SET text = 'Celebrate l''Iddio degli dèi, perché la sua benignità dura in eterno.' WHERE "verseID" = 102796 AND (text = 'Celebrate l''Iddio degli dèi,'); -- 23 136:2
UPDATE "LUZZI" SET text = 'Celebrate il Signor dei signori, perché la sua benignità dura in eterno.' WHERE "verseID" = 102797 AND (text = 'Celebrate il Signor dei signori,'); -- 23 136:3
UPDATE "LUZZI" SET text = 'Colui che solo opera grandi maraviglie, perché la sua benignità dura in eterno.' WHERE "verseID" = 102798 AND (text = 'Colui che solo opera grandi maraviglie,'); -- 23 136:4
UPDATE "LUZZI" SET text = 'Colui che ha fatto con intendimento i cieli, perché la sua benignità dura in eterno.' WHERE "verseID" = 102799 AND (text = 'Colui che ha fatto con intendimento i cieli,'); -- 23 136:5
UPDATE "LUZZI" SET text = 'Colui che ha steso la terra sopra le acque, perché la sua benignità dura in eterno.' WHERE "verseID" = 102800 AND (text = 'Colui che ha steso la terra sopra le acque,'); -- 23 136:6
UPDATE "LUZZI" SET text = 'Colui che ha fatto i grandi luminari, perché la sua benignità dura in eterno:' WHERE "verseID" = 102801 AND (text = 'Colui che ha fatto i grandi luminari,'); -- 23 136:7
UPDATE "LUZZI" SET text = 'il sole per regnare sul giorno, perché la sua benignità dura in eterno;' WHERE "verseID" = 102802 AND (text = 'il sole per regnare sul giorno,'); -- 23 136:8
UPDATE "LUZZI" SET text = 'e la luna e le stelle per regnare sulla notte, perché la sua benignità dura in eterno.' WHERE "verseID" = 102803 AND (text = 'e la luna e le stelle per regnare sulla notte,'); -- 23 136:9
UPDATE "LUZZI" SET text = 'Colui che percosse gli Egizi nei loro primogeniti, perché la sua benignità dura in eterno;' WHERE "verseID" = 102804 AND (text = 'Colui che percosse gli Egizi nei loro primogeniti,'); -- 23 136:10
UPDATE "LUZZI" SET text = 'e trasse fuori Israele dal mezzo di loro, perché la sua benignità dura in eterno;' WHERE "verseID" = 102805 AND (text = 'e trasse fuori Israele dal mezzo di loro,'); -- 23 136:11
UPDATE "LUZZI" SET text = 'con mano potente e con braccio steso, perché la sua benignità dura in eterno.' WHERE "verseID" = 102806 AND (text = 'con mano potente e con braccio steso,'); -- 23 136:12
UPDATE "LUZZI" SET text = 'Colui che divise il Mar rosso in due, perché la sua benignità dura in eterno;' WHERE "verseID" = 102807 AND (text = 'Colui che divise il Mar rosso in due,'); -- 23 136:13
UPDATE "LUZZI" SET text = 'e fece passare Israele in mezzo ad esso, perché la sua benignità dura in eterno;' WHERE "verseID" = 102808 AND (text = 'e fece passare Israele in mezzo ad esso,'); -- 23 136:14
UPDATE "LUZZI" SET text = 'e travolse Faraone e il suo esercito nel Mar Rosso, perché la sua benignità dura in eterno.' WHERE "verseID" = 102809 AND (text = 'e travolse Faraone e il suo esercito nel Mar Rosso,'); -- 23 136:15
UPDATE "LUZZI" SET text = 'Colui che condusse il suo popolo attraverso il deserto, perché la sua benignità dura in eterno.' WHERE "verseID" = 102810 AND (text = 'Colui che condusse il suo popolo attraverso il deserto,'); -- 23 136:16
UPDATE "LUZZI" SET text = 'Colui che percosse re grandi, perché la sua benignità dura in eterno;' WHERE "verseID" = 102811 AND (text = 'Colui che percosse re grandi,'); -- 23 136:17
UPDATE "LUZZI" SET text = 'e uccise re potenti, perché la sua benignità dura in eterno:' WHERE "verseID" = 102812 AND (text = 'e uccise re potenti,'); -- 23 136:18
UPDATE "LUZZI" SET text = 'Sihon, re degli Amorei, perché la sua benignità dura in eterno,' WHERE "verseID" = 102813 AND (text = 'Sihon, re degli Amorei,'); -- 23 136:19
UPDATE "LUZZI" SET text = 'e Og, re di Basan, perché la sua benignità dura in eterno;' WHERE "verseID" = 102814 AND (text = 'e Og, re di Basan,'); -- 23 136:20
UPDATE "LUZZI" SET text = 'e dette il loro paese in eredità, perché la sua benignità dura in eterno,' WHERE "verseID" = 102815 AND (text = 'e dette il loro paese in eredità,'); -- 23 136:21
UPDATE "LUZZI" SET text = 'in eredità ad Israele, suo servitore, perché la sua benignità dura in eterno.' WHERE "verseID" = 102816 AND (text = 'in eredità ad Israele, suo servitore,'); -- 23 136:22
UPDATE "LUZZI" SET text = 'Colui che si ricordò di noi nel nostro abbassamento, perché la sua benignità dura in eterno;' WHERE "verseID" = 102817 AND (text = 'Colui che si ricordò di noi nel nostro abbassamento,'); -- 23 136:23
UPDATE "LUZZI" SET text = 'e ci ha liberati dai nostri nemici, perché la sua benignità dura in eterno.' WHERE "verseID" = 102818 AND (text = 'e ci ha liberati dai nostri nemici,'); -- 23 136:24
UPDATE "LUZZI" SET text = 'Colui che dà il cibo ad ogni carne, perché la sua benignità dura in eterno.' WHERE "verseID" = 102819 AND (text = 'Colui che dà il cibo ad ogni carne,'); -- 23 136:25
UPDATE "LUZZI" SET text = 'Celebrate l''Iddio dei cieli, perché la sua benignità dura in eterno.' WHERE "verseID" = 102820 AND (text = 'Celebrate l''Iddio dei cieli,perché la sua benignità dura in eterno.'); -- 23 136:26
UPDATE "LUZZI" SET text = 'Là presso i fiumi di Babilonia, sedevamo ed anche piangevamo ricordandoci di Sion.' WHERE "verseID" = 102821 AND (text = 'Là presso i fiumi di Babilonia,'); -- 23 137:1
UPDATE "LUZZI" SET text = 'Ai salici delle sponde avevamo appese le nostre cetre.' WHERE "verseID" = 102822 AND (text = 'Ai salici delle sponde'); -- 23 137:2
UPDATE "LUZZI" SET text = 'Poiché là quelli che ci avevan menati in cattività ci chiedevano dei canti, e quelli che ci predavano, delle canzoni d''allegrezza, dicendo: Cantateci delle canzoni di Sion!' WHERE "verseID" = 102823 AND (text = 'Poiché là quelli che ci avevan menati in cattività' OR text = 'Poiché là quelli che ci avevan menati in cattività ci chiedevano dei canti, quelli che ci predavano, delle canzoni d''allegrezza, dicendo: Cantateci delle canzoni di Sion!'); -- 23 137:3
UPDATE "LUZZI" SET text = 'Come potremmo noi cantare le canzoni dell''Eterno in terra straniera?' WHERE "verseID" = 102824 AND (text = 'Come potremmo noi cantare le canzoni dell''Eterno'); -- 23 137:4
UPDATE "LUZZI" SET text = 'Se io ti dimentico, o Gerusalemme, dimentichi la mia destra e le sue funzioni,' WHERE "verseID" = 102825 AND (text = 'Se io ti dimentico, o Gerusalemme,' OR text = 'Se io ti dimentico, o Gerusalemme, dimentichi la mia destra le sue funzioni,'); -- 23 137:5
UPDATE "LUZZI" SET text = 'resti la mia lingua attaccata al palato se io non mi ricordo di te, se non metto Gerusalemme al disopra d''ogni mia allegrezza.' WHERE "verseID" = 102826 AND (text = 'resti la mia lingua attaccata al palato'); -- 23 137:6
UPDATE "LUZZI" SET text = 'Ricordati, o Eterno, dei figliuoli di Edom, che nel giorno di Gerusalemme dicevano: Spianatela, spianatela fin dalle fondamenta!' WHERE "verseID" = 102827 AND (text = 'Ricordati, o Eterno, dei figliuoli di Edom,' OR text = 'Ricordati, o Eterno, dei figliuoli di Edom, che nel giorno di Gerusalemme dicevano: Spianatela, spianatela, fin dalle fondamenta!'); -- 23 137:7
UPDATE "LUZZI" SET text = 'O figliuola di Babilonia, che devi esser distrutta, beato chi ti darà la retribuzione del male che ci hai fatto!' WHERE "verseID" = 102828 AND (text = 'O figliuola di Babilonia, che devi esser distrutta,' OR text = 'O figliuola di Babilonia, che devi esser distrutta, beati chi ti darà la retribuzione del male che ci hai fatto!'); -- 23 137:8
UPDATE "LUZZI" SET text = 'Beato chi piglierà i tuoi piccoli bambini e li sbatterà contro la roccia!' WHERE "verseID" = 102829 AND (text = 'Beato chi piglierà i tuoi piccoli bambinie li sbatterà contro la roccia!'); -- 23 137:9
UPDATE "LUZZI" SET text = 'Salmo di Davide. Io ti celebrerò con tutto il mio cuore, dinanzi agli dèi salmeggerò a te.' WHERE "verseID" = 102830 AND (text = 'Salmo di Davide.'); -- 23 138:1
UPDATE "LUZZI" SET text = 'Adorerò vòlto al tempio della tua santità, e celebrerò il tuo nome per la tua benignità e per la tua fedeltà; poiché tu hai magnificato la tua parola oltre ogni tua rinomanza.' WHERE "verseID" = 102831 AND (text = 'Adorerò vòlto al tempio della tua santità,' OR text = 'Adorerò vòlto al tempio della tua santità, celebrerò il tuo nome per la tua benignità e per la tua fedeltà; poiché tu hai magnificato la tua parola oltre ogni tua rinomanza.'); -- 23 138:2
UPDATE "LUZZI" SET text = 'Nel giorno che ho gridato a te, tu m''hai risposto, m''hai riempito di coraggio, dando forza all''anima mia.' WHERE "verseID" = 102832 AND (text = 'Nel giorno che ho gridato a te, tu m''hai risposto,'); -- 23 138:3
UPDATE "LUZZI" SET text = 'Tutti i re della terra ti celebreranno, o Eterno, quando avranno udito le parole della tua bocca;' WHERE "verseID" = 102833 AND (text = 'Tutti i re della terra ti celebreranno, o Eterno,'); -- 23 138:4
UPDATE "LUZZI" SET text = 'e canteranno le vie dell''Eterno, perché grande è la gloria dell''Eterno.' WHERE "verseID" = 102834 AND (text = 'e canteranno le vie dell''Eterno,'); -- 23 138:5
UPDATE "LUZZI" SET text = 'Sì, eccelso è l''Eterno, eppure ha riguardo agli umili, e da lungi conosce l''altero.' WHERE "verseID" = 102835 AND (text = 'Sì, eccelso è l''Eterno, eppure ha riguardo agli umili,'); -- 23 138:6
UPDATE "LUZZI" SET text = 'Se io cammino in mezzo alla distretta, tu mi ridai la vita; tu stendi la mano contro l''ira dei miei nemici, e la tua destra mi salva.' WHERE "verseID" = 102836 AND (text = 'Se io cammino in mezzo alla distretta,'); -- 23 138:7
UPDATE "LUZZI" SET text = 'L''Eterno compirà in mio favore l''opera sua; la tua benignità, o Eterno, dura in perpetuo; non abbandonare le opere delle tue mani.' WHERE "verseID" = 102837 AND (text = 'L''Eterno compirà in mio favore l''opera sua;la tua benignità, o Eterno, dura in perpetuo;non abbandonare le opere delle tue mani.'); -- 23 138:8
UPDATE "LUZZI" SET text = 'Per il capo de'' musici. Salmo di Davide. O Eterno tu m''hai investigato e mi conosci.' WHERE "verseID" = 102838 AND (text = 'Per il capo de'' musici. Salmo di Davide.'); -- 23 139:1
UPDATE "LUZZI" SET text = 'Tu sai quando mi seggo e quando m''alzo, tu intendi da lungi il mio pensiero.' WHERE "verseID" = 102839 AND (text = 'Tu sai quando mi seggo e quando m''alzo,'); -- 23 139:2
UPDATE "LUZZI" SET text = 'Tu mi scruti quando cammino e quando mi giaccio, e conosci a fondo tutte le mie vie.' WHERE "verseID" = 102840 AND (text = 'Tu mi scruti quando cammino e quando mi giaccio,'); -- 23 139:3
UPDATE "LUZZI" SET text = 'Poiché la parola non è ancora sulla mia lingua, che tu, o Eterno, già la conosci appieno.' WHERE "verseID" = 102841 AND (text = 'Poiché la parola non è ancora sulla mia lingua,'); -- 23 139:4
UPDATE "LUZZI" SET text = 'Tu mi stringi di dietro e davanti, e mi metti la mano addosso.' WHERE "verseID" = 102842 AND (text = 'Tu mi stringi di dietro e davanti,'); -- 23 139:5
UPDATE "LUZZI" SET text = 'Una tal conoscenza è troppo maravigliosa per me, tanto alta, che io non posso arrivarci.' WHERE "verseID" = 102843 AND (text = 'Una tal conoscenza è troppo maravigliosa per me,'); -- 23 139:6
UPDATE "LUZZI" SET text = 'Dove me ne andrò lungi dal tuo spirito? e dove fuggirò dal tuo cospetto?' WHERE "verseID" = 102844 AND (text = 'Dove me ne andrò lungi dal tuo spirito?'); -- 23 139:7
UPDATE "LUZZI" SET text = 'Se salgo in cielo tu vi sei; se mi metto a giacere nel soggiorno dei morti, eccoti quivi.' WHERE "verseID" = 102845 AND (text = 'Se salgo in cielo tu vi sei;'); -- 23 139:8
UPDATE "LUZZI" SET text = 'Se prendo le ali dell''alba e vo a dimorare all''estremità del mare,' WHERE "verseID" = 102846 AND (text = 'Se prendo le ali dell''alba'); -- 23 139:9
UPDATE "LUZZI" SET text = 'anche quivi mi condurrà la tua mano, e la tua destra mi afferrerà.' WHERE "verseID" = 102847 AND (text = 'anche quivi mi condurrà la tua mano,'); -- 23 139:10
UPDATE "LUZZI" SET text = 'Se dico: Certo le tenebre mi nasconderanno, e la luce diventerà notte intorno a me,' WHERE "verseID" = 102848 AND (text = 'Se dico: Certo le tenebre mi nasconderanno,'); -- 23 139:11
UPDATE "LUZZI" SET text = 'le tenebre stesse non possono nasconderti nulla, e la notte risplende come il giorno; le tenebre e la luce son tutt''uno per te.' WHERE "verseID" = 102849 AND (text = 'le tenebre stesse non possono nasconderti nulla,'); -- 23 139:12
UPDATE "LUZZI" SET text = 'Poiché sei tu che hai formato le mie reni, che m''hai intessuto nel seno di mia madre.' WHERE "verseID" = 102850 AND (text = 'Poiché sei tu che hai formato le mie reni,'); -- 23 139:13
UPDATE "LUZZI" SET text = 'Io ti celebrerò, perché sono stato fatto in modo maraviglioso, stupendo. Maravigliose sono le tue opere, e l''anima mia lo sa molto bene.' WHERE "verseID" = 102851 AND (text = 'Io ti celebrerò, perché sono stato fatto'); -- 23 139:14
UPDATE "LUZZI" SET text = 'Le mie ossa non t''erano nascoste, quand''io fui formato in occulto e tessuto nelle parti più basse della terra.' WHERE "verseID" = 102852 AND (text = 'Le mie ossa non t''erano nascoste,'); -- 23 139:15
UPDATE "LUZZI" SET text = 'I tuoi occhi videro la massa informe del mio corpo; e nel tuo libro erano tutti scritti i giorni che m''eran destinati, quando nessun d''essi era sorto ancora.' WHERE "verseID" = 102853 AND (text = 'I tuoi occhi videro la massa informe del mio corpo;'); -- 23 139:16
UPDATE "LUZZI" SET text = 'Oh quanto mi son preziosi i tuoi pensieri, o Dio! Quant''è grande la somma d''essi!' WHERE "verseID" = 102854 AND (text = 'Oh quanto mi son preziosi i tuoi pensieri, o Dio!'); -- 23 139:17
UPDATE "LUZZI" SET text = 'Se li voglio contare, son più numerosi della rena; quando mi sveglio sono ancora con te.' WHERE "verseID" = 102855 AND (text = 'Se li voglio contare, son più numerosi della rena;'); -- 23 139:18
UPDATE "LUZZI" SET text = 'Certo, tu ucciderai l''empio, o Dio; perciò dipartitevi da me, uomini di sangue.' WHERE "verseID" = 102856 AND (text = 'Certo, tu ucciderai l''empio, o Dio;'); -- 23 139:19
UPDATE "LUZZI" SET text = 'Essi parlano contro di te malvagiamente; i tuoi nemici usano il tuo nome a sostener la menzogna.' WHERE "verseID" = 102857 AND (text = 'Essi parlano contro di te malvagiamente;'); -- 23 139:20
UPDATE "LUZZI" SET text = 'O Eterno, non odio io quelli che t''odiano? E non aborro io quelli che si levano contro di te?' WHERE "verseID" = 102858 AND (text = 'O Eterno, non odio io quelli che t''odiano?'); -- 23 139:21
UPDATE "LUZZI" SET text = 'Io li odio di un odio perfetto; li tengo per miei nemici.' WHERE "verseID" = 102859 AND (text = 'Io li odio di un odio perfetto;'); -- 23 139:22
UPDATE "LUZZI" SET text = 'Investigami, o Dio, e conosci il mio cuore. Provami, e conosci i miei pensieri.' WHERE "verseID" = 102860 AND (text = 'Investigami, o Dio, e conosci il mio cuore.'); -- 23 139:23
UPDATE "LUZZI" SET text = 'E vedi se v''è in me qualche via iniqua, e guidami per la via eterna.' WHERE "verseID" = 102861 AND (text = 'E vedi se v''è in me qualche via iniqua,e guidami per la via eterna.'); -- 23 139:24
UPDATE "LUZZI" SET text = 'Per il capo de'' musici. Salmo di Davide. Liberami, o Eterno, dall''uomo malvagio; guardami dall''uomo violento,' WHERE "verseID" = 102862 AND (text = 'Per il capo de'' musici. Salmo di Davide.'); -- 23 140:1
UPDATE "LUZZI" SET text = 'i quali macchinano delle malvagità nel loro cuore, e continuamente muovono guerre.' WHERE "verseID" = 102863 AND (text = 'i quali macchinano delle malvagità nel loro cuore,'); -- 23 140:2
UPDATE "LUZZI" SET text = 'Aguzzano la loro lingua come il serpente, hanno un veleno d''aspide sotto le loro labbra. Sela.' WHERE "verseID" = 102864 AND (text = 'Aguzzano la loro lingua come il serpente,'); -- 23 140:3
UPDATE "LUZZI" SET text = 'Preservami, o Eterno, dalle mani dell''empio, guardami dall''uomo violento, i quali han macchinato di farmi cadere.' WHERE "verseID" = 102865 AND (text = 'Preservami, o Eterno, dalle mani dell''empio,'); -- 23 140:4
UPDATE "LUZZI" SET text = 'I superbi hanno nascosto per me un laccio e delle funi, m''hanno teso una rete sull''orlo del sentiero, m''hanno posto degli agguati. Sela.' WHERE "verseID" = 102866 AND (text = 'I superbi hanno nascosto per me un laccio e delle funi,'); -- 23 140:5
UPDATE "LUZZI" SET text = 'Io ho detto all''Eterno: Tu sei il mio Dio; porgi l''orecchio, o Eterno, al grido delle mie supplicazioni.' WHERE "verseID" = 102867 AND (text = 'Io ho detto all''Eterno: Tu sei il mio Dio;'); -- 23 140:6
UPDATE "LUZZI" SET text = 'O Eterno, o Signore, che sei la forza della mia salvezza, tu hai coperto il mio capo nel giorno dell''armi.' WHERE "verseID" = 102868 AND (text = 'O Eterno, o Signore, che sei la forza della mia salvezza,'); -- 23 140:7
UPDATE "LUZZI" SET text = 'Non concedere, o Eterno, agli empi quel che desiderano; non dar compimento ai loro disegni, che talora non s''esaltino. Sela.' WHERE "verseID" = 102869 AND (text = 'Non concedere, o Eterno, agli empi quel che desiderano;'); -- 23 140:8
UPDATE "LUZZI" SET text = 'Sulla testa di quelli che m''attorniano ricada la perversità delle loro labbra!' WHERE "verseID" = 102870 AND (text = 'Sulla testa di quelli che m''attorniano'); -- 23 140:9
UPDATE "LUZZI" SET text = 'Cadano loro addosso dei carboni accesi! Siano gettati nel fuoco, in fosse profonde, donde non possano risorgere.' WHERE "verseID" = 102871 AND (text = 'Cadano loro addosso dei carboni accesi!'); -- 23 140:10
UPDATE "LUZZI" SET text = 'Il maldicente non sarà stabilito sulla terra; il male darà senza posa la caccia all''uomo violento.' WHERE "verseID" = 102872 AND (text = 'Il maldicente non sarà stabilito sulla terra;'); -- 23 140:11
UPDATE "LUZZI" SET text = 'Io so che l''Eterno farà ragione all''afflitto e giustizia ai poveri.' WHERE "verseID" = 102873 AND (text = 'Io so che l''Eterno farà ragione all''afflitto'); -- 23 140:12
UPDATE "LUZZI" SET text = 'Certo i giusti celebreranno il tuo nome; gli uomini retti abiteranno alla tua presenza.' WHERE "verseID" = 102874 AND (text = 'Certo i giusti celebreranno il tuo nome;gli uomini retti abiteranno alla tua presenza.'); -- 23 140:13
UPDATE "LUZZI" SET text = 'Salmo di Davide. O Eterno io t''invoco; affrettati a rispondermi. Porgi l''orecchio alla mia voce quand''io grido a te.' WHERE "verseID" = 102875 AND (text = 'Salmo di Davide.'); -- 23 141:1
UPDATE "LUZZI" SET text = 'La mia preghiera stia nel tuo cospetto come l''incenso, l''elevazione delle mie mani come il sacrifizio della sera.' WHERE "verseID" = 102876 AND (text = 'La mia preghiera stia nel tuo cospetto come l''incenso,'); -- 23 141:2
UPDATE "LUZZI" SET text = 'O Eterno, poni una guardia dinanzi alla mia bocca, guarda l''uscio delle mie labbra.' WHERE "verseID" = 102877 AND (text = 'O Eterno, poni una guardia dinanzi alla mia bocca,'); -- 23 141:3
UPDATE "LUZZI" SET text = 'Non inclinare il mio cuore ad alcuna cosa malvagia, per commettere azioni empie con gli operatori d''iniquità; e fa'' ch''io non mangi delle loro delizie.' WHERE "verseID" = 102878 AND (text = 'Non inclinare il mio cuore ad alcuna cosa malvagia,'); -- 23 141:4
UPDATE "LUZZI" SET text = 'Mi percuota pure il giusto; sarà un favore; mi riprenda pure; sarà come olio sul capo; il mio capo non lo rifiuterà; anzi malgrado la loro malvagità, continuerò a pregare.' WHERE "verseID" = 102879 AND (text = 'Mi percuota pure il giusto; sarà un favore;'); -- 23 141:5
UPDATE "LUZZI" SET text = 'I loro giudici saran precipitati per il fianco delle rocce, e si darà ascolto alle mie parole, perché sono piacevoli.' WHERE "verseID" = 102880 AND (text = 'I loro giudici saran precipitati per il fianco delle rocce,'); -- 23 141:6
UPDATE "LUZZI" SET text = 'Come quando si ara e si rompe la terra, le nostre ossa sono sparse all''ingresso del soggiorno dei morti.' WHERE "verseID" = 102881 AND (text = 'Come quando si ara e si rompe la terra,'); -- 23 141:7
UPDATE "LUZZI" SET text = 'Poiché a te son vòlti gli occhi miei, o Eterno, o Signore; in te mi rifugio, non abbandonare l''anima mia.' WHERE "verseID" = 102882 AND (text = 'Poiché a te son vòlti gli occhi miei, o Eterno, o Signore;'); -- 23 141:8
UPDATE "LUZZI" SET text = 'Guardami dal laccio che m''hanno teso, e dagli agguati degli operatori d''iniquità.' WHERE "verseID" = 102883 AND (text = 'Guardami dal laccio che m''hanno teso,'); -- 23 141:9
UPDATE "LUZZI" SET text = 'Cadano gli empi nelle loro proprie reti, mentre io passerò oltre.' WHERE "verseID" = 102884 AND (text = 'Cadano gli empi nelle loro proprie reti,mentre io passerò oltre.'); -- 23 141:10
UPDATE "LUZZI" SET text = 'Cantico di Davide, quand''era nella spelonca. Preghiera. Io grido con la mia voce all''Eterno; con la mia voce supplico l''Eterno.' WHERE "verseID" = 102885 AND (text = 'Cantico di Davide, quand''era nella spelonca. Preghiera.'); -- 23 142:1
UPDATE "LUZZI" SET text = 'Effondo il mio lamento dinanzi a lui, espongo dinanzi a lui la mia tribolazione.' WHERE "verseID" = 102886 AND (text = 'Effondo il mio lamento dinanzi a lui,'); -- 23 142:2
UPDATE "LUZZI" SET text = 'Quando lo spirito mio è abbattuto in me, tu conosci il mio sentiero. Sulla via per la quale io cammino, essi hanno nascosto un laccio per me.' WHERE "verseID" = 102887 AND (text = 'Quando lo spirito mio è abbattuto in me,'); -- 23 142:3
UPDATE "LUZZI" SET text = 'Guarda alla mia destra e vedi; non v''è alcuno che mi riconosca. Ogni rifugio m''è venuto a mancare; non v''è alcuno che abbia cura dell''anima mia.' WHERE "verseID" = 102888 AND (text = 'Guarda alla mia destra e vedi;' OR text = 'Guarda alla mia destra e vedi; non v''è alcuno che mi riconosca. Ogni rifugio m''è venuto a mancare: non v''è alcuno che abbia cura dell''anima mia.'); -- 23 142:4
UPDATE "LUZZI" SET text = 'Io grido a te, o Eterno. Io dico: Tu sei il mio rifugio, la mia parte nella terra dei viventi.' WHERE "verseID" = 102889 AND (text = 'Io grido a te, o Eterno.'); -- 23 142:5
UPDATE "LUZZI" SET text = 'Sii attento al mio grido, perché son ridotto in molto misero stato. Liberami da quelli che mi perseguitano, perché sono più forti di me.' WHERE "verseID" = 102890 AND (text = 'Sii attento al mio grido,'); -- 23 142:6
UPDATE "LUZZI" SET text = 'Trai di prigione l''anima mia, ond''io celebri il tuo nome. I giusti trionferanno meco, perché m''avrai colmato di beni.' WHERE "verseID" = 102891 AND (text = 'Trai di prigione l''anima mia,ond''io celebri il tuo nome.I giusti trionferanno meco,perché m''avrai colmato di beni.'); -- 23 142:7
UPDATE "LUZZI" SET text = 'Salmo di Davide. O Eterno, ascolta la mia preghiera, porgi l''orecchio alle mie supplicazioni; nella tua fedeltà e nella tua giustizia, rispondimi,' WHERE "verseID" = 102892 AND (text = 'Salmo di Davide.'); -- 23 143:1
UPDATE "LUZZI" SET text = 'e non venire a giudicio col tuo servitore, perché nessun vivente sarà trovato giusto nel tuo cospetto.' WHERE "verseID" = 102893 AND (text = 'e non venire a giudicio col tuo servitore,'); -- 23 143:2
UPDATE "LUZZI" SET text = 'Poiché il nemico perseguita l''anima mia; egli calpesta al suolo la mia vita; mi fa abitare in luoghi tenebrosi come quelli che son morti già da lungo tempo.' WHERE "verseID" = 102894 AND (text = 'Poiché il nemico perseguita l''anima mia;'); -- 23 143:3
UPDATE "LUZZI" SET text = 'Il mio spirito è abbattuto in me, il mio cuore è tutto smarrito dentro di me.' WHERE "verseID" = 102895 AND (text = 'Il mio spirito è abbattuto in me,'); -- 23 143:4
UPDATE "LUZZI" SET text = 'Io mi ricordo dei giorni antichi; io medito tutti i tuoi fatti; io rifletto sull''opera delle tue mani.' WHERE "verseID" = 102896 AND (text = 'Io mi ricordo dei giorni antichi;'); -- 23 143:5
UPDATE "LUZZI" SET text = 'Io stendo le mie mani verso te; l''anima mia è assetata di te come terra asciutta. Sela.' WHERE "verseID" = 102897 AND (text = 'Io stendo le mie mani verso te;'); -- 23 143:6
UPDATE "LUZZI" SET text = 'Affrettati a rispondermi, o Eterno; lo spirito mio vien meno; non nascondere da me la tua faccia, che talora io non diventi simile a quelli che scendono nella fossa.' WHERE "verseID" = 102898 AND (text = 'Affrettati a rispondermi, o Eterno;'); -- 23 143:7
UPDATE "LUZZI" SET text = 'Fammi sentire la mattina la tua benignità, poiché in te mi confido; fammi conoscer la via per la quale devo camminare, poiché io elevo l''anima mia a te.' WHERE "verseID" = 102899 AND (text = 'Fammi sentire la mattina la tua benignità,'); -- 23 143:8
UPDATE "LUZZI" SET text = 'Liberami dai miei nemici, o Eterno; io cerco rifugio presso di te.' WHERE "verseID" = 102900 AND (text = 'Liberami dai miei nemici, o Eterno;'); -- 23 143:9
UPDATE "LUZZI" SET text = 'Insegnami a far la tua volontà, poiché tu sei il mio Dio; il tuo buono Spirito mi guidi in terra piana.' WHERE "verseID" = 102901 AND (text = 'Insegnami a far la tua volontà,'); -- 23 143:10
UPDATE "LUZZI" SET text = 'O Eterno, vivificami, per amor del tuo nome; nella tua giustizia, ritrai l''anima mia dalla distretta!' WHERE "verseID" = 102902 AND (text = 'O Eterno, vivificami, per amor del tuo nome;'); -- 23 143:11
UPDATE "LUZZI" SET text = 'E nella tua benignità distruggi i miei nemici, e fa'' perire tutti quelli che affliggono l''anima mia; perché io son tuo servitore.' WHERE "verseID" = 102903 AND (text = 'E nella tua benignità distruggi i miei nemici,e fa'' perire tutti quelli che affliggono l''anima mia;perché io son tuo servitore.'); -- 23 143:12
UPDATE "LUZZI" SET text = 'Salmo di Davide. Benedetto sia l''Eterno, la mia ròcca, che ammaestra le mie mani alla pugna e le mie dita alla battaglia;' WHERE "verseID" = 102904 AND (text = 'Salmo di Davide.'); -- 23 144:1
UPDATE "LUZZI" SET text = 'ch''è il mio benefattore e la mia fortezza, il mio alto ricetto e il mio liberatore, il mio scudo, colui nel quale mi rifugio, che mi rende soggetto il mio popolo.' WHERE "verseID" = 102905 AND (text = 'ch''è il mio benefattore e la mia fortezza,' OR text = 'ch''è il mio benefattore e la mia fortezza, il mio alto ricetto, e il mio liberatore il mio scudo, colui nel quale mi rifugio, che mi rende soggetto il mio popolo.'); -- 23 144:2
UPDATE "LUZZI" SET text = 'O Eterno, che cos''è l''uomo, che tu ne prenda conoscenza? o il figliuol dell''uomo che tu ne tenga conto?' WHERE "verseID" = 102906 AND (text = 'O Eterno, che cos''è l''uomo, che tu ne prenda conoscenza?'); -- 23 144:3
UPDATE "LUZZI" SET text = 'L''uomo è simile a un soffio, i suoi giorni son come l''ombra che passa.' WHERE "verseID" = 102907 AND (text = 'L''uomo è simile a un soffio,'); -- 23 144:4
