UPDATE "LUZZI" SET text = 'Fa'' guizzare il lampo e disperdi i miei nemici. Lancia le tue saette, e mettili in rotta.' WHERE "verseID" = 102909 AND (text = 'Fa'' guizzare il lampo e disperdi i miei nemici.'); -- 23 144:6
UPDATE "LUZZI" SET text = 'Stendi le tue mani dall''alto, salvami e liberami dalle grandi acque, dalla mano degli stranieri,' WHERE "verseID" = 102910 AND (text = 'Stendi le tue mani dall''alto,'); -- 23 144:7
UPDATE "LUZZI" SET text = 'la cui bocca parla menzogna, e la cui destra è destra di frode.' WHERE "verseID" = 102911 AND (text = 'la cui bocca parla menzogna,'); -- 23 144:8
