UPDATE "LUZZI" SET text = 'I nostri granai siano pieni e forniscano ogni specie di beni. Le nostre gregge moltiplichino a migliaia e a diecine di migliaia nelle nostre campagne.' WHERE "verseID" = 102916 AND (text = 'I nostri granai siano pieni'); -- 23 144:13
