UPDATE "LUZZI" SET text = 'L''Eterno è grande e degno di somma lode, e la sua grandezza non si può investigare.' WHERE "verseID" = 102921 AND (text = 'L''Eterno è grande e degno di somma lode,'); -- 23 145:3
UPDATE "LUZZI" SET text = 'Un''età dirà all''altra le lodi delle tue opere, e farà conoscer le tue gesta.' WHERE "verseID" = 102922 AND (text = 'Un''età dirà all''altra le lodi delle tue opere,'); -- 23 145:4
