UPDATE "LUZZI" SET text = 'E gli uomini diranno la potenza dei tuoi atti tremendi, e io racconterò la tua grandezza.' WHERE "verseID" = 102924 AND (text = 'E gli uomini diranno la potenza dei tuoi atti tremendi,'); -- 23 145:6
