UPDATE "LUZZI" SET text = 'L''Eterno è presso a tutti quelli che lo invocano, a tutti quelli che lo invocano in verità.' WHERE "verseID" = 102936 AND (text = 'L''Eterno è presso a tutti quelli che lo invocano,'); -- 23 145:18
