UPDATE "LUZZI" SET text = 'Parole del re Lemuel. Sentenze con le quali sua madre lo ammaestrò.' WHERE "verseID" = 103883 AND (text = 'Parole del re Lemuel.'); -- 24 31:1
UPDATE "LUZZI" SET text = 'Oracolo su Moab. Sì, nella notte in cui è devastata, Ar-Moab perisce! Sì, nella notte in cui è devastata, Kir-Moab perisce!' WHERE "verseID" = 104559 AND (text = 'Oracolo su Moab.Sì, nella notte in cui è devastata, Ar-Moab perisce! Sì, nella notte in cui è devastata, Kir-Moab perisce!'); -- 29 15:1
UPDATE "LUZZI" SET text = 'Oracolo contro Damasco. Ecco, Damasco è tolto dal numero delle città, e non sarà più che un ammasso di rovine.' WHERE "verseID" = 104582 AND (text = 'Oracolo contro Damasco.Ecco, Damasco è tolto dal numero delle città, e non sarà più che un ammasso di rovine.'); -- 29 17:1
UPDATE "LUZZI" SET text = 'Oracolo sull''Egitto. Ecco l''Eterno, che cavalca portato da una nuvola leggera, e viene in Egitto; gl''idoli d''Egitto tremano dinanzi a lui, e all''Egitto si strugge, dentro, il cuore.' WHERE "verseID" = 104603 AND (text = 'Oracolo sull''Egitto.Ecco l''Eterno, che cavalca portato da una nuvola leggera, e viene in Egitto; gl''idoli d''Egitto tremano dinanzi a lui, e all''Egitto si strugge, dentro, il cuore.'); -- 29 19:1
UPDATE "LUZZI" SET text = 'Oracolo contro il deserto marittimo. Come gli uragani del mezzodì quando si scatenano, ei viene dal deserto, da un paese spaventoso.' WHERE "verseID" = 104634 AND (text = 'Oracolo contro il deserto marittimo.Come gli uragani del mezzodì quando si scatenano, ei viene dal deserto, da un paese spaventoso.'); -- 29 21:1
UPDATE "LUZZI" SET text = 'Oracolo contro Duma. Mi si grida da Seir: ''Sentinella, a che punto è la notte? Sentinella, a che punto è la notte?''' WHERE "verseID" = 104644 AND (text = 'Oracolo contro Duma.Mi si grida da Seir: ''Sentinella, a che punto è la notte? Sentinella, a che punto è la notte?'''); -- 29 21:11
UPDATE "LUZZI" SET text = 'Oracolo contro l''Arabia. Passerete la notte nelle foreste, in Arabia, o carovane dei Dedaniti!' WHERE "verseID" = 104646 AND (text = 'Oracolo contro l''Arabia.Passerete la notte nelle foreste, in Arabia, o carovane dei Dedaniti!'); -- 29 21:13
UPDATE "LUZZI" SET text = 'Oracolo contro la Valle della Visione. Che hai tu dunque che tu sia tutta quanta salita sui tetti,' WHERE "verseID" = 104651 AND (text = 'Oracolo contro la Valle della Visione.Che hai tu dunque che tu sia tutta quanta salita sui tetti,'); -- 29 22:1
UPDATE "LUZZI" SET text = 'Oracolo contro Tiro. Urlate, o navi di Tarsis! Poich''essa è distrutta; non più case! non più alcuno ch''entri in essa! Dalla terra di Kittim n''è giunta loro la notizia.' WHERE "verseID" = 104676 AND (text = 'Oracolo contro Tiro.Urlate, o navi di Tarsis! Poich''essa è distrutta; non più case! non più alcuno ch''entri in essa! Dalla terra di Kittim n''è giunta loro la notizia.'); -- 29 23:1
UPDATE "LUZZI" SET text = 'e questa è la parola che l''Eterno ha pronunziata contro di lui: La vergine, figliuola di Sion, ti disprezza e si fa beffe di te; la figliuola di Gerusalemme scuote la testa dietro a te.' WHERE "verseID" = 104972 AND (text = 'e questa è la parola che l''Eterno ha pronunziata contro di lui:La vergine, figliuola di Sion, ti disprezza e si fa beffe di te; la figliuola di Gerusalemme scuote la testa dietro a te.'); -- 29 37:22
UPDATE "LUZZI" SET text = '''Perché, dicono essi, quando abbiam digiunato, non ci hai tu avuto riguardo?'' ''Perché quando abbiamo afflitte le anime nostre, non v''hai tu posto mente?'' Ecco, nel giorno del vostro digiuno voi fate i vostri affari, ed esigete che sian fatti tutti i vostri lavori.' WHERE "verseID" = 105387 AND (text = '''Perché, dicono essi, quando abbiam digiunato, non ci hai tu avuto riguardo?'' ''Perché quando abbiamo afflitte le anime nostre, non v''hai tu posto mente?''Ecco, nel giorno del vostro digiuno voi fate i vostri affari, ed esigete che sian fatti tutti i vostri lavori.'); -- 29 58:3
UPDATE "LUZZI" SET text = 'la verità è scomparsa, e chi si ritrae dal male s''espone ad essere spogliato. E l''Eterno l''ha veduto, e gli è dispiaciuto che non vi sia più rettitudine;' WHERE "verseID" = 105413 AND (text = 'la verità è scomparsa, e chi si ritrae dal male s''espone ad essere spogliato.E l''Eterno l''ha veduto, e gli è dispiaciuto che non vi sia più rettitudine;'); -- 29 59:15
UPDATE "LUZZI" SET text = 'Or dunque parla agli uomini di Giuda e agli abitanti di Gerusalemme, e di'': Così parla l''Eterno: Ecco, io preparo contro di voi del male, e formo contro di voi un disegno. Si converta ora ciascun di voi dalla sua via malvagia, ed emendate le vostre vie e le vostre azioni!' WHERE "verseID" = 105992 AND (text = 'Or dunque parla agli uomini di Giuda e agli abitanti di Gerusalemme, e di'':Così parla l''Eterno: Ecco, io preparo contro di voi del male, e formo contro di voi un disegno. Si converta ora ciascun di voi dalla sua via malvagia, ed emendate le vostre vie e le vostre azioni!'); -- 30 18:11
UPDATE "LUZZI" SET text = 'Contro i profeti. Il cuore mi si spezza in seno, tutte le mie ossa tremano; io sono come un ubriaco, come un uomo sopraffatto dal vino, a cagione dell''Eterno e a cagione delle sue parole sante.' WHERE "verseID" = 106090 AND (text = 'Contro i profeti.Il cuore mi si spezza in seno, tutte le mie ossa tremano; io sono come un ubriaco, come un uomo sopraffatto dal vino, a cagione dell''Eterno e a cagione delle sue parole sante.'); -- 30 23:9
UPDATE "LUZZI" SET text = 'Riguardo a Moab. Così parla l''Eterno degli eserciti, l''Iddio d''Israele: Guai a Nebo! poiché è devastata; Kiriathaim è coperta d''onta, è presa; Misgab è coperta d''onta e sbigottita.' WHERE "verseID" = 106678 AND (text = 'Riguardo a Moab.Così parla l''Eterno degli eserciti, l''Iddio d''Israele: Guai a Nebo! poiché è devastata; Kiriathaim è coperta d''onta, è presa; Misgab è coperta d''onta e sbigottita.'); -- 30 48:1
UPDATE "LUZZI" SET text = 'Riguardo ai figliuoli di Ammon. Così parla l''Eterno: Israele non ha egli figliuoli? Non ha egli erede? Perché dunque Malcom prend''egli possesso di Gad, e il suo popolo abita nelle città d''esso?' WHERE "verseID" = 106725 AND (text = 'Riguardo ai figliuoli di Ammon.Così parla l''Eterno: Israele non ha egli figliuoli? Non ha egli erede? Perché dunque Malcom prend''egli possesso di Gad, e il suo popolo abita nelle città d''esso?'); -- 30 49:1
UPDATE "LUZZI" SET text = 'Riguardo a Edom. Così parla l''Eterno degli eserciti: Non v''è egli più saviezza in Teman? Gl''intelligenti non sanno essi più consigliare? La loro saviezza è dessa svanita?' WHERE "verseID" = 106731 AND (text = 'Riguardo a Edom.Così parla l''Eterno degli eserciti: Non v''è egli più saviezza in Teman? Gl''intelligenti non sanno essi più consigliare? La loro saviezza è dessa svanita?'); -- 30 49:7
UPDATE "LUZZI" SET text = 'Riguardo a Damasco. Hamath e Arpad sono confuse, poiché hanno udito una cattiva notizia; vengon meno; è un''agitazione come quella del mare, che non può calmarsi.' WHERE "verseID" = 106747 AND (text = 'Riguardo a Damasco.Hamath e Arpad sono confuse, poiché hanno udito una cattiva notizia; vengon meno; è un''agitazione come quella del mare, che non può calmarsi.'); -- 30 49:23
UPDATE "LUZZI" SET text = 'Riguardo a Kedar e ai regni di Hatsor, che Nebucadnetsar, re di Babilonia, sconfisse. Così parla l''Eterno: Levatevi, salite contro Kedar, distruggete i figliuoli dell''oriente!' WHERE "verseID" = 106752 AND (text = 'Riguardo a Kedar e ai regni di Hatsor, che Nebucadnetsar, re di Babilonia, sconfisse.Così parla l''Eterno: Levatevi, salite contro Kedar, distruggete i figliuoli dell''oriente!'); -- 30 49:28
UPDATE "LUZZI" SET text = 'e dirai: - Così affonderà Babilonia, e non si rialzerà più, a motivo del male ch''io faccio venire su di lei; cadrà esausta''. Fin qui, le parole di Geremia.' WHERE "verseID" = 106873 AND (text = 'e dirai: - Così affonderà Babilonia, e non si rialzerà più, a motivo del male ch''io faccio venire su di lei; cadrà esausta''.Fin qui, le parole di Geremia.'); -- 30 51:64
UPDATE "LUZZI" SET text = 'un fuoco è uscito dal suo ramo fronzuto, e ne ha divorato il frutto, sì che non v''è in essa più ramo forte né scettro per governare''. Questa la lamentazione, ch''è diventata una lamentazione.' WHERE "verseID" = 107492 AND (text = 'un fuoco è uscito dal suo ramo fronzuto, e ne ha divorato il frutto, sì che non v''è in essa più ramo forte né scettro per governare''.Questa la lamentazione, ch''è diventata una lamentazione.'); -- 33 19:14
UPDATE "LUZZI" SET text = '''Figliuol d''uomo, profetizza, e di'': Così parla il Signore. Di'': La spada! la spada! è aguzzata ed anche forbita:' WHERE "verseID" = 107550 AND (text = '''Figliuol d''uomo, profetizza, e di'': Così parla il Signore. Di'':La spada! la spada! è aguzzata ed anche forbita:'); -- 33 21:14
UPDATE "LUZZI" SET text = 'Egli disse: L''Eterno rugge da Sion, e fa risonar la sua voce da Gerusalemme; i pascoli dei pastori fanno cordoglio, e la vetta del Carmelo è inaridita.' WHERE "verseID" = 108963 AND (text = 'Egli disse:'); -- 37 1:2
UPDATE "LUZZI" SET text = 'Visione di Abdia. Così parla il Signore, l''Eterno, riguardo a Edom: Noi abbiam ricevuto un messaggio dall''Eterno, e un ambasciatore è stato mandato alle nazioni: ''Levatevi! Leviamoci contro Edom a combattere!''' WHERE "verseID" = 109107 AND (text = 'Visione di Abdia.Così parla il Signore, l''Eterno, riguardo a Edom: Noi abbiam ricevuto un messaggio dall''Eterno, e un ambasciatore è stato mandato alle nazioni: ''Levatevi! Leviamoci contro Edom a combattere!'''); -- 38 1:1
UPDATE "LUZZI" SET text = 'L''Eterno, il Signore, è la mia forza; egli renderà i miei piedi come quelli delle cerve, e mi farà camminare sui miei alti luoghi. Al Capo de'' musici. Per strumenti a corda.' WHERE "verseID" = 109383 AND (text = 'L''Eterno, il Signore, è la mia forza; egli renderà i miei piedi come quelli delle cerve, e mi farà camminare sui miei alti luoghi.Al Capo de'' musici. Per strumenti a corda.'); -- 42 3:19
UPDATE "LUZZI" SET text = 'Oracolo, parola dell''Eterno, riguardo a Israele. Parola dell''Eterno che ha disteso i cieli e fondata la terra, e che ha formato lo spirito dell''uomo dentro di lui:' WHERE "verseID" = 109642 AND (text = 'Oracolo, parola dell''Eterno, riguardo a Israele.Parola dell''Eterno che ha disteso i cieli e fondata la terra, e che ha formato lo spirito dell''uomo dentro di lui:'); -- 45 12:1
UPDATE "LUZZI" SET text = 'E Maria disse: «L''anima mia magnifica il Signore,' WHERE "verseID" = 111535 AND (text = 'E Maria disse:«L''anima mia magnifica il Signore,'); -- 49 1:46
UPDATE "LUZZI" SET text = 'Mentre avete la luce, credete nella luce, affinché diventiate figliuoli di luce. Queste cose disse Gesù, poi se ne andò e si nascose da loro.' WHERE "verseID" = 113211 AND (text = 'Queste cose disse Gesù, poi se ne andò e si nascose da loro.'); -- 50 12:36
UPDATE "LUZZI" SET text = 'E avendo preso cibo, riacquistò le forze. E Saulo rimase alcuni giorni coi discepoli che erano a Damasco.' WHERE "verseID" = 113830 AND (text = 'E Saulo rimase alcuni giorni coi discepoli che erano a Damasco.'); -- 51 9:19

